def pi_bbp(terms: int = 90) -> Decimal:
    total = Decimal(0)
    for k in range(terms):
        kk = Decimal(k)
        total += (Decimal(1) / (Decimal(16) ** k)) * (
            Decimal(4) / (Decimal(8) * kk + Decimal(1))
            - Decimal(2) / (Decimal(8) * kk + Decimal(4))
            - Decimal(1) / (Decimal(8) * kk + Decimal(5))
            - Decimal(1) / (Decimal(8) * kk + Decimal(6))
        )
    return +total


PI_D = pi_bbp()
PI = float(PI_D)
SQRT2_D = Decimal(2).sqrt()
SQRT2 = float(SQRT2_D)


def d(x) -> Decimal:
    if isinstance(x, Decimal):
        return x
    if isinstance(x, Fraction):
        return Decimal(x.numerator) / Decimal(x.denominator)
    return Decimal(str(x))


def pct_error(pred, ref) -> Decimal:
    p, r = d(pred), d(ref)
    if r == 0:
        return Decimal(0) if p == 0 else Decimal("Infinity")
    return abs(p - r) / abs(r) * Decimal(100)


def sci(x, digits: int = 12) -> str:
    return f"{d(x):.{digits}E}"


def dec(x, digits: int = 12) -> str:
    return f"{d(x):.{digits}f}"


def ffmt(x: float, digits: int = 12) -> str:
    ax = abs(x)
    if ax != 0.0 and (ax >= 1e6 or ax < 1e-5):
        return f"{x:.{digits}e}"
    return f"{x:.{digits}f}"


def line(ch: str = "=", n: int = 132) -> str:
    return ch * n


def print_table(headers: Sequence[str], rows: Sequence[Sequence[object]]) -> None:
    text = [[str(v) for v in row] for row in rows]
    widths = [len(h) for h in headers]
    for row in text:
        for i, value in enumerate(row):
            widths[i] = max(widths[i], len(value))
    print(" | ".join(headers[i].ljust(widths[i]) for i in range(len(headers))))
    print("-+-".join("-" * widths[i] for i in range(len(headers))))
    for row in text:
        print(" | ".join(row[i].ljust(widths[i]) for i in range(len(headers))))


# Arithmetic-series natural logarithm.  No runtime log call is used.
def ln_series(x: float, terms: int = 90) -> float:
    if x <= 0.0:
        raise ValueError("ln input must be positive")
    # Scale into [0.75, 1.5] with exact powers of two.
    k = 0
    y = x
    while y > 1.5:
        y *= 0.5
        k += 1
    while y < 0.75:
        y *= 2.0
        k -= 1

    def atanh_log(z: float) -> float:
        u = (z - 1.0) / (z + 1.0)
        u2 = u * u
        power = u
        s = 0.0
        for n in range(terms):
            s += power / float(2 * n + 1)
            power *= u2
        return 2.0 * s

    ln2 = atanh_log(2.0)
    return atanh_log(y) + k * ln2


