def native_seed_bundle(
    dual: int = DUAL,
    shift: int = SHIFT,
    g5: int = G5,
    d8: int = D8,
    c12: int = C12,
) -> Dict[str, Decimal]:
    if min(dual, shift, g5, d8, c12) <= 0:
        raise ValueError("all native integers must be positive")
    if g5 - shift <= 0 or d8 - g5 == 0:
        raise ValueError("invalid primitive relation")

    alpha = Decimal(1) / (PI_D * (Decimal(1) + PI_D + (Decimal(2) * PI_D) ** 2))
    alpha_s = (
        Decimal(c12 + g5) / Decimal(c12 * c12)
        - Decimal(g5 + shift) / Decimal((c12 ** 4) * g5)
    )
    sin2w = Decimal(3) / Decimal(c12 + shift)

    weak_scale_factor = Decimal(c12 ** 5) * (
        Decimal(dual)
        - Decimal(1) / Decimal(c12 + g5 - shift)
        - Decimal(1) / Decimal((c12 ** 2) * d8)
        - Decimal(1) / Decimal((c12 ** 3) * d8)
        - Decimal(1) / Decimal((c12 ** 3) * (g5 - shift))
    )

    gravity_factor = (
        Fraction((c12 * c12) ** c12, 1)
        * Fraction(d8 ** d8, 1)
        * Fraction(g5 ** (d8 - shift), 1)
        * Fraction(g5 + shift, g5)
        * Fraction(d8 - d8 // dual, d8 - g5)
        * Fraction(d8 * d8 + shift, d8 * d8)
    )
    inv_alpha_g = d(gravity_factor)

    pe_base = Fraction((g5 + dual) * d8, 1)
    pe_compact = Fraction(d8 * d8, dual)
    pe_sync = (
        Fraction(1, 1)
        + Fraction(1, d8 * g5)
        - Fraction(c12 - shift, (c12 * c12) * d8 * (g5 * g5))
        + Fraction(c12 + shift, (c12 ** 4) * d8 * g5)
    )
    pe_ratio = d(pe_base * pe_compact * pe_sync)

    return {
        "alpha_EM": alpha,
        "alpha_S_MZ_native": alpha_s,
        "sin2_theta_W": sin2w,
        "weak_scale_factor_v_over_me": weak_scale_factor,
        "inverse_alpha_G_pp": inv_alpha_g,
        "alpha_G_pp": Decimal(1) / inv_alpha_g,
        "proton_electron_ratio": pe_ratio,
    }


def anchored_absolute_bundle(native: Dict[str, Decimal]) -> Dict[str, Decimal]:
    c = SEALED["c_m_s"]
    h = SEALED["h_J_s"]
    charge = SEALED["e_C"]
    me = SEALED["m_e_kg"]
    hbar = h / (Decimal(2) * PI_D)
    joule_per_gev = charge * Decimal("1e9")
    me_energy_gev = me * c * c / joule_per_gev
    v_weak = native["weak_scale_factor_v_over_me"] * me_energy_gev
    gf = Decimal(1) / (SQRT2_D * v_weak * v_weak)

    mp = native["proton_electron_ratio"] * me
    g_si = native["alpha_G_pp"] * hbar * c / (mp * mp)
    alpha_g_ref = SEALED["G_SI"] * SEALED["m_p_kg"] ** 2 / (hbar * c)
    inv_alpha_g_ref = Decimal(1) / alpha_g_ref

    return {
        "hbar_J_s": hbar,
        "electron_energy_GeV": me_energy_gev,
        "v_weak_GeV": v_weak,
        "GF_GeV_m2": gf,
        "m_p_pred_kg": mp,
        "G_pred_SI": g_si,
        "inverse_alpha_G_pp_reference": inv_alpha_g_ref,
    }


