def fraction_rank(rows: Sequence[Sequence[Fraction]]) -> int:
    a = [list(row) for row in rows]
    if not a:
        return 0
    m, n = len(a), len(a[0])
    rank = 0
    col = 0
    while rank < m and col < n:
        pivot = None
        for r in range(rank, m):
            if a[r][col] != 0:
                pivot = r
                break
        if pivot is None:
            col += 1
            continue
        a[rank], a[pivot] = a[pivot], a[rank]
        p = a[rank][col]
        a[rank] = [x / p for x in a[rank]]
        for r in range(m):
            if r == rank:
                continue
            factor = a[r][col]
            if factor != 0:
                a[r] = [a[r][j] - factor * a[rank][j] for j in range(n)]
        rank += 1
        col += 1
    return rank


def scale_rank_audit() -> List[Tuple[str, int, int, str]]:
    # Base dimensions ordered as (M,L,T,Q).  A supplied dimensionful primitive
    # adds one independent row.  Pure dimensionless ledger equations add none.
    c_vec = (Fraction(0), Fraction(1), Fraction(-1), Fraction(0))
    hbar_vec = (Fraction(1), Fraction(2), Fraction(-1), Fraction(0))
    e_vec = (Fraction(0), Fraction(0), Fraction(0), Fraction(1))
    me_vec = (Fraction(1), Fraction(0), Fraction(0), Fraction(0))
    tau55_vec = (Fraction(0), Fraction(0), Fraction(1), Fraction(0))
    cases = [
        ("STRICT_DIMENSIONLESS_ONLY", []),
        ("C_ONLY", [c_vec]),
        ("C_HBAR_E", [c_vec, hbar_vec, e_vec]),
        ("C_HBAR_E_ME_DECODER", [c_vec, hbar_vec, e_vec, me_vec]),
        ("C_HBAR_E_TAU55_POSTULATE", [c_vec, hbar_vec, e_vec, tau55_vec]),
    ]
    out = []
    for name, rows in cases:
        rank = fraction_rank(rows)
        nullity = 4 - rank
        out.append((name, rank, nullity, "CLOSED" if nullity == 0 else "SCALE_FREEDOM_OPEN"))
    return out


