def contact_action_lens() -> Dict[str, object]:
    defect = abs(2 - 8)
    r = Fraction(defect, C12 * C12)
    a = (Fraction(1) - r * r) / (Fraction(1) + r * r)
    b = (Fraction(2) * r) / (Fraction(1) + r * r)

    x, z = Fraction(1), Fraction(0)
    orbit = [(x, z)]
    for _ in range(18):
        x, z = a * x - b * z, b * x + a * z
        orbit.append((x, z))

    norm_residuals = [xv * xv + zv * zv - Fraction(1) for xv, zv in orbit]
    del_residuals = []
    action_terms = []
    q = [p[0] for p in orbit]
    for i in range(len(q) - 1):
        # L_d(q_n,q_{n+1}) = a/2(q_n^2+q_{n+1}^2)-q_n q_{n+1}
        action_terms.append(a * (q[i] * q[i] + q[i + 1] * q[i + 1]) / 2 - q[i] * q[i + 1])
    for i in range(1, len(q) - 1):
        # D2 L_d(q_{n-1},q_n)+D1 L_d(q_n,q_{n+1}) = 0
        del_residuals.append(2 * a * q[i] - q[i - 1] - q[i + 1])

    return {
        "r": r,
        "a": a,
        "b": b,
        "det_R": a * a + b * b,
        "max_norm_residual": max(abs(v) for v in norm_residuals),
        "max_discrete_euler_lagrange_residual": max(abs(v) for v in del_residuals),
        "discrete_action": sum(action_terms, Fraction(0)),
        "orbit": orbit,
    }


