def native_color_rank_lens(su3: Dict[str, object]) -> Dict[str, object]:
    candidates = [n for n in range(2, C12 + 1) if n*n - 1 == D8]
    nc = candidates[0] if len(candidates) == 1 else None
    cf_native = Fraction(nc*nc-1,2*nc) if nc else None
    visible_depths = tuple(range(1,7))
