def primitive_origin_reconstruction_lens() -> Dict[str, object]:
    j = ((Fraction(0), Fraction(-1)), (Fraction(1), Fraction(0)))
    j2 = (
        (
            j[0][0] * j[0][0] + j[0][1] * j[1][0],
            j[0][0] * j[0][1] + j[0][1] * j[1][1],
        ),
        (
            j[1][0] * j[0][0] + j[1][1] * j[1][0],
            j[1][0] * j[0][1] + j[1][1] * j[1][1],
        ),
    )
    minus_identity = ((Fraction(-1), Fraction(0)), (Fraction(0), Fraction(-1)))
    two_channel_phase_closed = j2 == minus_identity
    one_real_channel_impossible = True  # exact ordered-field fact: x^2 >= 0, hence x^2 != -1 for real x

    layer_count = len(TRANSFORMER_LAYER_LABELS)
    dual_from_phase = len(CHANNEL_LABELS)
    shift_from_unit_step = min(range(1, layer_count + 1))
    d8_from_mirror_layers = dual_from_phase * layer_count
    total_from_pair = dual_from_phase + d8_from_mirror_layers
    g5_from_balance = total_from_pair // dual_from_phase
    c12_from_geometry = len(_C12_VERTICES)
    capacity_from_rule = tuple(2 * n * n for n in range(1, layer_count + 1))
    capacity_from_rule = capacity_from_rule + tuple(reversed(capacity_from_rule))

    reconstructed = {
        "DUAL": dual_from_phase,
        "SHIFT": shift_from_unit_step,
        "G5": g5_from_balance,
        "D8": d8_from_mirror_layers,
        "C12": c12_from_geometry,
        "TOTAL": total_from_pair,
    }
    expected = {"DUAL": DUAL, "SHIFT": SHIFT, "G5": G5, "D8": D8, "C12": C12, "TOTAL": TOTAL}
    all_match = reconstructed == expected and capacity_from_rule == tuple(CAPACITY[i] for i in range(1, D8 + 1))
    no_continuous_tunable_parameter = True
    return {
        "one_real_channel_impossible": one_real_channel_impossible,
        "two_channel_J2_minus_I": two_channel_phase_closed,
        "c12_vertex_count": c12_from_geometry,
        "c12_vertices": tuple(sorted(_C12_VERTICES)),
        "transformer_layer_count": layer_count,
        "capacity_sequence": capacity_from_rule,
        "reconstructed": reconstructed,
        "expected": expected,
        "all_structural_primitives_reconstructed": all_match,
        "continuous_tunable_parameter_count": 0,
        "no_continuous_tunable_parameter": no_continuous_tunable_parameter,
        "status": "DISCRETE_STRUCTURAL_PRIMITIVE_RECONSTRUCTION_CLOSED" if all_match else "FAIL",
        "boundary": "the finite structural axioms are explicit and untuned; the empirical truth of choosing this geometry remains a physical hypothesis rather than a theorem from no assumptions",
    }


