def dimensionless_four_interaction_core_lens(native: Dict[str, Decimal]) -> Dict[str, object]:
    k_v_me = native["weak_scale_factor_v_over_me"]
    weak_invariant = Decimal(1) / (SQRT2_D * k_v_me * k_v_me)  # G_F * m_e^2 in natural units
    weak_reference = SEALED["GF_GeV_m2"] * SEALED["m_e_GeV"] * SEALED["m_e_GeV"]

    hbar = SEALED["h_J_s"] / (Decimal(2) * PI_D)
    alpha_g_reference = SEALED["G_SI"] * SEALED["m_p_kg"] ** 2 / (hbar * SEALED["c_m_s"])

    generated = {
        "alpha_EM": native["alpha_EM"],
        "alpha_s_boundary": native["alpha_S_MZ_native"],
        "G_F_times_m_e_squared": weak_invariant,
        "alpha_G_pp": native["alpha_G_pp"],
    }
    references = {
        "alpha_EM": SEALED["alpha"],
        "alpha_s_boundary": SEALED["alpha_s_MZ"],
        "G_F_times_m_e_squared": weak_reference,
        "alpha_G_pp": alpha_g_reference,
    }
    rows = []
    for name in generated:
        rows.append((name, generated[name], references[name], pct_error(generated[name], references[name])))

    # Exact global-scale exponents.  All four are zero after quotienting by the
    # one-parameter M/L/T rescaling symmetry.
    scale_exponents = {
        "alpha_EM": Fraction(0),
        "alpha_s_boundary": Fraction(0),
        "G_F_times_m_e_squared": Fraction(2) + Fraction(-2),
        "alpha_G_pp": Fraction(-1) + Fraction(2) + Fraction(-1),
    }
    exact_dimensionless = all(v == 0 for v in scale_exponents.values())
    return {
        "rows": rows,
        "generated": generated,
        "references": references,
        "scale_exponents": scale_exponents,
        "all_scale_exponents_zero": exact_dimensionless,
        "native_generation_anchor_count": 0,
        "status": "INDEPENDENT_DIMENSIONLESS_FOUR_INTERACTION_CORE_CLOSED" if exact_dimensionless else "FAIL",
        "boundary": "the theorem is complete for the four dimensionless interaction readouts; absolute SI magnitudes remain a separate decoder problem",
    }


# ==================================================================================================
# 29. Reference-quarantine mutation / anti-circularity replay lens
# ==================================================================================================


def reference_quarantine_replay_lens() -> Dict[str, object]:
    native_before = native_seed_bundle()
    digest_before = hashlib.sha256(
        "|".join(f"{k}={native_before[k]}" for k in sorted(native_before)).encode("utf-8")
    ).hexdigest()

    saved = dict(SEALED)
    try:
        for index, key in enumerate(sorted(SEALED)):
            factor = Decimal(index + DUAL + SHIFT) / Decimal(index + SHIFT)
            SEALED[key] = saved[key] * factor
        native_after = native_seed_bundle()
        digest_after = hashlib.sha256(
            "|".join(f"{k}={native_after[k]}" for k in sorted(native_after)).encode("utf-8")
        ).hexdigest()
        anchored_after = anchored_absolute_bundle(native_after)
    finally:
        SEALED.clear()
        SEALED.update(saved)

    anchored_before = anchored_absolute_bundle(native_before)
    native_unchanged = native_before == native_after and digest_before == digest_after
    decoder_changed = anchored_before["GF_GeV_m2"] != anchored_after["GF_GeV_m2"]
    return {
        "native_digest_before": digest_before,
        "native_digest_after": digest_after,
        "native_values_unchanged_under_all_reference_mutations": native_unchanged,
        "decoder_values_change_when_anchors_change": decoder_changed,
        "status": "SEALED_REFERENCE_QUARANTINE_AND_ANTI_CIRCULARITY_REPLAY_PASS" if native_unchanged and decoder_changed else "FAIL",
        "boundary": "this proves computational non-backflow from the sealed table into native generation; it does not prove that the chosen native formulas are physically unique in all mathematics",
    }


