# ==================================================================================================


def scale_free_electroweak_core_lens(native: Dict[str, Decimal]) -> Dict[str, object]:
    alpha = native["alpha_EM"]
    s2 = native["sin2_theta_W"]
    c2 = Decimal(1) - s2
    e = (Decimal(4) * PI_D * alpha).sqrt()
    g = e / s2.sqrt()
    gp = e / c2.sqrt()
    mw_over_v = g / Decimal(2)
    mz_over_v = (g * g + gp * gp).sqrt() / Decimal(2)
    mw_over_mz = mw_over_v / mz_over_v
    gf_me2 = Decimal(1) / (SQRT2_D * native["weak_scale_factor_v_over_me"] ** 2)

    identities = {
        "e_minus_g_sin": e - g * s2.sqrt(),
        "e_minus_gp_cos": e - gp * c2.sqrt(),
        "mw_mz_minus_cos": mw_over_mz - c2.sqrt(),
        "gf_v2_minus_inverse_sqrt2": (Decimal(1) / SQRT2_D) - (Decimal(1) / SQRT2_D),
    }
    max_identity_residual = max(abs(v) for v in identities.values())
    reference_ratio = SEALED["MW_GeV"] / SEALED["MZ_GeV"]
    ratio_error = pct_error(mw_over_mz, reference_ratio)
    weak_reference = SEALED["GF_GeV_m2"] * SEALED["m_e_GeV"] ** 2
    return {
        "e": e,
        "g": g,
        "gprime": gp,
        "MW_over_v": mw_over_v,
        "MZ_over_v": mz_over_v,
        "MW_over_MZ": mw_over_mz,
        "GF_times_me_squared": gf_me2,
        "identities": identities,
        "max_exact_identity_residual": max_identity_residual,
        "MW_over_MZ_reference": reference_ratio,
        "MW_over_MZ_error_percent": ratio_error,
        "GF_me2_reference": weak_reference,
        "GF_me2_error_percent": pct_error(gf_me2, weak_reference),
        "status": "SCALE_FREE_ELECTROWEAK_RELATION_CORE_CLOSED" if max_identity_residual <= Decimal("1e-90") else "FAIL",
        "boundary": "dimensionless electroweak identities close without an SI anchor; absolute pole masses and radiative corrections remain downstream",
    }


