# ==================================================================================================
# 34. Exact automatic-differentiation engine for finite action variation
# ==================================================================================================

class Jet:
    """Exact value/gradient/Hessian jet over Fractions for polynomial finite actions."""

    def __init__(self, value: Fraction, grad: Tuple[Fraction, ...], hess: Tuple[Tuple[Fraction, ...], ...]):
        self.value = Fraction(value)
        self.grad = tuple(Fraction(v) for v in grad)
        self.hess = tuple(tuple(Fraction(v) for v in row) for row in hess)

    @staticmethod
    def constant(value, n: int) -> "Jet":
        z = tuple(Fraction(0) for _ in range(n))
        return Jet(Fraction(value), z, tuple(z for _ in range(n)))

    @staticmethod
    def variable(value, index: int, n: int) -> "Jet":
        g = [Fraction(0) for _ in range(n)]
        g[index] = Fraction(1)
        h = tuple(tuple(Fraction(0) for _ in range(n)) for _ in range(n))
        return Jet(Fraction(value), tuple(g), h)

    def _coerce(self, other) -> "Jet":
        if isinstance(other, Jet):
            if len(other.grad) != len(self.grad):
                raise ValueError("jet dimensions differ")
            return other
        return Jet.constant(other, len(self.grad))

    def __add__(self, other):
        o = self._coerce(other)
        n = len(self.grad)
        return Jet(
            self.value + o.value,
            tuple(self.grad[i] + o.grad[i] for i in range(n)),
            tuple(tuple(self.hess[i][j] + o.hess[i][j] for j in range(n)) for i in range(n)),
        )

    __radd__ = __add__

    def __neg__(self):
        n = len(self.grad)
        return Jet(
            -self.value,
            tuple(-v for v in self.grad),
            tuple(tuple(-self.hess[i][j] for j in range(n)) for i in range(n)),
        )

    def __sub__(self, other):
        return self + (-self._coerce(other))

    def __rsub__(self, other):
        return self._coerce(other) + (-self)

    def __mul__(self, other):
        o = self._coerce(other)
        n = len(self.grad)
        grad = tuple(self.grad[i] * o.value + self.value * o.grad[i] for i in range(n))
        hess = []
        for i in range(n):
            row = []
            for j in range(n):
                row.append(
                    self.hess[i][j] * o.value
                    + self.grad[i] * o.grad[j]
                    + self.grad[j] * o.grad[i]
                    + self.value * o.hess[i][j]
                )
            hess.append(tuple(row))
        return Jet(self.value * o.value, grad, tuple(hess))

    __rmul__ = __mul__

    def __truediv__(self, other):
        if isinstance(other, Jet):
            raise TypeError("division by a variable jet is not used in the finite polynomial action")
        return self * (Fraction(1, 1) / Fraction(other))

    def __pow__(self, power: int):
        if power < 0:
            raise ValueError("negative jet powers are not used")
        result = Jet.constant(1, len(self.grad))
        for _ in range(power):
            result = result * self
        return result


def _cross3(a: Sequence, b: Sequence) -> Tuple:
    return (
        a[1] * b[2] - a[2] * b[1],
        a[2] * b[0] - a[0] * b[2],
        a[0] * b[1] - a[1] * b[0],
    )


def _dot3(a: Sequence, b: Sequence):
    return sum(a[i] * b[i] for i in range(3))


