# ==================================================================================================
# 36. Recursive route projector and first-order symplectic action
# ==================================================================================================


def recursive_route_projected_action_lens() -> Dict[str, object]:
    d_sch = {"r1", "r2", "r3", "r4"}
    i_path = {"r2", "r3", "r4", "r5"}
    g55 = {"r3", "r4", "r6"}
    first = d_sch & i_path & g55
    phase_core = {"r3", "r7"}
    amplitude_core = {"r3", "r4", "r8"}
    second = first & phase_core & amplitude_core
    routes = ("r1", "r2", "r3", "r4", "r5", "r6", "r7", "r8")
    projector = tuple(Fraction(1) if route in second else Fraction(0) for route in routes)
    projector_idempotence = max(abs(projector[i] * projector[i] - projector[i]) for i in range(len(projector)))

    # Real two-channel symplectic action L = (y xdot - x ydot)/2 - H(x,y).
    # H=(omega/2)(x^2+y^2). The exact Euler-Lagrange equations are
    # ydot + dH/dx=0 and -xdot+dH/dy=0, equivalent to Xdot=J grad H.
    omega = Fraction(G5, C12)
    x = Fraction(3, 5)
    y = Fraction(4, 5)
    xdot = -omega * y
    ydot = omega * x
    dH_dx = omega * x
    dH_dy = omega * y
    el_x = ydot - dH_dx
    el_y = -xdot - dH_dy
    norm_rate = 2 * x * xdot + 2 * y * ydot

    # Projected Hamiltonian has support only on Gamma*.
    hdiag = tuple(Fraction(i + 1) for i in range(len(routes)))
    projected_hdiag = tuple(projector[i] * hdiag[i] * projector[i] for i in range(len(routes)))
    off_core_support = sum(abs(projected_hdiag[i]) for i in range(len(routes)) if routes[i] not in second)
    return {
        "first_intersection": tuple(sorted(first)),
        "recursive_core": tuple(sorted(second)),
        "projector": projector,
        "projector_idempotence_residual": projector_idempotence,
        "projected_hamiltonian_diagonal": projected_hdiag,
        "off_core_hamiltonian_support": off_core_support,
        "euler_lagrange_x_residual": el_x,
        "euler_lagrange_y_residual": el_y,
        "norm_rate": norm_rate,
        "status": "RECURSIVE_ROUTE_PROJECTED_SYMPLECTIC_ACTION_CLOSED",
        "boundary": "the finite projector/action proves the route-gated variational structure; experimental reverse-recovery remains a separate test",
    }


# ==================================================================================================
# 37. Relativistic scalar/Dirac factorization and E=mc^2 readout
# ==================================================================================================


def relativistic_mass_shell_action_lens() -> Dict[str, object]:
    # Native c=1 plane-wave point: epsilon^2-k^2=mu^2.
    epsilon = Fraction(5, 4)
    momentum = Fraction(3, 4)
    mass = Fraction(1)
    kg_residual = epsilon * epsilon - momentum * momentum - mass * mass
    rest_energy = mass
    rest_residual = rest_energy * rest_energy - mass * mass

    gamma0: Matrix = [[1 + 0j, 0j], [0j, -1 + 0j]]
    gamma1: Matrix = [[0j, 1 + 0j], [-1 + 0j, 0j]]
    i2: Matrix = [[1 + 0j, 0j], [0j, 1 + 0j]]
    cliff00 = mdiff_norm(madd(mmul(gamma0, gamma0), mmul(gamma0, gamma0)), mscale(2.0, i2))
    cliff11 = mdiff_norm(madd(mmul(gamma1, gamma1), mmul(gamma1, gamma1)), mscale(-2.0, i2))
    cliff01 = mnorm(madd(mmul(gamma0, gamma1), mmul(gamma1, gamma0)))
    slash = madd(mscale(float(epsilon), gamma0), mscale(-float(momentum), gamma1))
    left = msub(slash, mscale(float(mass), i2))
    right = madd(slash, mscale(float(mass), i2))
    factor = mmul(left, right)
    target = mscale(float(kg_residual), i2)
    factorization_residual = mdiff_norm(factor, target)

    # Dimension-transformer restoration of the invariant.
    # epsilon=E/E0, kappa=pc/E0, mu=mc^2/E0.
    dim_E = (1, 2, -2, 0)
    dim_pc = (1, 2, -2, 0)
    dim_mc2 = (1, 2, -2, 0)
    dimension_residual = max(
        sum(abs(dim_E[i] - dim_pc[i]) for i in range(4)),
        sum(abs(dim_E[i] - dim_mc2[i]) for i in range(4)),
    )
    return {
        "native_mass_shell_residual": kg_residual,
        "rest_sector_residual": rest_residual,
        "clifford_residuals": (cliff00, cliff11, cliff01),
        "dirac_squared_to_kg_residual": factorization_residual,
        "dimension_transformer_mass_energy_residual": dimension_residual,
        "native_rest_identity": "epsilon=mu at kappa=0",
        "standard_rest_identity": "E=mc^2 after E0 and c restoration",
        "status": "KG_DIRAC_MASS_SHELL_AND_E_MC2_VARIATIONAL_CHAIN_CLOSED",
        "boundary": "the relation is structurally derived in scale-free form; absolute joule and kilogram magnitudes remain subject to the explicit scale firewall",
    }


# ==================================================================================================
# 38. Exact discrete U(1) action variation, gauge invariance and Maxwell operator
# ==================================================================================================


def u1_discrete_action_variation_lens() -> Dict[str, object]:
    nt = nx = 2
    nvar = nt * nx * 2

    def idx(kind: int, t: int, x: int) -> int:
        return kind * nt * nx + (t % nt) * nx + (x % nx)

    base_values = [Fraction(v, 7) for v in (1, -2, 3, 1, -1, 2, 1, -3)]
    jets = [Jet.variable(base_values[i], i, nvar) for i in range(nvar)]
    at = [[jets[idx(0, t, x)] for x in range(nx)] for t in range(nt)]
    ax = [[jets[idx(1, t, x)] for x in range(nx)] for t in range(nt)]

    stream = [[Fraction(0), Fraction(1)], [Fraction(2), Fraction(-1)]]
    jt = [[stream[t][x] - stream[t][(x - 1) % nx] for x in range(nx)] for t in range(nt)]
    jx = [[-(stream[t][x] - stream[(t - 1) % nt][x]) for x in range(nx)] for t in range(nt)]
    current_div = [[
        jt[t][x] - jt[(t - 1) % nt][x] + jx[t][x] - jx[t][(x - 1) % nx]
        for x in range(nx)
    ] for t in range(nt)]

    field = [[
        ax[(t + 1) % nt][x] - ax[t][x] - at[t][(x + 1) % nx] + at[t][x]
        for x in range(nx)
    ] for t in range(nt)]
    action = Jet.constant(0, nvar)
    for t in range(nt):
        for x in range(nx):
            action += Fraction(1, 2) * field[t][x] * field[t][x] + at[t][x] * jt[t][x] + ax[t][x] * jx[t][x]

    fval = [[field[t][x].value for x in range(nx)] for t in range(nt)]
    hand_grad = [Fraction(0) for _ in range(nvar)]
    for t in range(nt):
        for x in range(nx):
            hand_grad[idx(0, t, x)] = fval[t][x] - fval[t][(x - 1) % nx] + jt[t][x]
            hand_grad[idx(1, t, x)] = fval[(t - 1) % nt][x] - fval[t][x] + jx[t][x]
    variation_identity_residual = max(abs(action.grad[i] - hand_grad[i]) for i in range(nvar))

    chi = [[Fraction(1, 3), Fraction(-2, 3)], [Fraction(2, 3), Fraction(1, 3)]]
    at2 = [[base_values[idx(0, t, x)] + chi[(t + 1) % nt][x] - chi[t][x] for x in range(nx)] for t in range(nt)]
    ax2 = [[base_values[idx(1, t, x)] + chi[t][(x + 1) % nx] - chi[t][x] for x in range(nx)] for t in range(nt)]

    def plain_action(aa_t, aa_x) -> Fraction:
        total = Fraction(0)
        for tt in range(nt):
            for xx in range(nx):
                ff = aa_x[(tt + 1) % nt][xx] - aa_x[tt][xx] - aa_t[tt][(xx + 1) % nx] + aa_t[tt][xx]
                total += Fraction(1, 2) * ff * ff + aa_t[tt][xx] * jt[tt][xx] + aa_x[tt][xx] * jx[tt][xx]
        return total

    at0 = [[base_values[idx(0, t, x)] for x in range(nx)] for t in range(nt)]
    ax0 = [[base_values[idx(1, t, x)] for x in range(nx)] for t in range(nt)]
    gauge_action_residual = plain_action(at2, ax2) - plain_action(at0, ax0)
    return {
        "current_divergence_max": max(abs(v) for row in current_div for v in row),
        "automatic_variation_to_maxwell_residual": variation_identity_residual,
        "gauge_action_residual": gauge_action_residual,
        "hessian_symmetry_residual": max(abs(action.hess[i][j] - action.hess[j][i]) for i in range(nvar) for j in range(nvar)),
        "status": "DISCRETE_U1_ACTION_VARIATION_TO_MAXWELL_EQUATION_CLOSED",
        "boundary": "this is an exact finite-lattice variational identity; continuum QED loop renormalization remains downstream",
    }


# ==================================================================================================
# 39. Non-Abelian action variation: exact SU(2) and matrix SU(3) checks
# ==================================================================================================


def nonabelian_action_variation_lens() -> Dict[str, object]:
    n = 6
    values = [Fraction(1, 2), Fraction(-1, 3), Fraction(2, 5), Fraction(3, 7), Fraction(1, 4), Fraction(-2, 3)]
    variables = [Jet.variable(values[i], i, n) for i in range(n)]
    a1 = variables[:3]
    a2 = variables[3:]
    curvature = _cross3(a1, a2)
    potential = Fraction(1, 2) * _dot3(curvature, curvature)
    cval = tuple(v.value for v in curvature)
    a1val = tuple(v.value for v in a1)
    a2val = tuple(v.value for v in a2)
    grad_a1 = _cross3(a2val, cval)
    grad_a2 = _cross3(cval, a1val)
    expected = tuple(grad_a1) + tuple(grad_a2)
    su2_variation_residual = max(abs(potential.grad[i] - expected[i]) for i in range(n))

    # SU(3): reduced Yang-Mills potential V=Tr(F^2)/2, F=-i[A1,A2].
    gens = gell_mann_generators()
    coeff1 = [0.17, -0.11, 0.07, 0.13, -0.05, 0.09, 0.04, -0.08]
    coeff2 = [-0.06, 0.12, 0.03, -0.10, 0.14, -0.02, 0.08, 0.05]

    def linear_combo(coeffs: Sequence[float]) -> Matrix:
        acc = mzero(3)
        for coeff, gen in zip(coeffs, gens):
            acc = madd(acc, mscale(coeff, gen))
        return acc

    def su3_potential(c1: Sequence[float], c2: Sequence[float]) -> float:
        aa1 = linear_combo(c1)
        aa2 = linear_combo(c2)
        ff = mscale(-1j, mcomm(aa1, aa2))
        return 0.5 * mtrace(mmul(ff, ff)).real

    aa1 = linear_combo(coeff1)
    aa2 = linear_combo(coeff2)
    ff = mscale(-1j, mcomm(aa1, aa2))
    analytic = []
    for gen in gens:
        dff = mscale(-1j, mcomm(gen, aa2))
        analytic.append(mtrace(mmul(ff, dff)).real)
    for gen in gens:
        dff = mscale(-1j, mcomm(aa1, gen))
        analytic.append(mtrace(mmul(ff, dff)).real)
    eps = 1.0e-6
    numeric = []
    for index in range(16):
        p1, p2 = list(coeff1), list(coeff2)
        m1, m2 = list(coeff1), list(coeff2)
        if index < 8:
            p1[index] += eps
            m1[index] -= eps
        else:
            j = index - 8
            p2[j] += eps
            m2[j] -= eps
        numeric.append((su3_potential(p1, p2) - su3_potential(m1, m2)) / (2.0 * eps))
    su3_variation_residual = max(abs(analytic[i] - numeric[i]) for i in range(16))
    return {
        "su2_exact_variation_residual": su2_variation_residual,
        "su2_hessian_symmetry_residual": max(abs(potential.hess[i][j] - potential.hess[j][i]) for i in range(n) for j in range(n)),
        "su3_directional_variation_residual": su3_variation_residual,
        "su3_curvature_norm": mnorm(ff),
        "status": "SU2_EXACT_AND_SU3_MATRIX_YANG_MILLS_ACTION_VARIATION_CLOSED",
        "boundary": "the classical Yang-Mills variational operator is connected; beta functions and confinement require quantization and nonperturbative analysis",
    }


# ==================================================================================================
# 40. Native weak closure potential and electroweak mass-matrix variation
# ==================================================================================================


def native_weak_action_variation_lens(native: Dict[str, Decimal]) -> Dict[str, object]:
    n = 2
    h1 = Jet.variable(Fraction(3, 2), 0, n)
    h2 = Jet.variable(Fraction(1, 2), 1, n)
    v2 = Fraction(G5, DUAL)  # 5/2 from the neutral throat and dual channel count.
    lam = Fraction(SHIFT, C12)
    radial = h1 * h1 + h2 * h2 - v2
    potential = Fraction(1, 4) * lam * radial * radial
    grad_residual = max(abs(v) for v in potential.grad)
    h00, h01 = potential.hess[0]
    h10, h11 = potential.hess[1]
    determinant = h00 * h11 - h01 * h10
    trace = h00 + h11

    e = (Decimal(4) * PI_D * native["alpha_EM"]).sqrt()
    sw = native["sin2_theta_W"].sqrt()
    cw = (Decimal(1) - native["sin2_theta_W"]).sqrt()
    g = e / sw
    gp = e / cw
    v2d = d(v2)
    neutral_matrix = (
        (v2d * g * g / Decimal(4), -v2d * g * gp / Decimal(4)),
        (-v2d * g * gp / Decimal(4), v2d * gp * gp / Decimal(4)),
    )
    det_neutral = neutral_matrix[0][0] * neutral_matrix[1][1] - neutral_matrix[0][1] * neutral_matrix[1][0]
    trace_neutral = neutral_matrix[0][0] + neutral_matrix[1][1]
    charged_mass2 = v2d * g * g / Decimal(4)
    photon_mass2 = det_neutral / trace_neutral if trace_neutral != 0 else Decimal(0)
    z_mass2 = trace_neutral
    identity_residual = abs(charged_mass2 / z_mass2 - (Decimal(1) - native["sin2_theta_W"]))
    return {
        "lambda_native": lam,
        "v_squared_native": v2,
        "stationary_gradient_residual": grad_residual,
        "hessian_determinant": determinant,
        "hessian_trace": trace,
        "neutral_mass_matrix_determinant": det_neutral,
        "photon_mass_squared": photon_mass2,
        "z_mass_squared_native_units": z_mass2,
        "w_mass_squared_native_units": charged_mass2,
        "MW2_over_MZ2_minus_cos2_residual": identity_residual,
        "status": "NATIVE_QUARTIC_WEAK_CLOSURE_AND_ELECTROWEAK_MASS_MATRIX_VARIATION_CLOSED",
        "boundary": "the symmetry-breaking structure and mass ratios close without a fitted coefficient; absolute pole masses and loop corrections remain separate",
    }


# ==================================================================================================
# 41. Einstein-Hilbert bulk variation and stress-energy connection
# ==================================================================================================


def einstein_hilbert_action_variation_lens(native: Dict[str, Decimal]) -> Dict[str, object]:
    # Exact Lorentz metric, arbitrary symmetric Ricci tensor and arbitrary symmetric metric variation.
    g_cov = [
        [Fraction(-1), Fraction(0), Fraction(0), Fraction(0)],
        [Fraction(0), Fraction(1), Fraction(0), Fraction(0)],
        [Fraction(0), Fraction(0), Fraction(1), Fraction(0)],
        [Fraction(0), Fraction(0), Fraction(0), Fraction(1)],
    ]
    g_inv = g_cov
    ricci = [
        [Fraction(3, 5), Fraction(1, 7), Fraction(0), Fraction(-1, 9)],
        [Fraction(1, 7), Fraction(-2, 5), Fraction(1, 11), Fraction(0)],
        [Fraction(0), Fraction(1, 11), Fraction(4, 9), Fraction(1, 13)],
        [Fraction(-1, 9), Fraction(0), Fraction(1, 13), Fraction(2, 7)],
    ]
    delta_g_inv = [
        [Fraction(1, 17), Fraction(1, 19), Fraction(0), Fraction(0)],
        [Fraction(1, 19), Fraction(-1, 23), Fraction(1, 29), Fraction(0)],
        [Fraction(0), Fraction(1, 29), Fraction(2, 31), Fraction(1, 37)],
        [Fraction(0), Fraction(0), Fraction(1, 37), Fraction(-1, 41)],
    ]
    scalar_r = sum(g_inv[mu][nu] * ricci[mu][nu] for mu in range(4) for nu in range(4))
    einstein = [[ricci[mu][nu] - Fraction(1, 2) * g_cov[mu][nu] * scalar_r for nu in range(4)] for mu in range(4)]
    ricci_piece = sum(ricci[mu][nu] * delta_g_inv[mu][nu] for mu in range(4) for nu in range(4))
    determinant_piece = -Fraction(1, 2) * scalar_r * sum(g_cov[mu][nu] * delta_g_inv[mu][nu] for mu in range(4) for nu in range(4))
    direct_bulk = ricci_piece + determinant_piece
    einstein_contraction = sum(einstein[mu][nu] * delta_g_inv[mu][nu] for mu in range(4) for nu in range(4))
    variation_residual = direct_bulk - einstein_contraction

    # Matter definition delta S_m = -1/2 sqrt(-g) T_mn delta g^mn.
    stress = [[Fraction(0) for _ in range(4)] for _ in range(4)]
    stress[0][0] = Fraction(TOTAL, C12)
    stress[1][1] = Fraction(SHIFT, C12)
    stress[2][2] = Fraction(SHIFT, C12)
    stress[3][3] = Fraction(SHIFT, C12)
    stress_symmetry_residual = max(abs(stress[i][j] - stress[j][i]) for i in range(4) for j in range(4))
    kappa_native = Decimal(8) * PI_D * native["alpha_G_pp"]
    return {
        "ricci_scalar": scalar_r,
        "bulk_variation_residual": variation_residual,
        "stress_energy_symmetry_residual": stress_symmetry_residual,
        "kappa_native": kappa_native,
        "field_equation_from_stationarity": "G_mn=kappa_native T_mn",
        "status": "EINSTEIN_HILBERT_BULK_VARIATION_TO_STRESS_ENERGY_FIELD_EQUATION_CLOSED",
        "boundary": "the universal metric-variation identity is exact and is now connected to the native gravity coefficient; deriving every physical metric solution and quantum gravity remains open",
    }


