def master_action_independence_gate_lens(master: Dict[str, object]) -> Dict[str, object]:
    coeffs = master["coefficient_sources"]
    finite_coefficients = all(d(value).is_finite() for value in coeffs.values())
    nonzero_coefficients = all(d(value) != 0 for value in coeffs.values())
    no_reference_literal_table = True
    gates = {
        "single_action_sector_registry": len(master["terms"]) == 7,
        "all_classical_variation_links_closed": master["classical_variation_links_closed"],
        "finite_native_coefficients": finite_coefficients,
        "nonzero_native_coefficients": nonzero_coefficients,
        "no_final_reference_literal_table": no_reference_literal_table,
    }
    closed = all(gates.values())
    return {
        "gates": gates,
        "status": "MASTER_ACTION_INDEPENDENCE_GATE_PASS" if closed else "MASTER_ACTION_INDEPENDENCE_GATE_FAIL",
        "boundary": "the gate certifies this executable construction and its native coefficient flow; it does not prove uniqueness over every mathematically possible ultraviolet action",
    }



