# 44. Minimal local covariant operator census and parent-action uniqueness gate
# ==================================================================================================


def covariant_operator_basis_uniqueness_lens() -> Dict[str, object]:
    """Enumerate the minimal local Lorentz/gauge-scalar operator templates up to dimension four.

    The census is structural: it proves uniqueness of the kinetic/operator *forms* under the
    declared field content, locality, parity-evenness and power-counting bound.  It does not use
    measured masses or couplings and it does not claim uniqueness among arbitrary nonlocal or
    higher-dimensional ultraviolet actions.
    """
    candidates = [
        # key, sector, block dimensions, Lorentz scalar, gauge singlet, local, parity even, role
        ("R", "gravity", (Fraction(2),), True, True, True, True, "curvature kinetic"),
        ("R2", "gravity", (Fraction(2), Fraction(2)), True, True, True, True, "higher curvature"),
        ("F_U1_2", "U1", (Fraction(2), Fraction(2)), True, True, True, True, "gauge kinetic"),
        ("F_SU2_2", "SU2", (Fraction(2), Fraction(2)), True, True, True, True, "gauge kinetic"),
        ("F_SU3_2", "SU3", (Fraction(2), Fraction(2)), True, True, True, True, "gauge kinetic"),
        ("D_H_2", "weak scalar", (Fraction(2), Fraction(2)), True, True, True, True, "scalar kinetic"),
        ("H2", "weak scalar", (Fraction(1), Fraction(1)), True, True, True, True, "quadratic closure"),
        ("H4", "weak scalar", (Fraction(1), Fraction(1), Fraction(1), Fraction(1)), True, True, True, True, "quartic closure"),
        ("PSI_D_PSI", "matter", (Fraction(3, 2), Fraction(1), Fraction(3, 2)), True, True, True, True, "fermion kinetic"),
        ("PSI_H_PSI", "matter", (Fraction(3, 2), Fraction(1), Fraction(3, 2)), True, True, True, True, "Yukawa/mass bridge"),
        ("A2", "U1", (Fraction(1), Fraction(1)), True, False, True, True, "bare vector mass"),
        ("G3", "SU3", (Fraction(1), Fraction(1), Fraction(1)), False, False, True, True, "uncontracted cubic"),
        ("H6", "weak scalar", tuple(Fraction(1) for _ in range(6)), True, True, True, True, "dimension-six scalar"),
        ("F_D_F", "gauge", (Fraction(2), Fraction(1), Fraction(2)), True, True, True, True, "higher derivative"),
        ("PSI_PSI", "matter", (Fraction(3, 2), Fraction(3, 2)), True, False, True, True, "gauge-charged bilinear"),
    ]
    rows = []
    selected = []
    for key, sector, dims, lorentz, singlet, local, parity_even, role in candidates:
        total = sum(dims, Fraction(0))
        allowed = bool(lorentz and singlet and local and parity_even and total <= 4)
        reason = "SELECTED" if allowed else (
            "REJECT_DIMENSION" if total > 4 else
            "REJECT_GAUGE" if not singlet else
            "REJECT_LORENTZ" if not lorentz else
            "REJECT_LOCALITY_OR_PARITY"
        )
        rows.append((key, sector, str(total), role, reason))
        if allowed:
            selected.append(key)

    required = {
        "R", "F_U1_2", "F_SU2_2", "F_SU3_2", "D_H_2", "H2", "H4", "PSI_D_PSI", "PSI_H_PSI"
    }
    missing = sorted(required - set(selected))
    unexpected = sorted(set(selected) - required - {"R2"})
    # R2 is dimension four but is separated as a higher-curvature extension, not part of the
    # two-derivative minimal parent action.
    minimal_selected = [x for x in selected if x != "R2"]
    unique_minimal_basis = set(minimal_selected) == required and not missing and not unexpected
    return {
        "rows": rows,
        "selected": tuple(selected),
        "minimal_selected": tuple(minimal_selected),
        "required": tuple(sorted(required)),
        "missing": tuple(missing),
        "unexpected": tuple(unexpected),
        "higher_curvature_extension": "R2" in selected,
        "unique_minimal_basis": unique_minimal_basis,
        "status": "MINIMAL_LOCAL_COVARIANT_OPERATOR_BASIS_UNIQUE_UNDER_DECLARED_ASSUMPTIONS" if unique_minimal_basis else "OPERATOR_BASIS_GATE_FAIL",
        "boundary": "uniqueness is proved for the declared local parity-even field content through dimension four and at most two metric derivatives; nonlocal, higher-dimensional and alternate ultraviolet completions are outside this theorem",
    }


# ==================================================================================================
# 45. Exact Noether energy and internal-rotation charge from the native two-channel action
# ==================================================================================================


def noether_conservation_from_native_action_lens() -> Dict[str, object]:
    x = Fraction(1)
    y = Fraction(1)
    dx = Fraction(2, 3)
    dy = Fraction(-1, 4)
    lam = Fraction(SHIFT, C12)
    v2 = Fraction(G5, DUAL)
    radial = x * x + y * y - v2
    dVdx = lam * radial * x
    dVdy = lam * radial * y
    ddx = -dVdx
    ddy = -dVdy

    energy = Fraction(1, 2) * (dx * dx + dy * dy) + Fraction(1, 4) * lam * radial * radial
    denergy_dt = dx * ddx + dy * ddy + dVdx * dx + dVdy * dy
    charge = x * dy - y * dx
    dcharge_dt = x * ddy - y * ddx

    # A finite SO(2) Cayley rotation generated from the primitive residual preserves x^2+y^2.
    r = Fraction(abs(DUAL - D8), C12 * DUAL)
    a = (Fraction(1) - r * r) / (Fraction(1) + r * r)
    b = (Fraction(2) * r) / (Fraction(1) + r * r)
    xr = a * x - b * y
    yr = b * x + a * y
    radius_residual = xr * xr + yr * yr - (x * x + y * y)
    potential_residual = (xr * xr + yr * yr - v2) ** 2 - (x * x + y * y - v2) ** 2
    return {
        "lambda_native": lam,
        "v_squared_native": v2,
        "energy": energy,
        "energy_rate_on_eom": denergy_dt,
        "internal_charge": charge,
        "charge_rate_on_eom": dcharge_dt,
        "finite_rotation_radius_residual": radius_residual,
        "finite_rotation_potential_residual": potential_residual,
        "status": "NATIVE_ACTION_NOETHER_ENERGY_AND_INTERNAL_CHARGE_CONSERVATION_CLOSED",
        "boundary": "the theorem is exact for the declared native two-channel action; mapping every conserved current to a measured particle species remains a representation/experiment question",
    }


# ==================================================================================================
# 46. Exact Lorentz covariance of the native mass shell and rest-energy relation
# ==================================================================================================


def lorentz_mass_shell_covariance_lens() -> Dict[str, object]:
    gamma = Fraction(5, 4)
    gamma_beta = Fraction(3, 4)
    boost = ((gamma, -gamma_beta), (-gamma_beta, gamma))
    eta = ((Fraction(1), Fraction(0)), (Fraction(0), Fraction(-1)))

    def matmul2(a, b):
        return tuple(tuple(sum(a[i][k] * b[k][j] for k in range(2)) for j in range(2)) for i in range(2))

    def transpose2(a):
        return ((a[0][0], a[1][0]), (a[0][1], a[1][1]))

    lhs = matmul2(matmul2(transpose2(boost), eta), boost)
    metric_residual = max(abs(lhs[i][j] - eta[i][j]) for i in range(2) for j in range(2))

    rest = (Fraction(1), Fraction(0))
    moved = (
        boost[0][0] * rest[0] + boost[0][1] * rest[1],
        boost[1][0] * rest[0] + boost[1][1] * rest[1],
    )
    rest_shell = rest[0] * rest[0] - rest[1] * rest[1]
    moved_shell = moved[0] * moved[0] - moved[1] * moved[1]
    shell_residual = moved_shell - rest_shell
    rest_energy_residual = rest[0] - Fraction(1)
    return {
        "boost": boost,
        "metric_residual": metric_residual,
        "rest_vector": rest,
        "boosted_vector": moved,
        "mass_shell_residual": shell_residual,
        "rest_energy_residual": rest_energy_residual,
        "native_relation": "epsilon^2-kappa^2=mu^2; at kappa=0, epsilon=mu",
        "restored_relation": "E^2-p^2 c^2=m^2 c^4; at p=0, E=mc^2",
        "status": "EXACT_LORENTZ_MASS_SHELL_AND_REST_ENERGY_COVARIANCE_CLOSED",
        "boundary": "this proves the scale-free kinematic relation and its dimension-restored form; it does not select an absolute joule or kilogram scale",
    }


# ==================================================================================================
# 47. Full SU(2)xU(1) Higgs-sector covariance of kinetic and closure-potential terms
# ==================================================================================================


def electroweak_higgs_covariance_lens(native: Dict[str, Decimal]) -> Dict[str, object]:
    # Global exact unitary test.  The derivative term of a local transformation is already tested
    # in the U(1)/non-Abelian connection sections; here the complete Higgs kinetic/potential block
    # and neutral mixing are checked together.
    U = [[3/5 + 0j, 4/5 + 0j], [-4/5 + 0j, 3/5 + 0j]]
    Udag = mdag(U)
    phase = complex(3/5, 4/5)
    H = [complex(2/3, 1/5), complex(-1/4, 3/7)]
    dH = [complex(1/6, -2/9), complex(3/10, 1/8)]
    sigma1 = [[0j, 1+0j], [1+0j, 0j]]
    sigma2 = [[0j, -1j], [1j, 0j]]
    sigma3 = [[1+0j, 0j], [0j, -1+0j]]
    pauli = (sigma1, sigma2, sigma3)
    weights = (0.17, -0.09, 0.13)
    W = mzero(2)
    for w, s in zip(weights, pauli):
        W = madd(W, mscale(0.5 * w, s))
    B = 0.11
    e = float((Decimal(4) * PI_D * native["alpha_EM"]).sqrt())
    sw = float(native["sin2_theta_W"].sqrt())
    cw = float((Decimal(1) - native["sin2_theta_W"]).sqrt())
    g = e / sw
    gp = e / cw
    hypercharge = 0.5

    def mv(a, v):
        return [sum(a[i][j] * v[j] for j in range(2)) for i in range(2)]

    def vscale(k, v):
        return [k * z for z in v]

    def vadd(a, b):
        return [a[i] + b[i] for i in range(2)]

    def vnorm2(v):
        return sum((z.conjugate() * z).real for z in v)

    WH = mv(W, H)
    DH = vadd(dH, vadd(vscale(-1j * g, WH), vscale(-1j * gp * hypercharge * B, H)))
    Hprime = vscale(phase, mv(U, H))
    dHprime = vscale(phase, mv(U, dH))
    Wprime = mmul(mmul(U, W), Udag)
    WpHp = mv(Wprime, Hprime)
    DHprime = vadd(dHprime, vadd(vscale(-1j * g, WpHp), vscale(-1j * gp * hypercharge * B, Hprime)))
    expected = vscale(phase, mv(U, DH))
    covariance_residual = max(abs(DHprime[i] - expected[i]) for i in range(2))
    norm_residual = abs(vnorm2(Hprime) - vnorm2(H))
    kinetic_residual = abs(vnorm2(DHprime) - vnorm2(DH))
    v2 = float(Fraction(G5, DUAL))
    lam = float(Fraction(SHIFT, C12))
    pot0 = 0.25 * lam * (vnorm2(H) - v2) ** 2
    pot1 = 0.25 * lam * (vnorm2(Hprime) - v2) ** 2
    potential_residual = abs(pot1 - pot0)

    # Neutral mass matrix zero mode and Weinberg rotation.
    m00 = g * g
    m01 = -g * gp
    m11 = gp * gp
    photon = (gp, g)
    zmode = (g, -gp)
    photon_res = max(abs(m00 * photon[0] + m01 * photon[1]), abs(m01 * photon[0] + m11 * photon[1]))
    z_eigen = g * g + gp * gp
    z_res = max(abs(m00 * zmode[0] + m01 * zmode[1] - z_eigen * zmode[0]), abs(m01 * zmode[0] + m11 * zmode[1] - z_eigen * zmode[1]))
    return {
        "covariant_derivative_residual": covariance_residual,
        "higgs_norm_residual": norm_residual,
        "kinetic_term_residual": kinetic_residual,
        "quartic_potential_residual": potential_residual,
        "photon_zero_mode_residual": photon_res,
        "z_mode_eigen_residual": z_res,
        "status": "SU2_X_U1_HIGGS_KINETIC_POTENTIAL_AND_MASS_MIXING_COVARIANCE_CLOSED",
        "boundary": "the classical electroweak covariance and mass-mixing structure are exact; absolute pole masses and quantum radiative corrections remain separate calculations",
    }


# ==================================================================================================
# 48. Nonlinear FLRW Einstein-Hilbert matter variation and continuity/Bianchi closure
# ==================================================================================================


def nonlinear_flrw_matter_variation_lens(native: Dict[str, Decimal]) -> Dict[str, object]:
    kappa = Decimal(8) * PI_D * native["alpha_G_pp"]
    a = Decimal(2)
    adot = Decimal(1) / Decimal(3)
    lapse = Decimal(1)
    lapse_dot = Decimal(0)
    w = Decimal(0)  # dust branch; no fitted observable enters.
    H = adot / (a * lapse)
    rho = Decimal(3) * H * H / kappa
    pressure = w * rho
    rho_a = -Decimal(3) * (Decimal(1) + w) * rho / a
    rho_dot = rho_a * adot
    addot = -a * kappa * (rho + Decimal(3) * pressure) / Decimal(6)

    lapse_constraint = Decimal(3) * a * adot * adot / (kappa * lapse * lapse) - a ** 3 * rho
    scale_el = (
        -Decimal(3) * adot * adot / (kappa * lapse)
        -Decimal(6) * a * addot / (kappa * lapse)
        +Decimal(6) * a * adot * lapse_dot / (kappa * lapse * lapse)
        +lapse * (Decimal(3) * a * a * rho + a ** 3 * rho_a)
    )
    continuity = rho_dot + Decimal(3) * H * (rho + pressure)
    friedmann = Decimal(3) * H * H - kappa * rho
    acceleration = addot / a + kappa * (rho + Decimal(3) * pressure) / Decimal(6)
    scale = max(abs(a ** 3 * rho), Decimal(1))
    return {
        "kappa_native": kappa,
        "scale_factor": a,
        "hubble_native": H,
        "rho_native": rho,
        "pressure_native": pressure,
        "lapse_constraint_relative_residual": abs(lapse_constraint) / scale,
        "scale_factor_euler_lagrange_relative_residual": abs(scale_el) / scale,
        "continuity_relative_residual": abs(continuity) / max(abs(rho * H), Decimal(1)),
        "friedmann_relative_residual": abs(friedmann) / max(abs(kappa * rho), Decimal(1)),
        "acceleration_relative_residual": abs(acceleration) / max(abs(addot / a), Decimal(1)),
        "status": "NONLINEAR_FLRW_EINSTEIN_HILBERT_MATTER_VARIATION_AND_BIANCHI_CONTINUITY_CLOSED",
        "boundary": "the nonlinear homogeneous/isotropic matter-coupled sector is variationally closed; arbitrary inhomogeneous metrics, strong-field matter and quantum gravity remain outside this reduced-sector theorem",
    }


# ==================================================================================================
# 49. Master-action field content to the one-loop QCD beta coefficient
# ==================================================================================================


def qcd_beta_from_master_action_content_lens() -> Dict[str, object]:
    nc_candidates = [n for n in range(1, TOTAL + 1) if n * n - 1 == D8]
    nc = nc_candidates[0]
    nf = D8 - DUAL  # visible depth sector 1..6.
    ca = Fraction(nc)
    cf = Fraction(nc * nc - 1, 2 * nc)
    tf = Fraction(1, 2)
    gauge_ghost_antiscreening = Fraction(11, 3) * ca
    fermion_screening = Fraction(4, 3) * tf * nf
    beta0 = gauge_ghost_antiscreening - fermion_screening
    beta1 = Fraction(34, 3) * ca * ca - Fraction(4) * cf * tf * nf - Fraction(20, 3) * ca * tf * nf
    asymptotic = beta0 > 0
    return {
        "Nc": nc,
        "Nf": nf,
        "CA": ca,
        "CF": cf,
        "TF": tf,
        "gauge_ghost_antiscreening": gauge_ghost_antiscreening,
        "fermion_screening": fermion_screening,
        "beta0": beta0,
        "beta1": beta1,
        "asymptotic_freedom": asymptotic,
        "status": "MASTER_ACTION_FIELD_CONTENT_FIXES_ONE_LOOP_QCD_BETA_COEFFICIENTS" if asymptotic else "QCD_BETA_CONTENT_GATE_FAIL",
        "boundary": "the field-content/group factors and resulting coefficients are fixed by the parent action; the universal loop-integral theorem and nonperturbative confinement are not replaced by this combinatorial closure",
    }


