# ==================================================================================================
# 55. Coupled product-gauge matter link inside one native parent action
# ==================================================================================================


def _identity_complex(n: int) -> Matrix:
    return [[1.0 + 0j if i == j else 0j for j in range(n)] for i in range(n)]


def _matrix_inverse_complex(a: Matrix) -> Matrix:
    n = len(a)
    aug = [list(a[i]) + list(_identity_complex(n)[i]) for i in range(n)]
    for col in range(n):
        pivot = max(range(col, n), key=lambda r: abs(aug[r][col]))
        if abs(aug[pivot][col]) < 1.0e-15:
            raise ValueError('singular complex matrix')
        if pivot != col:
            aug[col], aug[pivot] = aug[pivot], aug[col]
        p = aug[col][col]
        aug[col] = [z / p for z in aug[col]]
        for row in range(n):
            if row == col:
                continue
            factor = aug[row][col]
            if factor != 0j:
                aug[row] = [aug[row][j] - factor * aug[col][j] for j in range(2 * n)]
    return [row[n:] for row in aug]


def _kron(a: Matrix, b: Matrix) -> Matrix:
    return [
        [a[i][j] * b[p][q] for j in range(len(a[0])) for q in range(len(b[0]))]
        for i in range(len(a)) for p in range(len(b))
    ]


def _mvec(a: Matrix, v: Sequence[complex]) -> List[complex]:
    return [sum(a[i][j] * v[j] for j in range(len(v))) for i in range(len(a))]


def _vsub(a: Sequence[complex], b: Sequence[complex]) -> List[complex]:
    return [a[i] - b[i] for i in range(len(a))]


def _vnorm2(v: Sequence[complex]) -> float:
    return sum((z.conjugate() * z).real for z in v)


def _vdiff_norm(a: Sequence[complex], b: Sequence[complex]) -> float:
    return sum(abs(a[i] - b[i]) ** 2 for i in range(len(a))) ** 0.5


def _cayley_unitary(generator: Matrix, parameter: float) -> Matrix:
    n = len(generator)
    ident = _identity_complex(n)
    plus = madd(ident, mscale(1j * parameter, generator))
    minus = msub(ident, mscale(1j * parameter, generator))
    return mmul(plus, _matrix_inverse_complex(minus))


def _unitarity_residual(u: Matrix) -> float:
    ident = _identity_complex(len(u))
    return mdiff_norm(mmul(mdag(u), u), ident)


def _u1_cayley(parameter: float) -> complex:
    return (1.0 + 1j * parameter) / (1.0 - 1j * parameter)


def _u1_cayley_derivative(parameter: float) -> complex:
    return 2j / ((1.0 - 1j * parameter) ** 2)


def _native_test_matter_vector(site: int, dimension: int) -> List[complex]:
    # Every component is generated from the finite structural integers and the site/component indices.
    out: List[complex] = []
    for index in range(dimension):
        numerator_re = (site + SHIFT) * (index + SHIFT)
        denominator_re = C12 + D8 + site + index + DUAL
        numerator_im = G5 + site + index
        denominator_im = TOTAL + C12 + D8 + site + index
        sign = -1 if (site + index) % DUAL else 1
        out.append(complex(numerator_re / denominator_re, sign * numerator_im / denominator_im))
    return out


def coupled_product_gauge_matter_parent_action_lens(
    native: Dict[str, Decimal], genealogy: Dict[str, object]
) -> Dict[str, object]:
    c = genealogy['values']
    nc_candidates = [n for n in range(SHIFT, TOTAL + SHIFT) if n * n - SHIFT == D8]
    nc = nc_candidates[0]
    weak_dimension = DUAL
    matter_dimension = weak_dimension * nc

    half = 0.5
    pauli_1: Matrix = [[0j, half + 0j], [half + 0j, 0j]]
    pauli_3: Matrix = [[half + 0j, 0j], [0j, -half + 0j]]
    color_generators = gell_mann_generators()
    color_link_generator = madd(color_generators[G5 - SHIFT], mscale(float(c['route_weight']), color_generators[D8 - SHIFT]))
    color_gauge_generator_0 = color_generators[SHIFT - SHIFT]
    color_gauge_generator_1 = color_generators[DUAL - SHIFT]

    route = float(c['route_weight'])
    matter_scale = float(c['matter_mass2'])
    u1_parameter = route * float(c['e2'].sqrt())
    su2_parameter = route * float(c['g2'].sqrt())
    su3_parameter = route * float(c['gs2'].sqrt())

    phase_link = _u1_cayley(u1_parameter)
    weak_link = _cayley_unitary(pauli_3, su2_parameter)
    color_link = _cayley_unitary(color_link_generator, su3_parameter)
    product_link = mscale(phase_link, _kron(weak_link, color_link))

    local_parameter_0 = route + matter_scale
    local_parameter_1 = route + float(c['weak_lambda'])
    phase_0 = _u1_cayley(local_parameter_0 * float(c['e2'].sqrt()))
    phase_1 = _u1_cayley(local_parameter_1 * float(c['e2'].sqrt()))
    weak_g0 = _cayley_unitary(pauli_1, local_parameter_0 * float(c['g2'].sqrt()))
    weak_g1 = _cayley_unitary(pauli_3, local_parameter_1 * float(c['g2'].sqrt()))
    color_g0 = _cayley_unitary(color_gauge_generator_0, local_parameter_0 * float(c['gs2'].sqrt()))
    color_g1 = _cayley_unitary(color_gauge_generator_1, local_parameter_1 * float(c['gs2'].sqrt()))
    gauge_0 = mscale(phase_0, _kron(weak_g0, color_g0))
    gauge_1 = mscale(phase_1, _kron(weak_g1, color_g1))

    psi_0 = _native_test_matter_vector(0, matter_dimension)
    psi_1 = _native_test_matter_vector(SHIFT, matter_dimension)
    hopping_weight = float(c['route_weight'] + c['matter_mass2'])
    quartic_weight = float(c['weak_lambda'])
    target_norm = float(c['weak_v2'])

    def action(link: Matrix, field_0: Sequence[complex], field_1: Sequence[complex]) -> float:
        transported = _mvec(link, field_0)
        residual = _vsub(field_1, transported)
        n0 = _vnorm2(field_0)
        n1 = _vnorm2(field_1)
        hopping = hopping_weight * _vnorm2(residual)
        potential = quartic_weight * ((n0 - target_norm) ** 2 + (n1 - target_norm) ** 2) / float(len(CHANNEL_LABELS) * len(CHANNEL_LABELS))
        return hopping + potential

    action_before = action(product_link, psi_0, psi_1)
    psi_0_g = _mvec(gauge_0, psi_0)
    psi_1_g = _mvec(gauge_1, psi_1)
    link_g = mmul(mmul(gauge_1, product_link), mdag(gauge_0))
    action_after = action(link_g, psi_0_g, psi_1_g)

    residual_before = _vsub(psi_1, _mvec(product_link, psi_0))
    residual_after = _vsub(psi_1_g, _mvec(link_g, psi_0_g))
    covariant_target = _mvec(gauge_1, residual_before)
    covariance_residual = _vdiff_norm(residual_after, covariant_target)

    unitarity = max(
        _unitarity_residual(product_link),
        _unitarity_residual(gauge_0),
        _unitarity_residual(gauge_1),
    )

    # The U(1) link-current is obtained by differentiating the same hopping action.
    weak_color_link = _kron(weak_link, color_link)
    d_product_link = mscale(_u1_cayley_derivative(u1_parameter), weak_color_link)
    d_transport = _mvec(d_product_link, psi_0)
    analytic_current = -2.0 * hopping_weight * sum(
        (residual_before[i].conjugate() * d_transport[i]).real for i in range(matter_dimension)
    )

    step = float(c['route_weight'] ** len(TRANSFORMER_LAYER_LABELS))
    def action_at_u1(parameter: float) -> float:
        link = mscale(_u1_cayley(parameter), weak_color_link)
        return action(link, psi_0, psi_1)
    numerical_current = (action_at_u1(u1_parameter + step) - action_at_u1(u1_parameter - step)) / (2.0 * step)
    current_residual = abs(analytic_current - numerical_current) / max(1.0, abs(analytic_current), abs(numerical_current))

    finite = all(
        value == value and abs(value) < float('inf')
        for value in (action_before, action_after, covariance_residual, unitarity, analytic_current, numerical_current)
    )
    closed = (
        finite
        and abs(action_after - action_before) < 1.0e-11
        and covariance_residual < 1.0e-11
        and unitarity < 1.0e-11
        and current_residual < 1.0e-7
    )
    return {
        'matter_dimension': matter_dimension,
        'weak_dimension': weak_dimension,
        'color_dimension': nc,
        'action_before': action_before,
        'action_after': action_after,
        'action_invariance_residual': abs(action_after - action_before),
        'covariant_residual': covariance_residual,
        'unitarity_residual': unitarity,
        'analytic_u1_link_current': analytic_current,
        'numerical_u1_link_current': numerical_current,
        'current_variation_residual': current_residual,
        'closed': closed,
        'status': 'COUPLED_U1_SU2_SU3_MATTER_PARENT_ACTION_GAUGE_INVARIANT_AND_SOURCED' if closed else 'COUPLED_GAUGE_MATTER_ACTION_GATE_FAIL',
        'boundary': 'this closes an interacting classical product-gauge matter block and its sourced link variation inside the same native parent action; the complete chiral Standard Model representation table and quantum anomaly cancellation remain separate requirements',
    }


# ==================================================================================================
# 56. Gauge-orbit Noether identities and constraint propagation
# ==================================================================================================


def covariant_noether_constraint_propagation_lens(
    native: Dict[str, Decimal], genealogy: Dict[str, object], flrw: Dict[str, object]
) -> Dict[str, object]:
    c = genealogy['values']
    nc = [n for n in range(SHIFT, TOTAL + SHIFT) if n * n - SHIFT == D8][0]
    matter_dimension = DUAL * nc
    half = 0.5
    su2_generator: Matrix = [[0j, half + 0j], [half + 0j, 0j]]
    su3_generator = gell_mann_generators()[SHIFT - SHIFT]
    identity_2 = _identity_complex(DUAL)
    identity_3 = _identity_complex(nc)
    identity_6 = _identity_complex(matter_dimension)

    base_u1 = float(c['route_weight'] * c['e2'].sqrt())
    base_su2 = float(c['route_weight'] * c['g2'].sqrt())
    base_su3 = float(c['route_weight'] * c['gs2'].sqrt())
    link = mscale(
        _u1_cayley(base_u1),
        _kron(_cayley_unitary(su2_generator, base_su2), _cayley_unitary(su3_generator, base_su3)),
    )
    psi_0 = _native_test_matter_vector(0, matter_dimension)
    psi_1 = _native_test_matter_vector(SHIFT, matter_dimension)
    weight = float(c['route_weight'] + c['matter_mass2'])

    def hopping_action(u: Matrix, p0: Sequence[complex], p1: Sequence[complex]) -> float:
        return weight * _vnorm2(_vsub(p1, _mvec(u, p0)))

    epsilon = float(c['route_weight'] ** len(TRANSFORMER_LAYER_LABELS))

    def orbit_derivative(kind: str) -> Tuple[float, float]:
        values = []
        for sign in (-1.0, 1.0):
            eps = sign * epsilon
            if kind == 'U1':
                g1 = mscale(_u1_cayley(eps * float(c['e2'].sqrt())), identity_6)
            elif kind == 'SU2':
                g1 = _kron(_cayley_unitary(su2_generator, eps * float(c['g2'].sqrt())), identity_3)
            elif kind == 'SU3':
                g1 = _kron(identity_2, _cayley_unitary(su3_generator, eps * float(c['gs2'].sqrt())))
            else:
                raise ValueError(kind)
            transformed_link = mmul(g1, link)
            transformed_psi_1 = _mvec(g1, psi_1)
            values.append(hopping_action(transformed_link, psi_0, transformed_psi_1))
        derivative = (values[1] - values[0]) / (2.0 * epsilon)
        finite_difference_spread = abs(values[1] - values[0])
        return derivative, finite_difference_spread

    identities = {kind: orbit_derivative(kind) for kind in ('U1', 'SU2', 'SU3')}
    max_orbit_derivative = max(abs(value[0]) for value in identities.values())
    max_action_spread = max(value[1] for value in identities.values())
    gravity_constraint = max(
        float(flrw['continuity_relative_residual']),
        float(flrw['lapse_constraint_relative_residual']),
        float(flrw['acceleration_relative_residual']),
    )
    closed = max_orbit_derivative < 1.0e-10 and max_action_spread < 1.0e-12 and gravity_constraint < 1.0e-70
    return {
        'rows': [(kind, identities[kind][0], identities[kind][1]) for kind in ('U1', 'SU2', 'SU3')],
        'max_gauge_orbit_noether_derivative': max_orbit_derivative,
        'max_gauge_orbit_action_spread': max_action_spread,
        'gravity_constraint_propagation_residual': gravity_constraint,
        'closed': closed,
        'status': 'GAUGE_NOETHER_IDENTITIES_AND_GRAVITY_CONSTRAINT_PROPAGATION_CLOSED' if closed else 'NOETHER_CONSTRAINT_PROPAGATION_GATE_FAIL',
        'boundary': 'the finite coupled action satisfies the local product-gauge orbit identities and the homogeneous gravity constraint propagates with matter continuity; anomalies and unrestricted inhomogeneous constraint algebra are not silently claimed',
    }


