# 57. Gauge-fixed kinetic stability and characteristic-cone audit
# ==================================================================================================


def kinetic_hyperbolicity_stability_lens(genealogy: Dict[str, object]) -> Dict[str, object]:
    c = genealogy['values']
    kinetic = {
        'two_channel_matter': Decimal(SHIFT),
        'U1_transverse': Decimal(SHIFT) / c['e2'],
        'SU2_transverse': Decimal(SHIFT) / c['g2'],
        'SU3_transverse': Decimal(SHIFT) / c['gs2'],
        'weak_radial_scalar': Decimal(SHIFT),
    }
    signs = {name: value > 0 for name, value in kinetic.items()}
    determinant = Decimal(SHIFT)
    for value in kinetic.values():
        determinant *= value

    characteristic_rows = []
    max_massless_residual = Decimal(0)
    for index, (name, coefficient) in enumerate(kinetic.items()):
        wave_number = Decimal(index + SHIFT) / Decimal(C12 + D8 + index + SHIFT)
        frequency = wave_number
        residual = abs(coefficient * (frequency * frequency - wave_number * wave_number))
        max_massless_residual = max(max_massless_residual, residual)
        characteristic_rows.append((name, wave_number, frequency, residual))

    matter_k = Decimal(G5) / Decimal(C12 + D8)
    matter_mass2 = c['matter_mass2']
    matter_omega = (matter_k * matter_k + matter_mass2).sqrt()
    massive_residual = abs(matter_omega * matter_omega - matter_k * matter_k - matter_mass2)
    group_velocity2 = matter_k * matter_k / (matter_k * matter_k + matter_mass2)
    subluminal = Decimal(0) <= group_velocity2 < Decimal(SHIFT)

    positive = all(signs.values()) and determinant > 0
    closed = positive and max_massless_residual == 0 and massive_residual < Decimal('1e-90') and subluminal
    return {
        'rows': [(name, sci(value, 18), signs[name]) for name, value in kinetic.items()],
        'characteristic_rows': characteristic_rows,
        'kinetic_determinant': determinant,
        'all_propagating_kinetic_coefficients_positive': positive,
        'max_massless_characteristic_residual': max_massless_residual,
        'massive_matter_shell_residual': massive_residual,
        'massive_group_velocity_squared': group_velocity2,
        'massive_mode_subluminal': subluminal,
        'closed': closed,
        'status': 'GAUGE_FIXED_CLASSICAL_KINETIC_NO_GHOST_AND_HYPERBOLIC_CONE_GATE_PASS' if closed else 'KINETIC_HYPERBOLICITY_GATE_FAIL',
        'boundary': 'this is a classical quadratic, gauge-fixed propagating-sector audit; the gravitational conformal-factor problem, interacting quantum spectral positivity and nonperturbative unitarity require separate analysis',
    }


