# 58. Strict coupled-parent-action closure gate
# ==================================================================================================


def strict_coupled_parent_action_gate_lens(
    strict_parent: Dict[str, object],
    coupled: Dict[str, object],
    noether_constraints: Dict[str, object],
    stability: Dict[str, object],
) -> Dict[str, object]:
    gates = {
        'single_native_parent_action_prior_gate': strict_parent['closed'],
        'interacting_product_gauge_matter_block': coupled['closed'],
        'local_product_gauge_covariance': coupled['covariant_residual'] < 1.0e-11,
        'sourced_link_current_from_same_action': coupled['current_variation_residual'] < 1.0e-7,
        'gauge_orbit_noether_identities': noether_constraints['max_gauge_orbit_noether_derivative'] < 1.0e-10,
        'gravity_constraint_propagation': noether_constraints['gravity_constraint_propagation_residual'] < 1.0e-70,
        'positive_gauge_fixed_propagating_kinetics': stability['all_propagating_kinetic_coefficients_positive'],
        'hyperbolic_characteristic_cone': stability['max_massless_characteristic_residual'] == 0,
        'massive_matter_causal_shell': stability['massive_mode_subluminal'],
    }
    closed = all(gates.values())
    return {
        'gates': gates,
        'closed': closed,
        'status': 'STRICT_COUPLED_NATIVE_PARENT_ACTION_INTERACTION_NOETHER_HYPERBOLICITY_GATE_PASS' if closed else 'STRICT_COUPLED_PARENT_ACTION_GATE_FAIL',
        'boundary': 'the gate advances the parent action from an additive sector sum to a genuinely interacting classical gauge-matter system with exact symmetry identities and a stable gauge-fixed principal part; full chiral anomaly cancellation and quantum completion remain distinct tests',
    }



# ==================================================================================================
# 59. Exact chiral representation, unique hypercharge and anomaly cancellation
# ==================================================================================================




def chiral_projector_lens() -> Dict[str, object]:
    # Weyl-basis chirality operator.  The projectors are exact finite matrices.
    identity4: Matrix = [[1.0 + 0j if i == j else 0j for j in range(4)] for i in range(4)]
    gamma5: Matrix = [
        [-1.0 + 0j, 0j, 0j, 0j],
        [0j, -1.0 + 0j, 0j, 0j],
        [0j, 0j, 1.0 + 0j, 0j],
        [0j, 0j, 0j, 1.0 + 0j],
    ]
    p_left = mscale(0.5, msub(identity4, gamma5))
    p_right = mscale(0.5, madd(identity4, gamma5))
    gamma5_square_residual = mdiff_norm(mmul(gamma5, gamma5), identity4)
    left_idempotence_residual = mdiff_norm(mmul(p_left, p_left), p_left)
    right_idempotence_residual = mdiff_norm(mmul(p_right, p_right), p_right)
    orthogonality_residual = mnorm(mmul(p_left, p_right))
    completeness_residual = mdiff_norm(madd(p_left, p_right), identity4)
    left_rank = round(mtrace(p_left).real)
    right_rank = round(mtrace(p_right).real)
    closed = (
        gamma5_square_residual < 1.0e-15
        and left_idempotence_residual < 1.0e-15
        and right_idempotence_residual < 1.0e-15
        and orthogonality_residual < 1.0e-15
        and completeness_residual < 1.0e-15
        and left_rank == DUAL
        and right_rank == DUAL
    )
    return {
        'gamma5_square_residual': gamma5_square_residual,
        'left_idempotence_residual': left_idempotence_residual,
        'right_idempotence_residual': right_idempotence_residual,
        'orthogonality_residual': orthogonality_residual,
        'completeness_residual': completeness_residual,
        'left_rank': left_rank,
        'right_rank': right_rank,
        'closed': closed,
        'status': 'EXACT_CHIRAL_PROJECTOR_DECOMPOSITION_CLOSED' if closed else 'FAIL',
        'boundary': 'this fixes an exact left/right kinematic decomposition; observed flavor mixing and neutrino-mass completion require additional independently generated matter operators',
    }


def chiral_hypercharge_anomaly_parent_action_lens() -> Dict[str, object]:
    # Color rank is reconstructed from the eight-depth adjoint relation N_c^2-1=D8.
    nc_candidates = [n for n in range(SHIFT, TOTAL + SHIFT) if n * n - SHIFT == D8]
    if len(nc_candidates) != SHIFT:
        raise ValueError('native color-rank reconstruction is not unique')
    nc = nc_candidates[0]

    # The native weak doublet fixes the Higgs normalization Y_H = one seat / two-channel pair.
    y_h = Fraction(SHIFT, DUAL)

    # All variables are left-handed Weyl fields:
    # Q_L, u^c, d^c, L_L, e^c.  No right-handed neutrino is inserted.
    labels = ('Q_L', 'u_c', 'd_c', 'L_L', 'e_c')
    # Five independent exact constraints:
    #   N_c Y_Q + Y_L = 0                              [SU(2)^2 U(1)]
    #   Y_Q + Y_H + Y_uc = 0                           [up Yukawa]
    #   Y_Q - Y_H + Y_dc = 0                           [down Yukawa]
    #   Y_L - Y_H + Y_ec = 0                           [charged-lepton Yukawa]
    #   2N_cY_Q + N_cY_uc + N_cY_dc + 2Y_L + Y_ec = 0 [gravity^2 U(1)]
    matrix = [
        [Fraction(nc), Fraction(0), Fraction(0), Fraction(1), Fraction(0)],
        [Fraction(1), Fraction(1), Fraction(0), Fraction(0), Fraction(0)],
        [Fraction(1), Fraction(0), Fraction(1), Fraction(0), Fraction(0)],
        [Fraction(0), Fraction(0), Fraction(0), Fraction(1), Fraction(1)],
        [Fraction(2 * nc), Fraction(nc), Fraction(nc), Fraction(DUAL), Fraction(1)],
    ]
    rhs = [Fraction(0), -y_h, y_h, y_h, Fraction(0)]
    solution, rank, inconsistent = solve_fraction_system(matrix, rhs)
    charges = dict(zip(labels, solution))
    unique = (not inconsistent and rank == len(labels))

    yq = charges['Q_L']
    yu = charges['u_c']
    yd = charges['d_c']
    yl = charges['L_L']
    ye = charges['e_c']

    anomaly_su3_su3_u1 = DUAL * yq + yu + yd
    anomaly_su2_su2_u1 = nc * yq + yl
    anomaly_gravity_u1 = DUAL * nc * yq + nc * yu + nc * yd + DUAL * yl + ye
    anomaly_u1_cubed = DUAL * nc * yq**3 + nc * yu**3 + nc * yd**3 + DUAL * yl**3 + ye**3
    anomaly_su3_cubed = Fraction(DUAL - SHIFT - SHIFT)  # 2 fundamentals - u^c - d^c

    yukawa_up = yq + y_h + yu
    yukawa_down = yq - y_h + yd
    yukawa_electron = yl - y_h + ye

    t3_up = Fraction(SHIFT, DUAL)
    t3_down = -t3_up
    electric_charges = {
        'u_L': t3_up + yq,
        'd_L': t3_down + yq,
        'u_R': -yu,
        'd_R': -yd,
        'nu_L': t3_up + yl,
        'e_L': t3_down + yl,
        'e_R': -ye,
        'H_plus': t3_up + y_h,
        'H_zero': t3_down + y_h,
    }

    left_doublet_count = nc + SHIFT
    global_su2_witten_parity = left_doublet_count % DUAL

    expected = {
        'Q_L': Fraction(1, 6),
        'u_c': Fraction(-2, 3),
        'd_c': Fraction(1, 3),
        'L_L': Fraction(-1, 2),
        'e_c': Fraction(1),
    }
    expected_match = all(charges[key] == expected[key] for key in labels)
    all_local_anomalies_zero = all(
        value == 0
        for value in (
            anomaly_su3_su3_u1,
            anomaly_su2_su2_u1,
            anomaly_gravity_u1,
            anomaly_u1_cubed,
            anomaly_su3_cubed,
        )
    )
    all_yukawa_covariant = all(value == 0 for value in (yukawa_up, yukawa_down, yukawa_electron))
    electric_charge_closed = (
        electric_charges['u_L'] == electric_charges['u_R'] == Fraction(2, 3)
        and electric_charges['d_L'] == electric_charges['d_R'] == Fraction(-1, 3)
        and electric_charges['nu_L'] == 0
        and electric_charges['e_L'] == electric_charges['e_R'] == Fraction(-1)
        and electric_charges['H_plus'] == 1
        and electric_charges['H_zero'] == 0
    )
    closed = (
        unique
        and expected_match
        and all_local_anomalies_zero
        and all_yukawa_covariant
        and global_su2_witten_parity == 0
        and electric_charge_closed
    )
    return {
        'color_rank': nc,
        'higgs_hypercharge': y_h,
        'labels': labels,
        'charges': charges,
        'constraint_rank': rank,
        'constraint_nullity': len(labels) - rank,
        'inconsistent': inconsistent,
        'unique': unique,
        'anomaly_su3_su3_u1': anomaly_su3_su3_u1,
        'anomaly_su2_su2_u1': anomaly_su2_su2_u1,
        'anomaly_gravity_u1': anomaly_gravity_u1,
        'anomaly_u1_cubed': anomaly_u1_cubed,
        'anomaly_su3_cubed': anomaly_su3_cubed,
        'yukawa_up': yukawa_up,
        'yukawa_down': yukawa_down,
        'yukawa_electron': yukawa_electron,
        'electric_charges': electric_charges,
        'left_doublet_count': left_doublet_count,
        'global_su2_witten_parity': global_su2_witten_parity,
        'all_local_anomalies_zero': all_local_anomalies_zero,
        'all_yukawa_covariant': all_yukawa_covariant,
        'electric_charge_closed': electric_charge_closed,
        'closed': closed,
        'status': 'UNIQUE_CHIRAL_HYPERCHARGE_YUKAWA_AND_ANOMALY_CLOSURE_GATE_PASS' if closed else 'FAIL',
        'boundary': 'one anomaly-free chiral generation and its charge assignments are fixed without continuous fitting; generation replication, CKM/PMNS phases, neutrino masses and full loop amplitudes remain separate physical derivations',
    }


def strict_chiral_parent_action_gate_lens(
    prior_gate: Dict[str, object],
    projectors: Dict[str, object],
    chiral: Dict[str, object],
) -> Dict[str, object]:
    gates = {
        'prior_coupled_parent_action_closed': prior_gate['closed'],
        'exact_left_right_projectors': projectors['closed'],
        'hypercharge_solution_unique': chiral['unique'],
        'all_local_gauge_and_gravity_anomalies_cancel': chiral['all_local_anomalies_zero'],
        'all_native_yukawa_terms_gauge_covariant': chiral['all_yukawa_covariant'],
        'global_su2_witten_anomaly_absent': chiral['global_su2_witten_parity'] == 0,
        'electric_charge_spectrum_reconstructed': chiral['electric_charge_closed'],
    }
    closed = all(gates.values())
    return {
        'gates': gates,
        'closed': closed,
        'status': 'STRICT_CHIRAL_NATIVE_PARENT_ACTION_ANOMALY_CLOSURE_GATE_PASS' if closed else 'FAIL',
        'boundary': 'the classical parent action now carries an exact anomaly-free chiral representation for one generation; quantum radiative completion, generation structure and nonperturbative dynamics are not silently inferred',
    }

