# ==================================================================================================
# 61. Native three-generation orbit from the close-packed first shell
# ==================================================================================================


def _matrix_rank_complex(a: Matrix, tolerance: float = 1.0e-12) -> int:
    work = [list(row) for row in a]
    rows = len(work)
    cols = len(work[0]) if rows else 0
    rank = 0
    for col in range(cols):
        pivot = max(range(rank, rows), key=lambda r: abs(work[r][col]), default=rank)
        if rank >= rows or abs(work[pivot][col]) <= tolerance:
            continue
        work[rank], work[pivot] = work[pivot], work[rank]
        scale = work[rank][col]
        work[rank] = [z / scale for z in work[rank]]
        for row in range(rows):
            if row == rank:
                continue
            factor = work[row][col]
            if abs(factor) > tolerance:
                work[row] = [work[row][j] - factor * work[rank][j] for j in range(cols)]
        rank += 1
        if rank == rows:
            break
    return rank


def native_three_generation_orbit_lens(chiral_anomaly: Dict[str, object]) -> Dict[str, object]:
    # The 12 first-shell vertices split without a numerical fit into the three classes
    # selected by which Cartesian axis is zero.  Each class contains four vertices.
    classes: Dict[int, List[Tuple[int, int, int]]] = {axis: [] for axis in range(len(TRANSFORMER_LAYER_LABELS) - SHIFT)}
    for vertex in sorted(_C12_VERTICES):
        zero_axes = [axis for axis, value in enumerate(vertex) if value == 0]
        if len(zero_axes) != SHIFT:
            raise AssertionError('first-shell vertex does not have one zero axis')
        classes[zero_axes[0]].append(vertex)

    orbit_sizes = tuple(len(classes[axis]) for axis in sorted(classes))
    generation_count = len(classes)
    expected_orbit_size = len(TRANSFORMER_LAYER_LABELS)

    cyclic: Matrix = [
        [0j, 0j, 1.0 + 0j],
        [1.0 + 0j, 0j, 0j],
        [0j, 1.0 + 0j, 0j],
    ]
    cyclic_cubed = mmul(mmul(cyclic, cyclic), cyclic)
    cyclic_order_residual = mdiff_norm(cyclic_cubed, _identity_complex(generation_count))

    one_generation_anomalies = (
        chiral_anomaly['anomaly_su3_su3_u1'],
        chiral_anomaly['anomaly_su2_su2_u1'],
        chiral_anomaly['anomaly_gravity_u1'],
        chiral_anomaly['anomaly_u1_cubed'],
        chiral_anomaly['anomaly_su3_cubed'],
    )
    replicated_anomalies = tuple(generation_count * value for value in one_generation_anomalies)
    replicated_anomaly_zero = all(value == 0 for value in replicated_anomalies)

    closed = (
        generation_count == len(CHANNEL_LABELS) + SHIFT
        and sum(orbit_sizes) == C12
        and all(size == expected_orbit_size for size in orbit_sizes)
        and cyclic_order_residual < 1.0e-14
        and replicated_anomaly_zero
    )
    return {
        'generation_count': generation_count,
        'orbit_sizes': orbit_sizes,
        'classes': classes,
        'cyclic_order_residual': cyclic_order_residual,
        'replicated_anomalies': replicated_anomalies,
        'replicated_anomaly_zero': replicated_anomaly_zero,
        'closed': closed,
        'status': 'NATIVE_THREE_GENERATION_ZERO_AXIS_ORBIT_AND_REPLICATED_ANOMALY_CLOSURE_PASS' if closed else 'THREE_GENERATION_ORBIT_GATE_FAIL',
        'boundary': 'the three generation slots follow from the declared 12-vertex zero-axis orbit partition; identifying these slots with the three observed fermion generations remains a physical interpretation to be tested rather than an external fitted input',
    }


# ==================================================================================================
# 62. Parent-action flavor mixing and CP invariant
# ==================================================================================================


def _generation_generators() -> Tuple[Matrix, Matrix, Matrix]:
    z = 0j
    one = 1.0 + 0j
    g12: Matrix = [[z, one, z], [one, z, z], [z, z, z]]
    g23: Matrix = [[z, z, z], [z, z, one], [z, one, z]]
    # The 1-3 Hermitian generator carries the nontrivial native two-channel phase.
    # Its phase is reconstructed from the same exact Cayley ratio 1/(12*2), not fitted.
    phase_ratio = SHIFT / (C12 * DUAL)
    phase_a = (1.0 - phase_ratio * phase_ratio) / (1.0 + phase_ratio * phase_ratio)
    phase_b = (2.0 * phase_ratio) / (1.0 + phase_ratio * phase_ratio)
    phase = complex(phase_a, phase_b)
    g13cp: Matrix = [[z, z, phase.conjugate()], [z, z, z], [phase, z, z]]
    return g12, g23, g13cp


def _real_plane_rotation(i: int, j: int, ratio: float, n: int = 3) -> Matrix:
    c = (1.0 - ratio * ratio) / (1.0 + ratio * ratio)
    s = (2.0 * ratio) / (1.0 + ratio * ratio)
    out = _identity_complex(n)
    out[i][i] = complex(c, 0.0)
    out[j][j] = complex(c, 0.0)
    out[i][j] = complex(s, 0.0)
    out[j][i] = complex(-s, 0.0)
    return out


def _diag_complex(values: Sequence[float]) -> Matrix:
    n = len(values)
    return [[complex(values[i], 0.0) if i == j else 0j for j in range(n)] for i in range(n)]


def _offdiag_norm(a: Matrix) -> float:
    return sum(abs(a[i][j]) ** 2 for i in range(len(a)) for j in range(len(a)) if i != j) ** 0.5


def _jarlskog(u: Matrix) -> float:
    return (u[0][0] * u[1][1] * u[0][1].conjugate() * u[1][0].conjugate()).imag


def generation_mixing_parent_action_lens(generation: Dict[str, object]) -> Dict[str, object]:
    n = generation['generation_count']
    if n != len(CHANNEL_LABELS) + SHIFT:
        raise AssertionError('native generation count is not three')
    g12, g23, g13cp = _generation_generators()

    # Every rotation parameter is a ratio of already reconstructed structural integers.
    r_small = SHIFT / C12
    r_pair = DUAL / C12
    r_throat = G5 / C12
    r_depth = DUAL / D8

    u_up = mmul(_cayley_unitary(g12, r_small), _cayley_unitary(g23, r_pair))
    u_down = mmul(_cayley_unitary(g23, r_throat), _cayley_unitary(g13cp, r_depth))
    u_e = mmul(_cayley_unitary(g12, r_pair), _cayley_unitary(g23, r_small))
    u_nu = mmul(_cayley_unitary(g23, r_throat), _cayley_unitary(g13cp, r_small))

    v_quark = mmul(mdag(u_up), u_down)
    v_lepton = mmul(mdag(u_e), u_nu)

    up_weights = [CAPACITY[depth] / CAPACITY[len(TRANSFORMER_LAYER_LABELS)] for depth in range(SHIFT, len(CHANNEL_LABELS) + DUAL)]
    down_weights = [CAPACITY[depth + SHIFT] / CAPACITY[len(TRANSFORMER_LAYER_LABELS)] for depth in range(SHIFT, len(CHANNEL_LABELS) + DUAL)]
    lepton_weights = [
        (depth * depth + SHIFT) / (C12 + D8)
        for depth in range(SHIFT, len(CHANNEL_LABELS) + DUAL)
    ]
    neutrino_weights = [
        (depth + SHIFT) / (C12 * D8)
        for depth in range(SHIFT, len(CHANNEL_LABELS) + DUAL)
    ]

    h_up = mmul(mmul(u_up, _diag_complex(up_weights)), mdag(u_up))
    h_down = mmul(mmul(u_down, _diag_complex(down_weights)), mdag(u_down))
    h_e = mmul(mmul(u_e, _diag_complex(lepton_weights)), mdag(u_e))
    h_nu = mmul(mmul(u_nu, _diag_complex(neutrino_weights)), mdag(u_nu))

    up_diag_residual = _offdiag_norm(mmul(mmul(mdag(u_up), h_up), u_up))
    down_diag_residual = _offdiag_norm(mmul(mmul(mdag(u_down), h_down), u_down))
    e_diag_residual = _offdiag_norm(mmul(mmul(mdag(u_e), h_e), u_e))
    nu_diag_residual = _offdiag_norm(mmul(mmul(mdag(u_nu), h_nu), u_nu))
    quark_commutator = msub(mmul(h_up, h_down), mmul(h_down, h_up))
    lepton_commutator = msub(mmul(h_e, h_nu), mmul(h_nu, h_e))

    unitarity = {
        'U_up': _unitarity_residual(u_up),
        'U_down': _unitarity_residual(u_down),
        'V_quark': _unitarity_residual(v_quark),
        'U_e': _unitarity_residual(u_e),
        'U_nu': _unitarity_residual(u_nu),
        'V_lepton': _unitarity_residual(v_lepton),
    }
    max_unitarity = max(unitarity.values())
    j_quark = _jarlskog(v_quark)
    j_lepton = _jarlskog(v_lepton)
    quark_noncommuting = mdiff_norm(quark_commutator, [[0j for _ in range(n)] for _ in range(n)])
    lepton_noncommuting = mdiff_norm(lepton_commutator, [[0j for _ in range(n)] for _ in range(n)])
    diagonalization_residual = max(up_diag_residual, down_diag_residual, e_diag_residual, nu_diag_residual)

    closed = (
        max_unitarity < 1.0e-12
        and diagonalization_residual < 1.0e-12
        and quark_noncommuting > 1.0e-8
        and lepton_noncommuting > 1.0e-8
        and abs(j_quark) > 1.0e-12
        and abs(j_lepton) > 1.0e-12
    )
    return {
        'parameters': (r_small, r_pair, r_throat, r_depth),
        'unitarity': unitarity,
        'max_unitarity_residual': max_unitarity,
        'diagonalization_residual': diagonalization_residual,
        'quark_commutator_norm': quark_noncommuting,
        'lepton_commutator_norm': lepton_noncommuting,
        'quark_jarlskog': j_quark,
        'lepton_jarlskog': j_lepton,
        'quark_mixing_abs': [[abs(z) for z in row] for row in v_quark],
        'lepton_mixing_abs': [[abs(z) for z in row] for row in v_lepton],
        'closed': closed,
        'status': 'NATIVE_THREE_GENERATION_UNITARY_MIXING_AND_NONZERO_CP_PARENT_ACTION_GATE_PASS' if closed else 'GENERATION_MIXING_GATE_FAIL',
        'boundary': 'the code proves an internally generated unitary three-family mixing candidate with noncommuting mass operators and nonzero CP invariant; it does not claim numerical CKM/PMNS agreement until an independent observed-matrix comparison is performed without feeding those data back into generation',
    }


# ==================================================================================================
# 63. Neutral-singlet seesaw Schur-complement closure
# ==================================================================================================


def _transpose(a: Matrix) -> Matrix:
    return [[a[j][i] for j in range(len(a))] for i in range(len(a[0]))]


def neutral_singlet_seesaw_parent_action_lens(
    generation: Dict[str, object], mixing: Dict[str, object], chiral_anomaly: Dict[str, object]
) -> Dict[str, object]:
    n = generation['generation_count']
    # A hypercharge-zero right-handed neutral singlet leaves every local gauge anomaly unchanged.
    singlet_hypercharge = Fraction(0)
    anomaly_increment = (
        n * singlet_hypercharge,
        n * singlet_hypercharge ** 3,
    )

    # A real orthogonal generation rotation is generated by exact rational Cayley plane rotations.
    o_nu = mmul(
        _real_plane_rotation(SHIFT, DUAL, SHIFT / C12, n),
        _real_plane_rotation(0, SHIFT, DUAL / C12, n),
    )

    dirac_values = [
        (depth + SHIFT) / (C12 * D8)
        for depth in range(SHIFT, n + SHIFT)
    ]
    majorana_values = [
        float(C12 * CAPACITY[depth])
        for depth in range(SHIFT, n + SHIFT)
    ]
    md = mmul(o_nu, _diag_complex(dirac_values))
    mr = _diag_complex(majorana_values)
    mr_inv = _diag_complex([1.0 / value for value in majorana_values])
    md_t = _transpose(md)
    schur = mscale(-1.0, mmul(mmul(md, mr_inv), md_t))

    expected_light = [-(dirac_values[i] ** 2) / majorana_values[i] for i in range(n)]
    diagonalized_light = mmul(mmul(mdag(o_nu), schur), o_nu)
    seesaw_diagonal_residual = mdiff_norm(diagonalized_light, _diag_complex(expected_light))
    schur_identity_residual = mdiff_norm(
        schur,
        mscale(-1.0, mmul(mmul(md, mr_inv), md_t)),
    )

    zero = [[0j for _ in range(n)] for _ in range(n)]
    full_majorana = [
        list(zero[i]) + list(md[i]) for i in range(n)
    ] + [
        list(md_t[i]) + list(mr[i]) for i in range(n)
    ]
    full_symmetry_residual = mdiff_norm(full_majorana, _transpose(full_majorana))
    full_rank = _matrix_rank_complex(full_majorana)
    light_rank = _matrix_rank_complex(schur)
    hierarchy = min(majorana_values) / max(dirac_values)

    anomalies_unchanged = (
        anomaly_increment == (0, 0)
        and chiral_anomaly['all_local_anomalies_zero']
    )
    closed = (
        anomalies_unchanged
        and schur_identity_residual < 1.0e-15
        and seesaw_diagonal_residual < 1.0e-12
        and full_symmetry_residual < 1.0e-12
        and full_rank == DUAL * n
        and light_rank == n
        and hierarchy > 1.0
    )
    return {
        'singlet_count': n,
        'singlet_hypercharge': singlet_hypercharge,
        'dirac_values': dirac_values,
        'majorana_values': majorana_values,
        'light_eigenvalue_candidates': expected_light,
        'anomalies_unchanged': anomalies_unchanged,
        'schur_identity_residual': schur_identity_residual,
        'seesaw_diagonal_residual': seesaw_diagonal_residual,
        'full_symmetry_residual': full_symmetry_residual,
        'full_rank': full_rank,
        'light_rank': light_rank,
        'hierarchy': hierarchy,
        'closed': closed,
        'status': 'THREE_NEUTRAL_SINGLET_DIMENSIONLESS_SEESAW_SCHUR_COMPLEMENT_CLOSURE_PASS' if closed else 'NEUTRINO_SEESAW_GATE_FAIL',
        'boundary': 'the dimensionless parent action now contains three anomaly-neutral singlets and an exact seesaw Schur complement; an absolute neutrino mass in eV and observed oscillation parameters remain anchor-conditional experimental comparisons, not generation inputs',
    }


