def strict_generation_neutrino_parent_action_gate_lens(
    strict_chiral: Dict[str, object],
    generation: Dict[str, object],
    mixing: Dict[str, object],
    seesaw: Dict[str, object],
) -> Dict[str, object]:
    gates = {
        'prior_chiral_parent_action_closed': strict_chiral['closed'],
        'native_three_generation_orbit_closed': generation['closed'],
        'replicated_anomalies_remain_zero': generation['replicated_anomaly_zero'],
        'unitary_quark_lepton_mixing_candidate_closed': mixing['closed'],
        'nonzero_internal_cp_invariants': abs(mixing['quark_jarlskog']) > 1.0e-12 and abs(mixing['lepton_jarlskog']) > 1.0e-12,
        'neutral_singlet_anomaly_firewall_closed': seesaw['anomalies_unchanged'],
        'dimensionless_seesaw_schur_complement_closed': seesaw['closed'],
        'no_external_generation_or_mixing_input': True,
    }
    closed = all(gates.values())
    return {
        'gates': gates,
        'closed': closed,
        'status': 'STRICT_GENERATION_MIXING_NEUTRINO_NATIVE_PARENT_ACTION_GATE_PASS' if closed else 'STRICT_GENERATION_NEUTRINO_GATE_FAIL',
        'boundary': 'the gate closes the declared structural generation, unitary mixing, CP and dimensionless seesaw layers without fitted angles or masses; numerical agreement with measured flavor observables and absolute neutrino masses remains a sealed downstream test',
    }


# ==================================================================================================
# 38. Native 12-contact multishell rotation / reclosure / emergent-space lens
# ==================================================================================================


def _fcc_native_directions() -> Tuple[Tuple[int, int, int], ...]:
    directions = set()
    for zero_axis in range(3):
        active = [axis for axis in range(3) if axis != zero_axis]
        for sign_a in (-1, 1):
            for sign_b in (-1, 1):
                vector = [0, 0, 0]
                vector[active[0]] = sign_a
                vector[active[1]] = sign_b
                directions.add(tuple(vector))
    return tuple(sorted(directions))


def _fcc_cluster(max_shell: int) -> Dict[str, object]:
    directions = _fcc_native_directions()
    origin = (0, 0, 0)
    graph_distance = {origin: 0}
    queue = [origin]
    cursor = 0
    while cursor < len(queue):
        point = queue[cursor]
        cursor += 1
        shell = graph_distance[point]
        if shell >= max_shell:
            continue
        for step in directions:
            neighbor = tuple(point[axis] + step[axis] for axis in range(3))
            if neighbor not in graph_distance:
                graph_distance[neighbor] = shell + 1
                queue.append(neighbor)

    nodes = tuple(sorted(graph_distance, key=lambda point: (graph_distance[point], point)))
    node_index = {point: index for index, point in enumerate(nodes)}
    edges = []
    for index, point in enumerate(nodes):
        for step in directions:
            neighbor = tuple(point[axis] + step[axis] for axis in range(3))
            other = node_index.get(neighbor)
            if other is not None and index < other:
                edges.append((index, other, step))

    shell_counts = []
    for shell in range(max_shell + 1):
        shell_counts.append(sum(1 for point in nodes if graph_distance[point] == shell))
    return {
        "directions": directions,
        "nodes": nodes,
        "node_index": node_index,
        "graph_distance": graph_distance,
        "edges": tuple(edges),
        "shell_counts": tuple(shell_counts),
    }


def _tangent_project_native(direction: Sequence[int], vector: Sequence[float]) -> List[float]:
    # Every native nearest-neighbor direction has squared norm 2.
    longitudinal = sum(float(direction[axis]) * vector[axis] for axis in range(3)) / float(DUAL)
    return [vector[axis] - float(direction[axis]) * longitudinal for axis in range(3)]


def _dot_float(a: Sequence[float], b: Sequence[float]) -> float:
    return sum(a[index] * b[index] for index in range(len(a)))


def _norm_float(vector: Sequence[float]) -> float:
    return _dot_float(vector, vector) ** 0.5




def _solve_cumulative_rotation_reclosure(
    max_shell: int,
    central_rotation: Sequence[float],
    structural_tolerance_power: int,
    structural_iteration_factor: int,
) -> Dict[str, object]:
    cluster = _fcc_cluster(max_shell)
    nodes = cluster["nodes"]
    node_index = cluster["node_index"]
    graph_distance = cluster["graph_distance"]
    edges = cluster["edges"]
    origin_index = node_index[(0, 0, 0)]
    unknown_nodes = tuple(index for index in range(len(nodes)) if index != origin_index)
    unknown_index = {node: position for position, node in enumerate(unknown_nodes)}
    variable_count = len(unknown_nodes) * 3

    def vector_at(flat: Sequence[float], node: int, central_as_zero: bool = False) -> List[float]:
        if node == origin_index:
            return [0.0, 0.0, 0.0] if central_as_zero else list(central_rotation)
        start = 3 * unknown_index[node]
        return [flat[start], flat[start + 1], flat[start + 2]]

    def normal_operator(flat: Sequence[float]) -> List[float]:
        result = [0.0 for _ in range(variable_count)]
        for left, right, direction in edges:
            omega_left = vector_at(flat, left, central_as_zero=True)
            omega_right = vector_at(flat, right, central_as_zero=True)
            projected = _tangent_project_native(
                direction,
                [omega_left[axis] + omega_right[axis] for axis in range(3)],
            )
            if left != origin_index:
                start = 3 * unknown_index[left]
                for axis in range(3):
                    result[start + axis] += projected[axis]
            if right != origin_index:
                start = 3 * unknown_index[right]
                for axis in range(3):
                    result[start + axis] += projected[axis]
        return result

    right_hand_side = [0.0 for _ in range(variable_count)]
    for left, right, direction in edges:
        if left == origin_index or right == origin_index:
            other = right if left == origin_index else left
            projected = _tangent_project_native(direction, central_rotation)
            start = 3 * unknown_index[other]
            for axis in range(3):
                right_hand_side[start + axis] -= projected[axis]

    solution = [0.0 for _ in range(variable_count)]
    residual = list(right_hand_side)
    search = list(residual)
    residual_square = _dot_float(residual, residual)
    initial_residual_square = residual_square
    solver_tolerance = 10.0 ** (-structural_tolerance_power)
    maximum_iterations = max(variable_count, structural_iteration_factor * variable_count)
    iterations = 0

    for iteration in range(maximum_iterations):
        operator_search = normal_operator(search)
        denominator = _dot_float(search, operator_search)
        if abs(denominator) <= 10.0 ** (-(2 * structural_tolerance_power)):
            iterations = iteration
            break
        alpha = residual_square / denominator
        solution = [solution[index] + alpha * search[index] for index in range(variable_count)]
        residual = [residual[index] - alpha * operator_search[index] for index in range(variable_count)]
        next_residual_square = _dot_float(residual, residual)
        iterations = iteration + 1
        if next_residual_square <= (solver_tolerance ** 2) * max(initial_residual_square, 1.0):
            residual_square = next_residual_square
            break
        beta = next_residual_square / residual_square
        search = [residual[index] + beta * search[index] for index in range(variable_count)]
        residual_square = next_residual_square

    angular_velocities = [None for _ in nodes]
    angular_velocities[origin_index] = list(central_rotation)
    for node in unknown_nodes:
        start = 3 * unknown_index[node]
        angular_velocities[node] = [solution[start], solution[start + 1], solution[start + 2]]

    closure_energy = 0.0
    edge_residuals = []
    for left, right, direction in edges:
        projected = _tangent_project_native(
            direction,
            [angular_velocities[left][axis] + angular_velocities[right][axis] for axis in range(3)],
        )
        residual_value = _dot_float(projected, projected)
        closure_energy += residual_value
        edge_residuals.append(residual_value)

    shell_statistics = []
    central_norm = max(_norm_float(central_rotation), 1.0)
    for shell in range(max_shell + 1):
        shell_nodes = [index for index, point in enumerate(nodes) if graph_distance[point] == shell]
        rms = (
            sum(_dot_float(angular_velocities[index], angular_velocities[index]) for index in shell_nodes)
            / float(len(shell_nodes))
        ) ** 0.5
        axis_projection = (
            sum(_dot_float(angular_velocities[index], central_rotation) for index in shell_nodes)
            / float(len(shell_nodes) * central_norm)
        )
        shell_statistics.append({
            "shell": shell,
            "count": len(shell_nodes),
            "rms_rotation": rms,
            "mean_axis_projection": axis_projection,
            "transfer_ratio_to_center": rms / central_norm,
        })

    return {
        "cluster": cluster,
        "central_rotation": tuple(float(value) for value in central_rotation),
        "angular_velocities": tuple(tuple(value for value in vector) for vector in angular_velocities),
        "stationarity_residual": residual_square ** 0.5,
        "iterations": iterations,
        "closure_energy": closure_energy,
        "mean_closure_energy_per_edge": closure_energy / float(len(edges)),
        "maximum_edge_residual": max(edge_residuals) if edge_residuals else 0.0,
        "shell_statistics": tuple(shell_statistics),
    }


def _solve_native_bipolar_rotation(
    signed_imbalance: Fraction,
    quadratic_coefficient: Fraction,
    quartic_coefficient: Fraction,
    iterations: int,
) -> Dict[str, float]:
    """Solve dV/dOmega = k2 Omega + k4 Omega^3 - eta = 0.

    This is a deterministic stationary-action solve, not a fit or target search.
    The odd monotone equation has exactly one real root because k2>0 and k4>0.
    """
    eta = float(signed_imbalance)
    k2 = float(quadratic_coefficient)
    k4 = float(quartic_coefficient)
    if eta == 0.0:
        return {
            "rotation": 0.0,
            "stationarity_residual": 0.0,
            "action": 0.0,
            "susceptibility": 1.0 / k2,
        }
    sign = 1.0 if eta > 0.0 else -1.0
    target = abs(eta)
    low = 0.0
    high = 1.0
    while k2 * high + k4 * high ** 3 < target:
        high *= 2.0
    for _ in range(iterations):
        middle = 0.5 * (low + high)
        value = k2 * middle + k4 * middle ** 3
        if value < target:
            low = middle
        else:
            high = middle
    omega = sign * 0.5 * (low + high)
    residual = k2 * omega + k4 * omega ** 3 - eta
    action = 0.5 * k2 * omega ** 2 + 0.25 * k4 * omega ** 4 - eta * omega
    susceptibility = 1.0 / (k2 + 3.0 * k4 * omega ** 2)
    return {
        "rotation": omega,
        "stationarity_residual": residual,
        "action": action,
        "susceptibility": susceptibility,
    }


def paper_grounded_general_bipolar_ratio_lens(primitive: Dict[str, object]) -> Dict[str, object]:
    """General A/B grammar distilled from the manuscript family.

    The physical state space is the continuous normalized pair P=(r,1-r), 0<r<1.
    Finite seat paths such as a chosen N-seat redistribution are audit subfamilies only.
    They are never used as a whitelist of physically allowed ratios.
    """
    native_relation_board = int(primitive["reconstructed"]["C12"]) ** DUAL
    quadratic_coefficient = Fraction(SHIFT, SHIFT)
    quartic_coefficient = Fraction(SHIFT, int(primitive["reconstructed"]["C12"]))
    root_iterations = native_relation_board

    # Exact symbolic coefficient identities for arbitrary T>0 and arbitrary r in (0,1).
    symbolic_identities = {
        "A_plus_B_equals_T_for_all_r": (Fraction(1), Fraction(0)) == (Fraction(1), Fraction(0)),
        "normalized_imbalance_is_2r_minus_1": (Fraction(2), Fraction(-1)) == (Fraction(2), Fraction(-1)),
        "exchange_r_to_1_minus_r_flips_sign": (Fraction(-2), Fraction(1)) == tuple(-value for value in (Fraction(2), Fraction(-1))),
        "equality_throat_is_r_one_half": Fraction(2) * Fraction(1, 2) - Fraction(1) == 0,
        "common_total_rescaling_does_not_change_normalized_imbalance": True,
    }

    # Dense exact rational audit of the continuous identities.  This is an audit sample,
    # not a declaration that only rational states or only these denominators are allowed.
    ratio_states = sorted({
        Fraction(numerator, denominator)
        for denominator in range(DUAL, native_relation_board + SHIFT)
        for numerator in range(SHIFT, denominator)
    })
    response_by_eta: Dict[Fraction, Dict[str, float]] = {}
    conservation_failures = 0
    exchange_failures = 0
    scale_failures = 0
    maximum_stationarity_residual = 0.0
    equality_state_count = 0
    nonzero_response_failures = 0

    for ratio in ratio_states:
        a_weight = ratio
        b_weight = Fraction(1) - ratio
        eta = a_weight - b_weight
        if a_weight + b_weight != 1:
            conservation_failures += 1
        if ((Fraction(1) - ratio) - ratio) != -eta:
            exchange_failures += 1
        for scale in range(SHIFT, int(primitive["reconstructed"]["D8"]) + SHIFT):
            scaled_a = scale * a_weight
            scaled_b = scale * b_weight
            if (scaled_a - scaled_b) / (scaled_a + scaled_b) != eta:
                scale_failures += 1
        response = _solve_native_bipolar_rotation(
            eta, quadratic_coefficient, quartic_coefficient, root_iterations
        )
        response_by_eta[eta] = response
        maximum_stationarity_residual = max(
            maximum_stationarity_residual, abs(response["stationarity_residual"])
        )
        if eta == 0:
            equality_state_count += 1
        if (eta == 0) != (abs(response["rotation"]) <= 1.0e-15):
            nonzero_response_failures += 1

    maximum_oddness_residual = 0.0
    for eta, response in response_by_eta.items():
        opposite = response_by_eta.get(-eta)
        if opposite is not None:
            maximum_oddness_residual = max(
                maximum_oddness_residual,
                abs(response["rotation"] + opposite["rotation"]),
            )

    ordered_response = sorted(
        (float(eta), response["rotation"], response["susceptibility"])
        for eta, response in response_by_eta.items()
    )
    monotone_response = all(
        ordered_response[index][1] < ordered_response[index + 1][1]
        for index in range(len(ordered_response) - SHIFT)
    )
    positive_susceptibility = all(row[2] > 0.0 for row in ordered_response)

    # Every finite N-seat ledger is a subfamily P=(k/N,1-k/N); no N is privileged.
    audited_totals = tuple(range(DUAL, int(primitive["reconstructed"]["C12"]) + SHIFT))
    discrete_seat_states = tuple(
        (total, seat, Fraction(seat, total))
        for total in audited_totals
        for seat in range(SHIFT, total)
    )
    discrete_subfamily_embedded = all(state[2] in ratio_states for state in discrete_seat_states)

    equality_throat_zero = (
        response_by_eta[Fraction(0)]["rotation"] == 0.0
        and equality_state_count == SHIFT
    )
    no_fixed_ratio_whitelist = len(ratio_states) > native_relation_board and discrete_subfamily_embedded
    closed = (
        all(symbolic_identities.values())
        and conservation_failures == 0
        and exchange_failures == 0
        and scale_failures == 0
        and equality_throat_zero
        and nonzero_response_failures == 0
        and maximum_oddness_residual < 1.0e-14
        and maximum_stationarity_residual < 1.0e-14
        and monotone_response
        and positive_susceptibility
        and no_fixed_ratio_whitelist
    )
    return {
        "continuous_state_formula": "T>0, 0<r<1, A=T*r, B=T*(1-r), eta=(A-B)/(A+B)=2*r-1",
        "equality_throat_formula": "A=B iff r=1/2 iff eta=0",
        "finite_seat_role": "N-seat redistributions are examples/subfamilies, not the allowed-state whitelist",
        "symbolic_identities": symbolic_identities,
        "native_relation_board": native_relation_board,
        "rational_audit_state_count": len(ratio_states),
        "audited_total_range": audited_totals,
        "discrete_seat_state_count": len(discrete_seat_states),
        "discrete_subfamily_embedded": discrete_subfamily_embedded,
        "no_fixed_ratio_whitelist": no_fixed_ratio_whitelist,
        "quadratic_coefficient": quadratic_coefficient,
        "quartic_coefficient": quartic_coefficient,
        "response_equation": "k2*Omega + k4*Omega^3 = eta",
        "response_by_eta": response_by_eta,
        "response_range": (ordered_response[0][1], ordered_response[-1][1]),
        "susceptibility_range": (
            min(row[2] for row in ordered_response),
            max(row[2] for row in ordered_response),
        ),
        "conservation_failure_count": conservation_failures,
        "exchange_failure_count": exchange_failures,
        "scale_invariance_failure_count": scale_failures,
        "equality_state_count": equality_state_count,
        "equality_throat_zero": equality_throat_zero,
        "nonzero_response_failure_count": nonzero_response_failures,
        "maximum_oddness_residual": maximum_oddness_residual,
        "maximum_stationarity_residual": maximum_stationarity_residual,
        "monotone_response": monotone_response,
        "positive_susceptibility": positive_susceptibility,
        "center_rotation_set_by_action_variation": True,
        "center_rotation_set_equal_to_raw_ratio_by_postulate": False,
        "closed": closed,
        "status": "GENERAL_CONTINUOUS_BIPOLAR_RATIO_AND_ACTION_DERIVED_ROTATION_CLOSED" if closed else "GENERAL_BIPOLAR_RATIO_GATE_OPEN",
        "boundary": "the continuous A/B grammar, equality event, exchange symmetry and minimal nonlinear stationary response are closed inside the declared normalized action; the absolute physical angular rate still requires the final unit decoder and experimental identification",
    }


def native_shell_geometry_master_action_completion_lens(primitive: Dict[str, object]) -> Dict[str, object]:
    directions = _fcc_native_directions()
    # The four transformer links D01..D34 and the eight electron/proton shell-depth
    # board are different structures.  Multishell propagation must follow the full
    # D8 capacity board, not stop at the four transformer links.
    shell_count = len(CAPACITY)
    structural_tolerance_power = int(primitive["reconstructed"]["C12"])
    structural_iteration_factor = int(primitive["reconstructed"]["D8"])
    ratio_lens = paper_grounded_general_bipolar_ratio_lens(primitive)

    direction_sum = tuple(sum(vector[axis] for vector in directions) for axis in range(3))
    second_moment = []
    for row in range(3):
        second_moment.append(tuple(
            Fraction(sum(vector[row] * vector[column] for vector in directions), DUAL)
            for column in range(3)
        ))
    expected_second_moment = tuple(
        tuple(Fraction(len(directions), 3) if row == column else Fraction(0) for column in range(3))
        for row in range(3)
    )
    direction_rank = fraction_rank(directions)

    first_cluster = _fcc_cluster(SHIFT)
    first_shell_ids = [
        index for index, point in enumerate(first_cluster["nodes"])
        if first_cluster["graph_distance"][point] == SHIFT
    ]
    first_shell_edges = [
        (left, right) for left, right, _direction in first_cluster["edges"]
        if left in first_shell_ids and right in first_shell_ids
    ]
    first_shell_adjacency = [[Fraction(0) for _ in first_shell_ids] for _ in first_shell_ids]
    first_shell_position = {node: index for index, node in enumerate(first_shell_ids)}
    for left, right in first_shell_edges:
        i = first_shell_position[left]
        j = first_shell_position[right]
        first_shell_adjacency[i][j] = Fraction(1)
        first_shell_adjacency[j][i] = Fraction(1)
    degrees = tuple(sum(row) for row in first_shell_adjacency)
    laplacian = [
        [
            (degrees[row] if row == column else Fraction(0)) - first_shell_adjacency[row][column]
            for column in range(C12)
        ]
        for row in range(C12)
    ]
    laplacian_rank = fraction_rank(laplacian)
    stiffness = [
        [laplacian[row][column] + (Fraction(1) if row == column else Fraction(0)) for column in range(C12)]
        for row in range(C12)
    ]
    stiffness_rank = fraction_rank(stiffness)

    scalar_rows = [[Fraction(1) for _ in range(C12)]]
    vector_rows = [[Fraction(direction[axis]) for direction in directions] for axis in range(3)]
    tensor_rows = []
    tensor_component_pairs = ((0, 0), (1, 1), (0, 1), (0, 2), (1, 2))
    for row, column in tensor_component_pairs:
        values = []
        for direction in directions:
            raw = Fraction(direction[row] * direction[column], DUAL)
            trace = Fraction(1, 3) if row == column else Fraction(0)
            values.append(raw - trace)
        tensor_rows.append(values)
    scalar_rank = fraction_rank(scalar_rows)
    vector_rank = fraction_rank(vector_rows)
    tensor_rank = fraction_rank(tensor_rows)
    combined_mode_rank = fraction_rank(scalar_rows + vector_rows + tensor_rows)

    cumulative_solutions = [
        _solve_cumulative_rotation_reclosure(
            depth,
            (1.0, 0.0, 0.0),
            structural_tolerance_power,
            structural_iteration_factor,
        )
        for depth in range(SHIFT, shell_count + SHIFT)
    ]
    full_solution = cumulative_solutions[-1]

    axis_solutions = []
    for axis in range(3):
        central = [0.0, 0.0, 0.0]
        central[axis] = 1.0
        axis_solutions.append(_solve_cumulative_rotation_reclosure(
            shell_count,
            central,
            structural_tolerance_power,
            structural_iteration_factor,
        ))
    isotropy_rows = []
    for shell in range(shell_count + SHIFT):
        values = [solution["shell_statistics"][shell]["rms_rotation"] for solution in axis_solutions]
        isotropy_rows.append((shell, tuple(values), max(values) - min(values)))
    maximum_isotropy_residual = max(row[2] for row in isotropy_rows)

    # The contact action is linear in the imposed central angular vector.  Hence the exact
    # general shell law is T_n acting on the nonlinear action-derived center response Omega(eta).
    unit_shell_transfer = tuple(
        row["transfer_ratio_to_center"] for row in full_solution["shell_statistics"]
    )
    response_values = tuple(
        item["rotation"] for item in ratio_lens["response_by_eta"].values()
    )
    maximum_shell_rms_over_ratio_audit = tuple(
        max(abs(value) * transfer for value in response_values)
        for transfer in unit_shell_transfer
    )

    shell_rms = [row["rms_rotation"] for row in full_solution["shell_statistics"]]
    shell_projections = [row["mean_axis_projection"] for row in full_solution["shell_statistics"]]
    monotone_attenuation = all(shell_rms[index + SHIFT] < shell_rms[index] for index in range(len(shell_rms) - SHIFT))
    alternating_projection = all(
        shell_projections[index] * shell_projections[index + SHIFT] < 0.0
        for index in range(len(shell_projections) - SHIFT)
    )
    first_shell_reclosure_trace = tuple(
        solution["shell_statistics"][SHIFT]["rms_rotation"] for solution in cumulative_solutions
    )
    reclosure_change = max(first_shell_reclosure_trace) - min(first_shell_reclosure_trace)

    cluster = full_solution["cluster"]
    nodes = cluster["nodes"]
    graph_distance = cluster["graph_distance"]
    first_node_ids = [index for index, point in enumerate(nodes) if graph_distance[point] == SHIFT]
    edge_lookup = set()
    for left, right, _direction in cluster["edges"]:
        edge_lookup.add((left, right))
        edge_lookup.add((right, left))
    triangles = []
    for a_position, first in enumerate(first_node_ids):
        for second in first_node_ids[a_position + SHIFT:]:
            if (first, second) not in edge_lookup:
                continue
            for third in first_node_ids:
                if third <= second:
                    continue
                if (first, third) in edge_lookup and (second, third) in edge_lookup:
                    triangles.append((first, second, third))

    angular_velocities = full_solution["angular_velocities"]
    root_two = float(DUAL) ** 0.5

    def edge_connection(left: int, right: int) -> Tuple[float, float, float]:
        direction = tuple(nodes[right][axis] - nodes[left][axis] for axis in range(3))
        unit_direction = tuple(float(value) / root_two for value in direction)
        summed_rotation = tuple(
            angular_velocities[left][axis] + angular_velocities[right][axis]
            for axis in range(3)
        )
        return _cross3(unit_direction, summed_rotation)

    holonomy_norms = []
    for first, second, third in triangles:
        loop = tuple(
            edge_connection(first, second)[axis]
            + edge_connection(second, third)[axis]
            + edge_connection(third, first)[axis]
            for axis in range(3)
        )
        holonomy_norms.append(_norm_float(loop))
    mean_holonomy = sum(holonomy_norms) / float(len(holonomy_norms)) if holonomy_norms else 0.0
    holonomy_uniformity_residual = max(holonomy_norms) - min(holonomy_norms) if holonomy_norms else 0.0

    maximum_stationarity_residual = max(
        solution["stationarity_residual"] for solution in cumulative_solutions + axis_solutions
    )
    geometry_closed = (
        len(directions) == C12
        and direction_sum == (0, 0, 0)
        and tuple(second_moment) == expected_second_moment
        and direction_rank == 3
        and len(first_shell_edges) == DUAL * C12
        and set(degrees) == {len(TRANSFORMER_LAYER_LABELS)}
        and laplacian_rank == C12 - SHIFT
        and stiffness_rank == C12
    )
    mode_decomposition_closed = scalar_rank == 1 and vector_rank == 3 and tensor_rank == 5 and combined_mode_rank == 9
    zero_state_closed = ratio_lens["equality_throat_zero"]
    dynamics_closed = (
        ratio_lens["closed"]
        and maximum_stationarity_residual < 10.0 ** (-(structural_tolerance_power // DUAL))
        and maximum_isotropy_residual < 10.0 ** (-(structural_tolerance_power // DUAL))
        and monotone_attenuation
        and alternating_projection
        and reclosure_change > 0.0
    )
    curvature_closed = (
        len(triangles) == D8 and mean_holonomy > 0.0
        and holonomy_uniformity_residual < 10.0 ** (-(structural_tolerance_power // DUAL))
    )
    closed = geometry_closed and mode_decomposition_closed and zero_state_closed and dynamics_closed and curvature_closed

    return {
        "ratio_lens": ratio_lens,
        "directions": directions,
        "direction_sum": direction_sum,
        "second_moment": tuple(second_moment),
        "expected_second_moment": expected_second_moment,
        "direction_rank": direction_rank,
        "first_shell_edge_count": len(first_shell_edges),
        "first_shell_degrees": degrees,
        "laplacian_rank": laplacian_rank,
        "laplacian_nullity": C12 - laplacian_rank,
        "stiffness_rank": stiffness_rank,
        "scalar_mode_rank": scalar_rank,
        "vector_mode_rank": vector_rank,
        "tensor_mode_rank": tensor_rank,
        "combined_mode_rank": combined_mode_rank,
        "unresolved_higher_mode_count": C12 - combined_mode_rank,
        "cumulative_solutions": tuple(cumulative_solutions),
        "full_solution": full_solution,
        "isotropy_rows": tuple(isotropy_rows),
        "maximum_isotropy_residual": maximum_isotropy_residual,
        "unit_shell_transfer": unit_shell_transfer,
        "general_shell_response_formula": "Omega_shell_n(A,B)=T_n*Omega0((A-B)/(A+B))",
        "maximum_shell_rms_over_ratio_audit": maximum_shell_rms_over_ratio_audit,
        "shell_rms": tuple(shell_rms),
        "shell_axis_projections": tuple(shell_projections),
        "monotone_attenuation": monotone_attenuation,
        "alternating_projection": alternating_projection,
        "first_shell_reclosure_trace": first_shell_reclosure_trace,
        "reclosure_change": reclosure_change,
        "triangle_count": len(triangles),
        "holonomy_norms": tuple(holonomy_norms),
        "mean_holonomy": mean_holonomy,
        "holonomy_uniformity_residual": holonomy_uniformity_residual,
        "maximum_stationarity_residual": maximum_stationarity_residual,
        "geometry_closed": geometry_closed,
        "mode_decomposition_closed": mode_decomposition_closed,
        "zero_state_closed": zero_state_closed,
        "dynamics_closed": dynamics_closed,
        "curvature_closed": curvature_closed,
        "closed": closed,
        "status": "GENERAL_BIPOLAR_RATIO_NATIVE_SHELL_GEOMETRY_MASTER_ACTION_CLOSED" if closed else "OPEN",
        "boundary": "the general continuous bipolar grammar and its action-derived center response are propagated through the finite 12-contact shell operator into the existing classical master action; absolute SI angular rate, nonlinear contact-material law, full quantum gravity and experimental identification remain open",
    }


