def _pearson_correlation_native(values_a: Sequence[float], values_b: Sequence[float]) -> float:
    if len(values_a) != len(values_b) or not values_a:
        raise ValueError("correlation vectors must have equal nonzero length")
    mean_a = sum(values_a) / float(len(values_a))
    mean_b = sum(values_b) / float(len(values_b))
    centered_a = [value - mean_a for value in values_a]
    centered_b = [value - mean_b for value in values_b]
    numerator = sum(centered_a[index] * centered_b[index] for index in range(len(values_a)))
    denominator_a = sum(value * value for value in centered_a) ** 0.5
    denominator_b = sum(value * value for value in centered_b) ** 0.5
    if denominator_a == 0.0 or denominator_b == 0.0:
        return 0.0
    return numerator / (denominator_a * denominator_b)


def _native_electron_shell_occupancy(atomic_number: int) -> Tuple[int, ...]:
    if atomic_number < 0 or atomic_number > sum(CAPACITY.values()):
        raise ValueError("atomic number lies outside the native eight-shell capacity board")
    remaining = atomic_number
    occupancy = []
    for depth in range(SHIFT, D8 + SHIFT):
        fill = min(CAPACITY[depth], remaining)
        occupancy.append(fill)
        remaining -= fill
    return tuple(occupancy)


def eight_shell_electron_rotation_link_lens(
    primitive: Dict[str, object],
    shell_lens: Dict[str, object],
) -> Dict[str, object]:
    """Connect the full D8 shell transfer operator to the native electron board.

    The geometry transfer coefficient is not declared to be an observed electron
    energy.  It is combined with the paper's capacity, radius-ratio and d^4
    curvature grammar to produce explicit dimensionless structural burden
    candidates.  Occupancy feedback into the contact operator remains OPEN until
    a unique coupling term is derived from the parent action.
    """
    electron_shell_count = len(CAPACITY)
    transformer_layer_count = int(primitive["transformer_layer_count"])
    full_solution = shell_lens["full_solution"]
    shell_statistics = full_solution["shell_statistics"]
    capacities = tuple(CAPACITY[depth] for depth in range(SHIFT, D8 + SHIFT))
    geometric_counts = tuple(
        shell_statistics[depth]["count"] for depth in range(SHIFT, D8 + SHIFT)
    )
    transfers = tuple(
        shell_statistics[depth]["transfer_ratio_to_center"] for depth in range(SHIFT, D8 + SHIFT)
    )
    signed_projections = tuple(
        shell_statistics[depth]["mean_axis_projection"] for depth in range(SHIFT, D8 + SHIFT)
    )

    rows = []
    for depth in range(SHIFT, D8 + SHIFT):
        index = depth - SHIFT
        transfer = transfers[index]
        transfer_square = transfer * transfer
        electron_radius_square_factor = depth * depth
        proton_depth_curvature_factor = depth ** len(TRANSFORMER_LAYER_LABELS)
        per_electron_outward_rotational_burden = electron_radius_square_factor * transfer_square
        capacity_total_outward_rotational_burden = capacities[index] * per_electron_outward_rotational_burden
        per_paired_depth_curvature_burden = proton_depth_curvature_factor * transfer_square
        capacity_total_depth_curvature_burden = capacities[index] * per_paired_depth_curvature_burden
        rows.append({
            "depth": depth,
            "electron_capacity": capacities[index],
            "geometric_js_shell_count": geometric_counts[index],
            "unit_center_transfer_rms": transfer,
            "mean_axis_projection": signed_projections[index],
            "electron_radius_square_factor": electron_radius_square_factor,
            "proton_depth_curvature_factor": proton_depth_curvature_factor,
            "capacity_weighted_amplitude_load": capacities[index] * abs(transfer),
            "per_electron_outward_rotational_burden_candidate": per_electron_outward_rotational_burden,
            "capacity_total_outward_rotational_burden_candidate": capacity_total_outward_rotational_burden,
            "per_paired_depth_curvature_burden_candidate": per_paired_depth_curvature_burden,
            "capacity_total_depth_curvature_burden_candidate": capacity_total_depth_curvature_burden,
        })

    mirror_rows = []
    for depth in range(SHIFT, len(TRANSFORMER_LAYER_LABELS) + SHIFT):
        mirror = D8 + SHIFT - depth
        inner = rows[depth - SHIFT]
        outer = rows[mirror - SHIFT]
        mirror_rows.append({
            "depth_pair": (depth, mirror),
            "equal_capacity": inner["electron_capacity"] == outer["electron_capacity"],
            "capacity": inner["electron_capacity"],
            "transfer_ratio_inner_over_outer": (
                inner["unit_center_transfer_rms"] / outer["unit_center_transfer_rms"]
                if outer["unit_center_transfer_rms"] != 0.0 else float("inf")
            ),
            "outward_burden_ratio_inner_over_outer": (
                inner["per_electron_outward_rotational_burden_candidate"]
                / outer["per_electron_outward_rotational_burden_candidate"]
                if outer["per_electron_outward_rotational_burden_candidate"] != 0.0 else float("inf")
            ),
            "curvature_burden_ratio_inner_over_outer": (
                inner["per_paired_depth_curvature_burden_candidate"]
                / outer["per_paired_depth_curvature_burden_candidate"]
                if outer["per_paired_depth_curvature_burden_candidate"] != 0.0 else float("inf")
            ),
        })

    occupancy_audit_failures = 0
    for atomic_number in range(SHIFT, sum(capacities) + SHIFT):
        occupancy = _native_electron_shell_occupancy(atomic_number)
        if sum(occupancy) != atomic_number:
            occupancy_audit_failures += SHIFT
        if any(occupancy[index] > capacities[index] for index in range(D8)):
            occupancy_audit_failures += SHIFT

    selected_atomic_numbers = (SHIFT, DUAL, TOTAL, 18, 54, 86, 118, 119, 120)
    occupancy_rows = []
    for atomic_number in selected_atomic_numbers:
        occupancy = _native_electron_shell_occupancy(atomic_number)
        outward_total = sum(
            occupancy[index] * rows[index]["per_electron_outward_rotational_burden_candidate"]
            for index in range(D8)
        )
        curvature_total = sum(
            occupancy[index] * rows[index]["per_paired_depth_curvature_burden_candidate"]
            for index in range(D8)
        )
        occupancy_rows.append({
            "atomic_number": atomic_number,
            "occupancy": occupancy,
            "outward_rotational_burden_candidate": outward_total,
            "depth_curvature_burden_candidate": curvature_total,
        })

    occupancy_118 = _native_electron_shell_occupancy(118)
    occupancy_119 = _native_electron_shell_occupancy(119)
    occupancy_120 = _native_electron_shell_occupancy(120)
    endpoint_119_120_increment_outward = rows[-1]["per_electron_outward_rotational_burden_candidate"]
    endpoint_119_120_increment_curvature = rows[-1]["per_paired_depth_curvature_burden_candidate"]

    first_shell_trace = shell_lens["first_shell_reclosure_trace"]
    final_first_shell_value = first_shell_trace[-1]
    first_shell_convergence_to_eight = tuple(
        abs(value - final_first_shell_value) / final_first_shell_value
        for value in first_shell_trace
    )

    depth_values = [float(depth) for depth in range(SHIFT, D8 + SHIFT)]
    capacity_values = [float(value) for value in capacities]
    transfer_values = [float(value) for value in transfers]
    capacity_transfer_correlation = _pearson_correlation_native(capacity_values, transfer_values)
    depth_transfer_correlation = _pearson_correlation_native(depth_values, transfer_values)

    mirror_capacity_closed = all(row["equal_capacity"] for row in mirror_rows)
    mirror_transfer_asymmetric = all(
        abs(rows[depth - SHIFT]["unit_center_transfer_rms"] - rows[D8 - depth]["unit_center_transfer_rms"]) > 1.0e-18
        for depth in range(SHIFT, len(TRANSFORMER_LAYER_LABELS) + SHIFT)
    )
    all_eight_transfers_nonzero = all(value > 0.0 for value in transfers)
    geometric_counts_distinct_from_electron_capacity = all(
        geometric_counts[index] != capacities[index] for index in range(D8)
    )
    endpoint_occupancy_closed = (
        occupancy_118 == tuple(capacities[:-1]) + (0,)
        and occupancy_119 == tuple(capacities[:-1]) + (SHIFT,)
        and occupancy_120 == capacities
    )
    structural_closed = (
        transformer_layer_count == len(TRANSFORMER_LAYER_LABELS)
        and electron_shell_count == D8
        and len(shell_statistics) == D8 + SHIFT
        and capacities == tuple(_CAPACITY_SEQUENCE)
        and sum(capacities) == 120
        and sum(capacities[:-1]) == 118
        and mirror_capacity_closed
        and mirror_transfer_asymmetric
        and all_eight_transfers_nonzero
        and geometric_counts_distinct_from_electron_capacity
        and occupancy_audit_failures == 0
        and endpoint_occupancy_closed
        and len(first_shell_trace) == D8
    )

    return {
        "transformer_layer_count": transformer_layer_count,
        "electron_shell_count": electron_shell_count,
        "capacity_sequence": capacities,
        "capacity_total": sum(capacities),
        "closed_through_shell_seven": sum(capacities[:-1]),
        "geometric_shell_counts": geometric_counts,
        "shell_rows": tuple(rows),
        "mirror_rows": tuple(mirror_rows),
        "mirror_capacity_closed": mirror_capacity_closed,
        "mirror_transfer_asymmetric": mirror_transfer_asymmetric,
        "geometric_counts_distinct_from_electron_capacity": geometric_counts_distinct_from_electron_capacity,
        "all_eight_transfers_nonzero": all_eight_transfers_nonzero,
        "occupancy_rows": tuple(occupancy_rows),
        "occupancy_audit_failure_count": occupancy_audit_failures,
        "occupancy_118": occupancy_118,
        "occupancy_119": occupancy_119,
        "occupancy_120": occupancy_120,
        "endpoint_occupancy_closed": endpoint_occupancy_closed,
        "endpoint_119_120_increment_outward_candidate": endpoint_119_120_increment_outward,
        "endpoint_119_120_increment_curvature_candidate": endpoint_119_120_increment_curvature,
        "capacity_transfer_pearson": capacity_transfer_correlation,
        "depth_transfer_pearson": depth_transfer_correlation,
        "first_shell_reclosure_trace_to_eight": first_shell_trace,
        "first_shell_relative_distance_from_eight_shell_closure": first_shell_convergence_to_eight,
        "structural_energy_formula": "per_electron_outward=d^2*T_d^2; per_paired_depth_curvature=d^4*T_d^2; totals multiply by occupancy N_d",
        "general_ratio_shell_formula": shell_lens["general_shell_response_formula"],
        "structural_closed": structural_closed,
        "occupancy_backreaction_to_contact_operator_closed": False,
        "absolute_electron_energy_claim": False,
        "status": (
            "EIGHT_SHELL_ELECTRON_CAPACITY_ROTATION_STRUCTURAL_LINK_CLOSED_OCCUPANCY_BACKREACTION_OPEN"
            if structural_closed else "EIGHT_SHELL_ELECTRON_ROTATION_STRUCTURAL_LINK_FAIL"
        ),
        "boundary": "the full eight-shell transfer, capacity, mirror pairing, native occupancy and dimensionless d^2/d^4 burden candidates are computed without measured electron energies; a unique occupation-dependent feedback term in the contact operator and absolute energy calibration remain open",
    }



