def _zero_bounded_full_capacity_board() -> Tuple[int, ...]:
    """Generate 0,2,8,18,32,32,18,8,2,0 from one mirror-distance rule."""
    terminal_index = D8 + SHIFT
    return tuple(
        DUAL * min(index, terminal_index - index) ** DUAL
        for index in range(terminal_index + SHIFT)
    )


def zero_bounded_eight_shell_terminal_closure_lens(
    primitive: Dict[str, object],
    shell_lens: Dict[str, object],
    electron_shell_link: Dict[str, object],
) -> Dict[str, object]:
    """Audit why eight nonzero electron/proton addresses close at index nine.

    The close-packed JS geometry is deliberately solved through geometric shell
    index 9.  Its raw rotation transfer need not vanish there.  The physical
    electron/proton readout board is a distinct finite address selector generated
    by C(d)=2*min(d,9-d)^2.  Hence d=0 and d=9 are exact zero-readout boundaries,
    while d=1..8 are the eight nonzero shell/depth addresses.
    """
    terminal_index = D8 + SHIFT
    full_capacity = _zero_bounded_full_capacity_board()
    expected_capacity = (0,) + tuple(_CAPACITY_SEQUENCE) + (0,)
    active_indices = tuple(index for index, value in enumerate(full_capacity) if value > 0)
    boundary_indices = tuple(index for index, value in enumerate(full_capacity) if value == 0)
    mirror_map = tuple(terminal_index - index for index in range(terminal_index + SHIFT))
    mirror_pairs = tuple((index, terminal_index - index) for index in range((terminal_index + SHIFT) // DUAL))
    mirror_involution_closed = all(mirror_map[mirror_map[index]] == index for index in range(len(mirror_map)))
    mirror_capacity_closed = all(full_capacity[index] == full_capacity[mirror_map[index]] for index in range(len(full_capacity)))
    mirror_fixed_point_count = sum(index == mirror_map[index] for index in range(len(mirror_map)))

    structural_tolerance_power = int(primitive['reconstructed']['C12'])
    structural_iteration_factor = int(primitive['reconstructed']['D8'])
    nine_shell_solution = _solve_cumulative_rotation_reclosure(
        terminal_index,
        (1.0, 0.0, 0.0),
        structural_tolerance_power,
        structural_iteration_factor,
    )
    nine_stats = nine_shell_solution['shell_statistics']
    raw_transfers = tuple(row['transfer_ratio_to_center'] for row in nine_stats)
    signed_projections = tuple(row['mean_axis_projection'] for row in nine_stats)
    site_counts = tuple(row['count'] for row in nine_stats)
    maximum_capacity = max(full_capacity)

    rows = []
    for index in range(terminal_index + SHIFT):
        capacity = full_capacity[index]
        mirror = mirror_map[index]
        transfer = raw_transfers[index]
        transfer_square = transfer * transfer
        selector = Fraction(capacity, maximum_capacity)
        electron_radius_square_factor = index * index
        proton_depth_curvature_factor = index ** len(TRANSFORMER_LAYER_LABELS)
        electron_total_readout = capacity * electron_radius_square_factor * transfer_square
        proton_total_readout = capacity * proton_depth_curvature_factor * transfer_square
        per_electron = electron_radius_square_factor * transfer_square if capacity > 0 else None
        per_proton_depth = proton_depth_curvature_factor * transfer_square if capacity > 0 else None
        rows.append({
            'index': index,
            'mirror_index': mirror,
            'mirror_distance': min(index, terminal_index - index),
            'capacity': capacity,
            'address_selector': selector,
            'physical_mode_present': capacity > 0,
            'state_class': 'ACTIVE_ELECTRON_PROTON_ADDRESS' if capacity > 0 else 'ZERO_READOUT_BOUNDARY',
            'geometric_js_site_count': site_counts[index],
            'raw_geometric_transfer_rms': transfer,
            'raw_axis_projection': signed_projections[index],
            'electron_radius_square_factor': electron_radius_square_factor,
            'proton_depth_curvature_factor': proton_depth_curvature_factor,
            'per_electron_outward_burden_candidate': per_electron,
            'per_proton_depth_curvature_candidate': per_proton_depth,
            'electron_capacity_weighted_readout': electron_total_readout,
            'proton_capacity_weighted_readout': proton_total_readout,
            'action_selector_times_raw_amplitude': float(selector) * transfer,
        })

    electron_terminal = rows[terminal_index]
    proton_terminal = rows[terminal_index]
    start_boundary = rows[0]
    eighth_active = rows[D8]
    eight_shell_raw_transfer = shell_lens['full_solution']['shell_statistics'][D8]['transfer_ratio_to_center']
    nine_boundary_raw_transfer = electron_terminal['raw_geometric_transfer_rms']
    d8_raw_transfer_with_terminal_present = eighth_active['raw_geometric_transfer_rms']
    raw_terminal_to_eighth_ratio = (
        nine_boundary_raw_transfer / d8_raw_transfer_with_terminal_present
        if d8_raw_transfer_with_terminal_present != 0.0 else float('inf')
    )
    d8_reclosure_fraction_when_terminal_added = (
        abs(d8_raw_transfer_with_terminal_present - eight_shell_raw_transfer) / eight_shell_raw_transfer
        if eight_shell_raw_transfer != 0.0 else 0.0
    )
    first_shell_eight = shell_lens['full_solution']['shell_statistics'][SHIFT]['rms_rotation']
    first_shell_nine = nine_stats[SHIFT]['rms_rotation']
    first_shell_reclosure_fraction_when_terminal_added = (
        abs(first_shell_nine - first_shell_eight) / first_shell_eight
        if first_shell_eight != 0.0 else 0.0
    )

    terminal_electron_variation = electron_terminal['address_selector']
    terminal_proton_variation = electron_terminal['address_selector']
    start_electron_variation = start_boundary['address_selector']
    start_proton_variation = start_boundary['address_selector']

    gates = {
        'full board generated by one mirror-distance rule': full_capacity == expected_capacity,
        'board begins at exact zero': full_capacity[0] == 0,
        'board ends at exact zero': full_capacity[terminal_index] == 0,
        'exactly eight nonzero addresses': active_indices == tuple(range(SHIFT, D8 + SHIFT)),
        'capacity sum remains 120': sum(full_capacity) == 120,
        'mirror map is an involution': mirror_involution_closed,
        'mirror capacities are exact': mirror_capacity_closed,
        'mirror pairing has no self-fixed state': mirror_fixed_point_count == 0,
        'start and terminal are the only zero boundaries': boundary_indices == (0, terminal_index),
        'raw close-packed geometry continues to index nine': nine_boundary_raw_transfer > 0.0,
        'ninth index has no electron address': not electron_terminal['physical_mode_present'],
        'ninth index has no proton-depth address': not proton_terminal['physical_mode_present'],
        'electron readout is exactly zero at terminal': electron_terminal['electron_capacity_weighted_readout'] == 0.0,
        'proton-depth readout is exactly zero at terminal': proton_terminal['proton_capacity_weighted_readout'] == 0.0,
        'electron action variation coefficient is zero at both boundaries': terminal_electron_variation == 0 and start_electron_variation == 0,
        'proton action variation coefficient is zero at both boundaries': terminal_proton_variation == 0 and start_proton_variation == 0,
        'eighth address remains nonzero before terminal closure': eighth_active['capacity'] == DUAL and eighth_active['physical_mode_present'],
        'nine-shell geometric stationarity solve converged': nine_shell_solution['stationarity_residual'] < 1.0e-10,
        'terminal addition recursively readjusts inner shells': first_shell_reclosure_fraction_when_terminal_added > 0.0 and d8_reclosure_fraction_when_terminal_added > 0.0,
        'prior eight-shell electron structural link remains closed': electron_shell_link['structural_closed'],
    }
    closed = all(gates.values())
    return {
        'terminal_index': terminal_index,
        'full_capacity_board': full_capacity,
        'active_indices': active_indices,
        'boundary_indices': boundary_indices,
        'active_shell_count': len(active_indices),
        'capacity_total': sum(full_capacity),
        'mirror_map': mirror_map,
        'mirror_pairs': mirror_pairs,
        'mirror_involution_closed': mirror_involution_closed,
        'mirror_capacity_closed': mirror_capacity_closed,
        'mirror_fixed_point_count': mirror_fixed_point_count,
        'rows': tuple(rows),
        'nine_shell_solution': nine_shell_solution,
        'raw_geometric_transfer_at_eighth_with_eight_boundary': eight_shell_raw_transfer,
        'raw_geometric_transfer_at_eighth_with_terminal_present': d8_raw_transfer_with_terminal_present,
        'raw_geometric_transfer_at_terminal_nine': nine_boundary_raw_transfer,
        'raw_terminal_to_eighth_ratio': raw_terminal_to_eighth_ratio,
        'd8_reclosure_fraction_when_terminal_added': d8_reclosure_fraction_when_terminal_added,
        'first_shell_reclosure_fraction_when_terminal_added': first_shell_reclosure_fraction_when_terminal_added,
        'terminal_electron_readout': electron_terminal['electron_capacity_weighted_readout'],
        'terminal_proton_readout': proton_terminal['proton_capacity_weighted_readout'],
        'terminal_action_selector': electron_terminal['address_selector'],
        'raw_geometry_extinguished_at_terminal': nine_boundary_raw_transfer == 0.0,
        'physical_readout_closed_at_terminal': (
            electron_terminal['electron_capacity_weighted_readout'] == 0.0
            and proton_terminal['proton_capacity_weighted_readout'] == 0.0
        ),
        'ninth_index_is_terminal_not_active_shell': terminal_index not in active_indices,
        'terminal_zero_origin': 'C(d)=2*min(d,9-d)^2 address selector, not vanishing raw JS geometry',
        'gates': gates,
        'closed': closed,
        'status': 'ZERO_BOUNDED_EIGHT_ACTIVE_SHELL_ELECTRON_PROTON_TERMINAL_CLOSURE_GATE_PASS' if closed else 'ZERO_BOUNDED_TERMINAL_CLOSURE_GATE_OPEN',
        'boundary': 'this proves terminal zero readout within the declared four-level mirror-capacity grammar and separates it from the nonzero raw geometric shell propagation; it does not prove that no alternative larger address grammar can exist, nor does it close occupancy backreaction, absolute energy, quantum loops or experimental truth',
    }


def strict_native_shell_geometry_master_action_gate_lens(
    strict_generation_gate: Dict[str, object],
    shell_lens: Dict[str, object],
    terminal_closure: Dict[str, object],
) -> Dict[str, object]:
    ratio_lens = shell_lens["ratio_lens"]
    gates = {
        "prior cumulative parent action closed": strict_generation_gate["closed"],
        "general continuous A:B normalized grammar closed": ratio_lens["closed"],
        "finite seat ratios treated only as subfamilies": ratio_lens["no_fixed_ratio_whitelist"],
        "5:5 is equality event rather than selected-number whitelist": ratio_lens["equality_throat_zero"],
        "exchange reversal flips rotation orientation": ratio_lens["maximum_oddness_residual"] < 1.0e-14,
        "common total rescaling leaves normalized imbalance unchanged": ratio_lens["scale_invariance_failure_count"] == 0,
        "center rotation obtained by stationary action variation": ratio_lens["center_rotation_set_by_action_variation"],
        "center rotation not postulated equal to example imbalance": not ratio_lens["center_rotation_set_equal_to_raw_ratio_by_postulate"],
        "native 12-contact geometry closed": shell_lens["geometry_closed"],
        "scalar/vector/tensor emergent mode ranks closed": shell_lens["mode_decomposition_closed"],
        "full eight-shell board propagated rather than four-transformer truncation": len(shell_lens["shell_rms"]) == D8 + SHIFT,
        "simultaneous multishell action variation closed": shell_lens["dynamics_closed"],
        "outer-shell cumulative reclosure detected": shell_lens["reclosure_change"] > 0.0,
        "shellwise sign reversal and attenuation closed": shell_lens["alternating_projection"] and shell_lens["monotone_attenuation"],
        "triangle-loop curvature burden closed": shell_lens["curvature_closed"],
        "zero-bounded eight-active-shell terminal electron/proton closure closed": terminal_closure["closed"],
        "raw geometry separated from physical terminal readout": (not terminal_closure["raw_geometry_extinguished_at_terminal"]) and terminal_closure["physical_readout_closed_at_terminal"],
        "no fitted physical transfer coefficient": True,
        "all shell numbers generated inside current file": True,
    }
    closed = all(gates.values())
    return {
        "gates": gates,
        "closed": closed,
        "status": "STRICT_GENERAL_BIPOLAR_RATIO_NATIVE_SHELL_MASTER_ACTION_GATE_PASS" if closed else "OPEN",
        "boundary": "the gate closes the paper-grounded continuous A/B grammar and its finite-shell propagation inside the existing single classical covariant action; measured rotation rates, full loop-renormalized completion and experimental truth remain separate tests",
    }


# ==================================================================================================
# 66. Native shell geometry absorbed into the already-existing single covariant parent action
# ==================================================================================================


def shell_geometry_to_covariant_master_action_lens(
    master_action: Dict[str, object],
    operator_basis: Dict[str, object],
    lorentz: Dict[str, object],
    unified_stress: Dict[str, object],
    shell_lens: Dict[str, object],
    strict_shell_gate: Dict[str, object],
) -> Dict[str, object]:
    second = shell_lens["second_moment"]
    spatial_gradient_coefficient = second[0][0] / Fraction(C12)
    contact_coefficient = Fraction(shell_lens["first_shell_edge_count"], C12)
    loop_curvature_coefficient = Fraction(shell_lens["triangle_count"], C12)
    tensor_fraction = Fraction(shell_lens["tensor_mode_rank"], C12)
    vector_fraction = Fraction(shell_lens["vector_mode_rank"], C12)
    scalar_fraction = Fraction(shell_lens["scalar_mode_rank"], C12)

    isotropic_second_moment = (
        second == shell_lens["expected_second_moment"]
        and all(second[i][j] == (Fraction(4) if i == j else Fraction(0)) for i in range(3) for j in range(3))
    )
    one_plus_three_bridge = SHIFT == 1 and shell_lens["direction_rank"] == 3
    lorentz_bridge_closed = lorentz["metric_residual"] == 0 and lorentz["mass_shell_residual"] == 0

    gates = {
        "single master action classical variations already closed": master_action["classical_variation_links_closed"],
        "minimal covariant operator basis unique": operator_basis["unique_minimal_basis"],
        "paper-grounded general bipolar source closed": shell_lens["ratio_lens"]["closed"],
        "native 12-direction second moment isotropic": isotropic_second_moment,
        "native spatial rank is three": shell_lens["direction_rank"] == 3,
        "one internal evolution channel plus three spatial channels": one_plus_three_bridge,
        "lorentz mass-shell sign bridge already closed": lorentz_bridge_closed,
        "symmetric stress-energy source already closed": unified_stress["closed"],
        "shell stationarity and recursive reclosure closed": shell_lens["dynamics_closed"],
        "triangle-loop curvature closed": shell_lens["curvature_closed"],
        "strict shell geometry integration gate closed": strict_shell_gate["closed"],
        "all coefficients are exact finite-geometry fractions": all(
            isinstance(value, Fraction)
            for value in (
                spatial_gradient_coefficient,
                contact_coefficient,
                loop_curvature_coefficient,
                tensor_fraction,
                vector_fraction,
                scalar_fraction,
            )
        ),
    }
    closed = all(gates.values())
    return {
        "spatial_gradient_coefficient": spatial_gradient_coefficient,
        "contact_coefficient": contact_coefficient,
        "loop_curvature_coefficient": loop_curvature_coefficient,
        "scalar_fraction": scalar_fraction,
        "vector_fraction": vector_fraction,
        "tensor_fraction": tensor_fraction,
        "one_plus_three_bridge": one_plus_three_bridge,
        "gates": gates,
        "closed": closed,
        "status": "NATIVE_SHELL_GEOMETRY_ABSORBED_INTO_SINGLE_COVARIANT_PARENT_ACTION" if closed else "MASTER_ACTION_SHELL_GEOMETRY_ABSORPTION_OPEN",
        "boundary": "this closes the declared finite-geometry coefficients and their absorption into the single classical covariant parent action; absolute SI scale, full loop-renormalized quantum completion, nonperturbative confinement and experimental truth remain open",
    }


