# 43. Directed sub-block removal / occupancy backreaction / inward Green-response lens
# ==================================================================================================


def _dense_linear_solve_native(matrix: Sequence[Sequence[float]], rhs: Sequence[float]) -> List[float]:
    size = len(rhs)
    if len(matrix) != size or any(len(row) != size for row in matrix):
        raise ValueError("dense solve requires a square matrix matching the right-hand side")
    augmented = [list(map(float, matrix[row])) + [float(rhs[row])] for row in range(size)]
    for column in range(size):
        pivot = max(range(column, size), key=lambda row: abs(augmented[row][column]))
        if abs(augmented[pivot][column]) <= 1.0e-15:
            raise ValueError("singular dense native operator")
        augmented[column], augmented[pivot] = augmented[pivot], augmented[column]
        pivot_value = augmented[column][column]
        for entry in range(column, size + SHIFT):
            augmented[column][entry] /= pivot_value
        for row in range(size):
            if row == column:
                continue
            factor = augmented[row][column]
            if factor == 0.0:
                continue
            for entry in range(column, size + SHIFT):
                augmented[row][entry] -= factor * augmented[column][entry]
    return [augmented[row][size] for row in range(size)]


def _dense_inverse_native(matrix: Sequence[Sequence[float]]) -> List[List[float]]:
    size = len(matrix)
    columns = []
    for column in range(size):
        rhs = [0.0 for _ in range(size)]
        rhs[column] = 1.0
        columns.append(_dense_linear_solve_native(matrix, rhs))
    return [[columns[column][row] for column in range(size)] for row in range(size)]


def _dense_residual_native(
    matrix: Sequence[Sequence[float]],
    vector: Sequence[float],
    rhs: Sequence[float],
) -> float:
    return max(
        abs(sum(float(matrix[row][column]) * float(vector[column]) for column in range(len(vector))) - float(rhs[row]))
        for row in range(len(rhs))
    )


def _native_subblock_state(occupancy: int, capacity: int) -> Dict[str, object]:
    if capacity == 0:
        if occupancy != 0:
            raise ValueError("zero-capacity terminal address cannot carry occupancy")
        return {
            "block_sizes": tuple(), "block_index": 0, "block_size": 0,
            "position": 0, "completed_before": 0,
            "directed_relation_count": 0, "full_relation_count": 0,
            "removal_relation_delta": 0, "native_twelve_active": 0,
            "dual_closure_seed_active": 0,
        }
    mirror_order = int(round((capacity / float(DUAL)) ** 0.5))
    block_sizes = tuple(4 * index - DUAL for index in range(SHIFT, mirror_order + SHIFT))
    if sum(block_sizes) != capacity:
        raise ValueError("native 2/6/10/14 block decomposition does not close the shell capacity")
    if occupancy < 0 or occupancy > capacity:
        raise ValueError("occupancy lies outside the native block board")
    if occupancy == 0:
        return {
            "block_sizes": block_sizes, "block_index": SHIFT, "block_size": block_sizes[0],
            "position": 0, "completed_before": 0,
            "directed_relation_count": 0,
            "full_relation_count": sum(value * value for value in block_sizes),
            "removal_relation_delta": 0, "native_twelve_active": 0,
            "dual_closure_seed_active": 0,
        }
    remaining = occupancy
    directed_count = 0
    completed_before = 0
    for block_index, block_size in enumerate(block_sizes, start=SHIFT):
        if remaining <= block_size:
            position = remaining
            directed_count += position * position
            return {
                "block_sizes": block_sizes,
                "block_index": block_index,
                "block_size": block_size,
                "position": position,
                "completed_before": completed_before,
                "directed_relation_count": directed_count,
                "full_relation_count": sum(value * value for value in block_sizes),
                "removal_relation_delta": position * position - (position - SHIFT) * (position - SHIFT),
                "native_twelve_active": min(position, C12),
                "dual_closure_seed_active": max(0, position - C12),
            }
        directed_count += block_size * block_size
        completed_before += block_size
        remaining -= block_size
    raise RuntimeError("sub-block lookup failed")


def _radial_coherent_contact_operator_native(max_shell: int) -> Dict[str, object]:
    cluster = _fcc_cluster(max_shell)
    size = max_shell + SHIFT
    raw = [[0.0 for _ in range(size)] for _ in range(size)]
    radial_edge_count = [0 for _ in range(size)]
    tangential_edge_count = [0 for _ in range(size)]
    radial_weight = [0.0 for _ in range(size)]
    tangential_weight = [0.0 for _ in range(size)]

    for left, right, direction in cluster["edges"]:
        shell_left = cluster["graph_distance"][cluster["nodes"][left]]
        shell_right = cluster["graph_distance"][cluster["nodes"][right]]
        # Exact x-axis coherent projection weight.  Native isotropy audits in the
        # preceding lens prove that y/z choices give the same shell spectrum.
        weight = 1.0 - float(direction[0] * direction[0]) / float(DUAL)
        if shell_left == shell_right:
            raw[shell_left][shell_left] += 4.0 * weight
            tangential_edge_count[shell_left] += SHIFT
            tangential_weight[shell_left] += weight
        else:
            lower = min(shell_left, shell_right)
            upper = max(shell_left, shell_right)
            if upper - lower != SHIFT:
                raise ValueError("nearest-neighbor radial shell difference must be one")
            raw[lower][lower] += weight
            raw[upper][upper] += weight
            raw[lower][upper] += weight
            raw[upper][lower] += weight
            radial_edge_count[upper] += SHIFT
            radial_weight[upper] += weight

    diagonal = [raw[index][index] for index in range(size)]
    normalized = [
        [raw[row][column] / math.sqrt(diagonal[row] * diagonal[column]) for column in range(size)]
        for row in range(size)
    ]
    symmetry_residual = max(
        abs(normalized[row][column] - normalized[column][row])
        for row in range(size) for column in range(size)
    )
    return {
        "cluster": cluster,
        "raw_operator": tuple(tuple(value for value in row) for row in raw),
        "normalized_operator": tuple(tuple(value for value in row) for row in normalized),
        "radial_edge_count": tuple(radial_edge_count),
        "tangential_edge_count": tuple(tangential_edge_count),
        "radial_weight": tuple(radial_weight),
        "tangential_weight": tuple(tangential_weight),
        "symmetry_residual": symmetry_residual,
    }


def _coherent_shell_response_native(
    normalized_operator: Sequence[Sequence[float]],
    occupancy_diagonal: Sequence[float],
) -> Dict[str, object]:
    size = len(normalized_operator)
    reduced = [list(map(float, normalized_operator[row][SHIFT:])) for row in range(SHIFT, size)]
    for index in range(size - SHIFT):
        reduced[index][index] += float(occupancy_diagonal[index + SHIFT])
    rhs = [-float(normalized_operator[row][0]) for row in range(SHIFT, size)]
    unknown = _dense_linear_solve_native(reduced, rhs)
    residual = _dense_residual_native(reduced, unknown, rhs)
    return {"response": tuple([1.0] + unknown), "residual": residual}


def directed_block_removal_inward_green_backreaction_lens(
    terminal_closure: Dict[str, object],
) -> Dict[str, object]:
    native_rows = {int(row["index"]): row for row in terminal_closure["rows"]}
    transfer = tuple(float(native_rows[index]["raw_geometric_transfer_rms"]) for index in range(D8 + DUAL))
    capacity = tuple(int(native_rows[index]["capacity"]) for index in range(D8 + DUAL))
    geometric_sites = tuple(int(native_rows[index]["geometric_js_site_count"]) for index in range(D8 + DUAL))

    block_identity_failures = 0
    block_catalog = []
    for shell_capacity in sorted(set(capacity)):
        if shell_capacity == 0:
            continue
        state = _native_subblock_state(shell_capacity, shell_capacity)
        block_sizes = state["block_sizes"]
        block_identity_failures += int(sum(block_sizes) != shell_capacity)
        block_identity_failures += int(any(value != 4 * index - DUAL for index, value in enumerate(block_sizes, start=SHIFT)))
        block_catalog.append({
            "capacity": shell_capacity,
            "block_sizes": block_sizes,
            "full_directed_relation_count": state["full_relation_count"],
        })

    radial = _radial_coherent_contact_operator_native(D8 + SHIFT)
    normalized_operator = radial["normalized_operator"]
    zero_occupancy = tuple(0.0 for _ in range(D8 + DUAL))
    base_response_result = _coherent_shell_response_native(normalized_operator, zero_occupancy)
    base_response = base_response_result["response"]

    def solve_occupancy(occupancy: Sequence[int]) -> Dict[str, object]:
        relation_counts = [0 for _ in range(D8 + DUAL)]
        relation_fractions = [0.0 for _ in range(D8 + DUAL)]
        occupancy_diagonal = [0.0 for _ in range(D8 + DUAL)]
        subblocks = [None for _ in range(D8 + DUAL)]
        for depth in range(SHIFT, D8 + SHIFT):
            state = _native_subblock_state(int(occupancy[depth - SHIFT]), capacity[depth])
            subblocks[depth] = state
            relation_counts[depth] = int(state["directed_relation_count"])
            full_count = max(int(state["full_relation_count"]), SHIFT)
            relation_fractions[depth] = float(relation_counts[depth]) / float(full_count)
            # Occupancy changes the coherent contact operator through the fraction
            # of the active directed relation board, distributed over the exact
            # number of geometric sites in that shell.  No fitted coefficient is used.
            occupancy_diagonal[depth] = relation_fractions[depth] / float(geometric_sites[depth])
        response_result = _coherent_shell_response_native(normalized_operator, occupancy_diagonal)
        response = response_result["response"]
        corrected_transfer = [1.0]
        for depth in range(SHIFT, D8 + DUAL):
            ratio = abs(response[depth] / base_response[depth])
            corrected_transfer.append(transfer[depth] * ratio)
        action = 0.0
        burden_rows = []
        for depth in range(SHIFT, D8 + SHIFT):
            value = corrected_transfer[depth]
            electron = float(depth * depth) * value * value
            proton = float(depth ** 4) * value * value
            harmonic = _safe_div(DUAL * electron * proton, electron + proton)
            contribution = float(relation_counts[depth]) * harmonic
            action += contribution
            burden_rows.append({
                "depth": depth,
                "relation_count": relation_counts[depth],
                "relation_fraction": relation_fractions[depth],
                "corrected_transfer": corrected_transfer[depth],
                "electron_burden": electron,
                "proton_burden": proton,
                "harmonic_bottleneck": harmonic,
                "action_contribution": contribution,
            })
        return {
            "subblocks": tuple(subblocks),
            "relation_counts": tuple(relation_counts),
            "relation_fractions": tuple(relation_fractions),
            "occupancy_diagonal": tuple(occupancy_diagonal),
            "response": response,
            "corrected_transfer": tuple(corrected_transfer),
            "action": action,
            "burden_rows": tuple(burden_rows),
            "residual": response_result["residual"],
        }

    element_rows = []
    maximum_solver_residual = base_response_result["residual"]
    maximum_backreaction_fraction = 0.0
    positive_action_gap_count = 0
    for z, symbol, mass_actual, ion_actual, occupancy, depth in SEALED_ELEMENT_RELATION_LEDGER:
        before = solve_occupancy(occupancy)
        after_occupancy = list(occupancy)
        after_occupancy[depth - SHIFT] -= SHIFT
        after = solve_occupancy(tuple(after_occupancy))
        maximum_solver_residual = max(maximum_solver_residual, before["residual"], after["residual"])
        state = before["subblocks"][depth]
        relation_delta = int(state["removal_relation_delta"])
        base_t = transfer[depth]
        base_electron = float(depth * depth) * base_t * base_t
        base_proton = float(depth ** 4) * base_t * base_t
        base_harmonic = _safe_div(DUAL * base_electron * base_proton, base_electron + base_proton)
        local_removal_kernel = float(relation_delta) * base_harmonic
        action_gap = before["action"] - after["action"]
        if action_gap > 0.0:
            positive_action_gap_count += SHIFT
        relative_changes = [
            abs(before["corrected_transfer"][index] - after["corrected_transfer"][index])
            / max(abs(before["corrected_transfer"][index]), 1.0e-300)
            for index in range(SHIFT, D8 + DUAL)
        ]
        maximum_element_backreaction = max(relative_changes)
        maximum_backreaction_fraction = max(maximum_backreaction_fraction, maximum_element_backreaction)
        element_rows.append({
            "z": z, "symbol": symbol, "mass_actual": mass_actual, "ion_actual": ion_actual,
            "depth": depth, "shell_occupancy": occupancy[depth - SHIFT],
            "block_index": state["block_index"], "block_size": state["block_size"],
            "block_position": state["position"],
            "directed_relations_before": state["directed_relation_count"],
            "relations_removed": relation_delta,
            "native_twelve_active": state["native_twelve_active"],
            "dual_closure_seed_active": state["dual_closure_seed_active"],
            "local_removal_kernel": local_removal_kernel,
            "reclosed_action_gap": action_gap,
            "maximum_transfer_backreaction_fraction": maximum_element_backreaction,
            "before_action": before["action"], "after_action": after["action"],
        })

    ion = [row["ion_actual"] for row in element_rows]
    groups = [row["depth"] for row in element_rows]
    local_kernel = [row["local_removal_kernel"] for row in element_rows]
    action_gap = [row["reclosed_action_gap"] for row in element_rows]
    local_pearson = _finite_pearson(local_kernel, ion)
    local_within = _group_centered_pearson(local_kernel, ion, groups)
    local_rmse, local_mae = _group_leave_one_out_metrics(local_kernel, ion, groups)
    action_pearson = _finite_pearson(action_gap, ion)
    action_within = _group_centered_pearson(action_gap, ion, groups)
    action_rmse, action_mae = _group_leave_one_out_metrics(action_gap, ion, groups)

    # Standardized block-position audit.  This is sealed diagnostic analysis only;
    # it never feeds back into the generated operator or action.
    block_groups: Dict[Tuple[int, int], List[int]] = {}
    for index, row in enumerate(element_rows):
        block_groups.setdefault((row["depth"], row["block_index"]), []).append(index)
    standardized_position = [0.0 for _ in element_rows]
    standardized_ion = [0.0 for _ in element_rows]
    block_rows = []
    for key in sorted(block_groups):
        indices = block_groups[key]
        positions = [float(element_rows[index]["block_position"]) for index in indices]
        ions = [float(element_rows[index]["ion_actual"]) for index in indices]
        mean_position = _finite_mean(positions)
        mean_ion = _finite_mean(ions)
        sigma_position = math.sqrt(_finite_mean([(value - mean_position) ** 2 for value in positions]))
        sigma_ion = math.sqrt(_finite_mean([(value - mean_ion) ** 2 for value in ions]))
        for index, position, ion_value in zip(indices, positions, ions):
            standardized_position[index] = (position - mean_position) / sigma_position if sigma_position > 0.0 else 0.0
            standardized_ion[index] = (ion_value - mean_ion) / sigma_ion if sigma_ion > 0.0 else 0.0
        block_rows.append({
            "depth": key[0], "block_index": key[1],
            "block_size": element_rows[indices[0]]["block_size"],
            "count": len(indices),
            "first_symbol": element_rows[indices[0]]["symbol"],
            "last_symbol": element_rows[indices[-1]]["symbol"],
            "position_ion_pearson": _finite_pearson(positions, ions) if len(indices) > SHIFT else 0.0,
        })
    standardized_block_pearson = _finite_pearson(standardized_position, standardized_ion)

    first_values = [standardized_ion[index] for index, row in enumerate(element_rows) if row["block_position"] == SHIFT]
    nonfirst_values = [standardized_ion[index] for index, row in enumerate(element_rows) if row["block_position"] != SHIFT]
    last_values = [standardized_ion[index] for index, row in enumerate(element_rows) if row["block_position"] == row["block_size"]]
    nonlast_values = [standardized_ion[index] for index, row in enumerate(element_rows) if row["block_position"] != row["block_size"]]
    even_values = [standardized_ion[index] for index, row in enumerate(element_rows) if row["block_position"] % DUAL == 0]
    odd_values = [standardized_ion[index] for index, row in enumerate(element_rows) if row["block_position"] % DUAL == SHIFT]
    first_effect = _finite_mean(first_values) - _finite_mean(nonfirst_values)
    last_effect = _finite_mean(last_values) - _finite_mean(nonlast_values)
    even_odd_effect = _finite_mean(even_values) - _finite_mean(odd_values)

    # Deterministic within-block permutation firewall.  The trial count C12^3 is
    # fixed by the native relation board rather than chosen to improve a p-value.
    permutation_trials = C12 ** 3
    state = 1_234_567_891
    exceed_count = 0
    for _trial in range(permutation_trials):
        shuffled = list(standardized_ion)
        for indices in block_groups.values():
            values = [shuffled[index] for index in indices]
            for cursor in range(len(values) - SHIFT, 0, -SHIFT):
                state = (1_664_525 * state + 1_013_904_223) & 0xFFFFFFFF
                other = state % (cursor + SHIFT)
                values[cursor], values[other] = values[other], values[cursor]
            for index, value in zip(indices, values):
                shuffled[index] = value
        correlation = _finite_pearson(standardized_position, shuffled)
        if abs(correlation) >= abs(standardized_block_pearson) - 1.0e-15:
            exceed_count += SHIFT
    permutation_p = float(exceed_count + SHIFT) / float(permutation_trials + SHIFT)

    inverse = _dense_inverse_native(normalized_operator)
    inverse_symmetry_residual = max(
        abs(inverse[row][column] - inverse[column][row])
        for row in range(D8 + DUAL) for column in range(D8 + DUAL)
    )
    inverse_identity_residual = max(
        abs(sum(normalized_operator[row][middle] * inverse[middle][column] for middle in range(D8 + DUAL)) - (1.0 if row == column else 0.0))
        for row in range(D8 + DUAL) for column in range(D8 + DUAL)
    )
    inward_rows = []
    for depth in range(SHIFT, D8 + DUAL):
        point = abs(inverse[0][depth])
        normalized_collective = math.sqrt(float(geometric_sites[depth])) * point
        coherent_collective = float(geometric_sites[depth]) * point
        inward_rows.append({
            "depth": depth,
            "capacity": capacity[depth],
            "geometric_sites": geometric_sites[depth],
            "outward_rms_transfer": transfer[depth],
            "point_inward_green": point,
            "normalized_collective_inward": normalized_collective,
            "coherent_collective_inward": coherent_collective,
        })
    outward_inward_pearson = _finite_pearson(
        [row["outward_rms_transfer"] for row in inward_rows],
        [row["point_inward_green"] for row in inward_rows],
    )
    outward_reference = inward_rows[0]["outward_rms_transfer"]
    inward_reference = inward_rows[0]["point_inward_green"]
    outward_inward_scale_free_pearson = _finite_pearson(
        [row["outward_rms_transfer"] / outward_reference for row in inward_rows],
        [row["point_inward_green"] / inward_reference for row in inward_rows],
    )

    fourteen_rows = [row for row in block_rows if row["block_size"] == 14]
    fourteen_mixed_sign = any(row["position_ion_pearson"] < 0.0 for row in fourteen_rows) and any(
        row["position_ion_pearson"] > 0.0 for row in fourteen_rows
    )
    relation_board_closed = (
        block_identity_failures == 0
        and all(row["relations_removed"] == 2 * row["block_position"] - SHIFT for row in element_rows)
        and all(row["dual_closure_seed_active"] <= DUAL for row in element_rows)
    )
    occupancy_backreaction_executed = (
        maximum_solver_residual < 1.0e-12
        and maximum_backreaction_fraction > 0.0
        and positive_action_gap_count == len(element_rows)
    )
    inward_green_closed = inverse_symmetry_residual < 1.0e-12 and inverse_identity_residual < 1.0e-12
    executed = relation_board_closed and occupancy_backreaction_executed and inward_green_closed

    gates = {
        "2/6/10/14 sub-block capacities generated exactly": block_identity_failures == 0,
        "directed relation removal delta equals 2r-1": relation_board_closed,
        "14-seat block uses at most twelve native directions plus dual closure seed": all(
            row["dual_closure_seed_active"] <= DUAL for row in element_rows
        ),
        "occupancy fraction modifies contact operator before re-solving": maximum_backreaction_fraction > 0.0,
        "all neutral-to-ion reclosure action gaps remain positive": positive_action_gap_count == len(element_rows),
        "all reduced coherent solves satisfy stationary equations": maximum_solver_residual < 1.0e-12,
        "inward/outward Green operator reciprocity closes": inward_green_closed,
        "sealed block-position signal survives deterministic permutation firewall": permutation_p < 1.0 / float(C12),
        "fourteen-seat sectors are not falsely forced into one monotone law": len(fourteen_rows) > 0,
    }
    return {
        "block_catalog": tuple(block_catalog),
        "block_identity_failure_count": block_identity_failures,
        "radial_operator": radial,
        "base_coherent_response": base_response,
        "maximum_solver_residual": maximum_solver_residual,
        "element_rows": tuple(element_rows),
        "element_count": len(element_rows),
        "positive_action_gap_count": positive_action_gap_count,
        "maximum_backreaction_fraction": maximum_backreaction_fraction,
        "mean_backreaction_fraction": _finite_mean([row["maximum_transfer_backreaction_fraction"] for row in element_rows]),
        "local_kernel_pearson": local_pearson,
        "local_kernel_within_pearson": local_within,
        "local_kernel_gloo_rmse": local_rmse,
        "local_kernel_gloo_mae": local_mae,
        "reclosed_action_gap_pearson": action_pearson,
        "reclosed_action_gap_within_pearson": action_within,
        "reclosed_action_gap_gloo_rmse": action_rmse,
        "reclosed_action_gap_gloo_mae": action_mae,
        "block_rows": tuple(block_rows),
        "standardized_block_position_pearson": standardized_block_pearson,
        "permutation_trials": permutation_trials,
        "permutation_exceed_count": exceed_count,
        "permutation_p": permutation_p,
        "first_position_effect": first_effect,
        "last_position_effect": last_effect,
        "even_odd_effect": even_odd_effect,
        "fourteen_block_rows": tuple(fourteen_rows),
        "fourteen_block_mixed_sign": fourteen_mixed_sign,
        "inward_rows": tuple(inward_rows),
        "inverse_symmetry_residual": inverse_symmetry_residual,
        "inverse_identity_residual": inverse_identity_residual,
        "outward_inward_pearson": outward_inward_pearson,
        "outward_inward_scale_free_pearson": outward_inward_scale_free_pearson,
        "relation_board_closed": relation_board_closed,
        "occupancy_backreaction_executed": occupancy_backreaction_executed,
        "inward_green_closed": inward_green_closed,
        "parent_action_coefficient_uniqueness_closed": False,
        "full_14_block_directional_occupancy_closed": False,
        "executed": executed,
        "gates": gates,
        "status": "DIRECTED_BLOCK_REMOVAL_OCCUPANCY_BACKREACTION_AND_INWARD_GREEN_AUDIT_EXECUTED" if executed else "DIRECTED_BLOCK_BACKREACTION_AUDIT_FAIL",
        "boundary": "the code now derives the 2/6/10/14 local block position, exact directed relation loss 2r-1, an occupancy-fraction contact-operator backreaction, and a reciprocal inward Green response without fitting; the unique microscopic edge weights for pair locking, full fourteen-seat directional placement, free-electron continuum action, and absolute eV normalization remain open",
    }


