def _fraction_matrix_multiply_native(
    left: Sequence[Sequence[Fraction]],
    right: Sequence[Sequence[Fraction]],
) -> List[List[Fraction]]:
    return [
        [
            sum((left[row][middle] * right[middle][column] for middle in range(len(right))), Fraction(0))
            for column in range(len(right[0]))
        ]
        for row in range(len(left))
    ]


def _fraction_matrix_vector_native(
    matrix: Sequence[Sequence[Fraction]],
    vector: Sequence[Fraction],
) -> List[Fraction]:
    return [
        sum((matrix[row][column] * vector[column] for column in range(len(vector))), Fraction(0))
        for row in range(len(matrix))
    ]


def _fraction_transpose_vector_native(
    matrix: Sequence[Sequence[Fraction]],
    vector: Sequence[Fraction],
) -> List[Fraction]:
    return [
        sum((matrix[row][column] * vector[row] for row in range(len(matrix))), Fraction(0))
        for column in range(len(matrix[0]))
    ]


def _native_cuboctahedral_vertex_edge_face_complex() -> Dict[str, object]:
    vertices = tuple(sorted(_fcc_native_directions()))
    vertex_index = {vertex: index for index, vertex in enumerate(vertices)}

    edges = []
    for left in range(len(vertices)):
        for right in range(left + SHIFT, len(vertices)):
            distance_square = sum(
                (vertices[left][axis] - vertices[right][axis]) ** DUAL
                for axis in range(3)
            )
            if distance_square == DUAL:
                edges.append((left, right))
    edges = tuple(edges)
    edge_index = {edge: index for index, edge in enumerate(edges)}

    faces = []
    # Eight triangular faces: one for each signed octant normal.
    for sx in (-SHIFT, SHIFT):
        for sy in (-SHIFT, SHIFT):
            for sz in (-SHIFT, SHIFT):
                normal = (sx, sy, sz)
                face_vertices = tuple(
                    index for index, vertex in enumerate(vertices)
                    if sum(normal[axis] * vertex[axis] for axis in range(3)) == DUAL
                )
                faces.append({"type": "triangle", "normal": normal, "vertices": face_vertices})
    # Six square faces: one for each signed Cartesian-axis normal.
    for axis in range(3):
        for sign in (-SHIFT, SHIFT):
            normal_list = [0, 0, 0]
            normal_list[axis] = sign
            normal = tuple(normal_list)
            face_vertices = tuple(
                index for index, vertex in enumerate(vertices)
                if vertex[axis] == sign
            )
            faces.append({"type": "square", "normal": normal, "vertices": face_vertices})

    def face_cycle(face_vertices: Sequence[int]) -> Tuple[int, ...]:
        allowed = set(face_vertices)
        start = min(allowed)

        def search(path: List[int]) -> Tuple[int, ...] | None:
            if len(path) == len(allowed):
                if tuple(sorted((path[-SHIFT], path[0]))) in edge_index:
                    return tuple(path)
                return None
            current = path[-SHIFT]
            for candidate in sorted(allowed.difference(path)):
                if tuple(sorted((current, candidate))) in edge_index:
                    found = search(path + [candidate])
                    if found is not None:
                        return found
            return None

        cycle = search([start])
        if cycle is None:
            raise RuntimeError("native face cycle construction failed")
        return cycle

    oriented_faces = []
    face_edge_sets = []
    for face in faces:
        cycle = face_cycle(face["vertices"])
        edge_set = set()
        for left, right in zip(cycle, cycle[SHIFT:] + cycle[:SHIFT]):
            edge_set.add(edge_index[tuple(sorted((left, right)))])
        oriented_faces.append({**face, "cycle": cycle})
        face_edge_sets.append(frozenset(edge_set))
    faces = tuple(oriented_faces)

    vertex_edge_incidence = [
        [Fraction(0) for _ in vertices]
        for _ in edges
    ]
    for edge_id, (left, right) in enumerate(edges):
        vertex_edge_incidence[edge_id][left] = Fraction(-SHIFT)
        vertex_edge_incidence[edge_id][right] = Fraction(SHIFT)

    face_edge_incidence = [
        [Fraction(0) for _ in edges]
        for _ in faces
    ]
    for face_id, face in enumerate(faces):
        cycle = face["cycle"]
        for left, right in zip(cycle, cycle[SHIFT:] + cycle[:SHIFT]):
            undirected = tuple(sorted((left, right)))
            edge_id = edge_index[undirected]
            face_edge_incidence[face_id][edge_id] = Fraction(SHIFT if (left, right) == edges[edge_id] else -SHIFT)

    boundary_of_boundary = _fraction_matrix_multiply_native(
        face_edge_incidence,
        vertex_edge_incidence,
    )
    boundary_of_boundary_maximum = max(
        abs(value) for row in boundary_of_boundary for value in row
    )

    face_adjacency = [[0 for _ in faces] for _ in faces]
    for left in range(len(faces)):
        for right in range(left + SHIFT, len(faces)):
            if face_edge_sets[left].intersection(face_edge_sets[right]):
                face_adjacency[left][right] = SHIFT
                face_adjacency[right][left] = SHIFT

    triangle_indices = tuple(index for index, face in enumerate(faces) if face["type"] == "triangle")
    square_indices = tuple(index for index, face in enumerate(faces) if face["type"] == "square")
    face_degrees = tuple(sum(row) for row in face_adjacency)

    normal_to_face = {face["normal"]: index for index, face in enumerate(faces)}

    def canonical_axis(normal: Tuple[int, int, int]) -> Tuple[int, int, int]:
        for component in normal:
            if component != 0:
                return normal if component > 0 else tuple(-value for value in normal)
        raise RuntimeError("zero face normal is forbidden")

    unoriented_axes = sorted({canonical_axis(face["normal"]) for face in faces})
    opposite_pairs = tuple(
        (normal_to_face[axis], normal_to_face[tuple(-value for value in axis)])
        for axis in unoriented_axes
    )

    # A geometry-only canonical adjacency walk.  It is an audit ordering, not a fitted filling law.
    unvisited = set(range(len(faces)))
    topology_walk = []
    current = None
    while unvisited:
        if current is None:
            chosen = min(unvisited)
        else:
            neighbors = [index for index in unvisited if face_adjacency[current][index] == SHIFT]
            chosen = min(
                neighbors,
                key=lambda index: (faces[index]["type"], faces[index]["normal"], index),
            ) if neighbors else min(unvisited)
        topology_walk.append(chosen)
        unvisited.remove(chosen)
        current = chosen

    normal_pair_walk = []
    for axis in sorted(unoriented_axes):
        normal_pair_walk.extend((normal_to_face[axis], normal_to_face[tuple(-value for value in axis)]))

    return {
        "vertices": vertices,
        "vertex_index": vertex_index,
        "edges": edges,
        "edge_index": edge_index,
        "faces": faces,
        "face_edge_sets": tuple(face_edge_sets),
        "face_adjacency": tuple(tuple(value for value in row) for row in face_adjacency),
        "triangle_indices": triangle_indices,
        "square_indices": square_indices,
        "face_degrees": face_degrees,
        "unoriented_axes": tuple(unoriented_axes),
        "opposite_pairs": opposite_pairs,
        "vertex_edge_incidence": tuple(tuple(value for value in row) for row in vertex_edge_incidence),
        "face_edge_incidence": tuple(tuple(value for value in row) for row in face_edge_incidence),
        "boundary_of_boundary_maximum": boundary_of_boundary_maximum,
        "topology_walk": tuple(topology_walk),
        "normal_pair_walk": tuple(normal_pair_walk),
    }


def vertex_edge_face_dual_holonomy_parent_action_lens(
    occupancy_action: Dict[str, object],
) -> Dict[str, object]:
    complex_data = _native_cuboctahedral_vertex_edge_face_complex()
    vertices = complex_data["vertices"]
    edges = complex_data["edges"]
    faces = complex_data["faces"]
    b1 = complex_data["vertex_edge_incidence"]
    b2 = complex_data["face_edge_incidence"]

    vertex_count = len(vertices)
    edge_count = len(edges)
    face_count = len(faces)
    triangle_count = len(complex_data["triangle_indices"])
    square_count = len(complex_data["square_indices"])
    euler_characteristic = vertex_count - edge_count + face_count
    b1_rank = fraction_rank(b1)
    b2_rank = fraction_rank(b2)
    cycle_rank = edge_count - vertex_count + SHIFT
    independent_face_curvature_count = face_count - SHIFT

    mode_names = (
        "scalar_1",
        "quadrupole_x2_minus_y2", "quadrupole_2z2_minus_x2_minus_y2",
        "quadrupole_xy", "quadrupole_yz", "quadrupole_zx",
        "vector_x", "vector_y", "vector_z",
        "cubic_x_y2_minus_z2", "cubic_y_z2_minus_x2", "cubic_z_x2_minus_y2",
    )
    mode_rows = []
    for x, y, z in vertices:
        mode_rows.append((
            Fraction(SHIFT),
            Fraction(x * x - y * y),
            Fraction(DUAL * z * z - x * x - y * y),
            Fraction(x * y), Fraction(y * z), Fraction(z * x),
            Fraction(x), Fraction(y), Fraction(z),
            Fraction(x * (y * y - z * z)),
            Fraction(y * (z * z - x * x)),
            Fraction(z * (x * x - y * y)),
        ))
    mode_rank = fraction_rank(mode_rows)
    block_ranges = {
        "scalar": (0, 1),
        "symmetric_traceless_tensor": (1, 6),
        "polar_vector": (6, 9),
        "cubic_path": (9, 12),
    }
    block_ranks = {
        name: fraction_rank([row[start:end] for row in mode_rows])
        for name, (start, end) in block_ranges.items()
    }
    gram = [
        [
            sum((mode_rows[row][left] * mode_rows[row][right] for row in range(vertex_count)), Fraction(0))
            for right in range(len(mode_names))
        ]
        for left in range(len(mode_names))
    ]
    maximum_off_diagonal_gram = max(
        abs(gram[row][column])
        for row in range(len(mode_names))
        for column in range(len(mode_names))
        if row != column
    )
    gram_diagonal = tuple(gram[index][index] for index in range(len(mode_names)))

    vertex_index = {vertex: index for index, vertex in enumerate(vertices)}
    inversion_parity_failures = 0
    even_columns = tuple(range(0, 6))
    odd_columns = tuple(range(6, 12))
    for index, vertex in enumerate(vertices):
        opposite = vertex_index[tuple(-value for value in vertex)]
        for column in even_columns:
            inversion_parity_failures += int(mode_rows[opposite][column] != mode_rows[index][column])
        for column in odd_columns:
            inversion_parity_failures += int(mode_rows[opposite][column] != -mode_rows[index][column])

    # Exact discrete gauge/holonomy action:
    # h = B1*q - a, F = B2*a, S = ||h||^2/(2E) + ||F||^2/(2F).
    q = tuple(Fraction((index % G5) - DUAL, G5) for index in range(vertex_count))
    a = tuple(Fraction((index % 7) - 3, 7) for index in range(edge_count))
    gauge_parameter = tuple(Fraction((index % 4) - SHIFT, 11) for index in range(vertex_count))

    def action(vertex_field: Sequence[Fraction], edge_connection: Sequence[Fraction]) -> Fraction:
        gradient = _fraction_matrix_vector_native(b1, vertex_field)
        covariant_edge = [gradient[index] - edge_connection[index] for index in range(edge_count)]
        curvature = _fraction_matrix_vector_native(b2, edge_connection)
        return (
            sum((value * value for value in covariant_edge), Fraction(0)) / Fraction(DUAL * edge_count)
            + sum((value * value for value in curvature), Fraction(0)) / Fraction(DUAL * face_count)
        )

    base_action = action(q, a)
    b1_gauge = _fraction_matrix_vector_native(b1, gauge_parameter)
    transformed_q = tuple(q[index] + gauge_parameter[index] for index in range(vertex_count))
    transformed_a = tuple(a[index] + b1_gauge[index] for index in range(edge_count))
    transformed_action = action(transformed_q, transformed_a)
    gauge_action_residual = abs(transformed_action - base_action)

    gradient = _fraction_matrix_vector_native(b1, q)
    covariant_edge = [gradient[index] - a[index] for index in range(edge_count)]
    curvature = _fraction_matrix_vector_native(b2, a)
    q_gradient = [value / Fraction(edge_count) for value in _fraction_transpose_vector_native(b1, covariant_edge)]
    curvature_gradient = _fraction_transpose_vector_native(b2, curvature)
    a_gradient = [
        -covariant_edge[index] / Fraction(edge_count) + curvature_gradient[index] / Fraction(face_count)
        for index in range(edge_count)
    ]
    epsilon = Fraction(SHIFT, 10 ** 4)
    variation_residuals = []
    for index in range(vertex_count):
        plus = list(q); minus = list(q)
        plus[index] += epsilon; minus[index] -= epsilon
        numerical = (action(tuple(plus), a) - action(tuple(minus), a)) / (DUAL * epsilon)
        variation_residuals.append(abs(numerical - q_gradient[index]))
    for index in range(edge_count):
        plus = list(a); minus = list(a)
        plus[index] += epsilon; minus[index] -= epsilon
        numerical = (action(q, tuple(plus)) - action(q, tuple(minus))) / (DUAL * epsilon)
        variation_residuals.append(abs(numerical - a_gradient[index]))
    maximum_variation_residual = max(variation_residuals)

    face_adjacency = complex_data["face_adjacency"]

    def removal_deltas(order: Sequence[int]) -> Tuple[int, ...]:
        occupied = set()
        values = []
        for face in order:
            occupied_neighbors = sum(face_adjacency[face][other] for other in occupied)
            values.append(SHIFT + DUAL * occupied_neighbors)
            occupied.add(face)
        return tuple(values)

    geometry_orders = {
        "triangles_then_squares": tuple(complex_data["triangle_indices"] + complex_data["square_indices"]),
        "squares_then_triangles": tuple(complex_data["square_indices"] + complex_data["triangle_indices"]),
        "normal_pair_walk": tuple(complex_data["normal_pair_walk"]),
        "topology_adjacency_walk": tuple(complex_data["topology_walk"]),
    }
    order_deltas = {name: removal_deltas(order) for name, order in geometry_orders.items()}

    fourteen_elements = [row for row in occupancy_action["element_rows"] if row["block_size"] == 14]
    fourteen_groups = [(row["depth"], row["block_index"]) for row in fourteen_elements]
    group_ids = {group: index for index, group in enumerate(sorted(set(fourteen_groups)))}
    diagnostic_groups = [group_ids[group] for group in fourteen_groups]
    ion_values = [float(row["ion_actual"]) for row in fourteen_elements]
    face_order_diagnostics = []
    for name, deltas in order_deltas.items():
        features = []
        for row in fourteen_elements:
            position = int(row["block_position"])
            old_delta = DUAL * position - SHIFT
            harmonic = float(row["local_removal_kernel"]) / float(old_delta)
            features.append(float(deltas[position - SHIFT]) * harmonic)
        face_order_diagnostics.append({
            "name": name,
            "removal_deltas": deltas,
            "pearson": _finite_pearson(features, ion_values),
            "within_group_pearson": _group_centered_pearson(features, ion_values, diagnostic_groups),
            "gloo_rmse": _group_leave_one_out_metrics(features, ion_values, diagnostic_groups)[0],
        })
    face_order_diagnostics.sort(key=lambda row: (row["gloo_rmse"], -abs(row["within_group_pearson"]), row["name"]))

    face_type_bipartite = all(
        (faces[left]["type"] != faces[right]["type"])
        for left in range(face_count)
        for right in range(left + SHIFT, face_count)
        if face_adjacency[left][right]
    )
    triangle_degrees_exact = all(complex_data["face_degrees"][index] == 3 for index in complex_data["triangle_indices"])
    square_degrees_exact = all(complex_data["face_degrees"][index] == 4 for index in complex_data["square_indices"])

    gates = {
        "exact 12 vertices / 24 edges / 14 faces": (vertex_count, edge_count, face_count) == (12, 24, 14),
        "faces split into 8 triangles and 6 squares": (triangle_count, square_count) == (8, 6),
        "Euler closure V-E+F=2": euler_characteristic == DUAL,
        "boundary of boundary vanishes exactly": complex_data["boundary_of_boundary_maximum"] == 0,
        "vertex-edge incidence rank is V-1": b1_rank == vertex_count - SHIFT,
        "face-edge incidence rank equals independent cycle count": b2_rank == cycle_rank == independent_face_curvature_count,
        "fourteen face normals form seven antipodal pairs": len(complex_data["opposite_pairs"]) == 7,
        "dual face graph is triangle-square bipartite": face_type_bipartite,
        "triangle and square face degrees are 3 and 4": triangle_degrees_exact and square_degrees_exact,
        "complete vertex mode rank is 12": mode_rank == C12,
        "mode ranks are 1+5+3+3": block_ranks == {
            "scalar": 1,
            "symmetric_traceless_tensor": 5,
            "polar_vector": 3,
            "cubic_path": 3,
        },
        "mode basis is exactly orthogonal on twelve directions": maximum_off_diagonal_gram == 0,
        "even/odd inversion parity closes": inversion_parity_failures == 0,
        "discrete gauge action is exactly invariant": gauge_action_residual == 0,
        "analytic and central variations agree exactly": maximum_variation_residual == 0,
        "fourteen-seat face diagnostics executed without feedback": len(face_order_diagnostics) == 4 and len(fourteen_elements) > 0,
    }
    closed = all(gates.values())
    return {
        "complex": complex_data,
        "vertex_count": vertex_count,
        "edge_count": edge_count,
        "face_count": face_count,
        "triangle_count": triangle_count,
        "square_count": square_count,
        "euler_characteristic": euler_characteristic,
        "vertex_edge_rank": b1_rank,
        "face_edge_rank": b2_rank,
        "cycle_rank": cycle_rank,
        "independent_face_curvature_count": independent_face_curvature_count,
        "mode_names": mode_names,
        "mode_rank": mode_rank,
        "mode_block_ranks": block_ranks,
        "gram_diagonal": gram_diagonal,
        "maximum_off_diagonal_gram": maximum_off_diagonal_gram,
        "inversion_parity_failure_count": inversion_parity_failures,
        "base_action": base_action,
        "gauge_action_residual": gauge_action_residual,
        "maximum_variation_residual": maximum_variation_residual,
        "face_order_diagnostics": tuple(face_order_diagnostics),
        "fourteen_element_count": len(fourteen_elements),
        "face_type_bipartite": face_type_bipartite,
        "topological_parent_action_closed": closed,
        "full_fourteen_seat_physical_filling_order_closed": False,
        "continuum_lorentz_identification_closed": False,
        "gates": gates,
        "status": "EXACT_VERTEX_EDGE_FACE_DUAL_HOLONOMY_PARENT_ACTION_GATE_PASS" if closed else "VERTEX_EDGE_FACE_DUAL_HOLONOMY_GATE_FAIL",
        "boundary": "the exact cuboctahedral chain complex, complete 1+5+3+3 site-mode basis, gauge-invariant edge connection, face holonomy and fourteen-face diagnostic are closed without previous artifacts; the unique physical filling order of the fourteen-seat sector and the continuum Lorentz/Standard-Model identification remain open",
    }


# ==================================================================================================
# 43. Combined vertex/dual-face harmonic capacity and fourteen-seat spectral parent-action layer
# ==================================================================================================


def _native_harmonic_mode_blocks(point: Sequence[int]) -> Tuple[Tuple[Fraction, ...], ...]:
    x, y, z = (Fraction(value) for value in point)
    l0 = (Fraction(SHIFT),)
    l1 = (x, y, z)
    l2 = (
        x * x - y * y,
        DUAL * z * z - x * x - y * y,
        x * y,
        y * z,
        z * x,
    )
    l3 = (
        x * (DUAL * x * x - 3 * y * y - 3 * z * z),
        y * (DUAL * y * y - 3 * z * z - 3 * x * x),
        z * (DUAL * z * z - 3 * x * x - 3 * y * y),
        x * (y * y - z * z),
        y * (z * z - x * x),
        z * (x * x - y * y),
        x * y * z,
    )
    return l0, l1, l2, l3


def _fraction_identity_native(size: int) -> List[List[Fraction]]:
    return [
        [Fraction(SHIFT if row == column else 0) for column in range(size)]
        for row in range(size)
    ]


def _fraction_trace_native(matrix: Sequence[Sequence[Fraction]]) -> Fraction:
    return sum((matrix[index][index] for index in range(len(matrix))), Fraction(0))


def _fraction_characteristic_coefficients_native(
    matrix: Sequence[Sequence[Fraction]],
) -> Tuple[Fraction, ...]:
    """Return descending coefficients of det(lambda I - A) using exact traces."""
    size = len(matrix)
    power = _fraction_identity_native(size)
    powers = []
    for _ in range(size):
        power = _fraction_matrix_multiply_native(power, matrix)
        powers.append(power)
    coefficients = [Fraction(SHIFT)]
    for order in range(SHIFT, size + SHIFT):
        trace_sum = sum(
            (
                coefficients[order - inner]
                * _fraction_trace_native(powers[inner - SHIFT])
                for inner in range(SHIFT, order + SHIFT)
            ),
            Fraction(0),
        )
        coefficients.append(-trace_sum / Fraction(order))
    return tuple(coefficients)


def _fraction_polynomial_multiply_ascending_native(
    left: Sequence[Fraction],
    right: Sequence[Fraction],
) -> Tuple[Fraction, ...]:
    result = [Fraction(0) for _ in range(len(left) + len(right) - SHIFT)]
    for left_index, left_value in enumerate(left):
        for right_index, right_value in enumerate(right):
            result[left_index + right_index] += left_value * right_value
    return tuple(result)


def vertex_face_harmonic_shell_capacity_parent_action_lens(
    dual_holonomy: Dict[str, object],
    terminal_closure: Dict[str, object],
) -> Dict[str, object]:
    complex_data = dual_holonomy["complex"]
    vertices = tuple(complex_data["vertices"])
    face_normals = tuple(face["normal"] for face in complex_data["faces"])
    combined_points = vertices + face_normals

    def cumulative_mode_matrix(points: Sequence[Sequence[int]], maximum_degree: int) -> List[List[Fraction]]:
        matrix = []
        for point in points:
            blocks = _native_harmonic_mode_blocks(point)
            row = []
            for degree in range(maximum_degree + SHIFT):
                row.extend(blocks[degree])
            matrix.append(row)
        return matrix

    cumulative_ranks = {}
    incremental_ranks = {}
    for name, points in (
        ("vertex", vertices),
        ("dual_face", face_normals),
        ("combined", combined_points),
    ):
        ranks = tuple(
            fraction_rank(cumulative_mode_matrix(points, degree))
            for degree in range(4)
        )
        increments = tuple(
            ranks[index] - (ranks[index - SHIFT] if index else 0)
            for index in range(len(ranks))
        )
        cumulative_ranks[name] = ranks
        incremental_ranks[name] = increments

    l3_labels = (
        "axis_cubic_x", "axis_cubic_y", "axis_cubic_z",
        "path_cubic_x", "path_cubic_y", "path_cubic_z",
        "triple_product_xyz",
    )
    l3_rows = []
    l3_weights = []
    for point in combined_points:
        l3_rows.append(_native_harmonic_mode_blocks(point)[3])
        norm_square = sum((Fraction(value * value) for value in point), Fraction(0))
        l3_weights.append(Fraction(SHIFT, norm_square ** 3))
    l3_gram = [
        [
            sum(
                (
                    l3_weights[row]
                    * l3_rows[row][left]
                    * l3_rows[row][right]
                    for row in range(len(l3_rows))
                ),
                Fraction(0),
            )
            for right in range(7)
        ]
        for left in range(7)
    ]
    l3_gram_diagonal = tuple(l3_gram[index][index] for index in range(7))
    l3_maximum_off_diagonal = max(
        abs(l3_gram[row][column])
        for row in range(7)
        for column in range(7)
        if row != column
    )
    l3_positive_metric = all(value > 0 for value in l3_gram_diagonal)
    l3_metric_rank = fraction_rank(l3_gram)

    channel_count = DUAL
    angular_increments = incremental_ranks["combined"]
    two_channel_blocks = tuple(channel_count * value for value in angular_increments)
    cumulative_capacities = []
    running = 0
    for value in two_channel_blocks:
        running += value
        cumulative_capacities.append(running)
    cumulative_capacities = tuple(cumulative_capacities)
    derived_zero_bounded_board = (
        0,
        *cumulative_capacities,
        *tuple(reversed(cumulative_capacities)),
        0,
    )

    state_registry = []
    cumulative = 0
    for degree, angular_multiplicity in enumerate(angular_increments):
        added = channel_count * angular_multiplicity
        cumulative += added
        state_registry.append({
            "degree": degree,
            "angular_multiplicity": angular_multiplicity,
            "channel_count": channel_count,
            "added_seats": added,
            "cumulative_capacity": cumulative,
        })

    depth_rows = []
    terminal_rows = {int(row["index"]): row for row in terminal_closure["rows"]}
    for depth in range(SHIFT, D8 + SHIFT):
        mirror_distance = min(depth, D8 + SHIFT - depth)
        allowed_degrees = tuple(range(mirror_distance))
        expected_capacity = sum(two_channel_blocks[:mirror_distance])
        row = terminal_rows[depth]
        depth_rows.append({
            "depth": depth,
            "mirror_distance": mirror_distance,
            "allowed_degrees": allowed_degrees,
            "derived_capacity": expected_capacity,
            "terminal_capacity": int(row["capacity"]),
            "raw_radial_transfer": float(row["raw_geometric_transfer_rms"]),
        })

    face_count = len(face_normals)
    face_adjacency = complex_data["face_adjacency"]
    face_laplacian = [
        [
            Fraction(
                (sum(face_adjacency[row]) if row == column else 0)
                - face_adjacency[row][column]
            )
            for column in range(face_count)
        ]
        for row in range(face_count)
    ]
    opposite_pairs = tuple(complex_data["opposite_pairs"])
    odd_columns = []
    for positive, negative in opposite_pairs:
        vector = [Fraction(0) for _ in range(face_count)]
        vector[positive] = Fraction(SHIFT)
        vector[negative] = Fraction(-SHIFT)
        image = _fraction_matrix_vector_native(face_laplacian, vector)
        odd_columns.append(tuple(image[pair[0]] for pair in opposite_pairs))
    odd_laplacian = [
        [odd_columns[column][row] for column in range(7)]
        for row in range(7)
    ]
    odd_characteristic = _fraction_characteristic_coefficients_native(odd_laplacian)
    quadratic = (Fraction(8), Fraction(-7), Fraction(SHIFT))
    cubic_quadratic = _fraction_polynomial_multiply_ascending_native(
        quadratic,
        _fraction_polynomial_multiply_ascending_native(quadratic, quadratic),
    )
    expected_ascending = _fraction_polynomial_multiply_ascending_native(
        (Fraction(-3), Fraction(SHIFT)),
        cubic_quadratic,
    )
    expected_characteristic = tuple(reversed(expected_ascending))
    odd_characteristic_factorization_closed = odd_characteristic == expected_characteristic
    low_eigenvalue = (7.0 - math.sqrt(17.0)) / DUAL
    middle_eigenvalue = 3.0
    high_eigenvalue = (7.0 + math.sqrt(17.0)) / DUAL
    one_channel_spectral_multiplicities = (3, 1, 3)
    two_channel_spectral_multiplicities = tuple(channel_count * value for value in one_channel_spectral_multiplicities)

    # Exact positive angular parent-action metric: one identical seven-mode block per A/B channel.
    angular_hessian = [
        [Fraction(0) for _ in range(14)]
        for _ in range(14)
    ]
    for channel in range(channel_count):
        offset = channel * 7
        for mode in range(7):
            angular_hessian[offset + mode][offset + mode] = l3_gram_diagonal[mode]
    angular_hessian_rank = fraction_rank(angular_hessian)
    angular_hessian_positive = all(angular_hessian[index][index] > 0 for index in range(14))
    test_amplitudes_a = tuple(Fraction(index - 3, 11) for index in range(7))
    test_amplitudes_b = tuple(Fraction(3 - index, 13) for index in range(7))

    def angular_action(channel_a: Sequence[Fraction], channel_b: Sequence[Fraction]) -> Fraction:
        return sum(
            (
                l3_gram_diagonal[index]
                * (channel_a[index] * channel_a[index] + channel_b[index] * channel_b[index])
                for index in range(7)
            ),
            Fraction(0),
        ) / Fraction(DUAL)

    angular_action_value = angular_action(test_amplitudes_a, test_amplitudes_b)
    channel_exchange_residual = abs(
        angular_action(test_amplitudes_b, test_amplitudes_a) - angular_action_value
    )
    equality_channel_difference = sum(
        (
            l3_gram_diagonal[index]
            * (test_amplitudes_a[index] - test_amplitudes_a[index]) ** DUAL
            for index in range(7)
        ),
        Fraction(0),
    )

    total_active_state_count = sum(row["derived_capacity"] for row in depth_rows)
    radial_angular_weight_sum = sum(
        row["derived_capacity"] * row["raw_radial_transfer"] ** DUAL
        for row in depth_rows
    )

    gates = {
        "combined cumulative harmonic ranks are 1,4,9,16": cumulative_ranks["combined"] == (1, 4, 9, 16),
        "combined incremental harmonic ranks are 1,3,5,7": angular_increments == (1, 3, 5, 7),
        "vertex and dual-face cubic complements are 3 and 4": incremental_ranks["vertex"][3] == 3 and incremental_ranks["dual_face"][3] == 4,
        "combined cubic rank is complete seven": l3_metric_rank == 7,
        "combined cubic mode metric is exactly orthogonal": l3_maximum_off_diagonal == 0,
        "combined cubic mode metric is positive": l3_positive_metric,
        "two-channel seat blocks are 2,6,10,14": two_channel_blocks == (2, 6, 10, 14),
        "cumulative shell capacities are 2,8,18,32": cumulative_capacities == (2, 8, 18, 32),
        "zero-bounded mirror board is regenerated exactly": tuple(terminal_closure["full_capacity_board"]) == derived_zero_bounded_board,
        "all eight depth capacities match harmonic state count": all(row["derived_capacity"] == row["terminal_capacity"] for row in depth_rows),
        "total active electron-address state count is 120": total_active_state_count == 120,
        "odd dual-face Laplacian factors as (lambda-3)(lambda^2-7lambda+8)^3": odd_characteristic_factorization_closed,
        "one-channel odd spectral multiplicities are 3,1,3": sum(one_channel_spectral_multiplicities) == 7,
        "two-channel fourteen-seat spectral multiplicities are 6,2,6": two_channel_spectral_multiplicities == (6, 2, 6),
        "fourteen-mode angular Hessian is full rank and positive": angular_hessian_rank == 14 and angular_hessian_positive,
        "angular parent action is exactly A/B exchange invariant": channel_exchange_residual == 0,
        "equal A/B angular channels have zero difference burden": equality_channel_difference == 0,
    }
    structural_closed = all(gates.values())
    return {
        "cumulative_ranks": cumulative_ranks,
        "incremental_ranks": incremental_ranks,
        "l3_labels": l3_labels,
        "l3_gram_diagonal": l3_gram_diagonal,
        "l3_maximum_off_diagonal": l3_maximum_off_diagonal,
        "l3_metric_rank": l3_metric_rank,
        "two_channel_blocks": two_channel_blocks,
        "cumulative_capacities": cumulative_capacities,
        "derived_zero_bounded_board": derived_zero_bounded_board,
        "state_registry": tuple(state_registry),
        "depth_rows": tuple(depth_rows),
        "total_active_state_count": total_active_state_count,
        "radial_angular_weight_sum": radial_angular_weight_sum,
        "odd_laplacian": tuple(tuple(value for value in row) for row in odd_laplacian),
        "odd_characteristic_coefficients": odd_characteristic,
        "odd_expected_characteristic_coefficients": expected_characteristic,
        "odd_characteristic_factorization_closed": odd_characteristic_factorization_closed,
        "one_channel_spectral_multiplicities": one_channel_spectral_multiplicities,
        "two_channel_spectral_multiplicities": two_channel_spectral_multiplicities,
        "spectral_eigenvalues": (low_eigenvalue, middle_eigenvalue, high_eigenvalue),
        "angular_hessian_rank": angular_hessian_rank,
        "angular_hessian_positive": angular_hessian_positive,
        "angular_action_value": angular_action_value,
        "channel_exchange_residual": channel_exchange_residual,
        "equality_channel_difference": equality_channel_difference,
        "harmonic_capacity_parent_action_closed": structural_closed,
        "full_fourteen_seat_physical_filling_order_closed": False,
        "continuum_lorentz_identification_closed": False,
        "standard_model_internal_group_identification_closed": False,
        "gates": gates,
        "status": "EXACT_VERTEX_FACE_HARMONIC_CAPACITY_PARENT_ACTION_GATE_PASS" if structural_closed else "VERTEX_FACE_HARMONIC_CAPACITY_PARENT_ACTION_GATE_FAIL",
        "boundary": "the combined 12-vertex/14-dual-face support now derives exact angular increments 1,3,5,7, two-channel blocks 2,6,10,14, the complete zero-bounded shell-capacity board, a seven-mode odd dual-face spectrum and a positive exchange-invariant fourteen-mode angular action without previous artifacts; the unique physical filling sequence, continuum Lorentz limit and Standard-Model internal-group identification remain open",
    }


# ==================================================================================================
# 44. Pure l=3 projection, 1+3+3 native spectrum, and two-channel 2+6+6 occupancy sector layer
# ==================================================================================================


def _unit_harmonic_mode_blocks_float(point: Sequence[int]) -> Tuple[Tuple[float, ...], ...]:
    norm = math.sqrt(float(sum(value * value for value in point)))
    x, y, z = (float(value) / norm for value in point)
    l0 = (1.0,)
    l1 = (x, y, z)
    l2 = (
        x * x - y * y,
        DUAL * z * z - x * x - y * y,
        x * y,
        y * z,
        z * x,
    )
    l3 = (
        x * (DUAL * x * x - 3.0 * y * y - 3.0 * z * z),
        y * (DUAL * y * y - 3.0 * z * z - 3.0 * x * x),
        z * (DUAL * z * z - 3.0 * x * x - 3.0 * y * y),
        x * (y * y - z * z),
        y * (z * z - x * x),
        z * (x * x - y * y),
        x * y * z,
    )
    return l0, l1, l2, l3


def _modified_gram_schmidt_columns_native(
    matrix: Sequence[Sequence[float]],
    tolerance: float = 1.0e-12,
) -> Tuple[Tuple[Tuple[float, ...], ...], Tuple[float, ...]]:
    if not matrix:
        return tuple(), tuple()
    row_count = len(matrix)
    column_count = len(matrix[0])
    columns = []
    norms = []
    for column in range(column_count):
        vector = [float(matrix[row][column]) for row in range(row_count)]
        for _pass in range(DUAL):
            for basis in columns:
                overlap = sum(basis[row] * vector[row] for row in range(row_count))
                vector = [vector[row] - overlap * basis[row] for row in range(row_count)]
        norm = math.sqrt(sum(value * value for value in vector))
        norms.append(norm)
        if norm > tolerance:
            columns.append(tuple(value / norm for value in vector))
    return tuple(columns), tuple(norms)


def _jacobi_symmetric_eigendecomposition_native(
    matrix: Sequence[Sequence[float]],
    tolerance: float = 1.0e-13,
    maximum_iterations: int = 20000,
) -> Dict[str, object]:
    size = len(matrix)
    work = [[float(matrix[row][column]) for column in range(size)] for row in range(size)]
    vectors = [[1.0 if row == column else 0.0 for column in range(size)] for row in range(size)]
    iterations = 0
    for iterations in range(maximum_iterations):
        pairs = [(row, column) for row in range(size) for column in range(row + SHIFT, size)]
        if not pairs:
            break
        pivot_row, pivot_column = max(pairs, key=lambda pair: abs(work[pair[0]][pair[1]]))
        off_diagonal = work[pivot_row][pivot_column]
        if abs(off_diagonal) < tolerance:
            break
        tau = (work[pivot_column][pivot_column] - work[pivot_row][pivot_row]) / (DUAL * off_diagonal)
        tangent = (1.0 if tau >= 0.0 else -1.0) / (abs(tau) + math.sqrt(1.0 + tau * tau))
        cosine = 1.0 / math.sqrt(1.0 + tangent * tangent)
        sine = tangent * cosine
        diagonal_row = work[pivot_row][pivot_row]
        diagonal_column = work[pivot_column][pivot_column]
        for index in range(size):
            if index in (pivot_row, pivot_column):
                continue
            old_row = work[index][pivot_row]
            old_column = work[index][pivot_column]
            work[index][pivot_row] = work[pivot_row][index] = cosine * old_row - sine * old_column
            work[index][pivot_column] = work[pivot_column][index] = sine * old_row + cosine * old_column
        work[pivot_row][pivot_row] = (
            cosine * cosine * diagonal_row
            - DUAL * sine * cosine * off_diagonal
            + sine * sine * diagonal_column
        )
        work[pivot_column][pivot_column] = (
            sine * sine * diagonal_row
            + DUAL * sine * cosine * off_diagonal
            + cosine * cosine * diagonal_column
        )
        work[pivot_row][pivot_column] = work[pivot_column][pivot_row] = 0.0
        for index in range(size):
            old_row = vectors[index][pivot_row]
            old_column = vectors[index][pivot_column]
            vectors[index][pivot_row] = cosine * old_row - sine * old_column
            vectors[index][pivot_column] = sine * old_row + cosine * old_column
    eigenpairs = sorted(
        ((work[index][index], tuple(vectors[row][index] for row in range(size))) for index in range(size)),
        key=lambda pair: pair[0],
    )
    eigenvalues = tuple(pair[0] for pair in eigenpairs)
    eigenvectors = tuple(pair[1] for pair in eigenpairs)
    maximum_residual = 0.0
    for eigenvalue, vector in eigenpairs:
        for row in range(size):
            residual = sum(float(matrix[row][column]) * vector[column] for column in range(size)) - eigenvalue * vector[row]
            maximum_residual = max(maximum_residual, abs(residual))
    maximum_off_diagonal = max(
        (abs(work[row][column]) for row in range(size) for column in range(row + SHIFT, size)),
        default=0.0,
    )
    return {
        "eigenvalues": eigenvalues,
        "eigenvectors": eigenvectors,
        "maximum_residual": maximum_residual,
        "maximum_off_diagonal": maximum_off_diagonal,
        "iterations": iterations,
    }


def _cluster_numeric_multiplicities_native(
    values: Sequence[float],
    tolerance: float = 1.0e-9,
) -> Tuple[Tuple[float, int], ...]:
    clusters: List[List[float]] = []
    for value in sorted(float(entry) for entry in values):
        if not clusters or abs(value - _finite_mean(clusters[-SHIFT])) > tolerance:
            clusters.append([value])
        else:
            clusters[-SHIFT].append(value)
    return tuple((_finite_mean(cluster), len(cluster)) for cluster in clusters)


def _positive_even_three_partitions_of_fourteen_native() -> Tuple[Tuple[int, int, int], ...]:
    total = C12 + DUAL
    partitions = []
    for first in range(DUAL, total, DUAL):
        for second in range(DUAL, total - first, DUAL):
            third = total - first - second
            if third >= DUAL and third % DUAL == 0:
                partitions.append((first, second, third))
    return tuple(partitions)


def _sector_position_native(position: int, sector_sizes: Sequence[int]) -> Dict[str, int]:
    if position < SHIFT or position > sum(sector_sizes):
        raise ValueError("fourteen-seat position lies outside the pure-l3 sector board")
    completed = 0
    for sector_index, sector_size in enumerate(sector_sizes):
        if position <= completed + sector_size:
            local_position = position - completed
            return {
                "sector_index": sector_index,
                "sector_size": int(sector_size),
                "local_position": local_position,
                "completed_before": completed,
                "directed_relations_before": local_position * local_position,
                "directed_relations_after": (local_position - SHIFT) * (local_position - SHIFT),
                "relations_removed": DUAL * local_position - SHIFT,
            }
        completed += int(sector_size)
    raise RuntimeError("pure-l3 sector lookup failed")


def pure_l3_two_six_six_occupancy_reclosure_lens(
    dual_holonomy: Dict[str, object],
    harmonic_capacity: Dict[str, object],
    occupancy_action: Dict[str, object],
    terminal_closure: Dict[str, object],
) -> Dict[str, object]:
    complex_data = dual_holonomy["complex"]
    vertices = tuple(complex_data["vertices"])
    face_normals = tuple(face["normal"] for face in complex_data["faces"])
    points = vertices + face_normals
    vertex_count = len(vertices)
    face_count = len(face_normals)
    support_count = len(points)

    lower_rows = []
    cubic_rows = []
    for point in points:
        l0, l1, l2, l3 = _unit_harmonic_mode_blocks_float(point)
        lower_rows.append(tuple(l0 + l1 + l2))
        cubic_rows.append(tuple(l3))

    lower_gram = [
        [sum(lower_rows[row][left] * lower_rows[row][right] for row in range(support_count)) for right in range(9)]
        for left in range(9)
    ]
    lower_cross_cubic = [
        [sum(lower_rows[row][left] * cubic_rows[row][right] for row in range(support_count)) for right in range(7)]
        for left in range(9)
    ]
    inverse_lower_gram = _dense_inverse_native(lower_gram)
    projection_coefficients = [
        [sum(inverse_lower_gram[row][middle] * lower_cross_cubic[middle][column] for middle in range(9)) for column in range(7)]
        for row in range(9)
    ]
    pure_cubic_rows = [
        [
            cubic_rows[row][column]
            - sum(lower_rows[row][lower] * projection_coefficients[lower][column] for lower in range(9))
            for column in range(7)
        ]
        for row in range(support_count)
    ]
    lower_projection_residual = max(
        abs(sum(lower_rows[row][lower] * pure_cubic_rows[row][column] for row in range(support_count)))
        for lower in range(9)
        for column in range(7)
    )
    orthonormal_columns, raw_projected_norms = _modified_gram_schmidt_columns_native(pure_cubic_rows)
    pure_rank = len(orthonormal_columns)
    orthonormal_residual = max(
        abs(
            sum(orthonormal_columns[left][row] * orthonormal_columns[right][row] for row in range(support_count))
            - (1.0 if left == right else 0.0)
        )
        for left in range(pure_rank)
        for right in range(pure_rank)
    )

    adjacency = [[0.0 for _ in range(support_count)] for _ in range(support_count)]
    for left, right in complex_data["edges"]:
        adjacency[left][right] = adjacency[right][left] = 1.0
    face_adjacency = complex_data["face_adjacency"]
    for left in range(face_count):
        for right in range(left + SHIFT, face_count):
            if face_adjacency[left][right]:
                adjacency[vertex_count + left][vertex_count + right] = 1.0
                adjacency[vertex_count + right][vertex_count + left] = 1.0
    for face_index, face in enumerate(complex_data["faces"]):
        for vertex_index in face["vertices"]:
            adjacency[vertex_index][vertex_count + face_index] = 1.0
            adjacency[vertex_count + face_index][vertex_index] = 1.0
    native_laplacian = [[0.0 for _ in range(support_count)] for _ in range(support_count)]
    for row in range(support_count):
        native_laplacian[row][row] = sum(adjacency[row])
        for column in range(support_count):
            if row != column:
                native_laplacian[row][column] = -adjacency[row][column]

    pure_hessian = [
        [
            sum(
                orthonormal_columns[left][row]
                * sum(native_laplacian[row][column] * orthonormal_columns[right][column] for column in range(support_count))
                for row in range(support_count)
            )
            for right in range(pure_rank)
        ]
        for left in range(pure_rank)
    ]
    hessian_symmetry_residual = max(
        abs(pure_hessian[row][column] - pure_hessian[column][row])
        for row in range(pure_rank)
        for column in range(pure_rank)
    )
    eigensystem = _jacobi_symmetric_eigendecomposition_native(pure_hessian)
    spectral_clusters = _cluster_numeric_multiplicities_native(eigensystem["eigenvalues"])
    multiplicities = tuple(cluster[1] for cluster in spectral_clusters)
    two_channel_sector_sizes = tuple(DUAL * multiplicity for multiplicity in multiplicities)

    basis_rayleigh = tuple(pure_hessian[index][index] for index in range(pure_rank))
    axis_triplet_value = _finite_mean(basis_rayleigh[:3])
    path_triplet_value = _finite_mean(basis_rayleigh[3:6])
    xyz_singlet_value = basis_rayleigh[6]
    expected_order_values = (xyz_singlet_value, axis_triplet_value, path_triplet_value)
    expected_order_multiplicities = (SHIFT, 3, 3)
    sector_labels = ("xyz_singlet", "axis_cubic_triplet", "path_cubic_triplet")

    channel_a = tuple(Fraction(index + SHIFT, C12 + DUAL) for index in range(7))
    channel_b = tuple(Fraction((index + SHIFT) % G5, C12 + DUAL) for index in range(7))
    mode_weights = tuple(Fraction(str(value)) for value in (
        axis_triplet_value, axis_triplet_value, axis_triplet_value,
        path_triplet_value, path_triplet_value, path_triplet_value,
        xyz_singlet_value,
    ))

    def angular_action(left: Sequence[Fraction], right: Sequence[Fraction]) -> Fraction:
        kinetic = sum(
            (mode_weights[index] * (left[index] * left[index] + right[index] * right[index]) / DUAL for index in range(7)),
            Fraction(0),
        )
        exchange_closure = sum(((left[index] - right[index]) ** DUAL / DUAL for index in range(7)), Fraction(0))
        return kinetic + exchange_closure

    angular_action_value = angular_action(channel_a, channel_b)
    angular_exchange_residual = angular_action(channel_a, channel_b) - angular_action(channel_b, channel_a)
    angular_equality_burden = sum(((channel_a[index] - channel_a[index]) ** DUAL / DUAL for index in range(7)), Fraction(0))
    fourteen_hessian_diagonal = tuple(float(value) + 1.0 for value in expected_order_values for _channel in range(DUAL) for _copy in range(expected_order_multiplicities[expected_order_values.index(value)]))
    # The direct diagonal construction above is used only as a positivity witness; the physical
    # sector multiplicities and ordering come from the projected seven-mode Hessian itself.
    fourteen_hessian_rank = len(fourteen_hessian_diagonal)
    fourteen_hessian_positive = all(value > 0.0 for value in fourteen_hessian_diagonal)

    fourteen_rows = [row for row in occupancy_action["element_rows"] if row["block_size"] == C12 + DUAL]
    diagnostic_groups_base = [(int(row["depth"]), int(row["block_index"])) for row in fourteen_rows]
    ion_values = [float(row["ion_actual"]) for row in fourteen_rows]

    partition_rows = []
    for partition in _positive_even_three_partitions_of_fourteen_native():
        local_positions = []
        groups = []
        for row, base_group in zip(fourteen_rows, diagnostic_groups_base):
            state = _sector_position_native(int(row["block_position"]), partition)
            local_positions.append(float(state["local_position"]))
            groups.append(base_group + (state["sector_index"],))
        correlation = _group_centered_pearson(local_positions, ion_values, groups)
        partition_rows.append({
            "partition": partition,
            "within_sector_pearson": correlation,
        })
    partition_rows.sort(key=lambda row: (-row["within_sector_pearson"], row["partition"]))
    derived_partition_rank = next(
        index + SHIFT for index, row in enumerate(partition_rows)
        if row["partition"] == two_channel_sector_sizes
    )

    pure_sector_element_rows = []
    terminal_by_depth = {int(row["index"]): row for row in terminal_closure["rows"]}
    sector_eigenvalues = expected_order_values
    local_positions = []
    local_groups = []
    action_gap_candidates = []
    for row, base_group in zip(fourteen_rows, diagnostic_groups_base):
        state = _sector_position_native(int(row["block_position"]), two_channel_sector_sizes)
        depth = int(row["depth"])
        transfer = float(terminal_by_depth[depth]["raw_geometric_transfer_rms"])
        electron_burden = float(depth * depth) * transfer * transfer
        proton_burden = float(depth ** 4) * transfer * transfer
        bottleneck = DUAL * electron_burden * proton_burden / (electron_burden + proton_burden)
        sector_eigenvalue = float(sector_eigenvalues[state["sector_index"]])
        removal_gap = float(state["relations_removed"]) * sector_eigenvalue * bottleneck
        local_positions.append(float(state["local_position"]))
        local_groups.append(base_group + (state["sector_index"],))
        action_gap_candidates.append(removal_gap)
        pure_sector_element_rows.append({
            "Z": int(row["z"]),
            "symbol": row["symbol"],
            "depth": depth,
            "block_position": int(row["block_position"]),
            "sector_index": state["sector_index"],
            "sector_label": sector_labels[state["sector_index"]],
            "sector_size": state["sector_size"],
            "local_position": state["local_position"],
            "relations_removed": state["relations_removed"],
            "sector_eigenvalue": sector_eigenvalue,
            "radial_bottleneck": bottleneck,
            "pure_l3_removal_gap": removal_gap,
            "ion_actual": float(row["ion_actual"]),
        })

    derived_partition_correlation = _group_centered_pearson(local_positions, ion_values, local_groups)
    removal_gap_correlation = _finite_pearson(action_gap_candidates, ion_values)
    removal_gap_within_correlation = _group_centered_pearson(action_gap_candidates, ion_values, local_groups)

    segment_diagnostics = []
    for key in sorted(set(local_groups)):
        indices = [index for index, group in enumerate(local_groups) if group == key]
        segment_diagnostics.append({
            "depth": key[0],
            "block_index": key[1],
            "sector_index": key[2],
            "sector_label": sector_labels[key[2]],
            "size": len(indices),
            "pearson": _finite_pearson(
                [local_positions[index] for index in indices],
                [ion_values[index] for index in indices],
            ),
        })

    permutation_trials = C12 ** len(TRANSFORMER_LAYER_LABELS)
    permutation_state = 1_234_567_891
    exceed_count = 0
    base_block_groups: Dict[Tuple[int, int], List[int]] = {}
    for index, group in enumerate(diagnostic_groups_base):
        base_block_groups.setdefault(group, []).append(index)
    for _trial in range(permutation_trials):
        shuffled = list(ion_values)
        for indices in base_block_groups.values():
            values = [shuffled[index] for index in indices]
            for cursor in range(len(values) - SHIFT, 0, -SHIFT):
                permutation_state = (1_664_525 * permutation_state + 1_013_904_223) & 0xFFFFFFFF
                other = permutation_state % (cursor + SHIFT)
                values[cursor], values[other] = values[other], values[cursor]
            for index, value in zip(indices, values):
                shuffled[index] = value
        shuffled_correlation = _group_centered_pearson(local_positions, shuffled, local_groups)
        if shuffled_correlation >= derived_partition_correlation - 1.0e-15:
            exceed_count += SHIFT
    permutation_p = float(exceed_count + SHIFT) / float(permutation_trials + SHIFT)

    old_mixed_partition_correlation = next(
        row["within_sector_pearson"] for row in partition_rows if row["partition"] == (6, 2, 6)
    )
    alternate_partition_correlation = next(
        row["within_sector_pearson"] for row in partition_rows if row["partition"] == (6, 6, 2)
    )

    structural_gates = {
        "combined lower-degree support has rank nine": harmonic_capacity["cumulative_ranks"]["combined"][2] == 9,
        "lower-degree projection removes all l<=2 overlap": lower_projection_residual < 1.0e-12,
        "projected pure l=3 space has rank seven": pure_rank == 7,
        "pure l=3 orthonormal basis closes": orthonormal_residual < 1.0e-12,
        "native vertex-face-incidence Hessian is symmetric": hessian_symmetry_residual < 1.0e-12,
        "Jacobi eigenproblem closes": eigensystem["maximum_residual"] < 1.0e-10,
        "pure l=3 spectrum has multiplicities one plus three plus three": multiplicities == expected_order_multiplicities,
        "native sector order is singlet then axis triplet then path triplet": xyz_singlet_value < axis_triplet_value < path_triplet_value,
        "A/B doubling gives two plus six plus six seats": two_channel_sector_sizes == (2, 6, 6),
        "two-channel pure l=3 board has fourteen seats": sum(two_channel_sector_sizes) == C12 + DUAL,
        "fourteen-mode action is positive and exchange invariant": fourteen_hessian_rank == 14 and fourteen_hessian_positive and angular_exchange_residual == 0,
        "directed sector removal is exactly two-r-minus-one": all(
            row["relations_removed"] == DUAL * row["local_position"] - SHIFT
            for row in pure_sector_element_rows
        ),
    }
    structural_closed = all(structural_gates.values())
    diagnostic_gates = {
        "derived two-six-six partition ranks first among all fifteen even partitions": derived_partition_rank == SHIFT,
        "derived partition improves over mixed six-two-six face spectrum": derived_partition_correlation > old_mixed_partition_correlation,
        "derived partition improves over six-six-two ordering": derived_partition_correlation > alternate_partition_correlation,
        "all six sealed fourteen-seat sectors rise internally": all(row["pearson"] > 0.0 for row in segment_diagnostics),
        "fixed derived partition survives deterministic within-block permutation firewall": permutation_p < 1.0 / float(C12),
    }
    diagnostic_confirmed = all(diagnostic_gates.values())

    return {
        "support_count": support_count,
        "lower_degree_rank": harmonic_capacity["cumulative_ranks"]["combined"][2],
        "projection_coefficients": tuple(tuple(value for value in row) for row in projection_coefficients),
        "lower_projection_residual": lower_projection_residual,
        "raw_projected_norms": raw_projected_norms,
        "pure_rank": pure_rank,
        "orthonormal_residual": orthonormal_residual,
        "native_laplacian": native_laplacian,
        "pure_hessian": tuple(tuple(value for value in row) for row in pure_hessian),
        "hessian_symmetry_residual": hessian_symmetry_residual,
        "eigenvalues": eigensystem["eigenvalues"],
        "eigen_residual": eigensystem["maximum_residual"],
        "eigen_iterations": eigensystem["iterations"],
        "spectral_clusters": spectral_clusters,
        "pure_l3_multiplicities": multiplicities,
        "two_channel_sector_sizes": two_channel_sector_sizes,
        "sector_labels": sector_labels,
        "sector_eigenvalues": expected_order_values,
        "basis_rayleigh_values": basis_rayleigh,
        "angular_action_value": angular_action_value,
        "angular_exchange_residual": angular_exchange_residual,
        "angular_equality_burden": angular_equality_burden,
        "fourteen_hessian_rank": fourteen_hessian_rank,
        "fourteen_hessian_positive": fourteen_hessian_positive,
        "partition_rows": tuple(partition_rows),
        "derived_partition_rank": derived_partition_rank,
        "derived_partition_correlation": derived_partition_correlation,
        "old_mixed_partition_correlation": old_mixed_partition_correlation,
        "alternate_partition_correlation": alternate_partition_correlation,
        "removal_gap_correlation": removal_gap_correlation,
        "removal_gap_within_correlation": removal_gap_within_correlation,
        "segment_diagnostics": tuple(segment_diagnostics),
        "element_rows": tuple(pure_sector_element_rows),
        "permutation_trials": permutation_trials,
        "permutation_exceed_count": exceed_count,
        "permutation_p": permutation_p,
        "structural_gates": structural_gates,
        "diagnostic_gates": diagnostic_gates,
        "pure_l3_structural_closed": structural_closed,
        "sealed_two_block_diagnostic_confirmed": diagnostic_confirmed,
        "fourteen_seat_sector_order_closed": structural_closed,
        "full_state_by_state_filling_order_closed": False,
        "parent_action_operator_coefficient_uniqueness_closed": False,
        "status": "PURE_L3_TWO_SIX_SIX_SECTOR_PARENT_ACTION_GATE_PASS" if structural_closed else "PURE_L3_TWO_SIX_SIX_SECTOR_GATE_FAIL",
        "boundary": "the lower-degree-projected seven-dimensional l=3 sector, the native one-plus-three-plus-three Hessian multiplicities and their A/B-doubled two-plus-six-plus-six sector order are generated without observational feedback; sealed ionization values confirm the same fixed sector resets, but the unique microscopic state-by-state order inside each triplet, the unique weighting of vertex/face/incidence operators, and absolute eV prediction remain open",
    }


def geometry_weighted_l3_exhaustive_occupancy_lens(
    dual_holonomy: Dict[str, object],
    harmonic_capacity: Dict[str, object],
    pure_l3: Dict[str, object],
    occupancy_action: Dict[str, object],
    terminal_closure: Dict[str, object],
) -> Dict[str, object]:
    """Derive geometry weights and enumerate all fourteen-state occupancies.

    The support points are counted with equal seat measure because each allowed
    direction is one discrete state.  Geometry enters only through the Dirichlet
    couplings: primal edge inverse-length-squared, dual-edge Hodge ratio, and
    vertex-face incidence area/distance-squared.  No measured ionization value
    enters the operator, eigenmodes, pair matrix, or ground-state selection.
    """
    complex_data = dual_holonomy["complex"]
    vertices = tuple(complex_data["vertices"])
    faces = tuple(complex_data["faces"])
    edges = tuple(complex_data["edges"])
    vertex_count = len(vertices)
    face_count = len(faces)
    support_points = vertices + tuple(face["normal"] for face in faces)
    support_count = len(support_points)

    def vector_subtract(left: Sequence[float], right: Sequence[float]) -> Tuple[float, float, float]:
        return tuple(float(left[axis]) - float(right[axis]) for axis in range(3))  # type: ignore[return-value]

    def vector_norm(vector: Sequence[float]) -> float:
        return math.sqrt(sum(float(value) * float(value) for value in vector))

    def cross(left: Sequence[float], right: Sequence[float]) -> Tuple[float, float, float]:
        return (
            float(left[1]) * float(right[2]) - float(left[2]) * float(right[1]),
            float(left[2]) * float(right[0]) - float(left[0]) * float(right[2]),
            float(left[0]) * float(right[1]) - float(left[1]) * float(right[0]),
        )

    face_centroids = []
    face_areas = []
    for face in faces:
        cycle_vertices = [vertices[index] for index in face["cycle"]]
        anchor = cycle_vertices[0]
        area = 0.0
        for index in range(SHIFT, len(cycle_vertices) - SHIFT):
            first = vector_subtract(cycle_vertices[index], anchor)
            second = vector_subtract(cycle_vertices[index + SHIFT], anchor)
            area += vector_norm(cross(first, second)) / DUAL
        face_areas.append(area)
        face_centroids.append(tuple(
            sum(float(vertices[index][axis]) for index in face["vertices"]) / float(len(face["vertices"]))
            for axis in range(3)
        ))

    triangle_areas = tuple(face_areas[index] for index in complex_data["triangle_indices"])
    square_areas = tuple(face_areas[index] for index in complex_data["square_indices"])
    primal_edge_lengths = tuple(
        vector_norm(vector_subtract(vertices[left], vertices[right]))
        for left, right in edges
    )

    weighted_connections: List[Tuple[int, int, float, str]] = []
    for (left, right), length in zip(edges, primal_edge_lengths):
        weighted_connections.append((left, right, SHIFT / (length * length), "primal"))

    dual_weights = []
    for left in range(face_count):
        for right in range(left + SHIFT, face_count):
            if not complex_data["face_adjacency"][left][right]:
                continue
            shared_edges = complex_data["face_edge_sets"][left].intersection(complex_data["face_edge_sets"][right])
            if len(shared_edges) != SHIFT:
                raise RuntimeError("dual adjacent faces must share exactly one primal edge")
            shared_edge = next(iter(shared_edges))
            primal_length = primal_edge_lengths[shared_edge]
            dual_length = vector_norm(vector_subtract(face_centroids[left], face_centroids[right]))
            weight = dual_length / primal_length
            dual_weights.append(weight)
            weighted_connections.append((vertex_count + left, vertex_count + right, weight, "dual"))

    triangle_incidence_weights = []
    square_incidence_weights = []
    for face_index, face in enumerate(faces):
        for vertex_index in face["vertices"]:
            distance = vector_norm(vector_subtract(vertices[vertex_index], face_centroids[face_index]))
            weight = face_areas[face_index] / (float(len(face["vertices"])) * distance * distance)
            weighted_connections.append((vertex_index, vertex_count + face_index, weight, "incidence"))
            if face["type"] == "triangle":
                triangle_incidence_weights.append(weight)
            else:
                square_incidence_weights.append(weight)

    lower_rows = []
    cubic_rows = []
    for point in support_points:
        l0, l1, l2, l3 = _unit_harmonic_mode_blocks_float(point)
        lower_rows.append(tuple(l0 + l1 + l2))
        cubic_rows.append(tuple(l3))

    # Equal state/seat measure: every discrete direction counts once.
    lower_gram = [
        [sum(lower_rows[row][left] * lower_rows[row][right] for row in range(support_count)) for right in range(9)]
        for left in range(9)
    ]
    lower_cross_cubic = [
        [sum(lower_rows[row][left] * cubic_rows[row][right] for row in range(support_count)) for right in range(7)]
        for left in range(9)
    ]
    inverse_lower_gram = _dense_inverse_native(lower_gram)
    projection_coefficients = [
        [sum(inverse_lower_gram[row][middle] * lower_cross_cubic[middle][column] for middle in range(9)) for column in range(7)]
        for row in range(9)
    ]
    pure_cubic_rows = [
        [
            cubic_rows[row][column]
            - sum(lower_rows[row][lower] * projection_coefficients[lower][column] for lower in range(9))
            for column in range(7)
        ]
        for row in range(support_count)
    ]
    orthonormal_columns, projected_norms = _modified_gram_schmidt_columns_native(pure_cubic_rows)
    pure_rank = len(orthonormal_columns)
    lower_projection_residual = max(
        abs(sum(lower_rows[row][lower] * pure_cubic_rows[row][column] for row in range(support_count)))
        for lower in range(9)
        for column in range(7)
    )
    orthonormal_residual = max(
        abs(
            sum(orthonormal_columns[left][row] * orthonormal_columns[right][row] for row in range(support_count))
            - (1.0 if left == right else 0.0)
        )
        for left in range(pure_rank)
        for right in range(pure_rank)
    )

    weighted_laplacian = [[0.0 for _ in range(support_count)] for _ in range(support_count)]
    family_weight_sums = {"primal": 0.0, "dual": 0.0, "incidence": 0.0}
    for left, right, weight, family in weighted_connections:
        family_weight_sums[family] += weight
        weighted_laplacian[left][left] += weight
        weighted_laplacian[right][right] += weight
        weighted_laplacian[left][right] -= weight
        weighted_laplacian[right][left] -= weight

    pure_hessian = [
        [
            sum(
                orthonormal_columns[left][row]
                * sum(weighted_laplacian[row][column] * orthonormal_columns[right][column] for column in range(support_count))
                for row in range(support_count)
            )
            for right in range(pure_rank)
        ]
        for left in range(pure_rank)
    ]
    hessian_symmetry_residual = max(
        abs(pure_hessian[row][column] - pure_hessian[column][row])
        for row in range(pure_rank)
        for column in range(pure_rank)
    )
    eigensystem = _jacobi_symmetric_eigendecomposition_native(pure_hessian)
    spectral_clusters = _cluster_numeric_multiplicities_native(eigensystem["eigenvalues"], 1.0e-8)
    multiplicities = tuple(cluster[1] for cluster in spectral_clusters)
    two_channel_sector_sizes = tuple(DUAL * multiplicity for multiplicity in multiplicities)

    mode_functions = []
    for eigenvector in eigensystem["eigenvectors"]:
        mode_functions.append(tuple(
            sum(orthonormal_columns[basis][row] * eigenvector[basis] for basis in range(pure_rank))
            for row in range(support_count)
        ))

    density_overlap = [[0.0 for _ in range(pure_rank)] for _ in range(pure_rank)]
    wedge_overlap = [[0.0 for _ in range(pure_rank)] for _ in range(pure_rank)]
    for left in range(pure_rank):
        for right in range(pure_rank):
            density_overlap[left][right] = sum(
                mode_functions[left][row] * mode_functions[left][row]
                * mode_functions[right][row] * mode_functions[right][row]
                for row in range(support_count)
            )
            wedge_overlap[left][right] = sum(
                weight * (
                    mode_functions[left][u] * mode_functions[right][v]
                    - mode_functions[left][v] * mode_functions[right][u]
                ) ** DUAL
                for u, v, weight, _family in weighted_connections
            )

    orbital_count = pure_rank
    state_count = DUAL * orbital_count
    one_body_energies = tuple(
        float(eigensystem["eigenvalues"][orbital])
        for orbital in range(orbital_count)
        for _channel in range(DUAL)
    )
    pair_matrix = [[0.0 for _ in range(state_count)] for _ in range(state_count)]
    for left in range(state_count):
        left_orbital, left_channel = divmod(left, DUAL)
        for right in range(left + SHIFT, state_count):
            right_orbital, right_channel = divmod(right, DUAL)
            direct = density_overlap[left_orbital][right_orbital] + wedge_overlap[left_orbital][right_orbital]
            opposite_channel_same_mode_closure = (
                1.0 if left_orbital == right_orbital and left_channel != right_channel else 0.0
            )
            pair_matrix[left][right] = direct - opposite_channel_same_mode_closure
            pair_matrix[right][left] = pair_matrix[left][right]

    configuration_count = SHIFT << state_count
    best_energy = [float("inf") for _ in range(state_count + SHIFT)]
    minimizing_masks: List[List[int]] = [[] for _ in range(state_count + SHIFT)]
    all_energies = [0.0 for _ in range(configuration_count)]
    exchange_residual = 0.0

    def mask_energy(mask: int) -> float:
        occupied = [state for state in range(state_count) if mask & (SHIFT << state)]
        value = sum(one_body_energies[state] for state in occupied)
        for left_index in range(len(occupied)):
            for right_index in range(left_index + SHIFT, len(occupied)):
                value += pair_matrix[occupied[left_index]][occupied[right_index]]
        return value

    for mask in range(configuration_count):
        energy = mask_energy(mask)
        all_energies[mask] = energy
        occupied_count = mask.bit_count()
        if energy < best_energy[occupied_count] - 1.0e-11:
            best_energy[occupied_count] = energy
            minimizing_masks[occupied_count] = [mask]
        elif abs(energy - best_energy[occupied_count]) <= 1.0e-11:
            minimizing_masks[occupied_count].append(mask)

        exchanged = 0
        for orbital in range(orbital_count):
            if mask & (SHIFT << (DUAL * orbital)):
                exchanged |= SHIFT << (DUAL * orbital + SHIFT)
            if mask & (SHIFT << (DUAL * orbital + SHIFT)):
                exchanged |= SHIFT << (DUAL * orbital)
        if exchanged <= mask:
            exchange_residual = max(exchange_residual, abs(energy - mask_energy(exchanged)))

    cluster_ranges = []
    cursor = 0
    for _value, multiplicity in spectral_clusters:
        cluster_ranges.append((cursor, cursor + multiplicity))
        cursor += multiplicity

    occupancy_rows = []
    sector_pattern_unique = True
    removal_gaps = [0.0]
    previous_energy = best_energy[0]
    for occupied_count in range(state_count + SHIFT):
        masks = minimizing_masks[occupied_count]
        patterns = set()
        paired_orbital_counts = set()
        for mask in masks:
            sector_counts = tuple(
                sum(
                    SHIFT
                    for state in range(state_count)
                    if mask & (SHIFT << state) and start <= state // DUAL < stop
                )
                for start, stop in cluster_ranges
            )
            patterns.add(sector_counts)
            paired_orbital_counts.add(sum(
                SHIFT
                for orbital in range(orbital_count)
                if (mask & (SHIFT << (DUAL * orbital))) and (mask & (SHIFT << (DUAL * orbital + SHIFT)))
            ))
        sector_pattern_unique = sector_pattern_unique and len(patterns) == SHIFT
        canonical_mask = min(masks)
        canonical_states = tuple(state for state in range(state_count) if canonical_mask & (SHIFT << state))
        if occupied_count > 0:
            removal_gaps.append(best_energy[occupied_count] - previous_energy)
        previous_energy = best_energy[occupied_count]
        occupancy_rows.append({
            "electron_count": occupied_count,
            "ground_energy": best_energy[occupied_count],
            "degeneracy": len(masks),
            "sector_patterns": tuple(sorted(patterns)),
            "paired_orbital_counts": tuple(sorted(paired_orbital_counts)),
            "canonical_mask": canonical_mask,
            "canonical_states": canonical_states,
        })

    expected_sector_sizes = (DUAL, 6, 6)
    closure_counts = {
        DUAL: expected_sector_sizes[:1] + (0, 0),
        DUAL + 6: expected_sector_sizes[:2] + (0,),
        state_count: expected_sector_sizes,
    }
    sector_closure_failures = 0
    for electron_count, expected in closure_counts.items():
        patterns = occupancy_rows[electron_count]["sector_patterns"]
        sector_closure_failures += int(patterns != (expected,))

    positive_removal_gaps = all(value > 0.0 for value in removal_gaps[SHIFT:])
    microscopic_unique = all(row["degeneracy"] == SHIFT for row in occupancy_rows)

    fourteen_rows = [row for row in occupancy_action["element_rows"] if row["block_size"] == C12 + DUAL]
    terminal_by_depth = {int(row["index"]): row for row in terminal_closure["rows"]}
    diagnostic_features = []
    diagnostic_values = []
    diagnostic_groups = []
    diagnostic_rows = []
    for row in fourteen_rows:
        electron_count = int(row["block_position"])
        depth = int(row["depth"])
        transfer = float(terminal_by_depth[depth]["raw_geometric_transfer_rms"])
        electron_burden = float(depth * depth) * transfer * transfer
        proton_burden = float(depth ** 4) * transfer * transfer
        radial_bottleneck = DUAL * electron_burden * proton_burden / (electron_burden + proton_burden)
        angular_gap = removal_gaps[electron_count]
        candidate = angular_gap * radial_bottleneck
        diagnostic_features.append(candidate)
        diagnostic_values.append(float(row["ion_actual"]))
        diagnostic_groups.append((int(row["depth"]), int(row["block_index"])))
        diagnostic_rows.append({
            "Z": int(row["z"]),
            "symbol": row["symbol"],
            "depth": depth,
            "block_position": electron_count,
            "angular_ground_removal_gap": angular_gap,
            "radial_bottleneck": radial_bottleneck,
            "combined_candidate": candidate,
            "ion_actual": float(row["ion_actual"]),
        })

    diagnostic_pearson = _finite_pearson(diagnostic_features, diagnostic_values)
    diagnostic_within = _group_centered_pearson(diagnostic_features, diagnostic_values, diagnostic_groups)
    diagnostic_gloo_rmse, diagnostic_gloo_mae = _group_leave_one_out_metrics(
        diagnostic_features, diagnostic_values, diagnostic_groups
    )
    diagnostic_predictions = [0.0 for _ in diagnostic_features]
    all_indices = list(range(len(diagnostic_features)))
    for group in sorted(set(diagnostic_groups)):
        test_indices = [index for index, value in enumerate(diagnostic_groups) if value == group]
        train_indices = [index for index in all_indices if diagnostic_groups[index] != group]
        slope, intercept = _finite_linear_fit(
            [diagnostic_features[index] for index in train_indices],
            [diagnostic_values[index] for index in train_indices],
        )
        for index in test_indices:
            diagnostic_predictions[index] = slope * diagnostic_features[index] + intercept
    diagnostic_prediction_correlation = _finite_pearson(diagnostic_predictions, diagnostic_values)

    geometry_gates = {
        "all primal edges have one native length": max(primal_edge_lengths) - min(primal_edge_lengths) < 1.0e-12,
        "eight triangles have one area": max(triangle_areas) - min(triangle_areas) < 1.0e-12,
        "six squares have one area": max(square_areas) - min(square_areas) < 1.0e-12,
        "all geometry-derived connection weights are positive": all(weight > 0.0 for _u, _v, weight, _family in weighted_connections),
        "pure l3 projection remains rank seven": pure_rank == 7,
        "weighted l3 Hessian is symmetric": hessian_symmetry_residual < 1.0e-12,
        "weighted spectrum has one plus three plus three multiplicities": multiplicities == (SHIFT, 3, 3),
        "A/B doubling gives two plus six plus six states": two_channel_sector_sizes == expected_sector_sizes,
    }
    occupancy_gates = {
        "all two-to-the-fourteen configurations enumerated": configuration_count == DUAL ** (DUAL * 7),
        "one ground-state sector pattern exists for every electron count": sector_pattern_unique,
        "two/six/six sectors saturate at counts two/eight/fourteen": sector_closure_failures == 0,
        "all successive ground-state removal gaps are positive": positive_removal_gaps,
        "A/B exchange leaves every configuration energy invariant": exchange_residual < 1.0e-12,
    }
    geometry_closed = all(geometry_gates.values())
    occupancy_sector_closed = all(occupancy_gates.values())

    return {
        "support_count": support_count,
        "primal_edge_length": _finite_mean(primal_edge_lengths),
        "triangle_area": _finite_mean(triangle_areas),
        "square_area": _finite_mean(square_areas),
        "primal_edge_weight": _finite_mean([weight for _u, _v, weight, family in weighted_connections if family == "primal"]),
        "dual_edge_weight": _finite_mean(dual_weights),
        "triangle_incidence_weight": _finite_mean(triangle_incidence_weights),
        "square_incidence_weight": _finite_mean(square_incidence_weights),
        "family_weight_sums": family_weight_sums,
        "seat_measure": "UNIFORM_ONE_PER_DIRECTIONAL_STATE",
        "projected_norms": projected_norms,
        "lower_projection_residual": lower_projection_residual,
        "pure_rank": pure_rank,
        "orthonormal_residual": orthonormal_residual,
        "weighted_hessian": tuple(tuple(value for value in row) for row in pure_hessian),
        "hessian_symmetry_residual": hessian_symmetry_residual,
        "weighted_eigenvalues": eigensystem["eigenvalues"],
        "weighted_eigen_residual": eigensystem["maximum_residual"],
        "spectral_clusters": spectral_clusters,
        "multiplicities": multiplicities,
        "two_channel_sector_sizes": two_channel_sector_sizes,
        "density_overlap": tuple(tuple(value for value in row) for row in density_overlap),
        "wedge_overlap": tuple(tuple(value for value in row) for row in wedge_overlap),
        "one_body_energies": one_body_energies,
        "pair_matrix": tuple(tuple(value for value in row) for row in pair_matrix),
        "configuration_count": configuration_count,
        "occupancy_rows": tuple(occupancy_rows),
        "removal_gaps": tuple(removal_gaps),
        "sector_pattern_unique": sector_pattern_unique,
        "sector_closure_failures": sector_closure_failures,
        "positive_removal_gaps": positive_removal_gaps,
        "channel_exchange_residual": exchange_residual,
        "microscopic_state_order_unique": microscopic_unique,
        "diagnostic_rows": tuple(diagnostic_rows),
        "diagnostic_pearson": diagnostic_pearson,
        "diagnostic_within_pearson": diagnostic_within,
        "diagnostic_gloo_rmse": diagnostic_gloo_rmse,
        "diagnostic_gloo_mae": diagnostic_gloo_mae,
        "diagnostic_prediction_correlation": diagnostic_prediction_correlation,
        "prior_unweighted_removal_gap_pearson": pure_l3["removal_gap_correlation"],
        "prior_unweighted_within_pearson": pure_l3["removal_gap_within_correlation"],
        "geometry_gates": geometry_gates,
        "occupancy_gates": occupancy_gates,
        "geometry_weight_construction_closed": geometry_closed,
        "sector_level_exhaustive_filling_closed": occupancy_sector_closed,
        "full_microscopic_orientation_order_closed": microscopic_unique,
        "global_discretization_uniqueness_closed": False,
        "absolute_ionization_prediction_closed": False,
        "status": "GEOMETRY_WEIGHTED_L3_EXHAUSTIVE_SECTOR_FILLING_GATE_PASS" if geometry_closed and occupancy_sector_closed else "GEOMETRY_WEIGHTED_L3_EXHAUSTIVE_OCCUPANCY_GATE_FAIL",
        "boundary": "native lengths, face areas and primal/dual/incidence ratios fix one explicit geometry-weighted Dirichlet action and exhaustive enumeration fixes the two-plus-six-plus-six sector occupancy path without observational feedback; symmetry leaves microscopic orientations degenerate, the choice of discrete Dirichlet/Hodge prescription is not yet globally unique, and absolute eV ionization remains open",
    }


