# ==================================================================================================
# 78. Native time / Clifford / gauge-algebra / normalization root-reduction audit
# ==================================================================================================


def native_time_clifford_gauge_root_reduction_lens(
    dual_holonomy: Dict[str, object],
    harmonic_capacity: Dict[str, object],
    master_action: Dict[str, object],
) -> Dict[str, object]:
    """Attack the four root ambiguities that block the strict Master Covariant Action theorem.

    No standard gamma, Pauli or Gell-Mann matrix is inserted.  Small integer matrices are
    exhaustively generated from the native two-channel signed-permutation grammar.  The audit
    separates what is actually generated from what remains absent.
    """

    def eye(n: int) -> Tuple[Tuple[int, ...], ...]:
        return tuple(tuple(SHIFT if i == j else 0 for j in range(n)) for i in range(n))

    def zeros(n: int, m: int) -> Tuple[Tuple[int, ...], ...]:
        return tuple(tuple(0 for _ in range(m)) for _ in range(n))

    def mt(a: Sequence[Sequence[int]]) -> Tuple[Tuple[int, ...], ...]:
        return tuple(tuple(a[i][j] for i in range(len(a))) for j in range(len(a[0])))

    def mm(a: Sequence[Sequence[int]], b: Sequence[Sequence[int]]) -> Tuple[Tuple[int, ...], ...]:
        return tuple(
            tuple(sum(a[i][k] * b[k][j] for k in range(len(b))) for j in range(len(b[0])))
            for i in range(len(a))
        )

    def ma(a: Sequence[Sequence[int]], b: Sequence[Sequence[int]]) -> Tuple[Tuple[int, ...], ...]:
        return tuple(tuple(a[i][j] + b[i][j] for j in range(len(a[0]))) for i in range(len(a)))

    def ms(c: int, a: Sequence[Sequence[int]]) -> Tuple[Tuple[int, ...], ...]:
        return tuple(tuple(c * a[i][j] for j in range(len(a[0]))) for i in range(len(a)))

    def kron(a: Sequence[Sequence[int]], b: Sequence[Sequence[int]]) -> Tuple[Tuple[int, ...], ...]:
        return tuple(
            tuple(a[i][j] * b[p][q] for j in range(len(a[0])) for q in range(len(b[0])))
            for i in range(len(a)) for p in range(len(b))
        )

    def flat(a: Sequence[Sequence[int]]) -> Tuple[int, ...]:
        return tuple(value for row in a for value in row)

    def canonical_sign(a: Sequence[Sequence[int]]) -> Tuple[int, ...]:
        positive = flat(a)
        negative = tuple(-value for value in positive)
        return min(positive, negative)

    def square_sign(a: Sequence[Sequence[int]]) -> int:
        n = len(a)
        sq = mm(a, a)
        if sq == eye(n):
            return SHIFT
        if sq == ms(-SHIFT, eye(n)):
            return -SHIFT
        return 0

    def signed_permutation_matrices(n: int) -> Tuple[Tuple[Tuple[int, ...], ...], ...]:
        rows = []
        for permutation in itertools.permutations(range(n)):
            for signs in itertools.product((-SHIFT, SHIFT), repeat=n):
                matrix = [[0 for _ in range(n)] for _ in range(n)]
                for i, j in enumerate(permutation):
                    matrix[i][j] = signs[i]
                rows.append(tuple(tuple(row) for row in matrix))
        return tuple(rows)

    # ----------------------------------------------------------------------------------------------
    # Unique evolution parameter in the declared local linear norm-preserving two-channel grammar.
    # ----------------------------------------------------------------------------------------------
    two_by_two = []
    for entries in itertools.product((-SHIFT, 0, SHIFT), repeat=4):
        matrix = ((entries[0], entries[1]), (entries[2], entries[3]))
        skew_residual = ma(mt(matrix), matrix)
        if matrix != zeros(DUAL, DUAL) and skew_residual == zeros(DUAL, DUAL):
            two_by_two.append(matrix)
    skew_generator_representatives = tuple(sorted({canonical_sign(matrix) for matrix in two_by_two}))
    skew_generator_orbit_count = len(skew_generator_representatives)
    canonical_j_flat = skew_generator_representatives[0]
    J = (canonical_j_flat[:DUAL], canonical_j_flat[DUAL:])
    j_square_residual = ma(mm(J, J), eye(DUAL))

    def cayley(parameter: Fraction) -> Tuple[Tuple[Fraction, ...], ...]:
        denominator = Fraction(SHIFT) + parameter * parameter
        a = (Fraction(SHIFT) - parameter * parameter) / denominator
        b = (Fraction(DUAL) * parameter) / denominator
        return ((a, -b), (b, a))

    def mm_fraction(a, b):
        return tuple(
            tuple(sum(a[i][k] * b[k][j] for k in range(len(b))) for j in range(len(b[0])))
            for i in range(len(a))
        )

    u = Fraction(SHIFT, DUAL)
    v = Fraction(SHIFT, 3)
    composed_parameter = (u + v) / (Fraction(SHIFT) - u * v)
    cayley_composition_residual = max(
        abs(mm_fraction(cayley(u), cayley(v))[i][j] - cayley(composed_parameter)[i][j])
        for i in range(DUAL) for j in range(DUAL)
    )
    unique_time_parameter_closed = bool(
        skew_generator_orbit_count == SHIFT
        and j_square_residual == zeros(DUAL, DUAL)
        and cayley_composition_residual == 0
    )

    # ----------------------------------------------------------------------------------------------
    # Local principal-signature selection.  The 12 directions provide an isotropic positive
    # spatial quadratic form.  Hyperbolicity plus positive canonical energy selects one opposite
    # temporal sign, up to an irrelevant global sign convention.
    # ----------------------------------------------------------------------------------------------
    vertices = dual_holonomy["complex"]["vertices"]
    spatial_moment = tuple(
        tuple(
            sum(Fraction(vertex[i] * vertex[j], sum(value * value for value in vertex)) for vertex in vertices)
            / Fraction(len(vertices))
            for j in range(3)
        )
        for i in range(3)
    )
    spatial_isotropy_residual = max(
        abs(spatial_moment[i][j] - (Fraction(SHIFT, 3) if i == j else Fraction(0)))
        for i in range(3) for j in range(3)
    )
    signature_rows = []
    for time_sign in (-SHIFT, SHIFT):
        for space_sign in (-SHIFT, SHIFT):
            hyperbolic = time_sign * space_sign < 0
            positive_hamiltonian = time_sign > 0 and -space_sign > 0
            accepted = hyperbolic and positive_hamiltonian and spatial_isotropy_residual == 0
            signature_rows.append((time_sign, space_sign, hyperbolic, positive_hamiltonian, accepted))
    accepted_signatures = tuple((row[0], row[1]) for row in signature_rows if row[4])
    local_one_plus_three_signature_unique = len(accepted_signatures) == SHIFT

    # ----------------------------------------------------------------------------------------------
    # Generate the smallest real Clifford carrier from two native binary factors.  The first is
    # A/B.  The second is the orientation double-cover sheet.  All matrices are generated from
    # 2x2 signed permutations; no standard gamma matrices are supplied.
    # ----------------------------------------------------------------------------------------------
    signed2 = signed_permutation_matrices(DUAL)
    I2 = eye(DUAL)
    complex_structures = [m for m in signed2 if square_sign(m) == -SHIFT]
    J2 = min(complex_structures, key=canonical_sign)
    involution_reps = {}
    for matrix in signed2:
        if matrix == mt(matrix) and square_sign(matrix) == SHIFT and sum(matrix[i][i] for i in range(DUAL)) == 0:
            involution_reps[canonical_sign(matrix)] = matrix
    involutions = tuple(involution_reps[key] for key in sorted(involution_reps))
    binary_basis = (("I", I2), ("S0", involutions[0]), ("S1", involutions[1]), ("J", J2))
    tensor_basis = tuple((left_name + right_name, kron(left, right)) for left_name, left in binary_basis for right_name, right in binary_basis)
    nontrivial = tuple((name, matrix, square_sign(matrix)) for name, matrix in tensor_basis if name != "II" and square_sign(matrix) != 0)

    clifford_solutions = []
    for combination in itertools.combinations(nontrivial, 4):
        signs = [entry[2] for entry in combination]
        if signs.count(-SHIFT) != SHIFT or signs.count(SHIFT) != 3:
            continue
        pairwise = all(
            ma(mm(combination[i][1], combination[j][1]), mm(combination[j][1], combination[i][1])) == zeros(4, 4)
            for i in range(4) for j in range(i + SHIFT, 4)
        )
        if pairwise:
            clifford_solutions.append(combination)

    def clifford_key(solution) -> Tuple[Tuple[int, ...], Tuple[Tuple[int, ...], ...]]:
        time_matrix = next(entry[1] for entry in solution if entry[2] == -SHIFT)
        spatial_matrices = [entry[1] for entry in solution if entry[2] == SHIFT]
        return canonical_sign(time_matrix), tuple(sorted(canonical_sign(matrix) for matrix in spatial_matrices))

    signed4 = signed_permutation_matrices(4)
    remaining = set(range(len(clifford_solutions)))
    clifford_orbits = []
    while remaining:
        seed_index = min(remaining)
        seed = clifford_solutions[seed_index]
        time_matrix = next(entry[1] for entry in seed if entry[2] == -SHIFT)
        spatial_matrices = [entry[1] for entry in seed if entry[2] == SHIFT]
        orbit_keys = set()
        for transform in signed4:
            inverse = mt(transform)
            transformed_time = mm(mm(transform, time_matrix), inverse)
            transformed_space = [mm(mm(transform, matrix), inverse) for matrix in spatial_matrices]
            orbit_keys.add((canonical_sign(transformed_time), tuple(sorted(canonical_sign(matrix) for matrix in transformed_space))))
        orbit_members = {index for index, solution in enumerate(clifford_solutions) if clifford_key(solution) in orbit_keys}
        clifford_orbits.append(tuple(sorted(orbit_members)))
        remaining -= orbit_members

    clifford_unique_orbit = len(clifford_orbits) == SHIFT and len(clifford_solutions) > 0
    representative = clifford_solutions[0]
    gamma_time = next(entry[1] for entry in representative if entry[2] == -SHIFT)
    gamma_space = [entry[1] for entry in representative if entry[2] == SHIFT]
    bivector = mm(gamma_space[0], gamma_space[1])
    quarter_numerator = ma(eye(4), bivector)
    quarter_fourth = mm(mm(quarter_numerator, quarter_numerator), mm(quarter_numerator, quarter_numerator))
    spinor_full_turn_polynomial_residual = ma(quarter_fourth, ms(4, eye(4)))
    spinor_full_turn_minus_identity = spinor_full_turn_polynomial_residual == zeros(4, 4)
    integer_l3_full_turn_sign = (-SHIFT) ** (DUAL * 3)
    ab_vector_full_turn_sign = SHIFT
    l3_or_ab_alone_spinor_no_go = integer_l3_full_turn_sign == SHIFT and ab_vector_full_turn_sign == SHIFT

    # ----------------------------------------------------------------------------------------------
    # Partial internal gauge algebra.  U(1) is the one-dimensional phase generator.  The 4-real
    # carrier contains two commuting quaternionic SU(2) triples (left/right).  Choosing the weak
    # chiral copy still requires a native parity-breaking selector.  No independent complex
    # triplet carrier is present, so SU(3) remains open despite the native D8 dimension hint.
    # ----------------------------------------------------------------------------------------------
    negative_square = [(name, matrix) for name, matrix in tensor_basis if square_sign(matrix) == -SHIFT]
    su2_triples = []
    for combination in itertools.combinations(negative_square, 3):
        matrices = [entry[1] for entry in combination]
        pairwise_anticommuting = all(
            ma(mm(matrices[i], matrices[j]), mm(matrices[j], matrices[i])) == zeros(4, 4)
            for i in range(3) for j in range(i + SHIFT, 3)
        )
        if not pairwise_anticommuting:
            continue
        closure = all(
            any(mm(matrices[i], matrices[j]) == candidate or mm(matrices[i], matrices[j]) == ms(-SHIFT, candidate) for candidate in matrices)
            for i, j in ((0, 1), (1, 2), (2, 0))
        )
        if closure:
            su2_triples.append(combination)
    su2_pair_commutation_residual = None
    if len(su2_triples) == DUAL:
        residuals = []
        for left in su2_triples[0]:
            for right in su2_triples[1]:
                residuals.extend(abs(value) for value in flat(ma(mm(left[1], right[1]), ms(-SHIFT, mm(right[1], left[1])))))
        su2_pair_commutation_residual = max(residuals)
    u1_generator_count = skew_generator_orbit_count
    u1_native_closed = u1_generator_count == SHIFT
    su2_algebra_pair_generated = len(su2_triples) == DUAL and su2_pair_commutation_residual == 0
    weak_chiral_su2_copy_unique = False

    # Proper signed coordinate permutations act nontrivially on the three zero-axis classes;
    # those classes are spatial, not an internal color triplet commuting with rotations.
    nontrivial_zero_axis_actions = 0
    proper_rotation_count = 0
    for permutation in itertools.permutations(range(3)):
        parity_inversions = sum(permutation[i] > permutation[j] for i in range(3) for j in range(i + SHIFT, 3))
        permutation_sign = -SHIFT if parity_inversions % DUAL else SHIFT
        for signs in itertools.product((-SHIFT, SHIFT), repeat=3):
            determinant = permutation_sign * signs[0] * signs[1] * signs[2]
            if determinant != SHIFT:
                continue
            proper_rotation_count += SHIFT
            if tuple(permutation) != tuple(range(3)):
                nontrivial_zero_axis_actions += SHIFT
    zero_axis_triplet_commutes_with_spatial_rotations = nontrivial_zero_axis_actions == 0
    available_internal_complex_carrier_dimensions = (SHIFT, DUAL)
    su3_complex_triplet_carrier_present = 3 in available_internal_complex_carrier_dimensions and zero_axis_triplet_commutes_with_spatial_rotations
    full_product_gauge_algebra_closed = bool(u1_native_closed and su2_algebra_pair_generated and weak_chiral_su2_copy_unique and su3_complex_triplet_carrier_present)

    # ----------------------------------------------------------------------------------------------
    # Maxwell and Palatini cell-content audit.  The native chain complex gives a genuine spatial
    # Abelian curvature operator.  It has no temporal plaquettes and no 3/4-cells, so the full
    # spacetime Maxwell and Palatini actions cannot yet be claimed native.
    # ----------------------------------------------------------------------------------------------
    complex_data = dual_holonomy["complex"]
    b1 = complex_data["vertex_edge_incidence"]
    b2 = complex_data["face_edge_incidence"]
    boundary_boundary = _fraction_matrix_multiply_native(b2, b1)
    boundary_boundary_residual = max(abs(value) for row in boundary_boundary for value in row)
    spatial_abelian_curvature_native = boundary_boundary_residual == 0 and dual_holonomy["gauge_action_residual"] == 0
    face_orbit_count = len({face["type"] for face in complex_data["faces"]})
    gauge_quadratic_form_unique_without_hodge = face_orbit_count == SHIFT
    temporal_plaquette_count = 0
    full_spacetime_maxwell_native = bool(spatial_abelian_curvature_native and temporal_plaquette_count > 0 and gauge_quadratic_form_unique_without_hodge)
    chain_max_degree = DUAL
    native_three_cell_count = 0
    native_four_cell_count = 0
    discrete_palatini_native = native_four_cell_count > 0 and native_three_cell_count > 0

    # ----------------------------------------------------------------------------------------------
    # Relative normalization.  All assembled sectors are connected by interaction/stress-energy
    # couplings, so their relative normalization has one null direction: one overall action/unit
    # scale.  That remaining scale is an external decoder and does not feed back into generation.
    # ----------------------------------------------------------------------------------------------
    normalization_nodes = ("route", "matter", "U1", "SU2", "SU3", "weak_scalar", "metric")
    normalization_edges = (
        ("route", "matter"),
        ("matter", "U1"),
        ("matter", "SU2"),
        ("matter", "SU3"),
        ("matter", "weak_scalar"),
        ("matter", "metric"),
        ("U1", "metric"),
        ("SU2", "metric"),
        ("SU3", "metric"),
        ("weak_scalar", "metric"),
    )
    node_index = {name: index for index, name in enumerate(normalization_nodes)}
    normalization_matrix = []
    for left, right in normalization_edges:
        row = [Fraction(0) for _ in normalization_nodes]
        row[node_index[left]] = Fraction(SHIFT)
        row[node_index[right]] = Fraction(-SHIFT)
        normalization_matrix.append(row)
    normalization_rank = fraction_rank(normalization_matrix)
    normalization_nullity = len(normalization_nodes) - normalization_rank
    relative_normalization_unique_up_to_global_scale = normalization_nullity == SHIFT
    absolute_si_decoder_internal = False

    gates = {
        "one local norm-preserving two-channel evolution generator up to orientation": unique_time_parameter_closed,
        "internal phase is generated state coordinate rather than second time": cayley_composition_residual == 0,
        "twelve-direction spatial second moment is exactly isotropic": spatial_isotropy_residual == 0,
        "local positive-energy hyperbolic sign choice is unique": local_one_plus_three_signature_unique,
        "l3 and AB vector alone fail the spinor full-turn test": l3_or_ab_alone_spinor_no_go,
        "AB times orientation sheet generates one Clifford orbit": clifford_unique_orbit,
        "generated Clifford carrier has spinor minus sign under full turn": spinor_full_turn_minus_identity,
        "native U1 phase generator exists": u1_native_closed,
        "two commuting quaternionic SU2 copies are generated": su2_algebra_pair_generated,
        "zero-axis triplet is rejected as internal color carrier": not zero_axis_triplet_commutes_with_spatial_rotations,
        "spatial Abelian curvature is native": spatial_abelian_curvature_native,
        "relative normalization has exactly one global freedom": relative_normalization_unique_up_to_global_scale,
        "no false full product gauge closure": not full_product_gauge_algebra_closed,
        "no false full spacetime Maxwell closure": not full_spacetime_maxwell_native,
        "no false Palatini closure without 4-cells": not discrete_palatini_native,
    }
    audit_closed = all(gates.values())
    return {
        "skew_generator_count_before_orientation_quotient": len(two_by_two),
        "skew_generator_orbit_count": skew_generator_orbit_count,
        "j_square_residual": j_square_residual,
        "cayley_parameters": (u, v, composed_parameter),
        "cayley_composition_residual": cayley_composition_residual,
        "unique_time_parameter_closed": unique_time_parameter_closed,
        "spatial_second_moment": spatial_moment,
        "spatial_isotropy_residual": spatial_isotropy_residual,
        "signature_rows": tuple(signature_rows),
        "accepted_signatures": accepted_signatures,
        "local_one_plus_three_signature_unique": local_one_plus_three_signature_unique,
        "integer_l3_full_turn_sign": integer_l3_full_turn_sign,
        "ab_vector_full_turn_sign": ab_vector_full_turn_sign,
        "l3_or_ab_alone_spinor_no_go": l3_or_ab_alone_spinor_no_go,
        "clifford_solution_count": len(clifford_solutions),
        "clifford_orbit_count": len(clifford_orbits),
        "clifford_unique_orbit": clifford_unique_orbit,
        "representative_clifford_names": tuple(entry[0] for entry in representative),
        "representative_clifford_square_signs": tuple(entry[2] for entry in representative),
        "spinor_full_turn_polynomial_residual": spinor_full_turn_polynomial_residual,
        "spinor_full_turn_minus_identity": spinor_full_turn_minus_identity,
        "u1_generator_count": u1_generator_count,
        "u1_native_closed": u1_native_closed,
        "su2_triple_count": len(su2_triples),
        "su2_triples": tuple(tuple(entry[0] for entry in triple) for triple in su2_triples),
        "su2_pair_commutation_residual": su2_pair_commutation_residual,
        "su2_algebra_pair_generated": su2_algebra_pair_generated,
        "weak_chiral_su2_copy_unique": weak_chiral_su2_copy_unique,
        "proper_spatial_rotation_count": proper_rotation_count,
        "nontrivial_zero_axis_class_action_count": nontrivial_zero_axis_actions,
        "zero_axis_triplet_commutes_with_spatial_rotations": zero_axis_triplet_commutes_with_spatial_rotations,
        "available_internal_complex_carrier_dimensions": available_internal_complex_carrier_dimensions,
        "su3_dimension_hint": D8,
        "su3_complex_triplet_carrier_present": su3_complex_triplet_carrier_present,
        "full_product_gauge_algebra_closed": full_product_gauge_algebra_closed,
        "boundary_of_boundary_residual": boundary_boundary_residual,
        "face_orbit_count": face_orbit_count,
        "spatial_abelian_curvature_native": spatial_abelian_curvature_native,
        "gauge_quadratic_form_unique_without_hodge": gauge_quadratic_form_unique_without_hodge,
        "temporal_plaquette_count": temporal_plaquette_count,
        "full_spacetime_maxwell_native": full_spacetime_maxwell_native,
        "chain_max_degree": chain_max_degree,
        "native_three_cell_count": native_three_cell_count,
        "native_four_cell_count": native_four_cell_count,
        "discrete_palatini_native": discrete_palatini_native,
        "normalization_nodes": normalization_nodes,
        "normalization_edges": normalization_edges,
        "normalization_rank": normalization_rank,
        "normalization_nullity": normalization_nullity,
        "relative_normalization_unique_up_to_global_scale": relative_normalization_unique_up_to_global_scale,
        "absolute_si_decoder_internal": absolute_si_decoder_internal,
        "gates": gates,
        "audit_closed": audit_closed,
        "status": "NATIVE_TIME_CLIFFORD_PARTIAL_GAUGE_ROOT_REDUCTION_GATE_PASS" if audit_closed else "NATIVE_ROOT_REDUCTION_GATE_FAIL",
        "boundary": "the declared two-channel/local-linear grammar now yields one evolution parameter, a local 1+3 hyperbolic sign and one Clifford carrier orbit; U1 and two chiral SU2 copies are generated, but the weak chiral selector, an independent complex color triplet, temporal plaquettes, four-cells and a native Palatini variation remain open",
    }



# ==================================================================================================
# 80. Native filled three-ball and one-step spacetime Maxwell extrusion
# ==================================================================================================


def _native_filled_cuboctahedral_three_ball(
    boundary_complex: Dict[str, object],
) -> Dict[str, object]:
    """Cone the exact 12-24-14 boundary complex to one native center.

    The result is a finite three-ball.  No observed value or standard field equation enters.
    Boundary matrices use the same row-higher-cell / column-lower-cell convention as the prior
    vertex-edge-face complex.
    """
    boundary_vertices = boundary_complex["vertices"]
    boundary_edges = boundary_complex["edges"]
    boundary_faces = boundary_complex["faces"]
    boundary_b2 = boundary_complex["face_edge_incidence"]

    boundary_vertex_count = len(boundary_vertices)
    boundary_edge_count = len(boundary_edges)
    boundary_face_count = len(boundary_faces)
    center_vertex = boundary_vertex_count

    vertices = tuple(boundary_vertices) + ((0, 0, 0),)
    radial_edges = tuple((center_vertex, vertex) for vertex in range(boundary_vertex_count))
    edges = tuple(boundary_edges) + radial_edges
    vertex_count = len(vertices)
    edge_count = len(edges)

    # B1: edge -> oriented endpoint difference.
    b1 = [[Fraction(0) for _ in range(vertex_count)] for _ in range(edge_count)]
    for edge_id, (left, right) in enumerate(boundary_edges):
        b1[edge_id][left] = Fraction(-SHIFT)
        b1[edge_id][right] = Fraction(SHIFT)
    for vertex in range(boundary_vertex_count):
        edge_id = boundary_edge_count + vertex
        b1[edge_id][center_vertex] = Fraction(-SHIFT)
        b1[edge_id][vertex] = Fraction(SHIFT)

    # F2: fourteen outer faces plus one center-edge triangle for every boundary edge.
    outer_face_count = boundary_face_count
    internal_face_count = boundary_edge_count
    face_count = outer_face_count + internal_face_count
    b2 = [[Fraction(0) for _ in range(edge_count)] for _ in range(face_count)]
    for face in range(boundary_face_count):
        for edge in range(boundary_edge_count):
            b2[face][edge] = Fraction(boundary_b2[face][edge])
    for edge_id, (left, right) in enumerate(boundary_edges):
        face_id = outer_face_count + edge_id
        b2[face_id][edge_id] = Fraction(SHIFT)
        b2[face_id][boundary_edge_count + left] = Fraction(SHIFT)
        b2[face_id][boundary_edge_count + right] = Fraction(-SHIFT)

    # C3: cone over each oriented outer face.  Its boundary is outer face minus the signed
    # internal triangles over the outer-face boundary edges.
    cell_count = boundary_face_count
    b3 = [[Fraction(0) for _ in range(face_count)] for _ in range(cell_count)]
    for cell in range(cell_count):
        b3[cell][cell] = Fraction(SHIFT)
        for edge in range(boundary_edge_count):
            signed_edge = Fraction(boundary_b2[cell][edge])
            if signed_edge:
                b3[cell][outer_face_count + edge] = -signed_edge

    b2b1 = _fraction_matrix_multiply_native(b2, b1)
    b3b2 = _fraction_matrix_multiply_native(b3, b2)
    b2b1_residual = max(abs(value) for row in b2b1 for value in row)
    b3b2_residual = max(abs(value) for row in b3b2 for value in row)
    euler = vertex_count - edge_count + face_count - cell_count

    face_types = tuple(face["type"] for face in boundary_faces) + tuple(
        "radial_triangle" for _ in range(internal_face_count)
    )
    return {
        "vertices": vertices,
        "edges": edges,
        "face_types": face_types,
        "vertex_edge_incidence": tuple(tuple(value for value in row) for row in b1),
        "face_edge_incidence": tuple(tuple(value for value in row) for row in b2),
        "cell_face_incidence": tuple(tuple(value for value in row) for row in b3),
        "vertex_count": vertex_count,
        "edge_count": edge_count,
        "face_count": face_count,
        "cell_count": cell_count,
        "outer_face_count": outer_face_count,
        "internal_face_count": internal_face_count,
        "b2b1_residual": b2b1_residual,
        "b3b2_residual": b3b2_residual,
        "euler_characteristic": euler,
        "b1_rank": fraction_rank(b1),
        "b2_rank": fraction_rank(b2),
        "b3_rank": fraction_rank(b3),
    }


def _native_time_extrusion_of_three_ball(
    spatial: Dict[str, object],
) -> Dict[str, object]:
    """Form K x I for one native affine update step and construct B1..B4 exactly."""
    spatial_vertices = spatial["vertices"]
    spatial_edges = spatial["edges"]
    spatial_b1 = spatial["vertex_edge_incidence"]
    spatial_b2 = spatial["face_edge_incidence"]
    spatial_b3 = spatial["cell_face_incidence"]
    spatial_face_types = spatial["face_types"]

    nv = spatial["vertex_count"]
    ne = spatial["edge_count"]
    nf = spatial["face_count"]
    nc = spatial["cell_count"]

    vertex_count = DUAL * nv
    edge_count = DUAL * ne + nv
    face_count = DUAL * nf + ne
    three_cell_count = DUAL * nc + nf
    four_cell_count = nc

    e0 = 0
    e1 = ne
    et = DUAL * ne
    f0 = 0
    f1 = nf
    ft = DUAL * nf
    c0 = 0
    c1 = nc
    ct = DUAL * nc

    b1 = [[Fraction(0) for _ in range(vertex_count)] for _ in range(edge_count)]
    for time in range(DUAL):
        vertex_offset = time * nv
        edge_offset = time * ne
        for edge in range(ne):
            for vertex in range(nv):
                b1[edge_offset + edge][vertex_offset + vertex] = Fraction(spatial_b1[edge][vertex])
    for vertex in range(nv):
        b1[et + vertex][vertex] = Fraction(-SHIFT)
        b1[et + vertex][nv + vertex] = Fraction(SHIFT)

    b2 = [[Fraction(0) for _ in range(edge_count)] for _ in range(face_count)]
    for time in range(DUAL):
        face_offset = time * nf
        edge_offset = time * ne
        for face in range(nf):
            for edge in range(ne):
                b2[face_offset + face][edge_offset + edge] = Fraction(spatial_b2[face][edge])
    for edge, (left, right) in enumerate(spatial_edges):
        face = ft + edge
        b2[face][e0 + edge] = Fraction(SHIFT)
        b2[face][et + right] = Fraction(SHIFT)
        b2[face][e1 + edge] = Fraction(-SHIFT)
        b2[face][et + left] = Fraction(-SHIFT)

    b3 = [[Fraction(0) for _ in range(face_count)] for _ in range(three_cell_count)]
    for time in range(DUAL):
        cell_offset = time * nc
        face_offset = time * nf
        for cell in range(nc):
            for face in range(nf):
                b3[cell_offset + cell][face_offset + face] = Fraction(spatial_b3[cell][face])
    for face in range(nf):
        prism = ct + face
        b3[prism][f0 + face] = Fraction(-SHIFT)
        b3[prism][f1 + face] = Fraction(SHIFT)
        for edge in range(ne):
            signed_edge = Fraction(spatial_b2[face][edge])
            if signed_edge:
                b3[prism][ft + edge] = signed_edge

    b4 = [[Fraction(0) for _ in range(three_cell_count)] for _ in range(four_cell_count)]
    for cell in range(nc):
        b4[cell][c0 + cell] = Fraction(-SHIFT)
        b4[cell][c1 + cell] = Fraction(SHIFT)
        for face in range(nf):
            signed_face = Fraction(spatial_b3[cell][face])
            if signed_face:
                b4[cell][ct + face] = -signed_face

    b2b1 = _fraction_matrix_multiply_native(b2, b1)
    b3b2 = _fraction_matrix_multiply_native(b3, b2)
    b4b3 = _fraction_matrix_multiply_native(b4, b3)
    residual_21 = max(abs(value) for row in b2b1 for value in row)
    residual_32 = max(abs(value) for row in b3b2 for value in row)
    residual_43 = max(abs(value) for row in b4b3 for value in row)
    euler = vertex_count - edge_count + face_count - three_cell_count + four_cell_count

    face_types = (
        tuple("spatial_t0_" + face_type for face_type in spatial_face_types)
        + tuple("spatial_t1_" + face_type for face_type in spatial_face_types)
        + tuple("temporal_edge_rectangle" for _ in range(ne))
    )
    return {
        "vertex_count": vertex_count,
        "edge_count": edge_count,
        "face_count": face_count,
        "three_cell_count": three_cell_count,
        "four_cell_count": four_cell_count,
        "temporal_edge_count": nv,
        "temporal_plaquette_count": ne,
        "spatial_face_count_per_slice": nf,
        "spatial_three_cell_count_per_slice": nc,
        "vertex_edge_incidence": tuple(tuple(value for value in row) for row in b1),
        "face_edge_incidence": tuple(tuple(value for value in row) for row in b2),
        "three_cell_face_incidence": tuple(tuple(value for value in row) for row in b3),
        "four_cell_three_cell_incidence": tuple(tuple(value for value in row) for row in b4),
        "face_types": face_types,
        "face_offsets": (f0, f1, ft),
        "edge_offsets": (e0, e1, et),
        "three_cell_offsets": (c0, c1, ct),
        "b2b1_residual": residual_21,
        "b3b2_residual": residual_32,
        "b4b3_residual": residual_43,
        "euler_characteristic": euler,
    }


def native_spacetime_maxwell_extrusion_lens(
    dual_holonomy: Dict[str, object],
    root_audit: Dict[str, object],
) -> Dict[str, object]:
    """Derive a full one-slab Abelian spacetime action from the native chain complex.

    The construction includes scalar-potential gradients, spatial and temporal plaquettes,
    Bianchi identities, a Lorentz-signed quadratic action, exact gauge invariance, the variational
    Maxwell operator and exact current conservation.  The continuum convergence/uniqueness theorem
    remains explicitly separate.
    """
    boundary = dual_holonomy["complex"]
    spatial = _native_filled_cuboctahedral_three_ball(boundary)
    spacetime = _native_time_extrusion_of_three_ball(spatial)

    b1s = spatial["vertex_edge_incidence"]
    b2s = spatial["face_edge_incidence"]
    b1 = spacetime["vertex_edge_incidence"]
    b2 = spacetime["face_edge_incidence"]
    b3 = spacetime["three_cell_face_incidence"]

    # Electrostatic specialization: V is a native scalar 0-cochain.  E=-B1 V and B2 E=0.
    scalar_potential = tuple(Fraction(vertex[2]) for vertex in spatial["vertices"])
    electrostatic_gradient = _fraction_matrix_vector_native(b1s, scalar_potential)
    electrostatic_field = tuple(-value for value in electrostatic_gradient)
    electrostatic_curl = _fraction_matrix_vector_native(b2s, electrostatic_field)
    electrostatic_curl_residual = max(abs(value) for value in electrostatic_curl)
    equal_potential_edge_count = 0
    equal_potential_work_residual = Fraction(0)
    for edge, (left, right) in enumerate(spatial["edges"]):
        potential_difference = scalar_potential[right] - scalar_potential[left]
        if potential_difference == 0:
            equal_potential_edge_count += SHIFT
            equal_potential_work_residual = max(equal_potential_work_residual, abs(electrostatic_field[edge]))

    # Deterministic, observation-free spacetime connection and gauge parameter.
    edge_count = spacetime["edge_count"]
    vertex_count = spacetime["vertex_count"]
    connection = tuple(Fraction((7 * edge + 3) % 17 - 8, 17) for edge in range(edge_count))
    gauge_parameter = tuple(Fraction((5 * vertex + 1) % 13 - 6, 13) for vertex in range(vertex_count))
    curvature = tuple(_fraction_matrix_vector_native(b2, connection))
    gauge_gradient = _fraction_matrix_vector_native(b1, gauge_parameter)
    transformed_connection = tuple(connection[edge] + gauge_gradient[edge] for edge in range(edge_count))
    transformed_curvature = tuple(_fraction_matrix_vector_native(b2, transformed_connection))
    curvature_gauge_residual = max(abs(transformed_curvature[index] - curvature[index]) for index in range(len(curvature)))

    # Geometry-only squared-area Hodge weights.  Triangles have area^2=3/4, boundary squares 4,
    # and temporal rectangles length^2*dt^2=2 with dt=1 from the unique affine update step.
    hodge_weights = []
    lorentz_signs = []
    for face_type in spacetime["face_types"]:
        if face_type.endswith("triangle"):
            hodge_weights.append(Fraction(4, 3))
            lorentz_signs.append(SHIFT)
        elif face_type.endswith("square"):
            hodge_weights.append(Fraction(1, 4))
            lorentz_signs.append(SHIFT)
        elif face_type == "temporal_edge_rectangle":
            hodge_weights.append(Fraction(1, 2))
            lorentz_signs.append(-SHIFT)
        else:
            raise RuntimeError("unknown spacetime face type")
    signed_weights = tuple(Fraction(sign) * weight for sign, weight in zip(lorentz_signs, hodge_weights))

    def maxwell_action(edge_connection: Sequence[Fraction]) -> Fraction:
        field = _fraction_matrix_vector_native(b2, edge_connection)
        return sum(
            (signed_weights[face] * field[face] * field[face] for face in range(len(field))),
            Fraction(0),
        ) / Fraction(DUAL)

    base_action = maxwell_action(connection)
    transformed_action = maxwell_action(transformed_connection)
    action_gauge_residual = abs(transformed_action - base_action)

    weighted_curvature = [signed_weights[face] * curvature[face] for face in range(len(curvature))]
    maxwell_gradient = _fraction_transpose_vector_native(b2, weighted_curvature)
    current_conservation = _fraction_transpose_vector_native(b1, maxwell_gradient)
    current_conservation_residual = max(abs(value) for value in current_conservation)

    # Central variation is exact for the quadratic action.
    epsilon = Fraction(SHIFT, 10 ** 4)
    variation_residual = Fraction(0)
    for edge in range(edge_count):
        plus = list(connection)
        minus = list(connection)
        plus[edge] += epsilon
        minus[edge] -= epsilon
        numerical = (maxwell_action(tuple(plus)) - maxwell_action(tuple(minus))) / (DUAL * epsilon)
        variation_residual = max(variation_residual, abs(numerical - maxwell_gradient[edge]))

    # Homogeneous equations are the exact Bianchi chain B3 F=0.  The gauge-null identity is
    # M B1=0 for M=B2^T W B2, tested without assembling a standard continuum operator.
    bianchi = _fraction_matrix_vector_native(b3, curvature)
    bianchi_residual = max(abs(value) for value in bianchi)
    weighted_b2 = [
        [signed_weights[face] * Fraction(b2[face][edge]) for edge in range(edge_count)]
        for face in range(spacetime["face_count"])
    ]
    maxwell_operator = _fraction_matrix_multiply_native(
        tuple(tuple(Fraction(b2[face][edge]) for face in range(spacetime["face_count"])) for edge in range(edge_count)),
        weighted_b2,
    )
    gauge_null = _fraction_matrix_multiply_native(maxwell_operator, b1)
    gauge_null_residual = max(abs(value) for row in gauge_null for value in row)

    f0, f1, ft = spacetime["face_offsets"]
    spatial_curvature_count = DUAL * spacetime["spatial_face_count_per_slice"]
    electric_curvatures = curvature[ft:]
    magnetic_curvatures = curvature[:spatial_curvature_count]
    positive_field_energy = (
        sum((hodge_weights[index] * curvature[index] * curvature[index] for index in range(spatial_curvature_count)), Fraction(0))
        + sum((hodge_weights[ft + index] * electric_curvatures[index] * electric_curvatures[index] for index in range(len(electric_curvatures))), Fraction(0))
    ) / Fraction(DUAL)

    filled_three_ball_closed = bool(
        spatial["vertex_count"] == 13
        and spatial["edge_count"] == 36
        and spatial["face_count"] == 38
        and spatial["cell_count"] == 14
        and spatial["euler_characteristic"] == SHIFT
        and spatial["b2b1_residual"] == 0
        and spatial["b3b2_residual"] == 0
    )
    spacetime_chain_closed = bool(
        spacetime["vertex_count"] == 26
        and spacetime["edge_count"] == 85
        and spacetime["face_count"] == 112
        and spacetime["three_cell_count"] == 66
        and spacetime["four_cell_count"] == 14
        and spacetime["euler_characteristic"] == SHIFT
        and spacetime["b2b1_residual"] == 0
        and spacetime["b3b2_residual"] == 0
        and spacetime["b4b3_residual"] == 0
    )
    native_discrete_maxwell_closed = bool(
        filled_three_ball_closed
        and spacetime_chain_closed
        and root_audit["unique_time_parameter_closed"]
        and root_audit["local_one_plus_three_signature_unique"]
        and electrostatic_curl_residual == 0
        and equal_potential_edge_count > 0
        and equal_potential_work_residual == 0
        and curvature_gauge_residual == 0
        and action_gauge_residual == 0
        and bianchi_residual == 0
        and variation_residual == 0
        and current_conservation_residual == 0
        and gauge_null_residual == 0
        and spacetime["temporal_plaquette_count"] > 0
        and spacetime["four_cell_count"] > 0
    )
    continuum_maxwell_operator_uniqueness_closed = False
    gates = {
        "filled native cuboctahedral boundary is an exact three-ball": filled_three_ball_closed,
        "one native time step creates an exact four-dimensional chain": spacetime_chain_closed,
        "electrostatic field is minus the native scalar-potential gradient": electrostatic_curl_residual == 0,
        "equal-potential edges have exactly zero electric work": equal_potential_edge_count > 0 and equal_potential_work_residual == 0,
        "spacetime curvature is exactly gauge invariant": curvature_gauge_residual == 0,
        "Lorentz-signed quadratic Abelian action is exactly gauge invariant": action_gauge_residual == 0,
        "homogeneous Maxwell/Bianchi chain closes exactly": bianchi_residual == 0,
        "analytic action variation equals central variation": variation_residual == 0,
        "variational current is exactly conserved": current_conservation_residual == 0,
        "Maxwell operator annihilates every pure gauge gradient": gauge_null_residual == 0,
        "temporal plaquettes and four-cells are actually present": spacetime["temporal_plaquette_count"] > 0 and spacetime["four_cell_count"] > 0,
        "no false continuum-operator uniqueness claim": not continuum_maxwell_operator_uniqueness_closed,
    }
    audit_closed = all(gates.values())
    return {
        "spatial": spatial,
        "spacetime": spacetime,
        "scalar_potential": scalar_potential,
        "electrostatic_field": electrostatic_field,
        "electrostatic_curl_residual": electrostatic_curl_residual,
        "equal_potential_edge_count": equal_potential_edge_count,
        "equal_potential_work_residual": equal_potential_work_residual,
        "curvature_gauge_residual": curvature_gauge_residual,
        "action_gauge_residual": action_gauge_residual,
        "bianchi_residual": bianchi_residual,
        "variation_residual": variation_residual,
        "current_conservation_residual": current_conservation_residual,
        "gauge_null_residual": gauge_null_residual,
        "spatial_curvature_count": len(magnetic_curvatures),
        "temporal_curvature_count": len(electric_curvatures),
        "positive_field_energy": positive_field_energy,
        "lorentz_signed_action": base_action,
        "hodge_weights": tuple(hodge_weights),
        "filled_three_ball_closed": filled_three_ball_closed,
        "spacetime_chain_closed": spacetime_chain_closed,
        "native_discrete_maxwell_closed": native_discrete_maxwell_closed,
        "continuum_maxwell_operator_uniqueness_closed": continuum_maxwell_operator_uniqueness_closed,
        "gates": gates,
        "audit_closed": audit_closed,
        "status": "NATIVE_ONE_SLAB_SPACETIME_MAXWELL_ACTION_GATE_PASS" if audit_closed else "SPACETIME_MAXWELL_EXTRUSION_GATE_FAIL",
        "boundary": "the code now derives a complete finite one-slab U1 electric/magnetic chain, exact gauge action, Bianchi identities, variational Maxwell operator and conserved current from the ledger complex; convergence to a unique continuum F_mu_nu F^mu_nu normalization and the non-Abelian/Palatini sectors remain open",
    }




# ==================================================================================================
# 80. Multi-slab / Hodge / matter-current / Palatini-precursor audit
