def master_covariant_action_theorem_closure_audit_lens(
    dimcore: Dict[str, object],
    constitution: Dict[str, object],
    byteaudit: Dict[str, object],
    master_action: Dict[str, object],
    operator_basis: Dict[str, object],
    coefficient_genealogy: Dict[str, object],
    strict_parent_gate: Dict[str, object],
    strict_coupled_gate: Dict[str, object],
    strict_chiral_gate: Dict[str, object],
    strict_generation_gate: Dict[str, object],
    dual_holonomy: Dict[str, object],
    harmonic_capacity: Dict[str, object],
    shell_master: Dict[str, object],
    lorentz: Dict[str, object],
) -> Dict[str, object]:
    """Audit the exact theorem requested by the manuscript program.

    The theorem is deliberately stricter than an executable standard-theory bridge:

      dimensionless closed ledger
        -> unique continuum field dictionary
        -> one Lorentz/gauge invariant native action
        -> variation
        -> matter, electromagnetic, weak, strong and gravitational equations.

    A clause is counted as STRICT only when its form is generated from the native ledger.
    A clause may be executable and algebraically correct yet remain BRIDGED when a standard
    continuum operator template was supplied before the native discrete-to-continuum map was
    uniquely derived.  This prevents a classical-variation success from being mislabeled as
    a complete origin theorem.
    """

    # Finite field-dictionary grammar.  These are structural sectors recomputed from the
    # current code's chain complex and harmonic ranks; no previous output is read.
    sectors = (
        {"name": "C0_l0_scalar", "cochain": 0, "parity": "even", "rank": harmonic_capacity["incremental_ranks"]["combined"][0], "tags": ("scalar", "site")},
        {"name": "C0_l1_vector", "cochain": 0, "parity": "odd", "rank": harmonic_capacity["incremental_ranks"]["combined"][1], "tags": ("polar_vector", "site")},
        {"name": "C0_l2_shear", "cochain": 0, "parity": "even", "rank": harmonic_capacity["incremental_ranks"]["combined"][2], "tags": ("symmetric_traceless", "site")},
        {"name": "C0_l3_orbital", "cochain": 0, "parity": "odd", "rank": harmonic_capacity["incremental_ranks"]["combined"][3], "tags": ("cubic_orbital", "site", "spinor_candidate")},
        {"name": "C1_edge_connection", "cochain": 1, "parity": "oriented", "rank": len(dual_holonomy["complex"]["edges"]), "tags": ("connection", "gauge_shift", "spin_connection_candidate")},
        {"name": "C2_face_curvature", "cochain": 2, "parity": "oriented", "rank": dual_holonomy["independent_face_curvature_count"], "tags": ("curvature", "holonomy")},
        {"name": "radial_depth_board", "cochain": -1, "parity": "mirror", "rank": len(harmonic_capacity["depth_rows"]), "tags": ("radial", "green_transfer")},
        {"name": "A_B_internal_doublet", "cochain": -2, "parity": "internal", "rank": DUAL, "tags": ("internal_doublet", "spinor_candidate", "phase_axis_candidate")},
        {"name": "recursive_update_axis", "cochain": -3, "parity": "directed", "rank": SHIFT, "tags": ("time_candidate", "evolution")},
        {"name": "internal_phase_update_axis", "cochain": -4, "parity": "directed", "rank": SHIFT, "tags": ("time_candidate", "phase_axis_candidate", "evolution")},
        {"name": "edge_U1_algebra_candidate", "cochain": 1, "parity": "internal", "rank": SHIFT, "tags": ("gauge_algebra_candidate",)},
        {"name": "edge_SU2_algebra_candidate", "cochain": 1, "parity": "internal", "rank": 3, "tags": ("gauge_algebra_candidate",)},
        {"name": "edge_SU3_algebra_candidate", "cochain": 1, "parity": "internal", "rank": D8, "tags": ("gauge_algebra_candidate",)},
    )

    def select(**requirements: object) -> Tuple[str, ...]:
        selected = []
        for sector in sectors:
            ok = True
            for key, expected in requirements.items():
                if key == "tag":
                    ok = ok and str(expected) in sector["tags"]
                else:
                    ok = ok and sector[key] == expected
            if ok:
                selected.append(str(sector["name"]))
        return tuple(selected)

    dictionary_roles = (
        ("closure scalar", select(cochain=0, parity="even", rank=SHIFT, tag="scalar")),
        ("three spatial frame directions", select(cochain=0, parity="odd", rank=3, tag="polar_vector")),
        ("five metric-shear directions", select(cochain=0, parity="even", rank=5, tag="symmetric_traceless")),
        ("seven cubic orbital directions", select(cochain=0, parity="odd", rank=7, tag="cubic_orbital")),
        ("gauge connection one-cochain", select(cochain=1, tag="connection")),
        ("curvature two-cochain", select(cochain=2, tag="curvature")),
        ("radial Green-transfer address", select(tag="radial")),
        ("internal two-channel carrier", select(rank=DUAL, tag="internal_doublet")),
        ("time/evolution direction", select(rank=SHIFT, tag="time_candidate")),
        ("spinor carrier", select(tag="spinor_candidate")),
        ("internal gauge algebra", select(tag="gauge_algebra_candidate")),
    )
    dictionary_rows = tuple(
        (role, len(candidates), candidates, len(candidates) == SHIFT)
        for role, candidates in dictionary_roles
    )
    unique_dictionary_role_count = sum(row[3] for row in dictionary_rows)
    ambiguous_dictionary_roles = tuple(row[0] for row in dictionary_rows if not row[3])
    dictionary_candidate_product = math.prod(max(SHIFT, row[1]) for row in dictionary_rows)
    field_dictionary_unique = unique_dictionary_role_count == len(dictionary_rows)

    # Classify each assembled action term.  Only the two-channel route action currently has a
    # directly generated operator form.  The remaining continuum forms are executable bridges:
    # their variations are valid, but the native ledger has not yet uniquely forced those forms.
    action_term_rows = []
    for label, origin, action_form, variation in master_action["terms"]:
        if label == "L_route":
            origin_class = "NATIVE_OPERATOR_FORM_DERIVED"
            strict_native = True
        elif label == "L_weak_closure":
            origin_class = "MIXED_NATIVE_COEFFICIENT_BRIDGED_CONTINUUM_FORM"
            strict_native = False
        else:
            origin_class = "EXECUTABLE_STANDARD_OPERATOR_FORM_BRIDGE"
            strict_native = False
        action_term_rows.append((label, origin, action_form, variation, origin_class, strict_native))
    native_action_term_count = sum(row[5] for row in action_term_rows)
    bridged_action_term_count = len(action_term_rows) - native_action_term_count
    all_action_operator_forms_native = bridged_action_term_count == 0

    master_gates = master_action["gates"]
    bytecode_self_contained = "PASS" in byteaudit["status"]
    coefficient_native = bool(
        coefficient_genealogy["closed"]
        and coefficient_genealogy["continuous_adjustable_leaf_count"] == 0
    )
    lorentz_bridge = bool(lorentz["metric_residual"] == 0 and lorentz["mass_shell_residual"] == 0)

    # Exactly twenty theorem obligations.  Equal weighting is used only to report a transparent
    # checklist fraction; the final 100-percent gate itself is logical AND, not a score threshold.
    clauses = (
        ("A1", "dimensionless closed ledger", bool(dimcore["all_scale_exponents_zero"] and constitution["independent_dimensionless_core_closed"]), True, "NATIVE_DERIVED"),
        ("A2", "single-file no-prior-artifact reconstruction", bytecode_self_contained, bytecode_self_contained, "NATIVE_DERIVED"),
        ("A3", "exact vertex-edge-face chain complex and B2B1=0", bool(dual_holonomy["topological_parent_action_closed"]), bool(dual_holonomy["topological_parent_action_closed"]), "NATIVE_DERIVED"),
        ("A4", "native radial/angular field-state basis", bool(harmonic_capacity["harmonic_capacity_parent_action_closed"]), bool(harmonic_capacity["harmonic_capacity_parent_action_closed"]), "NATIVE_DERIVED"),
        ("B1", "unique complete continuum field dictionary", field_dictionary_unique, field_dictionary_unique, "OPEN_AMBIGUOUS_DICTIONARY"),
        ("B2", "unique native time/evolution variable", len(dictionary_roles[8][1]) == SHIFT, len(dictionary_roles[8][1]) == SHIFT, "OPEN_TWO_TIME_CANDIDATES"),
        ("B3", "native derivation of the 3+1 Lorentz signature", False, lorentz_bridge and bool(shell_master["one_plus_three_bridge"]), "BRIDGED_NOT_NATIVE_UNIQUE"),
        ("B4", "unique U1xSU2xSU3 internal gauge algebra from the ledger", False, bool(harmonic_capacity["standard_model_internal_group_identification_closed"]), "OPEN_GROUP_IDENTIFICATION"),
        ("B5", "unique continuum field normalization and decoder", False, False, "OPEN_SCALE_AND_NORMALIZATION"),
        ("C1", "one executable parent action density", all_action_operator_forms_native and bool(strict_parent_gate["closed"]), bool(strict_parent_gate["closed"]), "EXECUTABLE_BRIDGE"),
        ("C2", "acyclic native coefficient genealogy with no adjustable leaves", coefficient_native, coefficient_native, "NATIVE_DERIVED"),
        ("C3", "unique local operator basis from native field content", False, bool(operator_basis["unique_minimal_basis"]), "CONDITIONAL_ON_DECLARED_FIELD_CONTENT"),
        ("C4", "Lorentz invariance of the complete action", False, lorentz_bridge, "EXECUTABLE_BRIDGE"),
        ("C5", "local gauge invariance, Noether identity and constraint propagation", False, bool(strict_coupled_gate["closed"]), "EXECUTABLE_BRIDGE"),
        ("D1", "matter equations from variation", False, bool(master_gates["route_projector_and_symplectic_variation"] and master_gates["kg_dirac_mass_shell"]), "PART_NATIVE_PART_BRIDGED"),
        ("D2", "electromagnetic Maxwell equation from variation", False, bool(master_gates["u1_action_to_maxwell"]), "EXECUTABLE_BRIDGE"),
        ("D3", "weak SU2-Higgs equations from variation", False, bool(master_gates["weak_quartic_stationarity_and_mass_matrix"] and strict_chiral_gate["closed"]), "EXECUTABLE_BRIDGE"),
        ("D4", "strong SU3 Yang-Mills equation from variation", False, bool(master_gates["nonabelian_action_to_yang_mills"]), "EXECUTABLE_BRIDGE"),
        ("D5", "Einstein gravitational equation from metric variation", False, bool(master_gates["einstein_hilbert_metric_variation"]), "EXECUTABLE_BRIDGE"),
        ("E1", "native shell geometry absorbed into the same action", bool(shell_master["closed"]), bool(shell_master["closed"] and strict_generation_gate["closed"]), "NATIVE_GEOMETRY_INTEGRATED"),
    )

    strict_pass_count = sum(bool(row[2]) for row in clauses)
    bridge_pass_count = sum(bool(row[3]) for row in clauses)
    total_clause_count = len(clauses)
    strict_progress = Decimal(strict_pass_count) * Decimal(100) / Decimal(total_clause_count)
    bridge_progress = Decimal(bridge_pass_count) * Decimal(100) / Decimal(total_clause_count)
    strict_theorem_closed = strict_pass_count == total_clause_count
    executable_bridge_closed = bridge_pass_count == total_clause_count
    open_clause_ids = tuple(row[0] for row in clauses if not row[2])
    decisive_open_clauses = tuple(
        row[1] for row in clauses
        if row[0] in ("B1", "B2", "B3", "B4", "B5", "C1", "C3", "C4", "C5")
        and not row[2]
    )

    return {
        "sectors": sectors,
        "dictionary_rows": dictionary_rows,
        "dictionary_role_count": len(dictionary_rows),
        "unique_dictionary_role_count": unique_dictionary_role_count,
        "ambiguous_dictionary_roles": ambiguous_dictionary_roles,
        "dictionary_candidate_product": dictionary_candidate_product,
        "field_dictionary_unique": field_dictionary_unique,
        "action_term_rows": tuple(action_term_rows),
        "native_action_term_count": native_action_term_count,
        "bridged_action_term_count": bridged_action_term_count,
        "all_action_operator_forms_native": all_action_operator_forms_native,
        "clauses": clauses,
        "strict_pass_count": strict_pass_count,
        "bridge_pass_count": bridge_pass_count,
        "total_clause_count": total_clause_count,
        "strict_progress_percent": strict_progress,
        "bridge_progress_percent": bridge_progress,
        "strict_theorem_closed": strict_theorem_closed,
        "executable_bridge_closed": executable_bridge_closed,
        "open_clause_ids": open_clause_ids,
        "decisive_open_clauses": decisive_open_clauses,
        "audit_executed": True,
        "status": "MASTER_COVARIANT_ACTION_NATIVE_ORIGIN_THEOREM_100_PERCENT_CLOSED" if strict_theorem_closed else "MASTER_COVARIANT_ACTION_EXECUTABLE_BRIDGE_PRESENT_NATIVE_ORIGIN_THEOREM_OPEN",
        "boundary": "the executable classical envelope is not relabelled as a native-origin proof; 100 percent requires every one of the twenty declared theorem clauses to pass strictly, including a unique field dictionary, time variable, Lorentz signature, gauge algebra, normalization and native operator-form derivation",
    }

