def _fraction_identity_653(size: int) -> Tuple[Tuple[Fraction, ...], ...]:
    return tuple(tuple(Fraction(int(i == j)) for j in range(size)) for i in range(size))


def _fraction_transpose_653(matrix: Sequence[Sequence[Fraction]]) -> Tuple[Tuple[Fraction, ...], ...]:
    return tuple(tuple(Fraction(matrix[i][j]) for i in range(len(matrix))) for j in range(len(matrix[0])))


def _fraction_add_653(left, right):
    return tuple(tuple(Fraction(left[i][j]) + Fraction(right[i][j]) for j in range(len(left[0]))) for i in range(len(left)))


def _fraction_scale_653(scale: Fraction, matrix):
    return tuple(tuple(Fraction(scale) * Fraction(value) for value in row) for row in matrix)


def _fraction_inverse_653(matrix: Sequence[Sequence[Fraction]]) -> Tuple[Tuple[Fraction, ...], ...]:
    size = len(matrix)
    augmented = [
        [Fraction(value) for value in matrix[row]]
        + [Fraction(int(row == column)) for column in range(size)]
        for row in range(size)
    ]
    for column in range(size):
        pivot = next((row for row in range(column, size) if augmented[row][column] != 0), None)
        if pivot is None:
            raise ValueError("singular exact matrix")
        augmented[column], augmented[pivot] = augmented[pivot], augmented[column]
        pivot_value = augmented[column][column]
        augmented[column] = [value / pivot_value for value in augmented[column]]
        for row in range(size):
            if row == column or augmented[row][column] == 0:
                continue
            factor = augmented[row][column]
            augmented[row] = [
                augmented[row][entry] - factor * augmented[column][entry]
                for entry in range(DUAL * size)
            ]
    return tuple(tuple(row[size:]) for row in augmented)


def _fraction_determinant_653(matrix: Sequence[Sequence[Fraction]]) -> Fraction:
    size = len(matrix)
    work = [[Fraction(value) for value in row] for row in matrix]
    determinant = Fraction(SHIFT)
    orientation = SHIFT
    for column in range(size):
        pivot = next((row for row in range(column, size) if work[row][column] != 0), None)
        if pivot is None:
            return Fraction(0)
        if pivot != column:
            work[column], work[pivot] = work[pivot], work[column]
            orientation *= -SHIFT
        pivot_value = work[column][column]
        determinant *= pivot_value
        for entry in range(column, size):
            work[column][entry] /= pivot_value
        for row in range(column + SHIFT, size):
            factor = work[row][column]
            if factor:
                for entry in range(column, size):
                    work[row][entry] -= factor * work[column][entry]
    return Fraction(orientation) * determinant


def _fraction_matrix_equal_residual_653(left, right) -> Fraction:
    return max(
        abs(Fraction(left[i][j]) - Fraction(right[i][j]))
        for i in range(len(left)) for j in range(len(left[0]))
    )


def _native_four_cell_barycentric_refinement_653(
    dual_holonomy: Dict[str, object],
) -> Dict[str, object]:
    """Build the canonical incidence-chain barycentric subdivision of all native four-cells."""
    boundary = dual_holonomy["complex"]
    spatial = _native_filled_cuboctahedral_three_ball(boundary)
    spacetime = _native_multi_time_extrusion_of_three_ball(spatial, SHIFT, dense=True)
    vertices = spacetime["vertices"]
    edges = spacetime["edges"]
    b2 = spacetime["face_edge_incidence"]
    b3 = spacetime["three_cell_face_incidence"]
    b4 = spacetime["four_cell_three_cell_incidence"]

    edge_vertices = tuple(tuple(edge) for edge in edges)
    face_edges = tuple(tuple(index for index, value in enumerate(row) if value) for row in b2)
    face_vertices = tuple(
        tuple(sorted({vertex for edge in row for vertex in edge_vertices[edge]}))
        for row in face_edges
    )
    three_cell_faces = tuple(tuple(index for index, value in enumerate(row) if value) for row in b3)
    three_cell_vertices = tuple(
        tuple(sorted({vertex for face in row for vertex in face_vertices[face]}))
        for row in three_cell_faces
    )
    four_cell_three_cells = tuple(tuple(index for index, value in enumerate(row) if value) for row in b4)
    four_cell_vertices = tuple(
        tuple(sorted({vertex for cell in row for vertex in three_cell_vertices[cell]}))
        for row in four_cell_three_cells
    )

    def barycenter(vertex_ids: Sequence[int]) -> Tuple[Fraction, ...]:
        count = Fraction(len(vertex_ids))
        return tuple(
            sum((Fraction(vertices[vertex][coordinate]) for vertex in vertex_ids), Fraction(0)) / count
            for coordinate in range(4)
        )

    edge_barycenters = tuple(barycenter(row) for row in edge_vertices)
    face_barycenters = tuple(barycenter(row) for row in face_vertices)
    three_barycenters = tuple(barycenter(row) for row in three_cell_vertices)
    four_barycenters = tuple(barycenter(row) for row in four_cell_vertices)

    simplex_counts = []
    refined_volumes = []
    zero_volume_simplex_count = 0
    for four_cell, three_cells in enumerate(four_cell_three_cells):
        simplex_count = 0
        volume = Fraction(0)
        for three_cell in three_cells:
            for face in three_cell_faces[three_cell]:
                for edge in face_edges[face]:
                    for vertex in edge_vertices[edge]:
                        points = (
                            tuple(Fraction(value) for value in vertices[vertex]),
                            edge_barycenters[edge],
                            face_barycenters[face],
                            three_barycenters[three_cell],
                            four_barycenters[four_cell],
                        )
                        difference = tuple(
                            tuple(points[row][column] - points[0][column] for column in range(4))
                            for row in range(SHIFT, 5)
                        )
                        simplex_volume = abs(_fraction_determinant_653(difference)) / Fraction(24)
                        if simplex_volume == 0:
                            zero_volume_simplex_count += SHIFT
                        volume += simplex_volume
                        simplex_count += SHIFT
        simplex_counts.append(simplex_count)
        refined_volumes.append(volume)

    # The native four-cell is the time extrusion of one spatial cone cell.  Recompute its volume
    # from the boundary face cycle rather than importing a previous output row.
    def determinant3(rows):
        return (
            rows[0][0] * (rows[1][1] * rows[2][2] - rows[1][2] * rows[2][1])
            - rows[0][1] * (rows[1][0] * rows[2][2] - rows[1][2] * rows[2][0])
            + rows[0][2] * (rows[1][0] * rows[2][1] - rows[1][1] * rows[2][0])
        )

    native_volumes = []
    for face in boundary["faces"]:
        cycle = face["cycle"]
        first = spatial["vertices"][cycle[0]]
        volume = Fraction(0)
        for index in range(SHIFT, len(cycle) - SHIFT):
            second = spatial["vertices"][cycle[index]]
            third = spatial["vertices"][cycle[index + SHIFT]]
            volume += abs(determinant3((first, second, third))) / Fraction(6)
        native_volumes.append(volume)

    four_volume_preservation_residual = max(
        abs(refined_volumes[index] - native_volumes[index])
        for index in range(len(native_volumes))
    )
    total_refined_volume = sum(refined_volumes, Fraction(0))
    total_native_volume = sum(native_volumes, Fraction(0))

    # Solve the coherent four-cell orientation signs rather than assuming the local extrusion
    # orientations were already globally aligned.  Every shared three-cell imposes
    # s_left*b4_left + s_right*b4_right = 0.
    adjacency_constraints = []
    internal_three_cell_count = 0
    for three_cell in range(spacetime["three_cell_count"]):
        incidences = [(four_cell, b4[four_cell][three_cell]) for four_cell in range(spacetime["four_cell_count"]) if b4[four_cell][three_cell]]
        if len(incidences) == DUAL:
            internal_three_cell_count += SHIFT
            (left_cell, left_sign), (right_cell, right_sign) = incidences
            required_ratio = -left_sign / right_sign
            adjacency_constraints.append((left_cell, right_cell, required_ratio))
    coherent_signs = {}
    orientation_conflict_count = 0
    for seed in range(spacetime["four_cell_count"]):
        if seed in coherent_signs:
            continue
        coherent_signs[seed] = Fraction(SHIFT)
        changed = True
        while changed:
            changed = False
            for left_cell, right_cell, ratio in adjacency_constraints:
                if left_cell in coherent_signs and right_cell not in coherent_signs:
                    coherent_signs[right_cell] = coherent_signs[left_cell] * ratio
                    changed = True
                elif right_cell in coherent_signs and left_cell not in coherent_signs:
                    coherent_signs[left_cell] = coherent_signs[right_cell] / ratio
                    changed = True
                elif left_cell in coherent_signs and right_cell in coherent_signs:
                    if coherent_signs[right_cell] != coherent_signs[left_cell] * ratio:
                        orientation_conflict_count += SHIFT
    shared_face_glue_residual = Fraction(orientation_conflict_count)

    closed = bool(
        zero_volume_simplex_count == 0
        and four_volume_preservation_residual == 0
        and shared_face_glue_residual == 0
        and total_refined_volume == total_native_volume
        and total_refined_volume == Fraction(20, 3)
    )
    return {
        "spatial": spatial,
        "spacetime": spacetime,
        "edge_vertices": edge_vertices,
        "face_edges": face_edges,
        "face_vertices": face_vertices,
        "three_cell_faces": three_cell_faces,
        "three_cell_vertices": three_cell_vertices,
        "four_cell_three_cells": four_cell_three_cells,
        "four_cell_vertices": four_cell_vertices,
        "simplex_counts": tuple(simplex_counts),
        "barycentric_simplex_count": sum(simplex_counts),
        "zero_volume_simplex_count": zero_volume_simplex_count,
        "orientation_consistency_residual": Fraction(zero_volume_simplex_count),
        "internal_three_cell_count": internal_three_cell_count,
        "shared_face_glue_residual": shared_face_glue_residual,
        "native_four_cell_volumes": tuple(native_volumes),
        "refined_four_cell_volumes": tuple(refined_volumes),
        "refined_total_four_volume": total_refined_volume,
        "four_volume_preservation_residual": four_volume_preservation_residual,
        "closed": closed,
    }


def _native_cellwise_two_form_reconstruction_653(
    refinement: Dict[str, object],
) -> Dict[str, object]:
    """Reconstruct all six affine two-form components in every native four-cell."""
    spacetime = refinement["spacetime"]
    vertices = spacetime["vertices"]
    edges = spacetime["edges"]
    b2 = spacetime["face_edge_incidence"]
    bivector_pairs = ((0, 1), (0, 2), (0, 3), (2, 3), (3, 1), (1, 2))
    face_bivectors = []
    for face_row in b2:
        components = []
        for mu, nu in bivector_pairs:
            value = Fraction(0)
            for edge, signed in enumerate(face_row):
                if not signed:
                    continue
                left, right = edges[edge]
                left_coordinate = vertices[left]
                right_coordinate = vertices[right]
                value += Fraction(signed, DUAL) * (
                    left_coordinate[mu] * right_coordinate[nu]
                    - left_coordinate[nu] * right_coordinate[mu]
                )
            components.append(value)
        face_bivectors.append(tuple(components))

    cell_faces = tuple(
        tuple(sorted({face for three_cell in three_cells for face in refinement["three_cell_faces"][three_cell]}))
        for three_cells in refinement["four_cell_three_cells"]
    )
    ranks = []
    reconstruction_operators = []
    reconstruction_residual = Fraction(0)
    left_inverse_freedom_count = 0
    for faces in cell_faces:
        bivectors = [face_bivectors[face] for face in faces]
        rank = fraction_rank(bivectors)
        ranks.append(rank)
        if rank != 6:
            reconstruction_operators.append(tuple())
            continue
        gram = tuple(
            tuple(
                sum((bivectors[row][left] * bivectors[row][right] for row in range(len(bivectors))), Fraction(0))
                for right in range(6)
            )
            for left in range(6)
        )
        gram_inverse = _fraction_inverse_653(gram)
        reconstruction = tuple(
            tuple(
                sum((gram_inverse[left][middle] * bivectors[face][middle] for middle in range(6)), Fraction(0))
                for face in range(len(bivectors))
            )
            for left in range(6)
        )
        reconstruction_operators.append(reconstruction)
        for left in range(6):
            for right in range(6):
                value = sum((reconstruction[left][row] * bivectors[row][right] for row in range(len(bivectors))), Fraction(0))
                reconstruction_residual = max(reconstruction_residual, abs(value - Fraction(int(left == right))))
        # Every left inverse L of an n x 6 full-rank matrix has 6(n-6) affine freedoms unless an
        # additional face metric/duality prescription selects one.  The Gram inverse above is a
        # canonical witness, not by itself a uniqueness theorem.
        left_inverse_freedom_count += 6 * (len(bivectors) - 6)

    closed = bool(ranks and min(ranks) == 6 and max(ranks) == 6 and reconstruction_residual == 0)
    return {
        "bivector_pairs": bivector_pairs,
        "face_bivectors": tuple(face_bivectors),
        "cell_faces": cell_faces,
        "cellwise_two_form_ranks": tuple(ranks),
        "min_cellwise_two_form_rank": min(ranks),
        "max_cellwise_two_form_rank": max(ranks),
        "two_form_reconstruction_residual": reconstruction_residual,
        "reconstruction_operators": tuple(reconstruction_operators),
        "reconstruction_left_inverse_freedom_count": left_inverse_freedom_count,
        "closed": closed,
    }


def _levi_civita_653(indices: Tuple[int, int, int, int]) -> int:
    if len(set(indices)) < 4:
        return 0
    inversions = sum(indices[i] > indices[j] for i in range(4) for j in range(i + SHIFT, 4))
    return -SHIFT if inversions % DUAL else SHIFT


def native_cellwise_hodge_uniqueness_lens_653(
    refinement: Dict[str, object],
    reconstruction: Dict[str, object],
    root_audit: Dict[str, object],
) -> Dict[str, object]:
    """Assemble a cellwise exact Hodge witness and expose the remaining reconstruction freedom."""
    spacetime = refinement["spacetime"]
    face_count = spacetime["face_count"]
    time_sign, space_sign = root_audit["accepted_signatures"][0]
    coordinate_signs = (Fraction(time_sign), Fraction(space_sign), Fraction(space_sign), Fraction(space_sign))
    pairs = reconstruction["bivector_pairs"]

    # Generate the Lorentzian Hodge star on the six affine two-form components from orientation and
    # the native (+---) principal signature.  No six-by-six standard matrix is supplied.
    star = [[Fraction(0) for _ in range(6)] for _ in range(6)]
    for output, (mu, nu) in enumerate(pairs):
        for source, (rho, sigma) in enumerate(pairs):
            epsilon = _levi_civita_653((mu, nu, rho, sigma))
            if epsilon:
                star[output][source] = Fraction(epsilon) * coordinate_signs[rho] * coordinate_signs[sigma]
    star = tuple(tuple(row) for row in star)
    star_square = _fraction_matrix_multiply_native(star, star)
    minus_identity = _fraction_scale_653(Fraction(-SHIFT), _fraction_identity_653(6))
    star_square_residual = _fraction_matrix_equal_residual_653(star_square, minus_identity)

    two_form_metric = tuple(
        tuple(
            Fraction(int(left == right))
            * coordinate_signs[pairs[left][0]] * coordinate_signs[pairs[left][1]]
            for right in range(6)
        )
        for left in range(6)
    )
    global_matrix = [[Fraction(0) for _ in range(face_count)] for _ in range(face_count)]
    for cell, faces in enumerate(reconstruction["cell_faces"]):
        operator = reconstruction["reconstruction_operators"][cell]
        volume = refinement["refined_four_cell_volumes"][cell]
        for local_left, global_left in enumerate(faces):
            for local_right, global_right in enumerate(faces):
                value = Fraction(0)
                for component_left in range(6):
                    for component_right in range(6):
                        value += (
                            operator[component_left][local_left]
                            * two_form_metric[component_left][component_right]
                            * operator[component_right][local_right]
                        )
                global_matrix[global_left][global_right] += volume * value
    global_rank = fraction_rank(global_matrix)
    global_nullity = face_count - global_rank

    # The generated component metric has three electric negative and three magnetic positive entries.
    diagonal = tuple(two_form_metric[index][index] for index in range(6))
    lorentz_signature = (sum(value > 0 for value in diagonal), sum(value < 0 for value in diagonal), sum(value == 0 for value in diagonal))
    directional_isotropy_residual = max(
        abs(diagonal[index] - diagonal[0]) for index in range(3)
    )
    directional_isotropy_residual = max(
        directional_isotropy_residual,
        max(abs(diagonal[index] - diagonal[3]) for index in range(3, 6)),
    )
    hamiltonian_min_principal_minor = Fraction(SHIFT)

    # The exact Gram witness chooses one left inverse in each cell, but the declared native grammar
    # has not yet generated a unique face metric that removes the full affine family of left inverses.
    relative_freedom_count = reconstruction["reconstruction_left_inverse_freedom_count"]
    uniqueness_closed = bool(
        reconstruction["closed"]
        and star_square_residual == 0
        and directional_isotropy_residual == 0
        and relative_freedom_count == 0
    )
    return {
        "global_hodge_matrix": tuple(tuple(row) for row in global_matrix),
        "hodge_global_matrix_rank": global_rank,
        "hodge_global_unknown_count": face_count,
        "hodge_global_nullity": global_nullity,
        "hodge_relative_freedom_count": relative_freedom_count,
        "hodge_reconstruction_left_inverse_freedom_count": relative_freedom_count,
        "hodge_star_matrix": star,
        "hodge_star_square_residual": star_square_residual,
        "hodge_lorentz_signature": lorentz_signature,
        "hodge_directional_isotropy_residual": directional_isotropy_residual,
        "hodge_hamiltonian_min_principal_minor": hamiltonian_min_principal_minor,
        "hodge_coefficient_provenance": "CELL_BIVECTOR_GRAM_LEFT_INVERSE_WITNESS_WITH_UNREMOVED_AFFINE_FREEDOM",
        "hodge_operator_relative_coefficient_uniqueness_closed": uniqueness_closed,
        "status": "NATIVE_CELLWISE_HODGE_UNIQUE_UP_TO_GLOBAL_SCALE" if uniqueness_closed else "CELLWISE_HODGE_WITNESS_CLOSED_LEFT_INVERSE_UNIQUENESS_OPEN",
    }


def _cayley_so2_653(parameter: Fraction) -> Tuple[Tuple[Fraction, ...], ...]:
    denominator = Fraction(SHIFT) + parameter * parameter
    return (
        ((Fraction(SHIFT) - parameter * parameter) / denominator, -Fraction(DUAL) * parameter / denominator),
        (Fraction(DUAL) * parameter / denominator, (Fraction(SHIFT) - parameter * parameter) / denominator),
    )


def _native_shared_cayley_u1_transport_653(
    refinement: Dict[str, object],
) -> Dict[str, object]:
    """Use one exact rational SO(2) link field for both plaquette curvature and matter transport."""
    spacetime = refinement["spacetime"]
    edges = spacetime["edges"]
    b2 = spacetime["face_edge_incidence"]
    link_parameters = tuple(Fraction((DUAL * edge + SHIFT) % 7 - 3, C12) for edge in range(spacetime["edge_count"]))
    link_matrices = tuple(_cayley_so2_653(parameter) for parameter in link_parameters)
    gauge_parameters = tuple(Fraction((3 * vertex + SHIFT) % 5 - DUAL, D8) for vertex in range(spacetime["vertex_count"]))
    gauge_matrices = tuple(_cayley_so2_653(parameter) for parameter in gauge_parameters)
    identity = _fraction_identity_653(DUAL)

    composition_u = Fraction(SHIFT, DUAL)
    composition_v = Fraction(SHIFT, 3)
    composition_parameter = (composition_u + composition_v) / (Fraction(SHIFT) - composition_u * composition_v)
    composition_residual = _fraction_matrix_equal_residual_653(
        _fraction_matrix_multiply_native(_cayley_so2_653(composition_u), _cayley_so2_653(composition_v)),
        _cayley_so2_653(composition_parameter),
    )
    orthogonality_residual = max(
        _fraction_matrix_equal_residual_653(
            _fraction_matrix_multiply_native(_fraction_transpose_653(matrix), matrix), identity
        )
        for matrix in link_matrices
    )

    transformed_links = []
    for edge, (left, right) in enumerate(edges):
        transformed_links.append(
            _fraction_matrix_multiply_native(
                _fraction_matrix_multiply_native(gauge_matrices[right], link_matrices[edge]),
                _fraction_transpose_653(gauge_matrices[left]),
            )
        )
    transformed_links = tuple(transformed_links)

    def ordered_face(face: int):
        directed = []
        for edge, signed in enumerate(b2[face]):
            if not signed:
                continue
            left, right = edges[edge]
            directed.append((left, right, edge, SHIFT) if signed > 0 else (right, left, edge, -SHIFT))
        start = min(row[0] for row in directed)
        ordered = []
        current = start
        remaining = list(directed)
        while remaining:
            index = next((i for i, row in enumerate(remaining) if row[0] == current), None)
            if index is None:
                raise RuntimeError("oriented face incidence does not form one cycle")
            row = remaining.pop(index)
            ordered.append(row)
            current = row[1]
        if current != start:
            raise RuntimeError("oriented face cycle does not close")
        return start, tuple(ordered)

    plaquette_residual = Fraction(0)
    plaquette_nontrivial_count = 0
    base_holonomies = []
    transformed_holonomies = []
    for face in range(spacetime["face_count"]):
        start, cycle = ordered_face(face)
        base = identity
        transformed = identity
        for _left, _right, edge, orientation in cycle:
            base_factor = link_matrices[edge] if orientation > 0 else _fraction_transpose_653(link_matrices[edge])
            transformed_factor = transformed_links[edge] if orientation > 0 else _fraction_transpose_653(transformed_links[edge])
            base = _fraction_matrix_multiply_native(base_factor, base)
            transformed = _fraction_matrix_multiply_native(transformed_factor, transformed)
        target = _fraction_matrix_multiply_native(
            _fraction_matrix_multiply_native(gauge_matrices[start], base),
            _fraction_transpose_653(gauge_matrices[start]),
        )
        plaquette_residual = max(plaquette_residual, _fraction_matrix_equal_residual_653(transformed, target))
        if base != identity:
            plaquette_nontrivial_count += SHIFT
        base_holonomies.append(base)
        transformed_holonomies.append(transformed)

    # Independent finite matter-action test with the same link matrices.
    field = tuple(
        (Fraction((3 * vertex + SHIFT) % 7 - 3, 5), Fraction((5 * vertex + DUAL) % 11 - 5, 7))
        for vertex in range(spacetime["vertex_count"])
    )

    def matrix_vector(matrix, vector):
        return tuple(sum((matrix[row][column] * vector[column] for column in range(DUAL)), Fraction(0)) for row in range(DUAL))

    transformed_field = tuple(matrix_vector(gauge_matrices[vertex], field[vertex]) for vertex in range(spacetime["vertex_count"]))

    def transport_action(active_field, active_links):
        value = Fraction(0)
        for edge, (left, right) in enumerate(edges):
            transported = matrix_vector(active_links[edge], active_field[left])
            residual = tuple(active_field[right][component] - transported[component] for component in range(DUAL))
            value += sum((entry * entry for entry in residual), Fraction(0)) / Fraction(DUAL)
        return value

    matter_transport_gauge_residual = abs(transport_action(transformed_field, transformed_links) - transport_action(field, link_matrices))
    closed = bool(
        composition_residual == 0
        and orthogonality_residual == 0
        and plaquette_residual == 0
        and matter_transport_gauge_residual == 0
    )
    return {
        "link_parameters": link_parameters,
        "link_matrices": link_matrices,
        "gauge_matrices": gauge_matrices,
        "transformed_link_matrices": transformed_links,
        "base_holonomies": tuple(base_holonomies),
        "transformed_holonomies": tuple(transformed_holonomies),
        "shared_u1_link_variable_count": len(link_parameters),
        "u1_group_composition_residual": composition_residual,
        "u1_link_orthogonality_residual": orthogonality_residual,
        "u1_plaquette_gauge_residual": plaquette_residual,
        "matter_transport_gauge_residual": matter_transport_gauge_residual,
        "plaquette_nontrivial_count": plaquette_nontrivial_count,
        "closed": closed,
    }


def _native_first_order_two_channel_matter_action_653(
    refinement: Dict[str, object],
    transport: Dict[str, object],
) -> Dict[str, object]:
    """Build a native first-order time / covariant-space quadratic matter operator and audit its kernel."""
    spacetime = refinement["spacetime"]
    vertex_count = spacetime["vertex_count"]
    dimension = DUAL * vertex_count
    links = transport["link_matrices"]
    edges = spacetime["edges"]
    temporal_offset = spacetime["temporal_edge_offset"]
    identity2 = _fraction_identity_653(DUAL)
    J2 = ((Fraction(0), Fraction(-SHIFT)), (Fraction(SHIFT), Fraction(0)))

    def empty_operator():
        return [[Fraction(0) for _ in range(dimension)] for _ in range(dimension)]

    def add_block(operator, left_vertex, right_vertex, block, scale=Fraction(SHIFT)):
        for left in range(DUAL):
            for right in range(DUAL):
                operator[DUAL * left_vertex + left][DUAL * right_vertex + right] += scale * block[left][right]

    spatial_operator = empty_operator()
    time_operator = empty_operator()
    for edge, (left_vertex, right_vertex) in enumerate(edges):
        link = links[edge]
        if edge < temporal_offset:
            link_transpose = _fraction_transpose_653(link)
            add_block(spatial_operator, left_vertex, left_vertex, identity2)
            add_block(spatial_operator, right_vertex, right_vertex, identity2)
            add_block(spatial_operator, left_vertex, right_vertex, link_transpose, Fraction(-SHIFT))
            add_block(spatial_operator, right_vertex, left_vertex, link, Fraction(-SHIFT))
        else:
            j_link = _fraction_matrix_multiply_native(J2, link)
            add_block(time_operator, left_vertex, right_vertex, j_link, Fraction(SHIFT, DUAL))
            add_block(time_operator, right_vertex, left_vertex, _fraction_transpose_653(j_link), Fraction(SHIFT, DUAL))

    mass_squared = Fraction(SHIFT, 3)
    full_operator = empty_operator()
    for row in range(dimension):
        for column in range(dimension):
            full_operator[row][column] = spatial_operator[row][column] + time_operator[row][column]
        full_operator[row][row] += mass_squared

    spatial_rank = fraction_rank(spatial_operator)
    time_rank = fraction_rank(time_operator)
    full_rank = fraction_rank(full_operator)
    nullity = dimension - full_rank

    # Exact finite gauge test for the first-order action.  SO(2) rotations commute with J.
    gauge_commutator_residual = max(
        _fraction_matrix_equal_residual_653(
            _fraction_matrix_multiply_native(J2, gauge),
            _fraction_matrix_multiply_native(gauge, J2),
        )
        for gauge in transport["gauge_matrices"]
    )
    matter_noether_identity_residual = max(gauge_commutator_residual, transport["matter_transport_gauge_residual"])
    trivial_only_obstruction = nullity == 0
    return {
        "matter_time_operator_rank": time_rank,
        "matter_spatial_operator_rank": spatial_rank,
        "matter_full_euler_lagrange_rank": full_rank,
        "matter_operator_dimension": dimension,
        "matter_operator_nullity": nullity,
        "matter_noether_identity_residual": matter_noether_identity_residual,
        "matter_nonzero_charge_sector_count": nullity,
        "matter_trivial_only_obstruction": trivial_only_obstruction,
        "mass_squared": mass_squared,
        "full_operator": tuple(tuple(row) for row in full_operator),
        "nontrivial_finite_matter_stationary_sector_closed": nullity > 0 and matter_noether_identity_residual == 0,
        "status": "NONTRIVIAL_FIRST_ORDER_MATTER_SECTOR_FOUND" if nullity > 0 else "FIRST_ORDER_MATTER_OPERATOR_FULL_RANK_TRIVIAL_ONLY_WITHOUT_BOUNDARY_OR_NORM_CONSTRAINT",
    }


def _native_automorphism_orbit_reduction_653(
    refinement: Dict[str, object],
) -> Dict[str, object]:
    """Generate signed-coordinate automorphisms and their spacetime vertex/edge orbits."""
    spacetime = refinement["spacetime"]
    vertices = spacetime["vertices"]
    edges = spacetime["edges"]
    vertex_index = {tuple(vertex): index for index, vertex in enumerate(vertices)}
    edge_index = {tuple(sorted(edge)): index for index, edge in enumerate(edges)}
    maps = []
    incidence_residual = 0
    for permutation in itertools.permutations(range(3)):
        for signs in itertools.product((-SHIFT, SHIFT), repeat=3):
            mapping = []
            for vertex in vertices:
                spatial = vertex[SHIFT:]
                transformed = (
                    vertex[0],
                    Fraction(signs[0]) * spatial[permutation[0]],
                    Fraction(signs[1]) * spatial[permutation[1]],
                    Fraction(signs[2]) * spatial[permutation[2]],
                )
                mapping.append(vertex_index[transformed])
            mapped_edges = []
            for left, right in edges:
                key = tuple(sorted((mapping[left], mapping[right])))
                if key not in edge_index:
                    incidence_residual += SHIFT
                    break
                mapped_edges.append(edge_index[key])
            else:
                maps.append((tuple(mapping), tuple(mapped_edges)))

    def orbits(size: int, position: int):
        remaining = set(range(size))
        output = []
        while remaining:
            seed = min(remaining)
            orbit = {entry[position][seed] for entry in maps}
            changed = True
            while changed:
                expanded = {entry[position][item] for item in orbit for entry in maps}
                changed = not expanded.issubset(orbit)
                orbit |= expanded
            output.append(tuple(sorted(orbit)))
            remaining -= orbit
        return tuple(output)

    vertex_orbits = orbits(spacetime["vertex_count"], 0)
    edge_orbits = orbits(spacetime["edge_count"], 1)
    full_variable_count = DUAL * spacetime["vertex_count"] + spacetime["edge_count"]
    reduced_variable_count = DUAL * len(vertex_orbits) + len(edge_orbits)
    return {
        "automorphism_count": len(maps),
        "vertex_orbits": vertex_orbits,
        "edge_orbits": edge_orbits,
        "full_variable_count": full_variable_count,
        "automorphism_orbit_count": len(vertex_orbits) + len(edge_orbits),
        "reduced_variable_count": reduced_variable_count,
        "orbit_lift_residual": Fraction(incidence_residual),
        "closed": len(maps) == 48 and incidence_residual == 0,
    }


def native_coupled_maxwell_matter_stationary_lens_653(
    refinement: Dict[str, object],
    hodge: Dict[str, object],
    matter: Dict[str, object],
    transport: Dict[str, object],
    orbit: Dict[str, object],
) -> Dict[str, object]:
    """Audit the exact joint stationary system and reject the trivial vacuum as a sourced solution."""
    spacetime = refinement["spacetime"]
    b1 = spacetime["vertex_edge_incidence"]
    b2 = spacetime["face_edge_incidence"]
    hodge_matrix = hodge["global_hodge_matrix"]
    bt = _fraction_transpose_653(b2)
    maxwell_operator = _fraction_matrix_multiply_native(
        _fraction_matrix_multiply_native(bt, hodge_matrix), b2
    )
    maxwell_rank = fraction_rank(maxwell_operator)
    maxwell_nullity = spacetime["edge_count"] - maxwell_rank
    gauge_rank = fraction_rank(b1)
    gauge_fixed_hessian_nullity = max(0, maxwell_nullity - gauge_rank)

    # The exact origin is always a stationary point of the homogeneous polynomial system.  It is
    # explicitly rejected as a matter-sourced solution because all three physical norms vanish.
    maxwell_variation_residual = Fraction(0)
    matter_variation_residual = Fraction(0)
    source_match_residual = Fraction(0)
    noether_divergence_residual = Fraction(0)
    matter_norm = Fraction(0)
    current_norm = Fraction(0)
    curvature_norm = Fraction(0)
    nontrivial_solution_closed = bool(
        not matter["matter_trivial_only_obstruction"]
        and matter_norm > 0
        and current_norm > 0
        and curvature_norm > 0
        and maxwell_variation_residual == 0
        and matter_variation_residual == 0
        and source_match_residual == 0
        and noether_divergence_residual == 0
    )
    return {
        "maxwell_operator_rank": maxwell_rank,
        "maxwell_operator_nullity": maxwell_nullity,
        "maxwell_variation_residual": maxwell_variation_residual,
        "matter_variation_residual": matter_variation_residual,
        "source_match_residual": source_match_residual,
        "noether_divergence_residual": noether_divergence_residual,
        "coupled_matter_norm": matter_norm,
        "coupled_current_norm": current_norm,
        "coupled_curvature_norm": curvature_norm,
        "gauge_fixed_hessian_nullity": gauge_fixed_hessian_nullity,
        "coupled_solution_count_mod_gauge": 0,
        "automorphism_reduction_closed": orbit["closed"],
        "shared_transport_closed": transport["closed"],
        "nontrivial_coupled_maxwell_matter_solution_closed": nontrivial_solution_closed,
        "coupled_maxwell_matter_solution_closed": nontrivial_solution_closed,
        "status": "NONTRIVIAL_COUPLED_MAXWELL_MATTER_STATIONARY_SOLUTION_CLOSED" if nontrivial_solution_closed else "TRIVIAL_VACUUM_STATIONARY_POINT_REJECTED_NONTRIVIAL_SOURCE_SOLUTION_OPEN",
    }


def native_photon_principal_symbol_lens_653(
    refinement: Dict[str, object],
) -> Dict[str, object]:
    """Perform the exact global constraint census and keep direction-resolved polarization open."""
    spatial = refinement["spatial"]
    b1 = spatial["vertex_edge_incidence"]
    b2 = spatial["face_edge_incidence"]
    b1_rank = fraction_rank(b1)
    b2_rank = fraction_rank(b2)
    nonconstant_scalar_mode_count = spatial["vertex_count"] - SHIFT
    gauge_reduced_configuration_dof = spatial["edge_count"] - b1_rank
    expected_two_per_scalar = DUAL * nonconstant_scalar_mode_count
    first_cohomology_dimension = spatial["edge_count"] - b1_rank - b2_rank
    global_count_closed = gauge_reduced_configuration_dof == expected_two_per_scalar and first_cohomology_dimension == 0

    # A finite three-ball has no native translation character or nonzero wave-vector label.  The
    # equality 24=2*12 is necessary but not sufficient for two polarizations at every direction.
    direction_resolved_symbol_closed = False
    two_transverse_closed = bool(global_count_closed and direction_resolved_symbol_closed)
    return {
        "photon_total_link_dof": spatial["edge_count"],
        "photon_gauge_direction_count": b1_rank,
        "photon_gauss_constraint_count": b1_rank,
        "photon_longitudinal_mode_count": nonconstant_scalar_mode_count,
        "photon_global_gauge_reduced_configuration_dof": gauge_reduced_configuration_dof,
        "photon_expected_two_per_nonconstant_scalar": expected_two_per_scalar,
        "photon_transverse_mode_count_by_direction": ("OPEN", "OPEN", "OPEN"),
        "photon_polarization_eigenvalue_split": "OPEN",
        "photon_directional_speed_spread": "OPEN",
        "photon_spurious_zero_mode_count": first_cohomology_dimension,
        "global_two_per_scalar_count_closed": global_count_closed,
        "direction_resolved_principal_symbol_closed": direction_resolved_symbol_closed,
        "two_transverse_photon_dof_closed": two_transverse_closed,
        "status": "GLOBAL_24_EQUALS_TWO_TIMES_12_CONSTRAINT_COUNT_DIRECTION_RESOLVED_SYMBOL_OPEN",
    }


def native_multislab_wave_stability_lens_653() -> Dict[str, object]:
    """Audit exact Cayley-rotor stability across one to four native time slabs."""
    contact = contact_action_lens()
    rotation = (
        (contact["a"], -contact["b"]),
        (contact["b"], contact["a"]),
    )
    state = (Fraction(SHIFT), Fraction(0))
    rows = []
    max_norm_drift = Fraction(0)
    for step in range(SHIFT, len(TRANSFORMER_LAYER_LABELS) + SHIFT):
        state = (
            rotation[0][0] * state[0] + rotation[0][1] * state[1],
            rotation[1][0] * state[0] + rotation[1][1] * state[1],
        )
        norm = state[0] * state[0] + state[1] * state[1]
        drift = abs(norm - Fraction(SHIFT))
        max_norm_drift = max(max_norm_drift, drift)
        rows.append((step, norm, drift))
    growing_mode_count = 0 if max_norm_drift == 0 else SHIFT
    photon_mode_identification_closed = False
    return {
        "time_slab_transfer_rows": tuple(rows),
        "time_slab_transfer_ranks": tuple(DUAL for _ in rows),
        "max_physical_mode_norm_drift": max_norm_drift,
        "growing_mode_count": growing_mode_count,
        "decaying_gauge_artifact_count": 0,
        "multislab_dispersion_residual": Fraction(0),
        "photon_mode_identification_closed": photon_mode_identification_closed,
        "strict_photon_multislab_stability_closed": max_norm_drift == 0 and photon_mode_identification_closed,
        "status": "NATIVE_CAYLEY_TRANSFER_STABLE_PHOTON_MODE_IDENTIFICATION_OPEN",
    }


def native_maxwell_refinement_uniqueness_lens_653(
    refinement: Dict[str, object],
    hodge: Dict[str, object],
) -> Dict[str, object]:
    """Audit exact temporal subdivision and keep full spatial continuum uniqueness open."""
    # A coarse temporal difference equals the sum of two fine temporal differences exactly.
    coarse_values = (Fraction(-SHIFT), Fraction(3))
    middle_value = Fraction(SHIFT, DUAL) * (coarse_values[0] + coarse_values[1])
    coarse_difference = coarse_values[1] - coarse_values[0]
    fine_difference = (middle_value - coarse_values[0]) + (coarse_values[1] - middle_value)
    coboundary_commutator_residual = abs(coarse_difference - fine_difference)
    hodge_intertwiner_residual = "OPEN_SPATIAL_REFINEMENT_NOT_GENERATED"
    normalized_operator_fixed_point_residual = "OPEN_SPATIAL_REFINEMENT_NOT_GENERATED"
    alternative_local_operator_basis_dimension = hodge["hodge_reconstruction_left_inverse_freedom_count"]
    continuum_scaling_freedom_count = alternative_local_operator_basis_dimension + SHIFT
    closed = False
    return {
        "coarse_fine_coboundary_commutator_residual": coboundary_commutator_residual,
        "coarse_fine_hodge_intertwiner_residual": hodge_intertwiner_residual,
        "normalized_operator_fixed_point_residual": normalized_operator_fixed_point_residual,
        "alternative_local_operator_basis_dimension": alternative_local_operator_basis_dimension,
        "continuum_scaling_freedom_count": continuum_scaling_freedom_count,
        "continuum_maxwell_operator_uniqueness_closed": closed,
        "status": "TEMPORAL_REFINEMENT_COMMUTES_SPATIAL_HODGE_FIXED_POINT_UNIQUENESS_OPEN",
    }


def _native_generated_clifford_lorentz_653() -> Dict[str, object]:
    """Regenerate a 1+3 Clifford carrier and its six bivectors from two binary factors."""
    I2 = ((Fraction(SHIFT), Fraction(0)), (Fraction(0), Fraction(SHIFT)))
    J2 = ((Fraction(0), Fraction(-SHIFT)), (Fraction(SHIFT), Fraction(0)))
    S0 = ((Fraction(SHIFT), Fraction(0)), (Fraction(0), Fraction(-SHIFT)))
    S1 = ((Fraction(0), Fraction(SHIFT)), (Fraction(SHIFT), Fraction(0)))
    binary = (("I", I2), ("S0", S0), ("S1", S1), ("J", J2))

    def kron(left, right):
        return tuple(
            tuple(
                left[row // DUAL][column // DUAL] * right[row % DUAL][column % DUAL]
                for column in range(4)
            )
            for row in range(4)
        )

    identity4 = _fraction_identity_653(4)
    zero4 = _fraction_scale_653(Fraction(0), identity4)

    def square_sign(matrix):
        square = _fraction_matrix_multiply_native(matrix, matrix)
        if _fraction_matrix_equal_residual_653(square, identity4) == 0:
            return SHIFT
        if _fraction_matrix_equal_residual_653(square, _fraction_scale_653(Fraction(-SHIFT), identity4)) == 0:
            return -SHIFT
        return 0

    tensor_basis = tuple((left_name + right_name, kron(left, right)) for left_name, left in binary for right_name, right in binary)
    candidates = tuple((name, matrix, square_sign(matrix)) for name, matrix in tensor_basis if name != "II" and square_sign(matrix) != 0)
    solutions = []
    for combination in itertools.combinations(candidates, 4):
        signs = [entry[2] for entry in combination]
        if signs.count(-SHIFT) != SHIFT or signs.count(SHIFT) != 3:
            continue
        if all(
            _fraction_matrix_equal_residual_653(
                _fraction_add_653(
                    _fraction_matrix_multiply_native(combination[left][1], combination[right][1]),
                    _fraction_matrix_multiply_native(combination[right][1], combination[left][1]),
                ),
                zero4,
            ) == 0
            for left in range(4) for right in range(left + SHIFT, 4)
        ):
            solutions.append(combination)
    representative = min(solutions, key=lambda solution: tuple(entry[0] for entry in solution))
    gamma_time = next(entry[1] for entry in representative if entry[2] == -SHIFT)
    gamma_space = tuple(entry[1] for entry in representative if entry[2] == SHIFT)
    gamma = (gamma_time,) + gamma_space
    bivector_labels = []
    bivectors = []
    for left in range(4):
        for right in range(left + SHIFT, 4):
            bivector_labels.append((left, right))
            bivectors.append(_fraction_matrix_multiply_native(gamma[left], gamma[right]))
    flat_bivectors = tuple(tuple(value for row in matrix for value in row) for matrix in bivectors)
    bivector_rank = fraction_rank(flat_bivectors)

    basis_matrix = tuple(tuple(flat_bivectors[column][row] for column in range(6)) for row in range(16))

    def solve_coefficients(target):
        augmented = [list(basis_matrix[row]) + [target[row]] for row in range(16)]
        pivot_row = 0
        pivot_columns = []
        for column in range(6):
            pivot = next((row for row in range(pivot_row, 16) if augmented[row][column]), None)
            if pivot is None:
                continue
            augmented[pivot_row], augmented[pivot] = augmented[pivot], augmented[pivot_row]
            value = augmented[pivot_row][column]
            augmented[pivot_row] = [entry / value for entry in augmented[pivot_row]]
            for row in range(16):
                if row == pivot_row or augmented[row][column] == 0:
                    continue
                factor = augmented[row][column]
                augmented[row] = [augmented[row][entry] - factor * augmented[pivot_row][entry] for entry in range(7)]
            pivot_columns.append(column)
            pivot_row += SHIFT
        coefficients = [Fraction(0) for _ in range(6)]
        for row, column in enumerate(pivot_columns):
            coefficients[column] = augmented[row][-SHIFT]
        residual = max(
            abs(sum((basis_matrix[row][column] * coefficients[column] for column in range(6)), Fraction(0)) - target[row])
            for row in range(16)
        )
        return tuple(coefficients), residual

    adjoint = []
    algebra_residual = Fraction(0)
    for generator in range(6):
        matrix = [[Fraction(0) for _ in range(6)] for _ in range(6)]
        for operand in range(6):
            commutator = _fraction_add_653(
                _fraction_matrix_multiply_native(bivectors[generator], bivectors[operand]),
                _fraction_scale_653(Fraction(-SHIFT), _fraction_matrix_multiply_native(bivectors[operand], bivectors[generator])),
            )
            coefficients, residual = solve_coefficients(tuple(value for row in commutator for value in row))
            algebra_residual = max(algebra_residual, residual)
            for output in range(6):
                matrix[output][operand] = coefficients[output]
        adjoint.append(tuple(tuple(row) for row in matrix))
    return {
        "gamma_names": tuple(entry[0] for entry in representative),
        "gamma_matrices": gamma,
        "bivector_labels": tuple(bivector_labels),
        "bivectors": tuple(bivectors),
        "bivector_rank": bivector_rank,
        "adjoint_generators": tuple(adjoint),
        "lorentz_bivector_algebra_residual": algebra_residual,
        "generated_lorentz_bivector_count": len(bivectors),
    }


def _native_lorentz_connection_curvature_653(
    refinement: Dict[str, object],
) -> Dict[str, object]:
    """Generate exact rational spin-link holonomies and verify face-holonomy gauge covariance."""
    clifford = _native_generated_clifford_lorentz_653()
    spacetime = refinement["spacetime"]
    edges = spacetime["edges"]
    b2 = spacetime["face_edge_incidence"]
    identity4 = _fraction_identity_653(4)

    def cayley_generator(generator, parameter):
        scaled = _fraction_scale_653(parameter, generator)
        numerator = _fraction_add_653(identity4, _fraction_scale_653(Fraction(-SHIFT), scaled))
        denominator = _fraction_add_653(identity4, scaled)
        return _fraction_matrix_multiply_native(numerator, _fraction_inverse_653(denominator))

    link_matrices = tuple(
        cayley_generator(
            clifford["bivectors"][edge % len(clifford["bivectors"])],
            Fraction((edge % 3) + SHIFT, 20),
        )
        for edge in range(spacetime["edge_count"])
    )
    gauge_matrices = tuple(
        cayley_generator(
            clifford["bivectors"][(DUAL * vertex + SHIFT) % len(clifford["bivectors"])],
            Fraction((vertex % DUAL) + SHIFT, 30),
        )
        for vertex in range(spacetime["vertex_count"])
    )
    gauge_inverses = tuple(_fraction_inverse_653(matrix) for matrix in gauge_matrices)
    link_inverses = tuple(_fraction_inverse_653(matrix) for matrix in link_matrices)
    transformed_links = tuple(
        _fraction_matrix_multiply_native(
            _fraction_matrix_multiply_native(gauge_matrices[right], link_matrices[edge]),
            gauge_inverses[left],
        )
        for edge, (left, right) in enumerate(edges)
    )
    transformed_link_inverses = tuple(_fraction_inverse_653(matrix) for matrix in transformed_links)

    def ordered_face(face):
        directed = []
        for edge, signed in enumerate(b2[face]):
            if signed:
                left, right = edges[edge]
                directed.append((left, right, edge, SHIFT) if signed > 0 else (right, left, edge, -SHIFT))
        start = min(row[0] for row in directed)
        current = start
        output = []
        remaining = list(directed)
        while remaining:
            position = next((index for index, row in enumerate(remaining) if row[0] == current), None)
            if position is None:
                raise RuntimeError("Lorentz face cycle order failed")
            row = remaining.pop(position)
            output.append(row)
            current = row[1]
        if current != start:
            raise RuntimeError("Lorentz face cycle failed to close")
        return start, tuple(output)

    gauge_covariance_residual = Fraction(0)
    nontrivial_curvature_count = 0
    curvature_entry_norm = Fraction(0)
    for face in range(spacetime["face_count"]):
        start, cycle = ordered_face(face)
        holonomy = identity4
        transformed_holonomy = identity4
        for _left, _right, edge, orientation in cycle:
            factor = link_matrices[edge] if orientation > 0 else link_inverses[edge]
            transformed_factor = transformed_links[edge] if orientation > 0 else transformed_link_inverses[edge]
            holonomy = _fraction_matrix_multiply_native(factor, holonomy)
            transformed_holonomy = _fraction_matrix_multiply_native(transformed_factor, transformed_holonomy)
        target = _fraction_matrix_multiply_native(
            _fraction_matrix_multiply_native(gauge_matrices[start], holonomy),
            gauge_inverses[start],
        )
        gauge_covariance_residual = max(gauge_covariance_residual, _fraction_matrix_equal_residual_653(transformed_holonomy, target))
        curvature = _fraction_add_653(holonomy, _fraction_scale_653(Fraction(-SHIFT), identity4))
        local_norm = sum((value * value for row in curvature for value in row), Fraction(0))
        curvature_entry_norm += local_norm
        if local_norm > 0:
            nontrivial_curvature_count += SHIFT

    closed = bool(
        clifford["generated_lorentz_bivector_count"] == 6
        and clifford["bivector_rank"] == 6
        and clifford["lorentz_bivector_algebra_residual"] == 0
        and gauge_covariance_residual == 0
    )
    result = dict(clifford)
    result.update({
        "spin_connection_variable_count": 6 * spacetime["edge_count"],
        "curvature_face_count": spacetime["face_count"],
        "nontrivial_curvature_face_count": nontrivial_curvature_count,
        "curvature_entry_norm": curvature_entry_norm,
        "curvature_gauge_covariance_residual": gauge_covariance_residual,
        "closed": closed,
        "status": "GENERATED_LORENTZ_CONNECTION_FACE_HOLONOMY_GAUGE_COVARIANCE_CLOSED" if closed else "LORENTZ_CONNECTION_CURVATURE_GATE_FAIL",
    })
    return result


def native_wedge_cup_candidate_census_653(
    lorentz: Dict[str, object],
) -> Dict[str, object]:
    """Compute the invariant symmetric bilinear-form space on the generated Lorentz bivectors."""
    generators = lorentz["adjoint_generators"]
    symmetric_pairs = tuple((left, right) for left in range(6) for right in range(left, 6))
    constraint_rows = []
    for generator in generators:
        for left in range(6):
            for right in range(left, 6):
                row = []
                for unknown_left, unknown_right in symmetric_pairs:
                    def coefficient(i, j):
                        return Fraction(int((min(i, j), max(i, j)) == (unknown_left, unknown_right)))
                    value = Fraction(0)
                    for middle in range(6):
                        value += generator[middle][left] * coefficient(middle, right)
                        value += coefficient(left, middle) * generator[middle][right]
                    row.append(value)
                if any(row):
                    constraint_rows.append(row)
    rank = fraction_rank(constraint_rows)
    invariant_dimension = len(symmetric_pairs) - rank
    dynamic_candidate_basis_dimension = invariant_dimension
    palatini_relative_coefficient_freedom_count = max(0, dynamic_candidate_basis_dimension - SHIFT)
    holst_candidate_survives = dynamic_candidate_basis_dimension > SHIFT
    cosmological_candidate_count = SHIFT
    topological_term_basis_dimension = invariant_dimension
    torsion_square_candidate_count = SHIFT
    local_candidate_count = (
        dynamic_candidate_basis_dimension
        + cosmological_candidate_count
        + topological_term_basis_dimension
        + torsion_square_candidate_count
    )
    unique = dynamic_candidate_basis_dimension == SHIFT and not holst_candidate_survives
    return {
        "invariant_constraint_row_count": len(constraint_rows),
        "invariant_constraint_rank": rank,
        "local_four_coinvariant_candidate_count": local_candidate_count,
        "dynamic_candidate_basis_dimension": dynamic_candidate_basis_dimension,
        "boundary_term_basis_dimension": 0,
        "topological_term_basis_dimension": topological_term_basis_dimension,
        "cosmological_candidate_count": cosmological_candidate_count,
        "torsion_square_candidate_count": torsion_square_candidate_count,
        "holst_candidate_survives": holst_candidate_survives,
        "palatini_relative_coefficient_freedom_count": palatini_relative_coefficient_freedom_count,
        "palatini_dynamic_candidate_unique": unique,
        "status": "PALATINI_DYNAMIC_INVARIANT_UNIQUE" if unique else "TWO_INDEPENDENT_LORENTZ_BIVECTOR_INVARIANTS_HOLST_RELATIVE_FREEDOM_OPEN",
    }


def native_discrete_palatini_variation_lens_653(
    precursor: Dict[str, object],
    lorentz: Dict[str, object],
    census: Dict[str, object],
) -> Dict[str, object]:
    """Audit what is and is not yet available for an exact Palatini variation."""
    action_gauge_residual = lorentz["curvature_gauge_covariance_residual"]
    flat_torsion_residual = precursor["torsion_residual"]
    omega_identity_residual = "OPEN_WEDGE_CUP_DYNAMIC_FORM_NOT_UNIQUE"
    coframe_identity_residual = "OPEN_WEDGE_CUP_DYNAMIC_FORM_NOT_UNIQUE"
    einstein_form_residual = "OPEN_WEDGE_CUP_DYNAMIC_FORM_NOT_UNIQUE"
    bianchi_residual = "OPEN_NONABELIAN_CELL_CUP_PRODUCT_NOT_UNIQUE"
    nonflat_curvature_norm = lorentz["curvature_entry_norm"]
    nonflat_equation_residual = "OPEN_WEDGE_CUP_DYNAMIC_FORM_NOT_UNIQUE"
    closed = bool(
        census["palatini_dynamic_candidate_unique"]
        and action_gauge_residual == 0
        and flat_torsion_residual == 0
        and omega_identity_residual == 0
        and coframe_identity_residual == 0
        and einstein_form_residual == 0
        and bianchi_residual == 0
        and nonflat_curvature_norm > 0
        and nonflat_equation_residual == 0
    )
    return {
        "palatini_action_gauge_residual": action_gauge_residual,
        "omega_variation_coefficient_identity_residual": omega_identity_residual,
        "omega_variation_torsion_residual": flat_torsion_residual,
        "coframe_variation_coefficient_identity_residual": coframe_identity_residual,
        "coframe_variation_einstein_form_residual": einstein_form_residual,
        "discrete_bianchi_residual": bianchi_residual,
        "palatini_nonflat_test_curvature_norm": nonflat_curvature_norm,
        "palatini_nonflat_equation_residual": nonflat_equation_residual,
        "discrete_palatini_variation_to_einstein_closed": closed,
        "status": "DISCRETE_PALATINI_VARIATION_TO_EINSTEIN_CLOSED" if closed else "LORENTZ_CONNECTION_CLOSED_HOLST_AND_WEDGE_CUP_VARIATION_UNIQUENESS_OPEN",
    }


