def native_maxwell_principal_symbol_census_654() -> Dict[str, object]:
    matrix_pairs = tuple((left, right) for left in range(3) for right in range(left, 3))
    monomial_pairs = tuple((left, right) for left in range(3) for right in range(left, 3))
    unknowns = tuple((matrix_pair, monomial_pair) for matrix_pair in matrix_pairs for monomial_pair in monomial_pairs)
    unknown_index = {unknown: index for index, unknown in enumerate(unknowns)}
    constraints = []
    group_count = 0
    for permutation in itertools.permutations(range(3)):
        for signs in itertools.product((-SHIFT, SHIFT), repeat=3):
            group_count += SHIFT
            for i, j in matrix_pairs:
                for target_monomial in monomial_pairs:
                    row = [Fraction(0) for _ in unknowns]
                    for source_monomial in monomial_pairs:
                        a, b = source_monomial
                        mapped = tuple(sorted((permutation[a], permutation[b])))
                        if mapped == target_monomial:
                            row[unknown_index[((i, j), source_monomial)]] += Fraction(signs[a] * signs[b])
                    mapped_matrix = tuple(sorted((permutation[i], permutation[j])))
                    row[unknown_index[(mapped_matrix, target_monomial)]] -= Fraction(signs[i] * signs[j])
                    if any(row):
                        constraints.append(row)
    cubic_monomials = tuple(itertools.combinations_with_replacement(range(3), 3))
    for i in range(3):
        for cubic in cubic_monomials:
            row = [Fraction(0) for _ in unknowns]
            for j in range(3):
                matrix_pair = tuple(sorted((i, j)))
                for monomial_pair in monomial_pairs:
                    if tuple(sorted(monomial_pair + (j,))) == cubic:
                        row[unknown_index[(matrix_pair, monomial_pair)]] += Fraction(SHIFT)
            if any(row):
                constraints.append(row)
    constraint_rank = fraction_rank(constraints)
    basis = _fraction_nullspace_654(constraints)
    freedom = len(basis)
    representative = basis[0] if basis else tuple(Fraction(0) for _ in unknowns)
    coefficient = {unknown: representative[index] for index, unknown in enumerate(unknowns)}
    scale_candidates = [coefficient[((i, i), (a, a))] for i in range(3) for a in range(3) if a != i and coefficient[((i, i), (a, a))] != 0]
    scale = scale_candidates[0] if scale_candidates else Fraction(0)
    pattern_residual = Fraction(0)
    for i, j in matrix_pairs:
        for a, b in monomial_pairs:
            expected = Fraction(0)
            if i == j and a == b and a != i:
                expected = scale
            elif i != j and (a, b) == tuple(sorted((i, j))):
                expected = -scale
            pattern_residual = max(pattern_residual, abs(coefficient[((i, j), (a, b))] - expected))
    k = (Fraction(SHIFT), Fraction(DUAL), Fraction(3))
    symbol = [[Fraction(0) for _ in range(3)] for _ in range(3)]
    for i, j in matrix_pairs:
        value = sum((coefficient[((i, j), (a, b))] * k[a] * k[b] for a, b in monomial_pairs), Fraction(0))
        symbol[i][j] = value
        symbol[j][i] = value
    gauge_residual = max(abs(sum((symbol[i][j] * k[j] for j in range(3)), Fraction(0))) for i in range(3))
    symbol_rank = fraction_rank(symbol)
    eigenvalue = scale * sum((entry * entry for entry in k), Fraction(0))
    square = _fraction_matrix_multiply_native(symbol, symbol)
    multiplicity_residual = max(abs(square[i][j] - eigenvalue * symbol[i][j]) for i in range(3) for j in range(3))
    closed = bool(freedom == SHIFT and scale != 0 and pattern_residual == 0 and gauge_residual == 0 and symbol_rank == DUAL and multiplicity_residual == 0)
    return {
        "signed_permutation_group_count": group_count,
        "local_second_order_vector_operator_candidate_count": len(unknowns),
        "automorphism_invariant_symbol_constraint_rank": constraint_rank,
        "automorphism_invariant_symbol_basis_dimension": freedom,
        "gauge_identity_constraint_included": True,
        "symbol_freedom_up_to_scale": max(0, freedom - SHIFT),
        "generic_nonzero_k_symbol_rank": symbol_rank,
        "transverse_eigenvalue_multiplicity": DUAL if multiplicity_residual == 0 and symbol_rank == DUAL else "OPEN",
        "longitudinal_eigenvalue": Fraction(0) if gauge_residual == 0 else "NONZERO",
        "directional_symbol_residual": pattern_residual,
        "gauge_symbol_residual": gauge_residual,
        "equal_transverse_eigenvalue_residual": multiplicity_residual,
        "representative_scale": scale,
        "representative_symbol_at_1_2_3": tuple(tuple(row) for row in symbol),
        "direction_resolved_two_transverse_photon_symbol_closed": closed,
        "status": "UNIQUE_SIGNED_PERMUTATION_GAUGE_TRANSVERSE_SYMBOL_UP_TO_SCALE" if closed else "MAXWELL_PRINCIPAL_SYMBOL_CENSUS_OPEN",
    }


def native_photon_transfer_stability_lens_654(symbol: Dict[str, object]) -> Dict[str, object]:
    contact = contact_action_lens()
    rotation = ((contact["a"], -contact["b"]), (contact["b"], contact["a"]))
    states = [(Fraction(SHIFT), Fraction(0)), (Fraction(0), Fraction(SHIFT))]
    max_drift = Fraction(0)
    rows = []
    for slab in range(SHIFT, len(TRANSFORMER_LAYER_LABELS) + SHIFT):
        next_states = []
        for state in states:
            next_state = (
                rotation[0][0] * state[0] + rotation[0][1] * state[1],
                rotation[1][0] * state[0] + rotation[1][1] * state[1],
            )
            next_states.append(next_state)
        states = next_states
        norms = tuple(state[0] * state[0] + state[1] * state[1] for state in states)
        drift = max(abs(value - Fraction(SHIFT)) for value in norms)
        max_drift = max(max_drift, drift)
        rows.append((slab, norms, drift))
    actual_maxwell_transfer_derived = False
    closed = bool(symbol["direction_resolved_two_transverse_photon_symbol_closed"] and max_drift == 0 and actual_maxwell_transfer_derived)
    return {
        "photon_physical_mode_count": DUAL if symbol["direction_resolved_two_transverse_photon_symbol_closed"] else "OPEN",
        "photon_transfer_matrix_rank": DUAL,
        "photon_symplectic_residual": contact["max_norm_residual"],
        "photon_mode_norm_drift_by_slab": tuple(rows),
        "max_photon_mode_norm_drift": max_drift,
        "photon_growing_mode_count": 0 if max_drift == 0 else SHIFT,
        "photon_decaying_physical_mode_count": 0 if max_drift == 0 else SHIFT,
        "photon_dispersion_slab_spread": Fraction(0),
        "actual_maxwell_time_transfer_derived": actual_maxwell_transfer_derived,
        "photon_transfer_stability_closed": closed,
        "status": "TWO_SYMBOL_MODES_HAVE_CAYLEY_STABLE_WITNESS_ACTUAL_MAXWELL_TRANSFER_OPEN",
    }


