def _signed_permutation_orbit_655(prototype: Tuple[int, int, int]) -> Tuple[Tuple[int, int, int], ...]:
    vertices = set()
    for permutation in set(itertools.permutations(prototype)):
        nonzero = tuple(index for index, value in enumerate(permutation) if value != 0)
        for signs in itertools.product((-1, 1), repeat=len(nonzero)):
            vertex = list(permutation)
            for index, sign in zip(nonzero, signs):
                vertex[index] *= sign
            vertices.add(tuple(vertex))
    return tuple(sorted(vertices))


def _nearest_neighbor_polyhedral_census_655(vertices: Sequence[Tuple[int, int, int]]) -> Dict[str, object]:
    vertex_count = len(vertices)
    distances = []
    for left in range(vertex_count):
        for right in range(left + SHIFT, vertex_count):
            distance = sum((vertices[left][axis] - vertices[right][axis]) ** 2 for axis in range(3))
            if distance > 0:
                distances.append(distance)
    minimum_distance = min(distances) if distances else 0
    adjacency = [[False for _ in range(vertex_count)] for _ in range(vertex_count)]
    for left in range(vertex_count):
        for right in range(left + SHIFT, vertex_count):
            distance = sum((vertices[left][axis] - vertices[right][axis]) ** 2 for axis in range(3))
            if distance == minimum_distance:
                adjacency[left][right] = True
                adjacency[right][left] = True
    degrees = tuple(sum(1 for value in row if value) for row in adjacency)
    connected = False
    if vertex_count:
        reached = {0}
        stack = [0]
        while stack:
            current = stack.pop()
            for neighbor, linked in enumerate(adjacency[current]):
                if linked and neighbor not in reached:
                    reached.add(neighbor)
                    stack.append(neighbor)
        connected = len(reached) == vertex_count
    triangle_count = 0
    for a, b, c in itertools.combinations(range(vertex_count), 3):
        triangle_count += int(adjacency[a][b] and adjacency[a][c] and adjacency[b][c])
    induced_square_count = 0
    for subset in itertools.combinations(range(vertex_count), 4):
        edge_count = sum(int(adjacency[left][right]) for left, right in itertools.combinations(subset, 2))
        degree_two = all(sum(int(adjacency[vertex][other]) for other in subset if other != vertex) == 2 for vertex in subset)
        induced_square_count += int(edge_count == 4 and degree_two)
    second_diagonal = tuple(sum(vertex[axis] * vertex[axis] for vertex in vertices) for axis in range(3))
    second_off_diagonal = tuple(
        sum(vertex[left] * vertex[right] for vertex in vertices)
        for left, right in ((0, 1), (0, 2), (1, 2))
    )
    isotropic_second_moment = len(set(second_diagonal)) <= SHIFT and all(value == 0 for value in second_off_diagonal)
    vertex_set = set(vertices)
    inversion_closed = all(tuple(-coordinate for coordinate in vertex) in vertex_set for vertex in vertices)
    coordinate_rank = fraction_rank([[Fraction(coordinate) for coordinate in vertex] for vertex in vertices]) if vertices else 0
    return {
        "vertex_count": vertex_count,
        "minimum_neighbor_distance_squared": minimum_distance,
        "degree_sequence": degrees,
        "regular_degree": degrees[0] if degrees and len(set(degrees)) == SHIFT else None,
        "connected": connected,
        "triangle_count": triangle_count,
        "induced_square_count": induced_square_count,
        "second_moment_diagonal": second_diagonal,
        "second_moment_off_diagonal": second_off_diagonal,
        "isotropic_second_moment": isotropic_second_moment,
        "central_inversion_closed": inversion_closed,
        "coordinate_rank": coordinate_rank,
    }


