def _runtime_function_call_graph_657() -> Dict[str, Tuple[str, ...]]:
    functions = {
        name: value
        for name, value in globals().items()
        if callable(value) and getattr(value, "__module__", None) == __name__
        and hasattr(value, "__code__")
    }
    names = set(functions)
    graph = {}
    for name, function in functions.items():
        referenced = {
            instruction.argval
            for instruction in dis.get_instructions(function)
            if instruction.opname in {"LOAD_GLOBAL", "LOAD_NAME"}
            and instruction.argval in names
            and instruction.argval != name
        }
        graph[name] = tuple(sorted(referenced))
    return graph


def _call_graph_cycle_count_657(graph: Dict[str, Tuple[str, ...]]) -> int:
    color = {name: 0 for name in graph}
    cycle_edges = set()

    def visit(name: str) -> None:
        color[name] = 1
        for target in graph.get(name, ()):
            state = color.get(target, 2)
            if state == 0:
                visit(target)
            elif state == 1:
                cycle_edges.add((name, target))
        color[name] = 2

    for name in sorted(graph):
        if color[name] == 0:
            visit(name)
    return len(cycle_edges)


def optimized_independent_closed_proof_audit_657_lens(
    cumulative_gate: Dict[str, object],
    theorem_audit: Dict[str, object],
) -> Dict[str, object]:
    functions = {
        name: value
        for name, value in globals().items()
        if callable(value) and getattr(value, "__module__", None) == __name__
        and hasattr(value, "__code__")
    }
    graph = _runtime_function_call_graph_657()
    cycle_count = _call_graph_cycle_count_657(graph)

    bytecode_groups: Dict[Tuple[bytes, Tuple[object, ...], Tuple[str, ...]], List[str]] = {}
    for name, function in functions.items():
        constants = tuple(
            value if isinstance(value, (str, int, float, complex, bytes, type(None))) else type(value).__name__
            for value in function.__code__.co_consts
        )
        signature = (function.__code__.co_code, constants, function.__code__.co_names)
        bytecode_groups.setdefault(signature, []).append(name)
    duplicate_groups = tuple(
        tuple(sorted(group))
        for group in bytecode_groups.values()
        if len(group) > 1
    )

    forbidden_names = {
        "open", "exec", "eval", "compile", "input", "__import__",
        "minimize", "optimize", "curve_fit", "polyfit", "least_squares",
        "log", "log10", "log2", "exp", "expm1", "sin", "cos", "tan",
        "sinh", "cosh", "tanh", "asin", "acos", "atan",
        "numpy", "scipy", "pandas", "csv", "json", "zipfile", "pickle",
    }
    forbidden_hits = set()
    for name, function in functions.items():
        used = set(function.__code__.co_names).intersection(forbidden_names)
        forbidden_hits.update((name, item) for item in used)

    deterministic_generators = tuple(sorted(
        name for name in (
            "native_seed_bundle", "contact_action_lens",
            "gell_mann_generators", "_fcc_native_directions",
        )
        if name in functions
    ))
    whitney_function = functions.get("_native_barycentric_whitney_two_form_mass_654")
    dense_diagonal_hodge_materialized = bool(
        whitney_function
        and "global_hodge_matrix" in whitney_function.__code__.co_consts
    )

    checks = {
        "single_file_runtime_reconstruction": cumulative_gate["runtime_previous_artifact_read_count"] == 0,
        "no_optimizer_fit_or_external_runtime_api": not forbidden_hits,
        "function_call_graph_acyclic": cycle_count == 0,
        "exact_duplicate_function_body_count_zero": len(duplicate_groups) == 0,
        "dense_diagonal_hodge_matrix_removed": not dense_diagonal_hodge_materialized,
        "deterministic_generator_registry_complete": len(deterministic_generators) == 4,
        "strict_theorem_count_status_consistent": theorem_audit["strict_theorem_closed"] == (
            theorem_audit["strict_pass_count"] == theorem_audit["total_clause_count"]
        ),
        "native_bridge_classification_consistent": (
            (theorem_audit["bridged_action_term_count"] == 0)
            == theorem_audit["strict_theorem_closed"]
        ),
        "extended_24_clause_gate_preserved": theorem_audit["extended_total_clause_count"] == 24,
    }
    closed = all(checks.values())
    return {
        "function_count": len(functions),
        "call_graph_cycle_count": cycle_count,
        "duplicate_function_body_groups": duplicate_groups,
        "forbidden_runtime_hits": tuple(sorted(forbidden_hits)),
        "deterministic_generators": deterministic_generators,
        "dense_diagonal_hodge_materialized": dense_diagonal_hodge_materialized,
        "checks": checks,
        "closed": closed,
        "status": "OPTIMIZED_INDEPENDENT_CLOSED_PROOF_CODE_CONSTITUTION_PASS" if closed else "OPTIMIZATION_CONSTITUTION_OPEN",
        "boundary": "code-structure closure validates this implementation only; empirical equivalence, quantum completion and observed-scale tests remain separate",
    }



