def _fraction_zero_659(rows: int, columns: int) -> Tuple[Tuple[Fraction, ...], ...]:
    return tuple(tuple(Fraction(0) for _column in range(columns)) for _row in range(rows))


def _fraction_block_659(
    top_left: Sequence[Sequence[Fraction]],
    top_right: Sequence[Sequence[Fraction]],
    bottom_left: Sequence[Sequence[Fraction]],
    bottom_right: Sequence[Sequence[Fraction]],
) -> Tuple[Tuple[Fraction, ...], ...]:
    top = tuple(tuple(top_left[row]) + tuple(top_right[row]) for row in range(len(top_left)))
    bottom = tuple(tuple(bottom_left[row]) + tuple(bottom_right[row]) for row in range(len(bottom_left)))
    return top + bottom






def _fraction_matrix_max_abs_659(matrix: Sequence[Sequence[Fraction]]) -> Fraction:
    return max((abs(entry) for row in matrix for entry in row), default=Fraction(0))




def bipolar_incidence_dynamics_659_lens(audit_658: Dict[str, object]) -> Dict[str, object]:
    vertex_count = G5
    incidence = tuple(
        tuple(Fraction(-SHIFT if vertex == edge else SHIFT if vertex == edge + SHIFT else 0) for vertex in range(vertex_count))
        for edge in range(vertex_count - SHIFT)
    )
    incidence_t = _fraction_transpose_653(incidence)
    laplacian = _fraction_matrix_multiply_native(incidence_t, incidence)
    state = (Fraction(-SHIFT), Fraction(-SHIFT, DUAL), Fraction(0), Fraction(SHIFT, DUAL), Fraction(SHIFT))
    gradient = _fraction_matrix_vector_native(incidence, state)
    flux = tuple(-value for value in gradient)
    density_rate = tuple(-value for value in _fraction_matrix_vector_native(incidence_t, flux))
    continuity_residual = tuple(
        density_rate[index] + _fraction_matrix_vector_native(incidence_t, flux)[index]
        for index in range(vertex_count)
    )
    total_density_rate = sum(density_rate)

    identity = _fraction_identity_653(vertex_count)
    zero = _fraction_zero_659(vertex_count, vertex_count)
    negative_laplacian = _fraction_scale_653(Fraction(-SHIFT), laplacian)
    wave_generator = _fraction_block_659(zero, identity, negative_laplacian, zero)
    hamiltonian_metric = _fraction_block_659(laplacian, zero, zero, identity)
    symplectic_energy_residual = _fraction_add_653(
        _fraction_matrix_multiply_native(_fraction_transpose_653(wave_generator), hamiltonian_metric),
        _fraction_matrix_multiply_native(hamiltonian_metric, wave_generator),
    )
    gradient_energy = sum(value * value for value in gradient) / DUAL
    kinetic = (Fraction(1, 3), Fraction(-1, 4), Fraction(2, 5), Fraction(-3, 7), Fraction(5, 8))
    kinetic_energy = sum(value * value for value in kinetic) / DUAL

    source = (Fraction(SHIFT), Fraction(-SHIFT), Fraction(0), Fraction(0), Fraction(0))
    poisson_matrix = tuple(tuple(row) for row in laplacian) + ((Fraction(SHIFT), Fraction(0), Fraction(0), Fraction(0), Fraction(0)),)
    poisson_rhs = source + (Fraction(0),)
    potential, poisson_rank, poisson_inconsistent = solve_fraction_system(poisson_matrix, poisson_rhs)
    poisson_residual = tuple(value - source[index] for index, value in enumerate(_fraction_matrix_vector_native(laplacian, potential)))

    canonical_j = tuple(tuple(Fraction(entry) for entry in row) for row in audit_658["origin"]["canonical_j"])
    i2 = _fraction_identity_653(DUAL)
    half_step = Fraction(SHIFT, DUAL)
    cayley_left = _fraction_add_653(i2, _fraction_scale_653(-half_step / DUAL, canonical_j))
    cayley_right = _fraction_add_653(i2, _fraction_scale_653(half_step / DUAL, canonical_j))
