def paired_residual_wave_coupling_660_lens() -> Dict[str, object]:
    """Generalize the manuscript's reflected paired sequence to arbitrary rational total and ratio."""
    total = Fraction(17, 6)
    q_cycle = (
        Fraction(-3, G5), Fraction(-DUAL, G5), Fraction(-SHIFT, G5), Fraction(0),
        Fraction(SHIFT, G5), Fraction(DUAL, G5), Fraction(3, G5),
        Fraction(DUAL, G5), Fraction(SHIFT, G5), Fraction(0),
        Fraction(-SHIFT, G5), Fraction(-DUAL, G5), Fraction(-3, G5),
    )
    states = tuple(
        (total * (SHIFT + q_value) / DUAL, total * (SHIFT - q_value) / DUAL)
        for q_value in q_cycle
    )
    total_residual = max(abs(left + right - total) for left, right in states)
    coupled_step_residuals = []
    for index in range(len(states) - SHIFT):
        delta_left = states[index + SHIFT][0] - states[index][0]
