    half_count = 0
    zero_count = 0
    local_outer_energy_ratio = Fraction(0)
    for index, direction in enumerate(vertices, start=SHIFT):
        norm_square = sum(value * value for value in direction)
        axial_cosine_square = Fraction(direction[2] * direction[2], norm_square)
        tangential_speed_square_ratio = SHIFT - axial_cosine_square
        local_outer_energy_ratio += tangential_speed_square_ratio
        if tangential_speed_square_ratio == SHIFT:
            contact_class = "equatorial_full_tangent"
            full_count += SHIFT
        elif tangential_speed_square_ratio == Fraction(SHIFT, DUAL):
            contact_class = "oblique_half_energy_weight"
            half_count += SHIFT
        elif tangential_speed_square_ratio == 0:
            contact_class = "axis_zero_tangent"
            zero_count += SHIFT
        else:
            contact_class = "other_projection"
        projector = _contact_tangent_projector_662(direction)
        minimal_counter_rotation = tuple(
            -value for value in _three_vector_matrix_vector_662(projector, selected_axis)
        )
        rows.append((
            index,
            direction,
            axial_cosine_square,
            tangential_speed_square_ratio,
            minimal_counter_rotation,
            contact_class,
            SHIFT,
        ))

    initial_central_energy = Fraction(SHIFT, DUAL)
