def prior_primary_secondary_implementation_audit_665_lens(
    audit_662: Dict[str, object],
) -> Dict[str, object]:
    """Distinguish the implicit 662 source-response dynamics from an explicit A/B causal ledger."""
    dynamics = audit_662["dynamics"]
    implicit_source_response = bool(
        dynamics["initial_energy"] == Fraction(SHIFT, DUAL)
        and dynamics["first_transmitted_outer_kinetic"] > 0
        and dynamics["maximum_energy_conservation_residual"] == 0
    )
    required_explicit_keys = (
        "driver",
        "follower",
        "causal_lag",
        "directed_current",
        "contact_storage",
    )
    explicit_in_662 = all(key in dynamics for key in required_explicit_keys)
    return {
        "implicit_primary_secondary_dynamics_already_present": implicit_source_response,
        "explicit_primary_secondary_state_address_already_present": explicit_in_662,
        "required_explicit_keys": required_explicit_keys,
        "classification": "IMPLICIT_PRESENT_EXPLICIT_ADDRESS_MISSING" if implicit_source_response and not explicit_in_662 else "OTHER",
        "status": "PRIOR_CODE_PRIMARY_SECONDARY_AUDIT_PASS",
        "boundary": "CODE 8100-662 already places the initial angular impulse on one selected source coordinate and produces delayed neighbour response with exact energy conservation; it did not name arbitrary A/B driver-follower roles, a directed current sign, a lag variable or an explicit contact-storage co-state",
    }


def bipolar_primary_secondary_transition_665_lens() -> Dict[str, object]:
    """Make 5:5 -> 6:4 or 4:6 an ordered, exactly conserved driver-field-follower event."""
    total = Fraction(TOTAL)
    half = total / DUAL
    delta = Fraction(SHIFT)

    branch_a = (
        ("5:5 origin", half, half, Fraction(0), Fraction(0), "none", "none"),
        ("A driver opened", half + delta, half, -delta, delta, "A", "B"),
        ("B follower closed", half + delta, half - delta, Fraction(0), Fraction(0), "A", "B"),
    )
    branch_b = (
        ("5:5 origin", half, half, Fraction(0), Fraction(0), "none", "none"),
        ("B driver opened", half, half + delta, -delta, -delta, "B", "A"),
        ("A follower closed", half - delta, half + delta, Fraction(0), Fraction(0), "B", "A"),
    )

    def audit_branch(rows: Sequence[Tuple[object, ...]], driver_index: int, follower_index: int) -> Dict[str, object]:
        conservation = tuple(row[1] + row[2] + row[3] - total for row in rows)
        driver_changes_first = bool(
            rows[1][driver_index] != half
            and rows[1][follower_index] == half
            and rows[2][follower_index] != half
        )
        field_active_only_during_lag = bool(rows[0][3] == 0 and rows[1][3] != 0 and rows[2][3] == 0)
        return {
            "maximum_conservation_residual": max(abs(value) for value in conservation),
            "driver_changes_before_follower": driver_changes_first,
            "field_active_only_during_lag": field_active_only_during_lag,
            "lag_steps": SHIFT,
        }

    audit_a = audit_branch(branch_a, driver_index=1, follower_index=2)
    audit_b = audit_branch(branch_b, driver_index=2, follower_index=1)
    final_exchange_symmetric = bool(branch_a[-1][1] == branch_b[-1][2] and branch_a[-1][2] == branch_b[-1][1])
    current_reverses_with_driver = bool(branch_a[1][4] == -branch_b[1][4] and branch_a[1][4] != 0)
    simultaneous_endpoint_change_rejected = bool(
        branch_a[1][2] == half and branch_b[1][1] == half
    )
    closed = bool(
        audit_a["maximum_conservation_residual"] == 0
        and audit_b["maximum_conservation_residual"] == 0
        and audit_a["driver_changes_before_follower"]
        and audit_b["driver_changes_before_follower"]
        and audit_a["field_active_only_during_lag"]
        and audit_b["field_active_only_during_lag"]
        and final_exchange_symmetric
        and current_reverses_with_driver
        and simultaneous_endpoint_change_rejected
    )
    return {
        "A_driver_rows": branch_a,
        "B_driver_rows": branch_b,
        "A_driver_audit": audit_a,
        "B_driver_audit": audit_b,
        "final_exchange_symmetry": final_exchange_symmetric,
        "directed_current_reverses_under_driver_swap": current_reverses_with_driver,
        "simultaneous_endpoint_change_rejected": simultaneous_endpoint_change_rejected,
        "dynamic_state_address": "[final ratio, driver, follower, directed current, contact storage, causal lag]",
        "primary_secondary_bipolar_transition_closed": closed,
        "status": "ORDERED_5TO5_BREAKING_CAUSAL_CURRENT_PASS" if closed else "PRIMARY_SECONDARY_BIPOLAR_TRANSITION_OPEN",
        "boundary": "the finite ledger distinguishes equal final mirror magnitudes from unequal event order: one side changes first, the contact co-state temporarily carries the compensating burden, and the opposite side closes one update later; this is an exact causal bookkeeping layer, not yet a microscopic electrodynamic constitutive law",
    }


def _sphere_kinetic_energy_665(
    velocity: Sequence[Fraction],
    sphere: int,
) -> Fraction:
    return Fraction(SHIFT, DUAL) * sum(
        velocity[3 * sphere + component] ** DUAL for component in range(3)
    )


def equal_gear_driver_location_audit_665_lens(
    network: Dict[str, object],
) -> Dict[str, object]:
    """Swap the torque source across one equal-gear contact and compare local ratio with global work partition."""
    contact_index, (left, right, direction, contact_type) = next(
        (index, contact)
        for index, contact in enumerate(network["contacts"])
        if contact[3] == "central_outer" and contact[2][2] == 0
    )
    tangent_axis = next(axis for axis, component in enumerate(direction) if component == 0)
    unit_tangent = tuple(Fraction(SHIFT if axis == tangent_axis else 0) for axis in range(3))
    projector = _contact_tangent_projector_662(direction)
    local_counter = tuple(-value for value in _three_vector_matrix_vector_662(projector, unit_tangent))
    local_gear_ratio = local_counter[tangent_axis]
    step = Fraction(SHIFT, len(TRANSFORMER_LAYER_LABELS))

    rows = []
    source_results = {}
    for label, driver, follower, current_sign in (
        ("left_drives_right", left, right, Fraction(SHIFT)),
        ("right_drives_left", right, left, -Fraction(SHIFT)),
    ):
        history = _rotation_recurrence_history_662(
            network["stiffness"],
            source_axis=3 * driver + tangent_axis,
            steps=3,
            step=step,
        )
        initial_velocity = history["velocity_rows"][0]
        transmitted_velocity = history["velocity_rows"][1]
        initial_driver_energy = _sphere_kinetic_energy_665(initial_velocity, driver)
        initial_follower_energy = _sphere_kinetic_energy_665(initial_velocity, follower)
        transmitted_driver_energy = _sphere_kinetic_energy_665(transmitted_velocity, driver)
        transmitted_follower_energy = _sphere_kinetic_energy_665(transmitted_velocity, follower)
        total_transmitted_kinetic = Fraction(SHIFT, DUAL) * _fraction_norm_square_662(transmitted_velocity)
        total_energy = history["energy_values"][1]
        contact_storage = total_energy - total_transmitted_kinetic
        follower_component = transmitted_velocity[3 * follower + tangent_axis]
        result = {
            "driver": driver,
            "follower": follower,
            "current_sign": current_sign,
            "initial_driver_energy": initial_driver_energy,
            "initial_follower_energy": initial_follower_energy,
            "transmitted_driver_energy": transmitted_driver_energy,
            "transmitted_follower_energy": transmitted_follower_energy,
            "transmitted_total_kinetic": total_transmitted_kinetic,
            "contact_storage": contact_storage,
            "total_energy": total_energy,
            "follower_angular_component": follower_component,
            "follower_lag_steps": SHIFT,
        }
        source_results[label] = result
        rows.append((
            label,
            driver,
            follower,
            current_sign,
            local_gear_ratio,
            initial_driver_energy,
            initial_follower_energy,
            transmitted_driver_energy,
            transmitted_follower_energy,
            contact_storage,
            total_energy,
        ))

    left_result = source_results["left_drives_right"]
    right_result = source_results["right_drives_left"]
    local_equal_opposite_turn_rule = local_gear_ratio == -SHIFT
    both_have_delayed_follower = bool(
        left_result["initial_follower_energy"] == 0
        and right_result["initial_follower_energy"] == 0
        and left_result["transmitted_follower_energy"] > 0
        and right_result["transmitted_follower_energy"] > 0
        and left_result["follower_angular_component"] < 0
        and right_result["follower_angular_component"] < 0
    )
    exact_energy_both_directions = bool(
        left_result["total_energy"] == Fraction(SHIFT, DUAL)
        and right_result["total_energy"] == Fraction(SHIFT, DUAL)
    )
    source_location_changes_global_partition = bool(
        left_result["transmitted_driver_energy"] != right_result["transmitted_driver_energy"]
        or left_result["contact_storage"] != right_result["contact_storage"]
    )
    closed = bool(
        contact_type == "central_outer"
        and local_equal_opposite_turn_rule
        and both_have_delayed_follower
        and exact_energy_both_directions
        and source_location_changes_global_partition
        and left_result["current_sign"] == -right_result["current_sign"]
    )
    return {
        "contact_index": contact_index,
        "contact": (left, right, direction, contact_type),
        "tangent_axis": tangent_axis,
        "local_counter_rotation": local_counter,
        "local_equal_gear_ratio": local_gear_ratio,
        "rows": tuple(rows),
        "source_results": source_results,
        "local_equal_opposite_turn_rule": local_equal_opposite_turn_rule,
        "both_directions_have_delayed_follower": both_have_delayed_follower,
        "exact_energy_conservation_both_driver_choices": exact_energy_both_directions,
        "source_location_changes_global_energy_partition": source_location_changes_global_partition,
        "equal_gear_driver_location_audit_closed": closed,
        "status": "EQUAL_LOCAL_GEAR_DIFFERENT_GLOBAL_DRIVER_LOAD_PASS" if closed else "EQUAL_GEAR_DRIVER_LOCATION_AUDIT_OPEN",
        "boundary": "the selected equal-radius contact has the same local minus-one gear ratio whichever side is driven, but the central and outer source positions carry different full-network loads; source work, transient driver energy and contact storage therefore depend on where torque enters even though the local tooth/turn rule is unchanged",
    }


def all_contact_primary_secondary_current_665_lens(
    network: Dict[str, object],
) -> Dict[str, object]:
    """Verify that every one of the 36 contacts supports both causal driver choices with one-step lag."""
    step = Fraction(SHIFT, len(TRANSFORMER_LAYER_LABELS))
    rows = []
    failures = []
    for contact_index, (left, right, direction, contact_type) in enumerate(network["contacts"]):
        tangent_axis = next(axis for axis, component in enumerate(direction) if component == 0)
        for driver, follower, current_sign in (
            (left, right, Fraction(SHIFT)),
            (right, left, -Fraction(SHIFT)),
        ):
            history = _rotation_recurrence_history_662(
                network["stiffness"],
                source_axis=3 * driver + tangent_axis,
                steps=DUAL,
                step=step,
            )
            initial_velocity = history["velocity_rows"][0]
            transmitted_velocity = history["velocity_rows"][1]
            initial_follower_energy = _sphere_kinetic_energy_665(initial_velocity, follower)
            transmitted_follower_energy = _sphere_kinetic_energy_665(transmitted_velocity, follower)
            follower_component = transmitted_velocity[3 * follower + tangent_axis]
            total_residual = max(abs(value - history["energy_values"][0]) for value in history["energy_values"])
            passed = bool(
                initial_follower_energy == 0
                and transmitted_follower_energy > 0
                and follower_component < 0
                and total_residual == 0
            )
            row = (
                contact_index,
                contact_type,
                driver,
                follower,
                tangent_axis,
                current_sign,
                initial_follower_energy,
                transmitted_follower_energy,
                follower_component,
                total_residual,
                passed,
            )
            rows.append(row)
            if not passed:
                failures.append(row)
    directed_case_count = len(rows)
    expected_case_count = DUAL * network["total_contact_count"]
    closed = bool(directed_case_count == expected_case_count and not failures)
    return {
        "sample_rows": tuple(rows[:12]),
        "directed_case_count": directed_case_count,
        "expected_directed_case_count": expected_case_count,
        "failure_count": len(failures),
        "all_contacts_support_both_driver_choices": closed,
        "all_contact_primary_secondary_current_closed": closed,
        "status": "ALL_THIRTY_SIX_CONTACTS_BIDIRECTIONAL_CAUSAL_CURRENT_PASS" if closed else "ALL_CONTACT_CAUSAL_CURRENT_OPEN",
        "boundary": "every contact permits either endpoint to be selected as the event source; after selection the current sign and driver/follower order are definite, while before selection the two choices remain exchange-degenerate",
    }


