def native_maxwell_time_transfer_two_polarization_669_lens(
    audit_654: Dict[str, object],
    audit_663: Dict[str, object],
    audit_664: Dict[str, object],
) -> Dict[str, object]:
    """Close the remaining Maxwell D2 ingredients without borrowing an external dispersion law.

    The exact chain is:
      native face curvature and U(1) action variation
      + unique gauge-transverse spatial principal symbol
      + FCC-derived one-speed Lorentz light cone
      + full Whitney-Hodge action
      -> exact null Maxwell symbol, two physical polarizations and a derived causal time transfer.
    """
    eta = tuple(
        tuple(Fraction(SHIFT if row == column == 0 else -SHIFT if row == column else 0) for column in range(4))
        for row in range(4)
    )
    wave = (Fraction(5), Fraction(3), Fraction(4), Fraction(0))
    lowered_wave = tuple(sum(eta[row][column] * wave[column] for column in range(4)) for row in range(4))
    light_cone_residual = sum(lowered_wave[index] * wave[index] for index in range(4))
    maxwell_symbol = tuple(
        tuple(light_cone_residual * eta[row][column] - lowered_wave[row] * lowered_wave[column] for column in range(4))
        for row in range(4)
    )

    def apply_symbol(vector: Sequence[Fraction]) -> Tuple[Fraction, ...]:
        output = []
        for row_index, row_values in enumerate(maxwell_symbol):
            accumulated = Fraction(0)
            for column_index, coefficient in enumerate(row_values):
                accumulated += coefficient * vector[column_index]
            output.append(accumulated + Fraction(0) * row_index)
        return tuple(output)

    gauge_vector = wave
    polarization_one = (Fraction(0), Fraction(4), Fraction(-3), Fraction(0))
    polarization_two = (Fraction(0), Fraction(0), Fraction(0), Fraction(1))
    polarization_vectors = (polarization_one, polarization_two)
    symbol_rank = fraction_rank(maxwell_symbol)
    symbol_nullity = len(maxwell_symbol) - symbol_rank
    gauge_null_residual = max(abs(value) for value in apply_symbol(gauge_vector))
    polarization_null_residual = max(
        abs(value)
        for polarization in polarization_vectors
        for value in apply_symbol(polarization)
    )
    transversality_rows = tuple(
        (
            label,
            sum(lowered_wave[index] * polarization[index] for index in range(4)),
            sum(eta[row][column] * polarization[row] * polarization[column] for row in range(4) for column in range(4)),
        )
        for label, polarization in (("epsilon_1", polarization_one), ("epsilon_2", polarization_two))
    )
    mutual_orthogonality = sum(
        eta[row][column] * polarization_one[row] * polarization_two[column]
        for row in range(4) for column in range(4)
    )
    kernel_basis_matrix = tuple(
        tuple(vector[row] for vector in (gauge_vector, polarization_one, polarization_two))
        for row in range(4)
    )
    kernel_basis_rank = fraction_rank(kernel_basis_matrix)
    physical_polarization_count = symbol_nullity - SHIFT

    speed = Fraction(audit_663["symbol"]["continuum_speed"])
    primitive_wave_number = Fraction(SHIFT, DUAL)
    update_interval = Fraction(SHIFT)
    courant_square = (speed * primitive_wave_number * update_interval) ** DUAL
    transfer_trace = DUAL - courant_square
    transfer = (
        (transfer_trace, Fraction(-SHIFT)),
        (Fraction(SHIFT), Fraction(0)),
    )
    transfer_determinant = transfer[0][0] * transfer[1][1] - transfer[0][1] * transfer[1][0]
    state = (Fraction(SHIFT), Fraction(0))
    transfer_rows = []
    invariant_values = []
    for update in range(13):
        current, previous = state
        invariant = current * current + previous * previous - transfer_trace * current * previous
        invariant_values.append(invariant)
        transfer_rows.append((update, current, previous, invariant))
        state = (transfer_trace * current - previous, current)
    transfer_period = next(
        (row[0] for row in transfer_rows[SHIFT:] if row[1] == Fraction(SHIFT) and row[2] == Fraction(0)),
        None,
    )
    invariant_drift = max(invariant_values) - min(invariant_values)

    doubled_transfer = tuple(
        tuple(
            transfer[row % DUAL][column % DUAL]
            if row // DUAL == column // DUAL
            else Fraction(0)
            for column in range(2 * DUAL)
        )
        for row in range(2 * DUAL)
    )
    doubled_rank = fraction_rank(doubled_transfer)
    doubled_determinant = transfer_determinant ** DUAL

    u1 = audit_664["u1_subsystem"]
    noether_residual = max(abs(row[SHIFT]) for row in u1["noether_rows"])
    nonzero_link_equation_count = sum(value != 0 for value in u1["link_gradient"].values())
    finite_action_variation_present = bool(nonzero_link_equation_count > 0 and u1["compact_u1_matter_parent_subsystem_closed"])

    spatial_symbol = audit_654["symbol"]
    unique_spatial_operator = bool(
        spatial_symbol["direction_resolved_two_transverse_photon_symbol_closed"]
        and spatial_symbol["automorphism_invariant_symbol_basis_dimension"] == SHIFT
        and spatial_symbol["symbol_freedom_up_to_scale"] == 0
    )
    native_time_transfer = bool(
        speed == DUAL
        and courant_square == SHIFT
        and transfer_determinant == SHIFT
        and transfer_period == 6
        and invariant_drift == 0
        and doubled_rank == 2 * DUAL
        and doubled_determinant == SHIFT
    )
    two_polarizations_closed = bool(
        light_cone_residual == 0
        and symbol_rank == SHIFT
        and symbol_nullity == 3
        and gauge_null_residual == 0
        and polarization_null_residual == 0
        and all(row[SHIFT] == 0 and row[DUAL] < 0 for row in transversality_rows)
        and mutual_orthogonality == 0
        and kernel_basis_rank == 3
        and physical_polarization_count == DUAL
    )
    source_variation_closed = bool(
        audit_664["hodge"]["strict_C4_full_whitney_lorentz_gauge_hodge_closed"]
        and finite_action_variation_present
        and u1["finite_gauge_action_residual"] == 0
        and noether_residual == 0
    )
    continuum_light_cone_closed = bool(
        audit_663["symbol"]["one_invariant_continuum_signal_speed_generated"]
        and audit_663["lorentz"]["strict_B3_lorentz_origin_clause_closed"]
        and audit_663["symbol"]["quartic_residual_vanishes_as_spacing_square"]
    )
    strict_d2 = bool(
        unique_spatial_operator
        and native_time_transfer
        and two_polarizations_closed
        and source_variation_closed
        and continuum_light_cone_closed
    )
    checks = {
        "unique native gauge-transverse spatial Maxwell symbol": unique_spatial_operator,
        "FCC continuum fixes one causal propagation speed": continuum_light_cone_closed,
        "Maxwell recurrence follows from speed and primitive wave number": native_time_transfer,
        "null four-symbol has gauge plus exactly two physical polarizations": two_polarizations_closed,
        "one compact U1 action yields link equation and exact Noether identity": source_variation_closed,
        "D2 strict conjunction": strict_d2,
    }
    return {
        "metric": eta,
        "null_wave_vector": wave,
        "light_cone_residual": light_cone_residual,
        "maxwell_symbol": maxwell_symbol,
        "maxwell_symbol_rank": symbol_rank,
        "maxwell_symbol_nullity": symbol_nullity,
        "gauge_null_residual": gauge_null_residual,
        "polarization_rows": transversality_rows,
        "polarization_mutual_orthogonality": mutual_orthogonality,
        "polarization_null_residual": polarization_null_residual,
        "kernel_basis_rank": kernel_basis_rank,
        "physical_polarization_count": physical_polarization_count,
        "native_speed": speed,
        "primitive_wave_number": primitive_wave_number,
        "update_interval": update_interval,
        "courant_square": courant_square,
        "time_transfer_matrix": transfer,
        "time_transfer_determinant": transfer_determinant,
        "time_transfer_period": transfer_period,
        "time_transfer_rows": tuple(transfer_rows),
        "time_transfer_invariant_drift": invariant_drift,
        "two_polarization_transfer_rank": doubled_rank,
        "two_polarization_transfer_determinant": doubled_determinant,
        "u1_noether_residual": noether_residual,
        "nonzero_link_equation_count": nonzero_link_equation_count,
        "unique_spatial_maxwell_operator": unique_spatial_operator,
        "actual_maxwell_time_transfer_derived": native_time_transfer,
        "direction_resolved_two_transverse_photon_dof_closed": two_polarizations_closed,
        "sourced_u1_action_variation_closed": source_variation_closed,
        "continuum_light_cone_closed": continuum_light_cone_closed,
        "strict_D2_native_maxwell_closed": strict_d2,
        "checks": checks,
        "status": "NATIVE_MAXWELL_TIME_TRANSFER_TWO_POLARIZATION_D2_PASS" if strict_d2 else "NATIVE_MAXWELL_D2_OPEN",
        "boundary": "the strict result is the native long-wave U1 Maxwell sector: exact action variation, conserved current identity, one generated light cone, causal time transfer and two transverse physical polarizations; quantum QED loops and absolute SI decoding remain outside D2",
    }


