def causal_connection_field_671_lens() -> Dict[str, object]:
    """Derive the primitive A-Gamma-B transmission law without fitting or a continuous parameter.

    The native generator has no argument.  Equal 5:5 endpoint counts are reconstructed from the
    ten-seat bipolar ledger.  Mechanical embeddings contribute only an orientation parity.  The
    connector itself is the unique primitive signed incidence operator whose quadratic energy is
    positive, local, exchange-covariant and has the requested rigid transmission null mode.
    Pi is kept as a formal winding symbol; it is never numerically evaluated in this lens.
    """
    whole = TOTAL
    endpoint_count = whole // DUAL
    first_imbalance = SHIFT
    primary_value = endpoint_count + first_imbalance
    secondary_value = endpoint_count - first_imbalance
    tooth_count_primary = endpoint_count
    tooth_count_secondary = endpoint_count

    # Orientation parity is structural metadata of the embedding, not an adjustable coupling.
    # A parity count of zero preserves coordinate rotation; an odd count reverses it.
    connection_specs = (
        ("DIRECT_EXTERNAL_MESH", SHIFT),
        ("OPEN_CHAIN", 0),
        ("CROSSED_CHAIN", SHIFT),
        ("ELASTIC_FIELD_SAME_ORIENTATION", 0),
        ("ELASTIC_FIELD_OPPOSITE_ORIENTATION", SHIFT),
    )
    connection_rows = []
    torque_rows = []
    operator_rows = []
    all_operator_candidates: Dict[int, Tuple[Tuple[Tuple[int, int], Tuple[int, int]], ...]] = {}

    search_limit = endpoint_count
    for orientation_parity in (0, SHIFT):
        sign = SHIFT if orientation_parity % DUAL == 0 else -SHIFT
        null_mode = (SHIFT, sign)
        incidence = (-sign, SHIFT)
        expected_operator = (
            (incidence[0] * incidence[0], incidence[0] * incidence[1]),
            (incidence[1] * incidence[0], incidence[1] * incidence[1]),
        )
        candidates = []
        integer_range = range(-search_limit, search_limit + SHIFT)
        for diagonal_a, off_diagonal, diagonal_b in itertools.product(integer_range, repeat=3):
            matrix = ((diagonal_a, off_diagonal), (off_diagonal, diagonal_b))
            null_residual = (
                matrix[0][0] * null_mode[0] + matrix[0][1] * null_mode[1],
                matrix[1][0] * null_mode[0] + matrix[1][1] * null_mode[1],
            )
            determinant = diagonal_a * diagonal_b - off_diagonal * off_diagonal
            primitive_divisor = math.gcd(math.gcd(abs(diagonal_a), abs(off_diagonal)), abs(diagonal_b))
            positive_semidefinite = diagonal_a >= 0 and diagonal_b >= 0 and determinant >= 0
            rank_one_nonzero = determinant == 0 and diagonal_a + diagonal_b > 0
            if (
                null_residual == (0, 0)
                and positive_semidefinite
                and rank_one_nonzero
                and primitive_divisor == SHIFT
            ):
                candidates.append(matrix)
        all_operator_candidates[sign] = tuple(candidates)
        selected = candidates[0] if len(candidates) == SHIFT else tuple()
        operator_rows.append([
            sign,
            null_mode,
            incidence,
            len(candidates),
            selected,
            selected == expected_operator,
        ])

    for connection_label, orientation_parity in connection_specs:
        sign = SHIFT if orientation_parity % DUAL == 0 else -SHIFT
        ratio_magnitude = Fraction(tooth_count_primary, tooth_count_secondary)
        signed_ratio = sign * ratio_magnitude
        # Circumference is represented as coefficient * formal_PI^power.
        primary_circumference = (DUAL * tooth_count_primary, SHIFT)
        secondary_circumference = (DUAL * tooth_count_secondary, SHIFT)
        circumference_ratio = Fraction(primary_circumference[0], secondary_circumference[0])
        formal_pi_power_after_ratio = primary_circumference[1] - secondary_circumference[1]
        pi_cancels = formal_pi_power_after_ratio == 0
        pi_retained_in_full_winding = primary_circumference[1] == SHIFT
        connection_rows.append([
            connection_label,
            orientation_parity,
            sign,
            ratio_magnitude,
            signed_ratio,
            formal_pi_power_after_ratio,
            pi_cancels,
            pi_retained_in_full_winding,
        ])

        operator = all_operator_candidates[sign][0]
        initial_coordinate = (SHIFT, 0)
        generalized_torque = tuple(
            -sum(operator[row][column] * initial_coordinate[column] for column in range(DUAL))
            for row in range(DUAL)
        )
        signed_null_mode = (SHIFT, sign)
        generalized_conservation_residual = sum(
            signed_null_mode[index] * generalized_torque[index]
            for index in range(DUAL)
        )
        strain = -sign * initial_coordinate[0] + initial_coordinate[1]
        primitive_edge_energy = Fraction(strain * strain, DUAL)
        torque_rows.append([
            connection_label,
            sign,
            strain,
            generalized_torque[0],
            generalized_torque[1],
            generalized_conservation_residual,
            primitive_edge_energy,
        ])

    # Exhaust all deterministic reversible maps on the three causal roles.  Requiring
    # primary -> connector and connector -> secondary leaves exactly one primitive 3-cycle.
    roles = ("PRIMARY", "CONNECTOR", "SECONDARY")
    causal_permutations = tuple(
        permutation
        for permutation in itertools.permutations(range(len(roles)))
        if permutation[0] == SHIFT and permutation[SHIFT] == DUAL
    )
    causal_permutation = causal_permutations[0] if len(causal_permutations) == SHIFT else tuple()
    causal_rows = []
    role_index = 0
    for update in range(len(roles) + SHIFT):
        state = tuple(SHIFT if index == role_index else 0 for index in range(len(roles)))
        invariant = sum(component * component for component in state)
        causal_rows.append([update, roles[role_index], state, invariant])
        role_index = causal_permutation[role_index]

    causal_matrix = tuple(
        tuple(SHIFT if causal_permutation[column] == row else 0 for column in range(len(roles)))
        for row in range(len(roles))
    )
    causal_matrix_cube = tuple(
        tuple(
            sum(
                causal_matrix[row][middle_1]
                * causal_matrix[middle_1][middle_2]
                * causal_matrix[middle_2][column]
                for middle_1 in range(len(roles))
                for middle_2 in range(len(roles))
            )
            for column in range(len(roles))
        )
        for row in range(len(roles))
    )
    identity_three = tuple(
        tuple(SHIFT if row == column else 0 for column in range(len(roles)))
        for row in range(len(roles))
    )

    causal_55_rows = (
        ["A_PRIMARY_INITIAL", endpoint_count, endpoint_count, 0, 0, whole],
        ["A_PRIMARY_CONNECTOR_STORAGE", primary_value, endpoint_count, -first_imbalance, SHIFT, whole],
        ["A_PRIMARY_B_SECONDARY_CLOSED", primary_value, secondary_value, 0, 0, whole],
        ["B_PRIMARY_INITIAL", endpoint_count, endpoint_count, 0, 0, whole],
        ["B_PRIMARY_CONNECTOR_STORAGE", endpoint_count, primary_value, -first_imbalance, -SHIFT, whole],
        ["B_PRIMARY_A_SECONDARY_CLOSED", secondary_value, primary_value, 0, 0, whole],
    )
    causal_total_residual = max(
        abs(row[1] + row[2] + row[3] - whole)
        for row in causal_55_rows
    )

    local_link_invariants = tuple(sorted(set(
        (row[3], row[4]) for row in connection_rows
    )))
    checks = {
        "ten_seat_ledger_reconstructs_equal_five_five_endpoints": endpoint_count * DUAL == whole,
        "first_imbalance_reconstructs_six_four": (primary_value, secondary_value) == (endpoint_count + SHIFT, endpoint_count - SHIFT),
        "both_orientation_edge_operators_unique": all(len(candidates) == SHIFT for candidates in all_operator_candidates.values()),
        "edge_operator_equals_signed_incidence_square": all(row[-1] for row in operator_rows),
        "all_transfer_ratios_remove_formal_pi": all(row[5] == 0 and row[6] for row in connection_rows),
        "full_winding_retains_formal_pi": all(row[7] for row in connection_rows),
        "generalized_endpoint_torque_conserved": all(row[5] == 0 for row in torque_rows),
        "primitive_edge_energy_positive": all(row[6] > 0 for row in torque_rows),
        "causal_three_role_map_unique": len(causal_permutations) == SHIFT,
        "causal_transfer_is_exact_three_cycle": causal_matrix_cube == identity_three,
        "causal_transfer_preserves_unit_burden": all(row[3] == SHIFT for row in causal_rows),
        "five_five_transition_conserves_whole_at_every_stage": causal_total_residual == 0,
        "simultaneous_endpoint_change_not_required": causal_55_rows[1][2] == endpoint_count and causal_55_rows[4][1] == endpoint_count,
        "local_link_has_no_pi_strength_parameter": all(row[5] == 0 for row in connection_rows),
        "dimensionless_connection_free_parameter_count_zero": all(len(candidates) == SHIFT for candidates in all_operator_candidates.values()),
    }
    closed = all(checks.values())
    return {
        "whole": whole,
        "endpoint_count": endpoint_count,
        "primary_value": primary_value,
        "secondary_value": secondary_value,
        "connection_rows": connection_rows,
        "operator_rows": operator_rows,
        "torque_rows": torque_rows,
        "causal_permutation_candidates": causal_permutations,
        "causal_permutation": causal_permutation,
        "causal_matrix": causal_matrix,
        "causal_rows": causal_rows,
        "causal_55_rows": causal_55_rows,
        "causal_total_residual": causal_total_residual,
        "driver_to_connector_lag": SHIFT,
        "driver_to_follower_completion_lag": DUAL,
        "local_link_invariants": local_link_invariants,
        "formal_pi_local_coupling_derived": False,
        "formal_pi_global_winding_role": True,
        "primitive_dimensionless_coupling": SHIFT,
        "dimensionless_free_parameter_count": 0,
        "absolute_SI_link_scale_is_decoder_boundary": True,
        "checks": checks,
        "closed": closed,
        "status": "A_GAMMA_B_CAUSAL_CONNECTION_AND_PI_ROLE_CLOSED" if closed else "A_GAMMA_B_CONNECTION_OPEN",
        "boundary": "the local link fixes dimensionless ratio, orientation and causal storage; an absolute SI stiffness or time unit belongs to the single global decoder scale",
    }


def connection_constitution_671_lens(connection_audit: Dict[str, object]) -> Dict[str, object]:
    function_names = (
        "causal_connection_field_671_lens",
        "connection_constitution_671_lens",
        "manuscript_update_readiness_671_lens",
        "post_626_all_intermediate_results_cumulative_gate_671_lens",
    )
    forbidden_names = {
        "open", "exec", "eval", "compile", "input", "__import__",
        "minimize", "optimize", "curve_fit", "polyfit", "least_squares",
        "log", "log10", "log2", "exp", "expm1", "sin", "cos", "tan",
        "sinh", "cosh", "tanh", "asin", "acos", "atan",
        "numpy", "scipy", "pandas", "csv", "json", "zipfile", "pickle",
    }
    forbidden_hits = []
    sealed_hits = []
    float_constants = []
    missing_functions = []
    for function_name in function_names:
        function = globals().get(function_name)
        if not callable(function) or not hasattr(function, "__code__"):
            missing_functions.append(function_name)
            continue
        stack = [function.__code__]
        while stack:
            code_object = stack.pop()
            used_names = set(code_object.co_names)
            for forbidden_name in sorted(used_names.intersection(forbidden_names)):
                forbidden_hits.append((function_name, forbidden_name))
            if "SEALED" in used_names:
                sealed_hits.append(function_name)
            for constant in code_object.co_consts:
                if isinstance(constant, float):
                    float_constants.append((function_name, constant))
                elif hasattr(constant, "co_code") and hasattr(constant, "co_consts"):
                    stack.append(constant)

    native_function = globals()["causal_connection_field_671_lens"]
    native_names = set(native_function.__code__.co_names)
    circular_generation_hits = tuple(sorted(
        native_names.intersection({
            "complete_parent_variation_670_lens",
            "post_626_all_intermediate_results_cumulative_gate_670_lens",
            "manuscript_update_readiness_671_lens",
        })
    ))
    checks = {
        "all_671_functions_resident": not missing_functions,
        "no_log_exp_trigonometric_or_fit_calls": not forbidden_hits,
        "no_sealed_reference_in_671_layer": not sealed_hits,
        "no_float_coefficient_in_671_layer": not float_constants,
        "native_connection_generator_has_no_argument": native_function.__code__.co_argcount == 0,
        "native_connection_generation_not_downstream_circular": not circular_generation_hits,
        "connection_result_derived_by_exhaustion": connection_audit["checks"]["both_orientation_edge_operators_unique"],
        "no_dimensionless_free_parameter": connection_audit["dimensionless_free_parameter_count"] == 0,
    }
    closed = all(checks.values())
    return {
        "function_names": function_names,
        "missing_functions": tuple(missing_functions),
        "forbidden_hits": tuple(forbidden_hits),
        "sealed_hits": tuple(sealed_hits),
        "float_constants": tuple(float_constants),
        "circular_generation_hits": circular_generation_hits,
        "checks": checks,
        "closed": closed,
        "status": "CODE_8100_671_NO_LOG_NO_FIT_NO_PARAMETER_NO_CYCLE_PASS" if closed else "CODE_8100_671_CONSTITUTION_OPEN",
    }


