def native_spacetime_maxwell_671_lens() -> Dict[str, object]:
    directions = tuple(sorted(_C12_VERTICES))
    second_moment = tuple(
        tuple(sum(vector[row] * vector[column] for vector in directions) for column in range(3))
        for row in range(3)
    )
    spatial_rank = _fraction_rank_670([[Fraction(value) for value in row] for row in second_moment])
    isotropic_diagonal = tuple(second_moment[index][index] for index in range(3))
    off_diagonal = tuple(
        second_moment[row][column]
        for row in range(3)
        for column in range(3)
        if row != column
    )
    native_speed_squared = Fraction(isotropic_diagonal[0], DUAL)
    native_speed = DUAL if native_speed_squared == DUAL * DUAL else 0
    normalized_metric = tuple(
        tuple(Fraction(SHIFT if row == column == 0 else -SHIFT if row == column else 0) for column in range(4))
        for row in range(4)
    )
    generated_metric = tuple(
        tuple(Fraction(native_speed_squared if row == column == 0 else -SHIFT if row == column else 0) for column in range(4))
        for row in range(4)
    )

    beta = Fraction(3, G5)
    gamma = Fraction(G5, 4)
    physical_velocity = beta * native_speed
    boost = (
        (gamma, -gamma * physical_velocity / native_speed_squared, Fraction(0), Fraction(0)),
        (-gamma * physical_velocity, gamma, Fraction(0), Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(SHIFT), Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(0), Fraction(SHIFT)),
    )
    boost_metric = tuple(
        tuple(
            sum(
                boost[middle_left][row]
                * generated_metric[middle_left][middle_right]
                * boost[middle_right][column]
                for middle_left in range(4)
                for middle_right in range(4)
            )
            for column in range(4)
        )
        for row in range(4)
    )
    boost_residual = max(
        abs(boost_metric[row][column] - generated_metric[row][column])
        for row in range(4)
        for column in range(4)
    )

    wave_vector = (Fraction(G5), Fraction(3), Fraction(4), Fraction(0))
    covector = tuple(
        sum(normalized_metric[row][column] * wave_vector[column] for column in range(4))
        for row in range(4)
    )
    light_cone_residual = sum(covector[index] * wave_vector[index] for index in range(4))
    maxwell_symbol = tuple(
        tuple(-wave_vector[row] * covector[column] for column in range(4))
        for row in range(4)
    )
    maxwell_rank = _fraction_rank_670([list(row) for row in maxwell_symbol])
    maxwell_nullity = 4 - maxwell_rank
    gauge_residual = max(
        abs(sum(maxwell_symbol[row][column] * wave_vector[column] for column in range(4)))
        for row in range(4)
    )
    polarizations = (
        (Fraction(0), Fraction(4), Fraction(-3), Fraction(0)),
        (Fraction(0), Fraction(0), Fraction(0), Fraction(SHIFT)),
    )
    polarization_rows = []
    for polarization in polarizations:
        transversality = sum(covector[index] * polarization[index] for index in range(4))
        symbol_residual = max(
            abs(sum(maxwell_symbol[row][column] * polarization[column] for column in range(4)))
            for row in range(4)
        )
        polarization_rows.append((polarization, transversality, symbol_residual))
    polarization_rank = _fraction_rank_670([list(wave_vector), list(polarizations[0]), list(polarizations[1])])

    edges = ((0, SHIFT), (SHIFT, DUAL), (DUAL, 0))
    d0 = tuple(
        tuple(-SHIFT if vertex == tail else SHIFT if vertex == head else 0 for vertex in range(3))
        for tail, head in edges
    )
    d1 = (tuple(SHIFT for _ in edges),)
    chain_residual = max(
        abs(sum(d1[0][edge] * d0[edge][vertex] for edge in range(len(edges))))
        for vertex in range(3)
    )
    gauge_parameter = (Fraction(SHIFT), Fraction(-DUAL), Fraction(3))
    connection = (Fraction(SHIFT, DUAL), Fraction(DUAL, 3), Fraction(-SHIFT, 4))
    gauge_shift = tuple(
        sum(Fraction(d0[edge][vertex]) * gauge_parameter[vertex] for vertex in range(3))
        for edge in range(len(edges))
    )
    curvature = sum(Fraction(d1[0][edge]) * connection[edge] for edge in range(len(edges)))
    transformed_curvature = sum(
        Fraction(d1[0][edge]) * (connection[edge] + gauge_shift[edge])
        for edge in range(len(edges))
    )
    curvature_gauge_residual = transformed_curvature - curvature
    edge_euler = tuple(Fraction(d1[0][edge]) * curvature for edge in range(len(edges)))
    noether_residual = max(
        abs(sum(Fraction(d0[edge][vertex]) * edge_euler[edge] for edge in range(len(edges))))
        for vertex in range(3)
    )

    primitive_wave_number = Fraction(SHIFT, DUAL)
    courant_square = native_speed_squared * primitive_wave_number * primitive_wave_number
    recurrence_coefficient = DUAL - courant_square
    transfer_matrix = (
        (recurrence_coefficient, Fraction(-SHIFT)),
        (Fraction(SHIFT), Fraction(0)),
    )
    state = (Fraction(SHIFT), Fraction(0))
    initial_state = state
    transfer_rows = []
    period = 0
    for update in range(TOTAL * TOTAL + SHIFT):
        invariant = state[0] * state[0] - state[0] * state[1] + state[1] * state[1]
        transfer_rows.append((update, state[0], state[1], invariant))
        state = (
            transfer_matrix[0][0] * state[0] + transfer_matrix[0][1] * state[1],
            transfer_matrix[1][0] * state[0] + transfer_matrix[1][1] * state[1],
        )
        if state == initial_state:
            period = update + SHIFT
            break
    invariant_drift = max(abs(row[3] - transfer_rows[0][3]) for row in transfer_rows)

    checks = {
        "twelve_directions_have_zero_first_moment": all(sum(vector[axis] for vector in directions) == 0 for axis in range(3)),
        "twelve_directions_have_isotropic_second_moment": len(set(isotropic_diagonal)) == SHIFT and not any(off_diagonal),
        "three_spatial_directions_have_full_rank": spatial_rank == 3,
        "one_native_speed_is_generated": native_speed_squared == DUAL * DUAL and native_speed == DUAL,
        "generated_metric_has_one_plus_three_signature": generated_metric[0][0] > 0 and all(generated_metric[index][index] < 0 for index in range(SHIFT, 4)),
        "rational_boost_preserves_generated_metric": boost_residual == 0,
        "maxwell_wave_vector_is_null": light_cone_residual == 0,
        "maxwell_symbol_has_one_gauge_plus_two_physical_null_directions": maxwell_nullity - SHIFT == DUAL,
        "gauge_direction_is_null": gauge_residual == 0,
        "two_polarizations_are_transverse_symbol_nulls": all(row[1] == 0 and row[2] == 0 for row in polarization_rows),
        "gauge_and_two_polarizations_are_independent": polarization_rank == 3,
        "vertex_edge_face_chain_squares_to_zero": chain_residual == 0,
        "u1_curvature_is_gauge_invariant": curvature_gauge_residual == 0,
        "u1_noether_identity_is_exact": noether_residual == 0,
        "time_transfer_is_generated_from_native_speed": courant_square == SHIFT,
        "time_transfer_returns_with_finite_period": period > 0,
        "time_transfer_quadratic_invariant_is_exact": invariant_drift == 0,
    }
    closed = all(checks.values())
    return {
        "directions": directions,
        "second_moment": second_moment,
        "spatial_rank": spatial_rank,
        "native_speed_squared": native_speed_squared,
        "native_speed": native_speed,
        "generated_metric": generated_metric,
        "boost": boost,
        "boost_residual": boost_residual,
        "wave_vector": wave_vector,
        "light_cone_residual": light_cone_residual,
        "maxwell_rank": maxwell_rank,
        "maxwell_nullity": maxwell_nullity,
        "physical_polarization_count": maxwell_nullity - SHIFT,
        "polarization_rows": tuple(polarization_rows),
        "chain_residual": chain_residual,
        "curvature_gauge_residual": curvature_gauge_residual,
        "u1_noether_residual": noether_residual,
        "strict_D2_native_maxwell_closed": closed,
        "primitive_wave_number": primitive_wave_number,
        "courant_square": courant_square,
        "time_transfer_matrix": transfer_matrix,
        "time_transfer_period": period,
        "time_transfer_rows": tuple(transfer_rows),
        "time_transfer_invariant_drift": invariant_drift,
        "checks": checks,
        "closed": closed,
        "status": "NATIVE_SPACETIME_MAXWELL_D2_CLOSED" if closed else "NATIVE_SPACETIME_MAXWELL_OPEN",
    }


