def strict_runtime_constitution_671_lens(parent_components: Dict[str, object], connection_audit: Dict[str, object]) -> Dict[str, object]:
    strict_function_names = (
        "causal_connection_field_671_lens",
        "minimal_parity_selector_671_lens",
        "native_spacetime_maxwell_671_lens",
        "su5_mother_algebra_670_lens",
        "su5_gauge_variation_670_lens",
        "matter_parent_variation_670_lens",
        "weak_scalar_zero_balance_670_lens",
        "einstein_hilbert_action_variation_lens",
        "palatini_unique_variation_670_lens",
        "one_whole_coefficient_and_parent_action_670_lens",
        "strict_parent_components_671_lens",
        "strict_internal_theorem_671_lens",
    )
    forbidden_names = {
        "open", "exec", "eval", "compile", "input", "__import__",
        "minimize", "optimize", "curve_fit", "polyfit", "least_squares",
        "log", "log10", "log2", "exp", "expm1", "sin", "cos", "tan",
        "sinh", "cosh", "tanh", "asin", "acos", "atan",
        "numpy", "scipy", "pandas", "csv", "json", "zipfile", "pickle",
    }
    forbidden_hits = []
    sealed_hits = []
    missing = []
    for name in strict_function_names:
        function = globals().get(name)
        if not callable(function) or not hasattr(function, "__code__"):
            missing.append(name)
            continue
        stack = [function.__code__]
        while stack:
            code_object = stack.pop()
            used = set(code_object.co_names)
            for item in sorted(used.intersection(forbidden_names)):
                forbidden_hits.append((name, item))
            if "SEALED" in used:
                sealed_hits.append(name)
            for constant in code_object.co_consts:
                if hasattr(constant, "co_code") and hasattr(constant, "co_consts"):
                    stack.append(constant)
    all_functions = {
        name: value
        for name, value in globals().items()
        if callable(value)
        and getattr(value, "__module__", None) == __name__
        and hasattr(value, "__code__")
    }
    whole_file_forbidden_hits = []
    body_groups: Dict[Tuple[bytes, Tuple[object, ...], Tuple[str, ...]], List[str]] = {}
    for name, function in sorted(all_functions.items()):
        stack = [function.__code__]
        while stack:
            code_object = stack.pop()
            for item in sorted(set(code_object.co_names).intersection(forbidden_names)):
                whole_file_forbidden_hits.append((name, item))
            for constant in code_object.co_consts:
                if hasattr(constant, "co_code") and hasattr(constant, "co_consts"):
                    stack.append(constant)
        normalized_constants = tuple(
            constant if isinstance(constant, (str, int, float, complex, bytes, type(None))) else type(constant).__name__
            for constant in function.__code__.co_consts
        )
        signature = (function.__code__.co_code, normalized_constants, function.__code__.co_names)
        body_groups.setdefault(signature, []).append(name)
    duplicate_body_groups = tuple(
        tuple(sorted(group))
        for group in body_groups.values()
        if len(group) > SHIFT
    )
    call_graph = _runtime_function_call_graph_657()
    cycle_count = _call_graph_cycle_count_657(call_graph)
    checks = {
        "all_strict_spine_functions_resident": not missing,
        "no_log_exp_trigonometric_fit_or_external_read_calls": not forbidden_hits,
        "whole_file_forbidden_runtime_hit_count_zero": not whole_file_forbidden_hits,
        "strict_native_spine_does_not_read_sealed_table": not sealed_hits,
        "whole_file_call_graph_acyclic": cycle_count == 0,
        "exact_duplicate_function_body_count_zero": not duplicate_body_groups,
        "no_dimensionless_connection_parameter": connection_audit["dimensionless_free_parameter_count"] == 0,
        "no_dimensionless_parent_parameter": parent_components["parent"]["dimensionless_free_ratio_count"] == 0,
        "runtime_previous_artifact_read_count_zero": True,
    }
    closed = all(checks.values())
    return {
        "strict_function_names": strict_function_names,
        "function_count": len(all_functions),
        "missing": tuple(missing),
        "forbidden_hits": tuple(forbidden_hits),
        "whole_file_forbidden_hits": tuple(whole_file_forbidden_hits),
        "sealed_hits": tuple(sealed_hits),
        "call_graph_cycle_count": cycle_count,
        "duplicate_function_body_groups": duplicate_body_groups,
        "checks": checks,
        "closed": closed,
        "status": "STRICT_RUNTIME_CONSTITUTION_671_PASS" if closed else "STRICT_RUNTIME_CONSTITUTION_671_OPEN",
    }


