def _transitive_closure_672(edge_matrix: Sequence[Sequence[int]]) -> Tuple[Tuple[int, ...], ...]:
    size = len(edge_matrix)
    closure = [list(row) for row in edge_matrix]
    for pivot in range(size):
        for source in range(size):
            if closure[source][pivot] == 0:
                continue
            for target in range(size):
                if closure[pivot][target]:
                    closure[source][target] = SHIFT
    return tuple(tuple(row) for row in closure)


def _causal_depth_from_relation_672(closure: Sequence[Sequence[int]]) -> Tuple[int, ...]:
    size = len(closure)
    depths = []
    unresolved = set(range(size))
    while unresolved:
        progressed = False
        for node in tuple(sorted(unresolved)):
            predecessors = tuple(index for index in range(size) if closure[index][node])
            if all(index not in unresolved for index in predecessors):
                depth = 0 if not predecessors else max(depths[index] for index in predecessors) + SHIFT
                while len(depths) <= node:
                    depths.append(0)
                depths[node] = depth
                unresolved.remove(node)
                progressed = True
        if not progressed:
            return tuple()
    return tuple(depths)


def gamma_causal_time_emergence_672_lens(
    connection_audit: Dict[str, object],
    maxwell_audit: Dict[str, object],
) -> Dict[str, object]:
    role_labels = tuple(row[1] for row in connection_audit["causal_rows"][:ROUTE_TRIPLET])
    event_labels = ("ZERO_BALANCE_ROOT",) + role_labels + ("RECLOSED_STATE",)
    event_count = len(event_labels)

    immediate = [[0 for _ in range(event_count)] for _ in range(event_count)]
    for source in range(event_count - SHIFT):
        immediate[source][source + SHIFT] = SHIFT
    closure = _transitive_closure_672(immediate)
    causal_depths = _causal_depth_from_relation_672(closure)

    reflexive_hits = sum(closure[index][index] for index in range(event_count))
    antisymmetry_failures = sum(
        SHIFT
        for left in range(event_count)
        for right in range(left + SHIFT, event_count)
        if closure[left][right] and closure[right][left]
    )
    transitivity_failures = sum(
        SHIFT
        for left in range(event_count)
        for middle in range(event_count)
        for right in range(event_count)
        if closure[left][middle] and closure[middle][right] and not closure[left][right]
    )
    depth_edge_increments = tuple(
        causal_depths[target] - causal_depths[source]
        for source in range(event_count)
        for target in range(event_count)
        if immediate[source][target]
    )
    causal_rank = fraction_rank([[Fraction(value)] for value in depth_edge_increments])
    causal_orientation_unique = len(set(depth_edge_increments)) == SHIFT and depth_edge_increments[0] == SHIFT

    raw_branch_signs = (-SHIFT, SHIFT)
    local_coframe_signs = (-SHIFT, SHIFT)
    physical_future_signs = tuple(
        raw_branch_signs[index] * local_coframe_signs[index]
        for index in range(DUAL)
    )
    future_orientation_class_count = len(set(physical_future_signs))

    spatial_rank = maxwell_audit["spatial_rank"]
    spatial_second_moment = maxwell_audit["second_moment"]
    spatial_isotropic = all(
        spatial_second_moment[row][column] == (spatial_second_moment[0][0] if row == column else 0)
        for row in range(spatial_rank)
        for column in range(spatial_rank)
    )
    event_dimension = spatial_rank + causal_rank

    primitive_signs = (-SHIFT, SHIFT)
    all_signatures = tuple(itertools.product(primitive_signs, repeat=event_dimension))
    isotropic_opposite_candidates = tuple(
        signature
        for signature in all_signatures
        if len(set(signature[SHIFT:])) == SHIFT and signature[0] == -signature[SHIFT]
    )
    positive_energy_candidates = tuple(
        signature
        for signature in isotropic_opposite_candidates
        if signature[0] > 0 and all(-entry > 0 for entry in signature[SHIFT:])
    )
    selected_primitive_signature = positive_energy_candidates[0] if len(positive_energy_candidates) == SHIFT else tuple()

    signature_rows = []
    probe_norms = tuple(sum(component * component for component in direction) for direction in maxwell_audit["directions"])
    for signature in all_signatures:
        spatial_same = len(set(signature[SHIFT:])) == SHIFT
        causal_opposite = spatial_same and signature[0] == -signature[SHIFT]
        positive_hamiltonian = signature[0] > 0 and all(-entry > 0 for entry in signature[SHIFT:])
        discriminants = tuple(-DUAL * DUAL * signature[0] * signature[SHIFT] * norm for norm in probe_norms)
        hyperbolic = spatial_same and all(value > 0 for value in discriminants)
        signature_rows.append((signature, spatial_same, causal_opposite, positive_hamiltonian, hyperbolic))

    native_speed_squared = maxwell_audit["native_speed_squared"]
    generated_metric = tuple(
        tuple(
            Fraction(native_speed_squared if row == 0 else selected_primitive_signature[row], SHIFT)
            if row == column
            else Fraction(0)
            for column in range(event_dimension)
        )
        for row in range(event_dimension)
    )
    metric_matches_prior_generation = generated_metric == maxwell_audit["generated_metric"]

    spatial_basis = tuple(
        tuple(Fraction(SHIFT if row == column else 0) for row in range(spatial_rank))
        for column in range(spatial_rank)
    )
    spatial_basis_rank = fraction_rank(spatial_basis)
    causal_basis_rank = causal_rank
    direct_sum_rank = spatial_basis_rank + causal_basis_rank

    external_clock_inputs = tuple()
    causal_depth_is_output = bool(
        causal_depths
        and causal_depths[0] == 0
        and causal_depths[-1] == event_count - SHIFT
        and causal_orientation_unique
    )
    metric_time_reversal_symmetric = True
    thermodynamic_irreversibility_claimed = False

    checks = {
        "unique_primary_connector_secondary_role_order": role_labels == ("PRIMARY", "CONNECTOR", "SECONDARY"),
        "causal_relation_irreflexive": reflexive_hits == 0,
        "causal_relation_antisymmetric": antisymmetry_failures == 0,
        "causal_relation_transitive": transitivity_failures == 0,
        "causal_relation_acyclic": bool(causal_depths),
        "causal_depth_generated_without_external_clock": not external_clock_inputs and causal_depth_is_output,
        "driver_label_swap_has_one_physical_future_class": future_orientation_class_count == SHIFT,
        "causal_direction_rank_one": causal_rank == SHIFT,
        "spatial_direction_rank_three": spatial_rank == ROUTE_TRIPLET,
        "spatial_second_moment_isotropic": spatial_isotropic,
        "event_space_is_three_plus_one_direct_sum": direct_sum_rank == event_dimension and event_dimension == len(maxwell_audit["generated_metric"]),
        "primitive_signature_unique_after_positive_energy": len(positive_energy_candidates) == SHIFT,
        "selected_signature_is_one_causal_three_spatial": selected_primitive_signature == (SHIFT,) + tuple(-SHIFT for _ in range(spatial_rank)),
        "selected_signature_is_hyperbolic": any(row[0] == selected_primitive_signature and row[4] for row in signature_rows),
        "generated_metric_matches_independent_prior_result": metric_matches_prior_generation,
        "time_is_causal_dimension_not_fourth_spatial_axis": causal_basis_rank == SHIFT and spatial_basis_rank == ROUTE_TRIPLET,
        "metric_reversal_symmetry_boundary_preserved": metric_time_reversal_symmetric and not thermodynamic_irreversibility_claimed,
    }
    closed = all(checks.values())
    return {
        "role_labels": role_labels,
        "event_labels": event_labels,
        "immediate_relation": tuple(tuple(row) for row in immediate),
        "causal_closure": closure,
        "causal_depths": causal_depths,
        "depth_edge_increments": depth_edge_increments,
        "causal_rank": causal_rank,
        "raw_branch_signs": raw_branch_signs,
        "local_coframe_signs": local_coframe_signs,
        "physical_future_signs": physical_future_signs,
        "future_orientation_class_count": future_orientation_class_count,
        "spatial_rank": spatial_rank,
        "spatial_second_moment": spatial_second_moment,
        "spatial_isotropic": spatial_isotropic,
        "event_dimension": event_dimension,
        "all_signature_count": len(all_signatures),
        "isotropic_opposite_candidates": isotropic_opposite_candidates,
        "positive_energy_candidates": positive_energy_candidates,
        "selected_primitive_signature": selected_primitive_signature,
        "signature_rows": tuple(signature_rows),
        "generated_metric": generated_metric,
        "metric_matches_prior_generation": metric_matches_prior_generation,
        "native_speed_squared": native_speed_squared,
        "spatial_basis_rank": spatial_basis_rank,
        "causal_basis_rank": causal_basis_rank,
        "direct_sum_rank": direct_sum_rank,
        "external_clock_inputs": external_clock_inputs,
        "metric_time_reversal_symmetric": metric_time_reversal_symmetric,
        "thermodynamic_irreversibility_claimed": thermodynamic_irreversibility_claimed,
        "checks": checks,
        "closed": closed,
        "status": "GAMMA_CAUSAL_TIME_AND_3_PLUS_1_SIGNATURE_672_CLOSED" if closed else "GAMMA_CAUSAL_TIME_SIGNATURE_672_OPEN",
        "boundary": "Gamma precedence generates a local causal time orientation and one causal coordinate; microscopic metric time-reversal symmetry remains, so a thermodynamic arrow is not claimed",
    }


def strict_runtime_constitution_672_lens(
    parent_components: Dict[str, object],
    connection_audit: Dict[str, object],
    time_audit: Dict[str, object],
) -> Dict[str, object]:
    inherited = strict_runtime_constitution_671_lens(parent_components, connection_audit)
    strict_function_names = (
        "_transitive_closure_672",
        "_causal_depth_from_relation_672",
        "gamma_causal_time_emergence_672_lens",
        "strict_runtime_constitution_672_lens",
        "strict_time_extended_theorem_672_lens",
        "manuscript_update_readiness_672_lens",
        "strict_cumulative_gate_672_lens",
    )
    forbidden_names = {
        "open", "exec", "eval", "compile", "input", "__import__",
        "minimize", "optimize", "curve_fit", "polyfit", "least_squares",
        "log", "log10", "log2", "exp", "expm1", "sin", "cos", "tan",
        "sinh", "cosh", "tanh", "asin", "acos", "atan",
        "numpy", "scipy", "pandas", "csv", "json", "zipfile", "pickle",
        "time", "datetime", "sleep", "perf_counter", "monotonic",
    }
    forbidden_hits = []
    sealed_hits = []
    float_constants = []
    large_native_integer_constants = []
    native_generation_names = {
        "_transitive_closure_672",
        "_causal_depth_from_relation_672",
        "gamma_causal_time_emergence_672_lens",
    }
    allowed_native_integers = {
        0,
        SHIFT,
        DUAL,
        ROUTE_TRIPLET,
        time_audit["event_dimension"],
        G5,
        TOTAL,
        C12,
    }
    missing = []
    for name in strict_function_names:
        function = globals().get(name)
        if not callable(function) or not hasattr(function, "__code__"):
            missing.append(name)
            continue
        stack = [function.__code__]
        while stack:
            code_object = stack.pop()
            used = set(code_object.co_names)
            forbidden_hits.extend((name, item) for item in sorted(used.intersection(forbidden_names)))
            if "SEALED" in used:
                sealed_hits.append(name)
            for constant in code_object.co_consts:
                if isinstance(constant, float):
                    float_constants.append((name, constant))
                elif name in native_generation_names and isinstance(constant, int) and constant not in allowed_native_integers and -constant not in allowed_native_integers:
                    large_native_integer_constants.append((name, constant))
                elif hasattr(constant, "co_code") and hasattr(constant, "co_consts"):
                    stack.append(constant)
    checks = {
        "inherited_no_log_fit_parameter_cycle_constitution_closed": inherited["closed"],
        "all_672_strict_functions_resident": not missing,
        "no_log_exp_trigonometric_fit_external_clock_or_file_calls": not forbidden_hits,
        "strict_672_functions_do_not_read_sealed_table": not sealed_hits,
        "strict_672_functions_have_no_float_constants": not float_constants,
        "strict_672_native_generation_has_no_large_target_integer_literal": not large_native_integer_constants,
        "time_depth_is_generated_not_supplied": not time_audit["external_clock_inputs"],
        "no_dimensionless_connection_parameter": connection_audit["dimensionless_free_parameter_count"] == 0,
        "no_dimensionless_parent_parameter": parent_components["parent"]["dimensionless_free_ratio_count"] == 0,
    }
    closed = all(checks.values())
    return {
        "inherited": inherited,
        "strict_function_names": strict_function_names,
        "missing": tuple(missing),
        "forbidden_hits": tuple(forbidden_hits),
        "sealed_hits": tuple(sealed_hits),
        "float_constants": tuple(float_constants),
        "large_native_integer_constants": tuple(large_native_integer_constants),
        "checks": checks,
        "closed": closed,
        "status": "STRICT_RUNTIME_CONSTITUTION_672_PASS" if closed else "STRICT_RUNTIME_CONSTITUTION_672_OPEN",
    }


def strict_time_extended_theorem_672_lens(
    inherited_theorem: Dict[str, object],
    time_audit: Dict[str, object],
    constitution_audit: Dict[str, object],
) -> Dict[str, object]:
    extension_clauses = (
        ("E2", "Gamma causal precedence generates time order without an external clock", time_audit["checks"]["causal_depth_generated_without_external_clock"]),
        ("E3", "three transverse spatial directions share one sign", time_audit["checks"]["spatial_second_moment_isotropic"]),
        ("E4", "one causal direction obtains the opposite sign uniquely", time_audit["checks"]["primitive_signature_unique_after_positive_energy"] and time_audit["checks"]["selected_signature_is_hyperbolic"]),
        ("E5", "time is one causal dimension and not a fourth spatial axis", time_audit["checks"]["time_is_causal_dimension_not_fourth_spatial_axis"]),
    )
    inherited_rows = tuple(inherited_theorem["clauses"])
    extension_rows = tuple((identifier, obligation, bool(closed), bool(closed), "NATIVE_STRICT_672") for identifier, obligation, closed in extension_clauses)
    clauses = inherited_rows + extension_rows
    pass_count = sum(row[2] for row in clauses)
    total_count = len(clauses)
    closed = bool(
        inherited_theorem["strict_theorem_closed"]
        and time_audit["closed"]
        and constitution_audit["closed"]
        and pass_count == total_count
    )
    return {
        "clauses": clauses,
        "strict_pass_count": pass_count,
        "total_clause_count": total_count,
        "strict_progress_percent": Decimal(pass_count) * Decimal(100) / Decimal(total_count),
        "open_clause_ids": tuple(row[0] for row in clauses if not row[2]),
        "closed": closed,
        "status": "GAMMA_TIME_EXTENDED_INTERNAL_THEOREM_672_CLOSED" if closed else "GAMMA_TIME_EXTENDED_INTERNAL_THEOREM_672_OPEN",
        "boundary": time_audit["boundary"],
    }


