def _scalar_text_674(value: object) -> str:
    if isinstance(value, Fraction):
        return str(value)
    if isinstance(value, Decimal):
        return format(value, "f")
    if isinstance(value, complex):
        real = 0 if value.real == 0 else value.real
        imag = 0 if value.imag == 0 else value.imag
        return f"({real:.15g}{imag:+.15g}j)"
    return repr(value)


def _is_scalar_sequence_674(value: object) -> bool:
    return isinstance(value, (tuple, list)) and all(not isinstance(item, (dict, tuple, list)) for item in value)


def _print_full_tree_674(path: str, value: object, depth: int = 0) -> int:
    """Print every resident result leaf without truncation; return printed leaf/row count."""
    count = 0
    if isinstance(value, dict):
        print(f"[{path}] DICT_SIZE={len(value)}")
        for key in sorted(value, key=lambda item: str(item)):
            count += _print_full_tree_674(f"{path}.{key}", value[key], depth + 1)
        return count
    if isinstance(value, (tuple, list)):
        print(f"[{path}] SEQUENCE_LENGTH={len(value)}")
        if _is_scalar_sequence_674(value):
            print(f"[{path}] VALUE={tuple(_scalar_text_674(item) for item in value)}")
            return 1
        for index, item in enumerate(value):
            count += _print_full_tree_674(f"{path}[{index}]", item, depth + 1)
        return count
    print(f"[{path}] VALUE={_scalar_text_674(value)}")
    return 1


